// CPC question bank in English, generated by tools/cpc-en/build.js from cpc/data.js. Do not edit by hand.
window.CPC_TEMAS_EN = {"10":{"title":"Topic 10 - Operator Licensing","questions":[{"q":"For what duration is a Road Passenger Transport Operator Licence normally valid?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The Road Passenger Transport Operator Licence normally lasts 5 years and then has to be renewed."},{"q":"Which division is responsible for issuing the Road Passenger Transport Operator Licence and the Community Licence?","options":["RTOL Division, Department of Transport","The National Transport Authority","The Road Safety Authority","An Garda Síochána"],"correct":0,"exp":"The RTOL (Road Transport Operator Licensing Division) of the Department of Transport issues the operator licence and the Community Licence."},{"q":"Who issues the Large Public Service Vehicle (LPSV) Licence for the registered owner of the vehicle?","options":["A PSV Officer of An Garda Síochána","The Minister for Transport","The National Transport Authority (NTA)","The Driver and Vehicle Computer Services Division"],"correct":0,"exp":"The licence for each large vehicle (LPSV licence) is issued by a Garda PSV Officer to the vehicle owner, after checking that the vehicle complies."},{"q":"What type of licence is required to provide a regular public passenger service between specified terminal points or along a specified route?","options":["A Public Bus Passenger Service Licence","An International Road Passenger Transport Operator Licence","A Large Public Service Vehicle Licence","An Event-Specific PSV Licence"],"correct":0,"exp":"A regular service between fixed points or on a fixed route needs a Public Bus Passenger Service Licence (formerly called a 'Route Licence'), issued by the NTA."},{"q":"Who is the issuing authority for the Public Bus Passenger Service Licence?","options":["The National Transport Authority","An Garda Síochána","The Department of Transport","Local County Councils"],"correct":0,"exp":"The Public Bus Passenger Service Licence is issued by the National Transport Authority (NTA), not the Department of Transport."},{"q":"What four core criteria must an applicant satisfy to obtain a Road Passenger Transport Operator Licence under EU Regulations?","options":["Good repute, appropriate financial standing, professional competence, and a stable and effective establishment in Ireland","Irish citizenship, a minimum of 10 vehicles, 5 years of driving experience, and a tax clearance certificate","Local authority planning permission, a clean driving licence, public liability insurance, and a C-class driver","An annual profit of €50,000, zero traffic offences, ISO 9001 certification, and a contracted mechanic"],"correct":0,"exp":"Good repute, financial standing, professional competence, stable establishment."},{"q":"What constitutes a 'Large Public Service Vehicle' (LPSV)?","options":["Carries more than 8 passengers, plus the driver","Any vehicle used for hire or reward","A vehicle with a gross weight over 3.5 tonnes","Any MPV used for airport transfers"],"correct":0,"exp":"LPSV = vehicle for more than 8 passengers, not counting the driver. With 8 seats or fewer it is a 'small PSV' (taxi, hackney, limousine)."},{"q":"Which of the following operations is exempt from requiring a Road Passenger Transport Operator Licence?","options":["Transporting passengers for a fare between Dublin and Cork on a scheduled bus service","A hotel offering a complimentary transport service to its guests without charging them","Hiring a 50-seater coach to a sports club for a fee","Providing daily commuter services to a business park for paying passengers"],"correct":1,"exp":"A hotel that provides free transport, without charging."},{"q":"What happens if a road transport undertaking loses its tax clearance status from the Revenue Commissioners?","options":["The Minister may suspend or revoke the licence","A €5,000 fine, but the licence stays valid","It must apply for a temporary UK licence","The NTA takes over its financial management"],"correct":0,"exp":"The Minister can suspend/revoke the licence."},{"q":"How soon must the holder of a Road Passenger Transport Operator Licence notify the Minister in writing of a relevant conviction against any relevant person?","options":["Within 3 months of the appeal time running out","Within 1 month of the date of conviction","Within 6 months of the original court date","Only when the licence is next renewed"],"correct":0,"exp":"Within 3 months of the end of the appeal period."},{"q":"What financial standing threshold must an applicant demonstrate to authorize vehicles on their Road Passenger Transport Operator Licence?","options":["€10,000 for the first vehicle and €2,000 for each additional vehicle","€9,000 for the first vehicle and €5,000 for each additional vehicle","A flat rate of €50,000 regardless of fleet size","€5,000 per vehicle across the entire fleet"],"correct":1,"exp":"€9,000 for the first vehicle, €5,000 for each additional one."},{"q":"How must an established business (trading for more than 1 year) demonstrate financial standing?","options":["Certified accounts, year-end within 18 months","A bank statement covering the last 30 days","A letter of credit from an Irish bank branch","A Statement of Affairs from the last month"],"correct":0,"exp":"Certified annual accounts, with a year-end not more than 18 months old."},{"q":"How does a new business (trading for less than 1 year) demonstrate its financial standing?","options":["A certified Statement of Affairs, under 1 month old","Three months of projected cash flow forecasts","The founder's personal tax returns for 3 years","None: it is waived for the first year"],"correct":0,"exp":"A certified 'Statement of Affairs', dated no earlier than 1 month before."},{"q":"To satisfy the requirement of 'professional competence,' an undertaking must designate a Transport Manager who holds what specific document?","options":["A CPC in Road Passenger Transport","A Category D driving licence","A university degree in logistics","A Certificate of Roadworthiness"],"correct":0,"exp":"A CPC in Road Passenger Transport, from an EU authority."},{"q":"If a transport manager ceases to act in that role, what is the maximum period the Department of Transport may allow to designate a replacement?","options":["1 month","3 months","6 months","12 months"],"correct":2,"exp":"If the transport manager leaves the post, the Department of Transport can allow up to 6 months to appoint another one who holds the CPC."},{"q":"What are the strict limitations placed on a 'Contracted Transport Manager' regarding the number of undertakings and vehicles they can manage?","options":["Max 4 undertakings and 50 vehicles in total","Unlimited undertakings, up to 100 vehicles","Max 2 undertakings, 25 vehicles each","One undertaking with up to 10 vehicles"],"correct":0,"exp":"A maximum of 4 companies, with a combined total of no more than 50 vehicles."},{"q":"What does the requirement of a 'stable and effective establishment' strictly prohibit?","options":["'Letterbox' firms with only a mailing address","Operating vehicles over 10 years old","Employing drivers on part-time contracts","Parking vehicles overnight at a private house"],"correct":0,"exp":"'Letterbox' companies that only exist as a postal address."},{"q":"To maintain a stable and effective establishment, an operator must always have at least how many compliant vehicles at its disposal?","options":["One","Two","Three","Five"],"correct":0,"exp":"Stable and effective establishment: among other things, the operator must always have at its disposal at least one vehicle that complies with the rules."},{"q":"What documents must be carried on board a vehicle operating nationally under a Road Passenger Transport Operator Licence?","options":["The original Operator Licence and a photocopy of the Transport Manager's CPC","A vehicle-specific Certified Copy of the Licence and a displayed Transport Disc","A blank Journey Form and the company's annual accounts","The vehicle's original logbook (VLC) and the driver's birth certificate"],"correct":1,"exp":"A certified copy of the specific vehicle licence and the Transport Disc."},{"q":"For international road passenger operations within the EU, what additional licensing document is issued to the operator to be kept at the base of operations?","options":["A Journey Form booklet","A Community Licence","A European Route Authorisation","A Eurovignette"],"correct":1,"exp":"To operate within the EU a Community Licence is also issued: the original is kept at the base and a certified copy is carried in each vehicle."},{"q":"What document must be carried on board a vehicle operating internationally under an International Road Passenger Transport Operator Licence?","options":["A certified true copy of the Community Licence","The original Community Licence document","The driver's CPC translated into all EU languages","The original Certificate of Incorporation"],"correct":0,"exp":"A certified true copy of the Community Licence."},{"q":"What is 'Bus Cabotage'?","options":["Carrying passengers inside another EU state","Driving an empty bus across a border","Running an urban route only in Ireland","Hiring a foreign bus for a local school run"],"correct":0,"exp":"Point-to-point transport within another State, as part of an international service."},{"q":"In the context of International Services, what defines a 'Regular International Service'?","options":["Set intervals, set route and stops, open to all","Closed groups of tourists on an ad-hoc basis","Only for soldiers travelling between barracks","Runs only at weekends and on public holidays"],"correct":0,"exp":"Fixed intervals, predetermined route and stops, open to everyone."},{"q":"How is an 'Occasional International Service' characterized?","options":["Groups formed by the customer or the carrier","Follows a published timetable and fixed stops","Daily commuter routes across the border","Needs a separate ticket for every passenger"],"correct":0,"exp":"Groups formed on the initiative of the customer/carrier."},{"q":"What specific document must cover an Occasional International Service?","options":["A Journey Form","A Route Authorisation Certificate","A Special Regular Service Contract","A Cabotage Permit"],"correct":0,"exp":"International occasional services carry a Journey Form (formerly a 'waybill'), which is filled in before departure."},{"q":"Who supplies the books of Journey Forms required for Occasional International Services in Ireland?","options":["The Road Safety Authority (RSA)","The National Transport Authority (NTA)","An Garda Síochána","The European Commission"],"correct":1,"exp":"In Ireland, books of Journey Forms are issued by the NTA."},{"q":"Within what timeframe must a completed Journey Form be returned to the NTA after the journey is finished?","options":["Within 7 days","Within 14 days","Within 30 days","Within 60 days"],"correct":2,"exp":"The completed Journey Form is returned to the NTA within 30 days of the end of the journey."},{"q":"What characterizes a 'Special Regular International Service'?","options":["Contracted groups only, e.g. workers or pupils","Open to the public, with compulsory booking","Hop-on hop-off tourist services in cities","Services run with vintage buses for weddings"],"correct":0,"exp":"Specific people under contract, excluding others."},{"q":"What documentation must be carried on board for a Special Regular Service?","options":["The contract between organiser and carrier","A book of blank Journey Forms for each trip","Individual tickets for all passengers","A letter from the Department of Education"],"correct":0,"exp":"On a Special Regular Service (for example, carrying workers or students) a copy of the contract between the organiser and the carrier must be carried on board."},{"q":"If an operator wishes to substitute or remove a vehicle from their licence, how must the application be made?","options":["By writing a letter to the local Garda station","Through the online licensing portal on www.rtol.ie","By emailing the NTA route licensing division","By visiting the Department of Transport in person"],"correct":1,"exp":"To change or remove a vehicle from the licence, the application is made online on the www.rtol.ie portal."},{"q":"When removing a vehicle from an Operator Licence via the RTOL portal, what must be done with the vehicle's licensing documents (Transport Disc, Certified Copies)?","options":["They must be transferred to the replacement vehicle immediately","They are to be shredded and securely disposed of","They must be returned by registered post to the Department of Transport","They must be handed into the nearest Garda station"],"correct":1,"exp":"When a vehicle is removed from the licence, its disc and certified copies are securely destroyed (shredded)."},{"q":"Under the Public Bus Passenger Service Licence categories, what is a 'Commuter Service'?","options":["Peak-time services to work or education centres","Services only between small rural villages","Interurban services with no stops in between","A hop-on hop-off tourist route at mid-day"],"correct":0,"exp":"To places of work/study, mainly at peak hours."},{"q":"For how long are Regular Service Licences (issued by the NTA) typically granted?","options":["1 year","3 years","5 years","Indefinitely"],"correct":1,"exp":"NTA regular service licences are normally granted for 3 years."},{"q":"What is the validity period for Demand-responsive Service Licences issued by the NTA?","options":["1 year","3 years","5 years","6 months"],"correct":0,"exp":"NTA demand-responsive service licences last 1 year."},{"q":"What is a 'Shadow Operator' in the context of the Road Transport Act 2011?","options":["Someone who profits from or controls the operator","A transport manager who works part-time","An operator who only runs services at night","A sub-contractor hired for one school run"],"correct":0,"exp":"A person who, without being the named operator, controls the business directly or indirectly."},{"q":"Which of the following is considered a 'Serious Conviction' that must be notified to the Minister?","options":["Murder, drug trafficking or money laundering","A parking ticket received in a loading bay","A minor speeding offence caught on camera","Failing to display a valid tax disc"],"correct":0,"exp":"Murder, manslaughter, drug trafficking or money laundering."},{"q":"If a driver of a Large Public Service Vehicle is directed to stop by a passenger intending to alight at a lawful stopping point, what must the driver do?","options":["Stop at the next lawful place to set down","Stop only if it suits the driver's schedule","Ignore the request if the bus is running late","Stop at once, even in the middle of the road"],"correct":0,"exp":"Stopping at the next legal point to let passengers off."},{"q":"Under the regulations for drivers of LPSVs, what power does a driver have regarding offensive passengers?","options":["Refuse entry to them or ask them to leave","Impose an on-the-spot fine on them","Arrest them and hold them for the Gardaí","Ignore it and keep driving to the depot"],"correct":0,"exp":"The driver of an LPSV can refuse to carry, or ask to get off, anyone in a state likely to annoy the other passengers (for example, drunk)."},{"q":"What must the driver of an omnibus NOT do while the vehicle is moving or stopped in traffic?","options":["Enter into conversation with anyone","Check the mirrors and blind spots","Announce the name of the next stop","Operate the door controls"],"correct":0,"exp":"Engaging in conversation with any other person."},{"q":"What is required for an operator to carry out 'Own Account' International Transport Operations?","options":["No licence, if ancillary and non-commercial","An International operator licence is required","A route authorisation from the Commission","Journey Forms must be filed for every trip"],"correct":0,"exp":"Exempt from licensing if it is an ancillary, non-commercial, not-for-profit activity."},{"q":"In an application for a Regular International Service Authorisation, how long do the authorities of consulted Member States have to notify their decision?","options":["1 month","2 months","4 months","6 months"],"correct":1,"exp":"When applying for an international regular service authorisation, the States consulted have 2 months to reply."},{"q":"What happens if a consulted Member State authority does not reply within the specified 2-month limit regarding an International Route Authorisation?","options":["They are taken to have agreed","The application is automatically refused","The application is suspended indefinitely","The operator receives a heavy fine"],"correct":0,"exp":"If the State consulted does not reply within 2 months, it is taken to agree (tacit approval)."},{"q":"Who evaluates and manages the Garda vetting process required for establishing the 'good repute' of relevant persons in a transport undertaking?","options":["RTOL in the Department, with An Garda Síochána","The NTA, with the local county council","The Revenue Commissioners, with the CRO","The Road Safety Authority, with the HSA"],"correct":0,"exp":"RTOL/Dept. of Transport together with An Garda Síochána."},{"q":"Under Statutory Instrument 265 of 2018, which of the following records must an operator keep at their business address?","options":["Tachograph, working time, P45 and maintenance records","Only the financial accounts from the last decade","Birth certificates of all passengers carried","Every Journey Form from the last 10 years"],"correct":0,"exp":"Tachograph records, work patterns, P45s, maintenance and digital data for the last 12 months."},{"q":"If the overall number of vehicles on a licence is being increased through the RTOL portal, what must be done if the previously notified financial standing does not support the additional vehicles?","options":["Submit new proof of finance for the bigger fleet","Add vehicles now; prove finance at renewal","Pay a financial penalty to the Department","Switch to an international licence instead"],"correct":0,"exp":"New proof of financial standing must be provided for the new fleet size."},{"q":"Is holding a Road Passenger Transport Operator Licence proof that the holder continuously fulfills the conditions of the licence?","options":["No, it is not proof the conditions are still met","Yes, it is full proof for the whole 5 years","Yes, provided the tax clearance is valid","Yes, but only in the case of national licences"],"correct":0,"exp":"No, holding the licence does not in itself prove that the conditions are still being met."},{"q":"Are Road Passenger Transport Operator Licences transferable to another person or company?","options":["No, it is personal, unless the Department allows it","Yes, it can be sold freely on the open market","Yes, but only to members of the holder's family","No, and it is cancelled on any change of manager"],"correct":0,"exp":"It is personal to the holder and not transferable, unless expressly authorised."},{"q":"Which entity may direct the Road Safety Authority (RSA) to conduct a premises inspection to verify a declared address meets the 'stable and effective establishment' conditions?","options":["An Garda Síochána","The Department of Transport","The National Transport Authority (NTA)","The Revenue Commissioners"],"correct":1,"exp":"The Department of Transport can ask the RSA to inspect the premises to check that the declared address is a stable and effective establishment."},{"q":"What must an operator do by the 31st of March each year regarding their establishment?","options":["Report the number of employees at 31 December","Renew the whole operator licence for a year","Send all tachograph charts to the RSA","Pay an annual franchise fee to the NTA"],"correct":0,"exp":"Report the number of employees at 31 December of the previous year."},{"q":"Under the Road Traffic (Public Service Vehicles) Regulations 1963, how long is a Large Public Service Vehicle (LPSV) Licence issued by An Garda Síochána valid for?","options":["1 year","3 years","5 years","10 years"],"correct":1,"exp":"The LPSV licence issued by the Garda lasts 3 years, under the Road Traffic (Public Service Vehicles) Regulations 1963."}]},"11":{"title":"Topic 11 - Drivers' Hours and Records","questions":[{"q":"What international set of regulations governs drivers' hours for journeys outside the EU, aligned with EU Regulation 561/2006?","options":["The AETR Agreement","The Vienna Convention","The SEPA Framework","The Dublin Protocol"],"correct":0,"exp":"The AETR international agreement is aligned with Regulation 561/2006."},{"q":"Which passenger vehicles are generally exempt from EU Regulation 561/2006?","options":["Up to 9 persons including the driver","All coaches with more than 50 seats","Regular services on routes over 100 km","Double-decker buses used for city tours"],"correct":0,"exp":"Vehicles designed/adapted for a maximum of 9 people including the driver are exempt."},{"q":"Under EU Regulation 561/2006, what is the maximum continuous or aggregated driving time permitted before a driver must take a break?","options":["3 hours","4 hours","4.5 hours","5.5 hours"],"correct":2,"exp":"4.5 hours of continuous/accumulated driving before a compulsory break."},{"q":"What is the mandatory minimum duration of a break required after reaching the maximum driving limit under EU rules?","options":["15 minutes","30 minutes","45 minutes","60 minutes"],"correct":2,"exp":"The minimum compulsory break is 45 minutes."},{"q":"How may a 45-minute EU driving break be split?","options":["15 minutes first, then at least 30 minutes","Three equal breaks of 15 minutes each","A 20-minute break, then a 25-minute break","It can never be split in any circumstances"],"correct":0,"exp":"It is split as 15 min first and 30 min afterwards, in that order."},{"q":"What is the maximum permitted daily driving time under EU rules?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":1,"exp":"Daily driving: maximum 9 hours, which can be 10 hours twice a week."},{"q":"On how many occasions per week may daily driving time be extended to 10 hours?","options":["Once per week","Twice per week","Three times per week","It can never be extended"],"correct":1,"exp":"It can be extended to 10 hours up to twice a week."},{"q":"How does EU Regulation 561/2006 define the working week?","options":["From 00.00 hours on Monday to 24.00 hours on Sunday","Any rolling 7-day period","From Sunday midnight to Sunday midnight","A fixed 40-hour period determined by the employer"],"correct":0,"exp":"The week runs from 00:00 on Monday to 24:00 on Sunday."},{"q":"What is the maximum permitted weekly driving time?","options":["45 hours","48 hours","56 hours","60 hours"],"correct":2,"exp":"Weekly driving: maximum 56 hours, and never more than 90 hours in two consecutive weeks."},{"q":"What is the maximum total driving time permitted in any two consecutive working weeks (fortnightly limit)?","options":["80 hours","90 hours","96 hours","112 hours"],"correct":1,"exp":"Maximum in two consecutive weeks: 90 hours."},{"q":"What is the standard regular daily rest period required under EU rules within any 24-hour period?","options":["At least 9 consecutive hours","At least 10 consecutive hours","At least 11 consecutive hours","At least 12 consecutive hours"],"correct":2,"exp":"Regular daily rest: at least 11 consecutive hours."},{"q":"To what minimum number of hours may a daily rest be reduced, and on how many occasions between two weekly rests?","options":["To 9 hours, up to three times between weekly rests","To 8 hours, up to twice between weekly rests","To 10 hours, as often as needed in the week","To 9 hours, once a week and never more"],"correct":0,"exp":"It can be reduced to 9 hours, up to 3 times between two weekly rests."},{"q":"What are the daily rest requirements for a multi-manned vehicle under EU rules?","options":["9 hours within each 30-hour period","11 hours within each 24-hour period","12 hours taken jointly within 24 hours","None: rest rules do not apply to them"],"correct":0,"exp":"With multi-manning, each driver must rest at least 9h within a 30h period."},{"q":"What is the duration of a regular weekly rest period under EU rules?","options":["At least 24 consecutive hours","At least 36 consecutive hours","At least 45 consecutive hours","Exactly 48 consecutive hours"],"correct":2,"exp":"Regular weekly rest: at least 45 consecutive hours."},{"q":"To what minimum duration may a weekly rest period be reduced?","options":["12 hours","24 hours","30 hours","36 hours"],"correct":1,"exp":"The normal weekly rest is 45 h. It can be reduced to 24 h, but the difference must be made up before the end of the third following week."},{"q":"Within how many weeks must any reduction in a weekly rest period be compensated en bloc?","options":["By the end of the third week after that week","By the end of the next week after that week","By the end of the second week after that week","Within six months of the week in question"],"correct":0,"exp":"It must be compensated en bloc before the end of the 3rd following week."},{"q":"What special concession on weekly rest applies to coach drivers undertaking a single international journey?","options":["Postpone weekly rest to the end of the 12th day","They never need to take weekly rest at all","Reduce weekly rests to 10 hours permanently","Take just one weekly rest every month"],"correct":0,"exp":"The '12-day rule' allows the weekly rest to be postponed until the 12th day."},{"q":"How must a daily rest be interrupted when a driver is travelling by train or ferry boat?","options":["Up to twice, one hour in total, with a bunk","It can never be interrupted for any reason","Up to four times, with no limit on length","The whole crossing counts as working time"],"correct":0,"exp":"A maximum of 2 times, not exceeding 1h in total, with access to a bunk."},{"q":"What is the maximum average weekly working time limit under the Road Transport (Working Time) Regulations?","options":["40 hours","48 hours","56 hours","60 hours"],"correct":1,"exp":"Drivers' working time: maximum average of 48 hours a week, normally calculated over 4 months."},{"q":"Over what standard reference period is the average 48-hour working week calculated?","options":["4 weeks","13 weeks","17 weeks","26 weeks"],"correct":2,"exp":"The normal reference period is 17 weeks, extendable to 26 by collective agreement."},{"q":"What is the absolute maximum number of hours that may be worked in any single week under working time rules?","options":["48 hours","56 hours","60 hours","72 hours"],"correct":2,"exp":"In a single week a maximum of 60 hours can be worked, as long as the average still does not exceed 48."},{"q":"Under Working Time rules, what break must be taken if a driver works for between 6 and 9 hours in a day?","options":["15 minutes","30 minutes","45 minutes","60 minutes"],"correct":1,"exp":"A 30 min break if working between 6 and 9 hours."},{"q":"What total working time break is required if a driver's working day exceeds 9 hours?","options":["30 minutes","45 minutes","60 minutes","90 minutes"],"correct":1,"exp":"A 45 min break if the day exceeds 9 hours."},{"q":"How are 'Periods of Availability' treated under the Road Transport (Working Time) Regulations?","options":["They count fully as working time","They do not count towards working time limits","They count as mandatory driving breaks","They are classified as daily rest periods"],"correct":1,"exp":"POA does NOT count towards the working time limits."},{"q":"What defines a 'Period of Availability'?","options":["Known waiting time with reasonable freedom","Time spent driving on public motorways","Off-duty sleep in a hotel, without breaks","Vehicle checks carried out at the depot"],"correct":0,"exp":"Waiting time known in advance, with a reasonable degree of freedom."},{"q":"When does a driver qualify as a 'night worker' under working time regulations?","options":["If they drive between 22.00 and 06.00","If they work for any time at all between 01.00 and 05.00","If their shift exceeds 12 hours ending past midnight","If they perform more than 4 hours of night driving per week"],"correct":1,"exp":"A driver counts as a 'night worker' if they work any time between 01:00 and 05:00."},{"q":"What is the limit on hours worked in a 24-hour period for a designated night worker (unless modified by collective agreement)?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"A limit of 10 hours in 24h for a designated 'night worker'."},{"q":"For how long must employers retain records of working time under the regulations?","options":["At least 1 year","At least 2 years","At least 3 years","At least 6 years"],"correct":1,"exp":"Working time records are kept for at least 2 years."},{"q":"Which organization is responsible for the enforcement of Working Time provisions in Ireland?","options":["The Workplace Relations Commission","The Health and Safety Authority","The Road Safety Authority","The Department of Transport"],"correct":0,"exp":"The WRC enforces the Working Time rules in Ireland."},{"q":"Under Irish Domestic Regulations (Transport Act 1961/1968), what is the maximum driving time permitted without a break?","options":["4.5 hours","5.0 hours","5.5 hours","6.0 hours"],"correct":2,"exp":"Maximum driving without a break under domestic rules: 5.5 hours."},{"q":"What is the maximum daily driving time under Domestic Regulations?","options":["9 hours","10 hours","11 hours","16 hours"],"correct":1,"exp":"Maximum domestic daily driving: 10 hours."},{"q":"What is the maximum length of the working day (spreadover) under Domestic Regulations?","options":["12 hours","14 hours","16 hours","18 hours"],"correct":2,"exp":"Domestic rules: the whole working day, from start to finish (spreadover), cannot exceed 16 hours."},{"q":"What is the minimum daily rest period required under Domestic Regulations?","options":["8.5 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"Domestic rules: minimum daily rest of 10 hours (under EU rules it is 11)."},{"q":"Under Domestic Regulations, to what minimum duration may the 10-hour daily rest be reduced three times a week?","options":["8 hours","8 hours and 30 minutes","9 hours","No reduction is permitted"],"correct":1,"exp":"It can be reduced to 8h30min, up to 3 times a week."},{"q":"Under Domestic Regulations, what part-time driving exemption applies?","options":["Drivers driving 4 hours a day or less","Drivers driving 2 hours a day or less","Part-timers must always follow EU 561/2006","There is no part-time exemption in Ireland"],"correct":0,"exp":"Those who drive a maximum of 4h/day are exempt from the domestic hours rules."},{"q":"When a driver undertakes mixed EU and Domestic driving, how should time spent driving under Domestic rules be recorded when keeping records for the EU operation?","options":["As rest time","As other work","As a period of availability","It is omitted from records entirely"],"correct":1,"exp":"It is recorded as 'other work' on the tachograph for the EU operation."},{"q":"Can time spent driving under Domestic rules be counted as break or rest under EU rules during mixed driving?","options":["No, it can never count as break or rest","Yes, provided a tachograph is fitted","Yes, if the RSA approves it in advance","Only when driving on weekend shifts"],"correct":0,"exp":"In mixed driving, time driven under domestic rules counts as 'other work' for the EU rules; never as a break or rest."},{"q":"What authority do Gardai and RSA examiners have when they stop a moving vehicle?","options":["Inspect hours records and stop drivers going on","Only inspect the motor tax disc on the windscreen","Issue a WRC certificate before going on","Only check the tickets of the passengers"],"correct":0,"exp":"They can inspect hours records and prohibit the driver from continuing if there is a breach."},{"q":"Under EU Regulation 561/2006, what action must a driver take if delayed due to an unforeseeable emergency (e.g., motorway blockage after a major accident)?","options":["Depart only to reach a safe stop; record why","Abandon the vehicle and walk to the nearest exit","Keep driving until the normal weekly rest","Report to the European Commission within 24 h"],"correct":0,"exp":"The driver can depart from the rules only as far as necessary to reach a safe place, noting the reason on arrival."},{"q":"What does EU Regulation 561/2006 prohibit regarding driver remuneration and bonus schemes?","options":["Pay linked to distance or passengers, if unsafe","Hourly wages above the national minimum wage","Extra overtime pay for weekend shifts","Bonuses based on vehicle fuel efficiency"],"correct":0,"exp":"It prohibits bonuses linked to distance/passengers/time that endanger road safety."}]},"12":{"title":"Topic 12 - Drivers' Records / Tachograph","questions":[{"q":"When must drivers of 'out of scope' vehicles use a tachograph?","options":["Never: out-of-scope drivers need no tachograph","Whenever the vehicle is over 3.5 tonnes","Only when crossing international borders","Whenever the route is longer than 50 km"],"correct":0,"exp":"'Out of scope' vehicles (for example, buses on regular services up to 50 km) do not need a tachograph or records. Even so, the operator controls hours with rosters and timetables."},{"q":"Which passenger vehicles are 'out of scope' of the EU tachograph and drivers' hours rules?","options":["Regular services on routes up to 50 km","All coaches used for private hire","All vehicles with more than 16 seats","Any coach driven under 4 hours a day"],"correct":0,"exp":"Outside the EU rules: buses on regular services with a route of up to 50 km (that is why new city buses come without a tachograph) and non-commercial vehicles with 9 to 16 seats.\n📍 Book M12 p.1"},{"q":"How long can data relating to the use of a vehicle be stored in the mass memory of a digital tachograph Vehicle Unit (VU)?","options":["Up to 28 days","Up to 90 days","Up to one year","Up to five years"],"correct":2,"exp":"The memory of the vehicle unit (VU) stores usage data for at least a year."},{"q":"What colour is the driver card used in digital tachographs?","options":["Yellow","Red","Blue","White"],"correct":3,"exp":"Card colours: driver, white; company, yellow; workshop, red; control, blue."},{"q":"How many days of activity can the silicon chip on a driver card hold before overwriting old data?","options":["14 days","28 days","42 days","90 days"],"correct":1,"exp":"The driver card stores about 28 days of activity; that is why the company must download it at least every 28 days."},{"q":"What is the standard validity period for a driver card and a company card issued by the RSA?","options":["1 year","2 years","3 years","5 years"],"correct":3,"exp":"The driver card and the company card are issued by the RSA and last 5 years."},{"q":"Within what timeframe must the RSA be informed if a driver card is lost, stolen, or damaged?","options":["Within 7 days","Within 24 hours","Within 15 days","Within 28 days"],"correct":0,"exp":"If the card is lost, stolen or damaged, the RSA must be told as soon as possible and within 7 days at most. In the meantime, the driver prints out at the start and end of each working day."},{"q":"What is the maximum time permitted for a driver to drive without a card if it is lost, stolen, or damaged, provided they produce manual records?","options":["Up to 15 days","Up to 7 days","Up to 28 days","Up to 90 days"],"correct":0,"exp":"Up to 15 calendar days (or longer if it is impossible to return to base)."},{"q":"What must a driver do if they simply forget to bring their driver card to work on a particular day?","options":["Take manual printouts all day","They must not drive","Use a spare company card instead","Record activities on the back of an analogue chart"],"correct":1,"exp":"They must not drive (forgetting it is not the same as losing it)."},{"q":"What colour is the company card, and what is its primary purpose?","options":["Yellow: lets the operator download and lock data","Red: used only by workshop calibration fitters","Blue: used by Garda and RSA enforcement officers","White: issued to each individual driver"],"correct":0,"exp":"Yellow; it is the 'key' for downloading the VU memory."},{"q":"What colour is the workshop card, and who receives it?","options":["Red: for approved calibration centre staff","Blue: issued to RSA vehicle examiners","Yellow: issued to fleet transport managers","White: issued to trainee mechanics"],"correct":0,"exp":"Red; for qualified staff at approved centres."},{"q":"What colour is the control card, and what is its function?","options":["Blue: for Gardaí and RSA enforcement staff","Red: used for emergency vehicle overrides","Yellow: used for remote company downloads","White: used for tachograph firmware updates"],"correct":0,"exp":"The control card is blue and is used by officers (Garda and RSA) to read tachograph data."},{"q":"How frequently must digital tachographs be fully recalibrated?","options":["Every 2 years","Every 6 months","Every 12 months","Every 5 years"],"correct":0,"exp":"Digital tachographs are fully recalibrated at least every 2 years."},{"q":"In a digital tachograph, which card slot must the main driver use?","options":["Slot 2","Slot 1","Either slot interchangeably","The printer drawer slot"],"correct":1,"exp":"The driver who is going to drive puts their card in slot 1; the second driver, in slot 2."},{"q":"How is a co-driver's activity automatically recorded on a digital tachograph when the vehicle is in motion during a double-manned operation?","options":["Availability","Driving time","Break or rest","Other work"],"correct":0,"exp":"With multi-manning, while the vehicle is moving, the second driver's time is automatically recorded as availability (period of availability)."},{"q":"What time standard do digital tachographs use to record all activities across Europe?","options":["Local Irish Standard Time (IST)","Universal Time Co-ordinated (UTC)","Central European Time (CET)","Greenwich Mean Time minus one hour"],"correct":1,"exp":"Digital tachographs record in UTC (universal time), not local time. In Ireland it matches in winter and is one hour less in summer."},{"q":"At maximum intervals of how many days must an operator download data from the mass memory of a digital tachograph Vehicle Unit (VU)?","options":["Every 28 days","Every 42 days","Every 90 days","Every 365 days"],"correct":2,"exp":"Vehicle unit (VU) data is downloaded at least every 90 days."},{"q":"How frequently must an operator copy data from drivers' digital tachograph cards?","options":["Every 28 days","Every 50 days","Every 90 days","Every 365 days"],"correct":0,"exp":"The driver card is downloaded at least every 28 days, because it only stores about 28 days of activity."},{"q":"What does each completed 'V' stroke produced by the innermost distance trace on an analogue tachograph chart indicate?","options":["1 kilometre","5 kilometres","10 kilometres","20 kilometres"],"correct":2,"exp":"On the analogue chart, each stroke is 5 km, so each complete 'V' is 10 km."},{"q":"What does the thickest activity trace line represent on an analogue tachograph chart?","options":["Break or rest period","Other work","Driving","Period of availability"],"correct":2,"exp":"On the analogue chart: thick trace = driving; medium = other work; thin = break or rest."},{"q":"What does the thinnest activity trace line represent on an analogue tachograph chart?","options":["Driving","Other work","Break or rest period","Vehicle acceleration"],"correct":2,"exp":"Thin trace = break or rest. Thick = driving; medium = other work."},{"q":"What does the medium-thickness activity trace line represent on an analogue tachograph chart?","options":["Other work","Break or rest","Maximum speed","All of the above"],"correct":0,"exp":"Medium trace = other work (for passengers, for example, helping with luggage or cleaning the vehicle). Thick = driving; thin = rest."},{"q":"Within how many days must drivers return completed analogue tachograph charts to their employers?","options":["14 days","28 days","42 days","90 days"],"correct":2,"exp":"The driver must return used charts to the company within 42 days."},{"q":"For how long must operators retain completed analogue tachograph charts under standard EU regulations?","options":["12 months","6 months","2 years","5 years"],"correct":0,"exp":"12 months (if they are used for Working Time, 2 years)."},{"q":"If tachograph records are also relied upon for Working Time compliance, what is the minimum retention period required?","options":["1 year","2 years","3 years","5 years"],"correct":1,"exp":"Tachograph records are kept for at least 1 year; if they are also used to monitor working time, 2 years."},{"q":"What must happen if an analogue or digital tachograph breaks down or malfunctions on a journey?","options":["Keep manual records; repair it on return to base","The vehicle must be abandoned at once","Drive on with no records for up to 30 days","Report it to the WRC within 24 hours"],"correct":0,"exp":"Manual records and repair on returning to base (or on the road if it cannot be done within 1 week)."},{"q":"Within what operational accuracy limits must an analogue tachograph operate regarding speed?","options":["Within ±2 kph of real speed","Within ±6 kph of real speed","Within ±10 kph of real speed","Exact match with zero tolerance"],"correct":1,"exp":"The analogue tachograph must record speed within a tolerance of ±6 km/h."},{"q":"What is the permitted tolerance for distance recording accuracy on an analogue tachograph?","options":["Within ±1% of real distance","Within ±2% of real distance","Within ±4% of real distance","Within ±10% of real distance"],"correct":2,"exp":"Distance must be recorded within a tolerance of ±4%."},{"q":"What is the permitted time accuracy tolerance for a tachograph?","options":["±2 minutes a day or ±10 minutes a week","±1 minute a day or ±5 minutes a week","±5 minutes a day or ±30 minutes a week","No tolerance: it must be exact"],"correct":0,"exp":"The tachograph clock allows an error of ±2 minutes a day or ±10 minutes in 7 days."},{"q":"When an electronic tachograph experiences a power interruption, what does it record on the speed trace area as a warning?","options":["A vertical line to the outer edge of the chart","A blank white gap in the speed trace","A horizontal wavy line across the trace","A continuous error code number printed"],"correct":0,"exp":"A vertical line up to the outer edge of the chart."},{"q":"Under Irish Domestic regulations, when are drivers completely exempt from keeping any hours of work records?","options":["Non-licensed vehicles, or under 4 h within 50 km","When driving any vehicle over 3.5 tonnes","When driving coaches with more than 50 seats","When driving only inside private depot yards"],"correct":0,"exp":"A vehicle without an 'O' licence (≤3,500kg) or a maximum of 4h/day within a 50km radius."},{"q":"What is the basic form of record keeping required under Irish Domestic regulations when records are necessary?","options":["A digital smartcard reader","A weekly record book with duplicate pages and daily lines","Standard EU analogue tachograph charts","Monthly electronic spreadsheets submitted to the WRC"],"correct":1,"exp":"A weekly record book with duplicate pages."},{"q":"For how long must employers retain domestic weekly record books?","options":["1 year","2 years","3 years","6 years"],"correct":2,"exp":"The domestic record book is kept by the employer for 3 years."},{"q":"Within how many days must operators produce requested tachograph records when asked by Gardai or RSA examiners?","options":["Within 24 hours","Within 7 days","Within 10 days","Within 28 days"],"correct":2,"exp":"If the Garda or the RSA request the records, the operator has 10 days to produce them."},{"q":"For how long can enforcement authorities (Gardai or RSA) retain seized driver records that they believe to be false or fraudulent?","options":["Up to 1 month","Up to 3 months","Up to six months","Up to one year"],"correct":2,"exp":"Records that the Garda or the RSA take away because they believe they are false can be kept for up to 6 months."},{"q":"What is the maximum statutory court fine for record-keeping offences under transport legislation?","options":["€1,000","€3,000","€5,000","€10,000"],"correct":2,"exp":"The maximum fine for records offences is €5,000. If there is organised fraud, a charge of 'conspiracy' can be brought, which can lead to prison."},{"q":"What severe legal charge can be brought against drivers and operators who have conspired to produce fraudulent tachograph records?","options":["Conspiracy, with long prison sentences","Tax evasion under the Revenue Acts","Reckless endangerment of aircraft","Corporate fraud under the Companies Act"],"correct":0,"exp":"The offence of 'conspiracy', with long prison sentences."},{"q":"When asked by an Irish enforcement official on the road, how many preceding days must a driver be able to produce tachograph records for?","options":["Today plus the previous 28 days","Today plus the previous 7 days","Today plus the previous 14 days","Today plus the previous 56 days"],"correct":0,"exp":"The current day plus the previous 28 calendar days."},{"q":"What details must a driver fill in on the centre field of an analogue tachograph chart at the *beginning* of each working day?","options":["Name, start place, date, registration, odometer","Only the licence number and the destination","Employer's tax number and the week's hours","The insurance policy number and fuel level"],"correct":0,"exp":"Name, place and date of starting, registration number, and starting odometer reading."},{"q":"What details must a driver enter on the centre field of an analogue tachograph chart at the *end* of the working day?","options":["End place, end date and closing odometer","Total fuel used and rest breaks taken","The names of all passengers carried","The signature of the transport manager"],"correct":0,"exp":"Place, date of finishing, and final odometer reading."}]},"13":{"title":"Topic 13 - Planned Preventive Maintenance","questions":[{"q":"What is the primary responsibility of a transport operator regarding vehicle maintenance?","options":["Keep all vehicles and trailers safe at all times","Inspect vehicles only when drivers report defects","Rely on the annual CVRT test to check them","Pass all liability to outside contractors"],"correct":0,"exp":"They must ensure that all vehicles are in a safe and roadworthy condition at ALL times."},{"q":"According to Irish regulations, who must carry out vehicle safety maintenance inspections?","options":["A suitably qualified, competent person","Any driver holding a category D licence","Only RSA-certified vehicle examiners","The transport manager in person, always"],"correct":0,"exp":"A suitably qualified and technically competent person."},{"q":"What is one of the possible legal repercussions of operating an unroadworthy vehicle?","options":["Mandatory reduction of driving licence points","Revocation, suspension, or curtailment of the operator licence","Immediate confiscation of all company financial assets","Cancellation of the company's business registration"],"correct":1,"exp":"Revocation, suspension or curtailment of the operator licence."},{"q":"What is the top priority in a planned preventive maintenance system?","options":["Safety of road users, pedestrians and crew","Getting maximum mileage from the fleet","Keeping fuel consumption to a minimum","Cutting the cost of workshop labour"],"correct":0,"exp":"The safety of road users, pedestrians and crew is the main priority."},{"q":"Which of the following is considered a general business benefit of well-maintained vehicles?","options":["Better reputation and vehicle availability","Exemption from roadside inspections","Lower motor tax rates for the fleet","No need for tachograph calibration"],"correct":0,"exp":"Protecting the company's reputation and maximising vehicle availability."},{"q":"Which factor MUST be considered when deciding the frequency of maintenance inspections?","options":["The number of drivers employed by the company","Vehicle age, mileage, type of operation, and terrain","The purchase price of the vehicles","The location of the nearest motor tax office"],"correct":1,"exp":"Vehicle age, mileage, type of operation and terrain."},{"q":"What is the key primary objective of any planned maintenance programme?","options":["Safe vehicles with minimum disruption","Zero operating costs for the fleet","No more need for daily driver checks","Replacing vehicles every two years"],"correct":0,"exp":"Ensuring safe operation with minimum disruption."},{"q":"According to the RSA Guide, how should safety inspection intervals be scheduled?","options":["Based strictly on distance covered (kilometres)","Based on time intervals (weeks)","Based on fuel consumption","Based on driver shift patterns"],"correct":1,"exp":"By TIME intervals (weeks), not just by distance."},{"q":"Who is legally responsible for the roadworthy condition of a vehicle when it is being used on a public road?","options":["The transport manager only","The vehicle manufacturer only","Both the operator and the driver","The RSA inspector who last tested the vehicle"],"correct":2,"exp":"Both the operator and the driver are responsible."},{"q":"When must a driver carry out a daily walkaround check?","options":["At the end of every weekly rest period","Every time before a vehicle is used on a public road","Once a week during fuel stops","Only when requested by an enforcement officer"],"correct":1,"exp":"Before each use of the vehicle on a public road."},{"q":"What must be done if multiple drivers use the same vehicle during a single day?","options":["Each new driver does a walkaround check","Only the first driver needs to check","No checks are needed after the morning","The transport manager checks between shifts"],"correct":0,"exp":"Each subsequent driver must do their own check."},{"q":"What is a 'Nil' defect reporting system?","options":["Drivers report daily, even when nothing is wrong","Drivers report defects only after a breakdown","A policy of ignoring minor bodywork scratches","A computer system that shows zero error codes"],"correct":0,"exp":"The driver confirms in writing every day that they found no defects."},{"q":"Which document contains official tolerance limits and criteria for specific vehicle component defects in Ireland?","options":["The RSA 'Categorisation of Defects'","The Drivers' Hours Regulations handbook","The Rules of the Commercial Court","The Vehicle Registration Certificate"],"correct":0,"exp":"The RSA publication 'Categorisation of Defects'."},{"q":"What is meant by a 'red line item' defect found during a daily walkaround check?","options":["A minor cosmetic flaw that can be repaired at the next annual service","A defect that means the vehicle is not roadworthy and must not be used until repaired","A defect that only requires verbal notification to the workshop manager","A tachograph error that resets at midnight"],"correct":1,"exp":"A defect that makes the vehicle unroadworthy until it is repaired."},{"q":"What is the minimum legal tread depth requirement for commercial vehicle tyres in Ireland?","options":["1.6 mm across the central three-quarters","1.0 mm across the whole tyre surface","2.0 mm across half of the tyre width","3 mm on front axles, 1.6 mm on the rear"],"correct":0,"exp":"1.6mm in a continuous band across the central three-quarters of the tyre."},{"q":"Which tyre condition is illegal on a commercial vehicle?","options":["Tread depth of 2.5 mm","Mixing radial and cross-ply tyres on the same axle","Original tread pattern visible in grooves","Tyres inflated to manufacturer recommended pressures"],"correct":1,"exp":"Mixing radial and cross-ply tyres on the same axle is illegal."},{"q":"Which of the following methods can drivers use to check wheel nut security during a walkaround inspection?","options":["Tapping wheel nuts with a hammer to listen for a dull sound","Inspecting wheel nut indicators (tear drops) for misalignment","Looking for bright metal or rust marks around wheel nuts","All of the above"],"correct":3,"exp":"All the methods are valid: tapping with a hammer, indicators, rust/metal marks."},{"q":"What type of glass must be used for windscreens and windows on either side of the driver's seat?","options":["Laminated acoustic glass only","Standard toughened plate glass","Safety glass","Polycarbonate plastic"],"correct":2,"exp":"The windscreen and the windows beside the driver must be made of safety glass, which does not break into sharp pieces."},{"q":"Under what activity category on the tachograph must a driver record the time spent conducting a daily walkaround check?","options":["Rest / Break","Availability","Other Work","Driving"],"correct":2,"exp":"The daily walkround check is work: on the tachograph it is recorded as 'Other Work' (crossed hammers)."},{"q":"For how long must an operator retain vehicle defect reports and defect rectification records?","options":["15 months","6 months","12 months","5 years"],"correct":0,"exp":"At least 15 months (or 2 years according to specific guidance)."},{"q":"Regardless of distance travelled, what is the maximum recommended inspection interval for vehicles and trailers that are 12 years or older?","options":["Every 10 weeks","Every 8 weeks","Every 6 weeks","Every 4 weeks"],"correct":2,"exp":"Every 6 weeks for vehicles aged 12+ years, regardless of mileage."},{"q":"What is the primary duty of technically competent staff conducting safety inspections?","options":["Inspect to roadworthiness standards only","Carry out full engine rebuilds during it","Clean and valet the vehicle interior","Issue the motor tax discs for the fleet"],"correct":0,"exp":"Inspecting against roadworthiness standards, without repairing at the same time."},{"q":"Which passenger vehicles are subject to the Commercial Vehicle Roadworthiness Test (CVRT) in Ireland?","options":["All buses and coaches carrying passengers","Only coaches used on international trips","Only buses with more than 50 seats","Only vehicles over 10 years old"],"correct":0,"exp":"The CVRT applies to all buses and coaches carrying passengers, including hired ones, whether they work in Ireland or abroad. It is taken every year from the first year.\n📍 Book M19 p.2"},{"q":"Who is legally responsible for vehicle roadworthiness when maintenance is contracted out to an third-party garage?","options":["The third-party repairer exclusively","The transport operator","The driver who delivers the vehicle to the garage","The vehicle leasing company"],"correct":1,"exp":"The transport operator remains responsible, even if maintenance is subcontracted."},{"q":"How far in advance should an operator's preventive maintenance plan cover inspection and servicing dates?","options":["At least 1 month","At least 3 months","At least 6 months","At least 24 months"],"correct":2,"exp":"The preventive maintenance plan must have the inspection and service dates set at least 6 months in advance."},{"q":"Which of the following items of workshop equipment is specifically recommended for an in-house maintenance facility?","options":["Roller brake tester equipment","Headlamp adjustment test equipment","Ramps, hoists, or inspection pits","All of the above"],"correct":3,"exp":"All of them: brake tester, headlamp aim, ramps/lifts/pits."},{"q":"Which document forms part of a vehicle's history file to prove defects were fixed?","options":["A job card or defect rectification sheet","The company's Certificate of Incorporation","The driver's CPC qualification card","The operator licence disc in the window"],"correct":0,"exp":"In the vehicle history, the job card or repair sheet proves that the defect was fixed."},{"q":"How often must digital tachographs undergo full recalibration?","options":["Every 1 year","Every 2 years","Every 3 years","Every 6 years"],"correct":1,"exp":"Digital tachograph: full calibration at least every 2 years."},{"q":"How often must analogue tachographs undergo inspection/recalibration?","options":["2-year inspection, 6-year full calibration","Every year, with no full calibration","Every 5 years, at the CVRT test","Only when it breaks down on the road"],"correct":0,"exp":"Analogue tachograph: inspection every 2 years and full calibration every 6 years."},{"q":"Which authorities have the legal right to inspect and seize vehicle maintenance records?","options":["An Garda Síochána and RSA examiners","Revenue Commissioners and Customs","Health and Safety Authority (HSA) only","Local County Council officials"],"correct":0,"exp":"The Garda and RSA examiners can inspect maintenance records and take them away."},{"q":"What system rates transport operators based on risk and compliance findings over a rolling period?","options":["Commercial Vehicle Risk Rating","Operator Financial Standing Index","Driver Penalty Points System","All of the above"],"correct":0,"exp":"The Commercial Vehicle Risk Rating (CVRR) classifies operators as green, amber or red according to the results of their inspections and tests."},{"q":"How long is the rolling period used to calculate an operator's Risk Rating?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"The Risk Rating is calculated with the results of the last 2 years (rolling period)."},{"q":"What is the impact of an 'Amber' or 'Red' Risk Rating on an operator?","options":["Immediate revocation of business license","Increased frequency of inspections by the RSA","Automatic doubling of motor tax fees","Mandatory replacement of the transport manager within 7 days"],"correct":1,"exp":"With an amber or red Risk Rating, the RSA inspects the vehicles and the company more often."},{"q":"What is an advantage of maintaining fleet vehicles in-house rather than contracting out?","options":["Direct control and no contractor profit","No need to keep any written records","Exemption from Garda roadside checks","Exemption from the annual CVRT test"],"correct":0,"exp":"Direct control, flexibility and avoiding a third party's margin."},{"q":"If an operator hires a trailer, who holds the legal responsibility for ensuring its roadworthiness on the road?","options":["The operator and driver using it","The company that built the trailer","The hire company, and no one else","The insurance broker for the fleet"],"correct":0,"exp":"Even if the trailer is hired, whoever uses it is responsible for it being in good condition on the road: the operator and the driver."},{"q":"What action should a Transport Manager take if an audit reveals repeated unrecorded vehicle defects?","options":["Retrain drivers and tighten defect reporting","Ignore it if there have been no accidents","Reduce the number of safety inspections","Hand back the operator licence voluntarily"],"correct":0,"exp":"Reviewing training, reinforcing daily reporting and auditing procedures."}]},"14":{"title":"Topic 14 - Vehicle Costing","questions":[{"q":"Why is historical financial accounting (such as annual profit & loss accounts) alone insufficient for vehicle costing purposes?","options":["It is late and does not show where profits arise","It is rejected by the Revenue Commissioners","It cannot be used to calculate the VAT due","It only records the overtime paid to drivers"],"correct":0,"exp":"It arrives late and does not show WHERE the specific profit/loss is generated."},{"q":"What is a 'cost unit' in transport costing?","options":["A measure such as cost per kilometre run","The total annual overhead of the fleet","The accounting software used by the TM","A specific depot location in the network"],"correct":0,"exp":"Unit of cost measurement, e.g. cost per km or per tonne."},{"q":"What is a 'cost centre'?","options":["A fleet, group or single vehicle bearing costs","A single filling station used by the fleet","The central administration office in Dublin","The bank account holding working capital"],"correct":0,"exp":"The fleet, a group or an individual vehicle to which costs are allocated."},{"q":"Which of the following is classified as a DIRECT cost in vehicle costing?","options":["Fuel, tyres, driver wages and insurance","Office staff salaries and the office rent","Bonuses paid to the executive directors","Heating and lighting for the main office"],"correct":0,"exp":"Fuel, tyres, driver's wages and insurance."},{"q":"Which of the following is an INDIRECT cost (overhead / establishment charge)?","options":["Office rent, rates and admin salaries","Diesel fuel used by the coaches","The drivers' basic weekly wages","Tyres fitted to the vehicles"],"correct":0,"exp":"Office rent, rates, telephone, administrative salaries."},{"q":"How are FIXED costs (standing costs) defined?","options":["Costs that do not change with mileage","Costs that vary directly with kilometres","Costs incurred only on international trips","Fuel and lubricant costs per kilometre"],"correct":0,"exp":"They do not normally vary, whatever the mileage or activity."},{"q":"Which of the following is a VARIABLE cost (running cost)?","options":["Vehicle motor tax","Vehicle annual depreciation","Diesel fuel and lubricants","Vehicle comprehensive insurance"],"correct":2,"exp":"Variable costs (running costs): they change with the km covered, such as diesel, lubricants, tyres and maintenance."},{"q":"Which cost item is both a DIRECT cost and a VARIABLE cost?","options":["Vehicle insurance","Driver basic wage","Tyre wear","Depot property rates"],"correct":2,"exp":"Tyre wear is a direct cost (allocated to that vehicle) and variable (it depends on the km)."},{"q":"Which cost item is both a DIRECT cost and a FIXED cost?","options":["Diesel fuel","Vehicle motor tax","Spare parts used in repairs","Toll charges"],"correct":1,"exp":"Motor tax is direct (for that vehicle) and fixed (it is paid the same even if the vehicle does not move)."},{"q":"Which five main items make up Vehicle Standing Costs?","options":["Tax, insurance, basic wages, depreciation, admin","Fuel, tyres, oil, repairs and maintenance","Overtime, ferries, parking, fines and tax","Rent, rates, heating, telephone, advertising"],"correct":0,"exp":"Tax, insurance, basic wage, depreciation and administration."},{"q":"For passenger vehicles in Ireland, motor tax rates are calculated based on:","options":["Engine cubic capacity (cc)","Gross vehicle weight","Number of seats","Overall vehicle length"],"correct":2,"exp":"For buses and coaches, motor tax depends on the number of seats, not on the weight or the engine."},{"q":"Which insurance premium is included under Vehicle Standing Costs?","options":["Motor insurance for the vehicle","Goods in transit insurance","Public liability cover for the office","Employer's liability cover for depot staff"],"correct":0,"exp":"The vehicle's standing costs include its insurance. The company's other insurances (public liability, employees) go in overheads."},{"q":"How should initial tyre equipment supplied with a new vehicle be treated when calculating vehicle depreciation?","options":["Deducted from the price before depreciation","Included fully in the price for depreciation","Written off as an administrative expense","Added to the drivers' standing wage cost"],"correct":0,"exp":"It is deducted from the purchase price before calculating depreciation."},{"q":"An operator buys a vehicle for €85,000. The initial tyre equipment is valued at €6,875 and the estimated residual value after 5 years is €25,625. Using the straight-line method, what is the annual depreciation charge?","options":["€10,500","€11,875","€15,625","€17,000"],"correct":0,"exp":"(85,000−6,875−25,625)÷5 = 52,500÷5 = €10,500."},{"q":"What is the key characteristic of the Straight-Line Depreciation method?","options":["The same amount written off every year","Higher charges early on, then falling","Based only on the kilometres driven","Changes in line with the price of fuel"],"correct":0,"exp":"The same amount each year over the expected useful life."},{"q":"What is the key characteristic of the Reducing Balance Depreciation method?","options":["More in early years, less in later years","The same amount written off every year","No depreciation in the first year","It ignores the original purchase price"],"correct":0,"exp":"Reducing balance depreciation: a fixed % is applied to what is left each year, so more is depreciated at the start, when the vehicle loses most value."},{"q":"An operator has total administration overheads of €120,000 and a fleet of 15 identical vehicles. Using the Number of Vehicles basis, what is the overhead allocation per vehicle?","options":["€4,000","€6,000","€8,000","€10,000"],"correct":2,"exp":"Allocation per vehicle: 120,000 ÷ 15 = €8,000 each. It is the simplest method and the one the book recommends for similar buses."},{"q":"Which four main components comprise Vehicle Running Costs?","options":["Fuel, oil, tyres, repairs and maintenance","Tax, insurance, depreciation and admin","Overtime, tolls, ferries and subsistence","Rent, rates, light, heat and telephone"],"correct":0,"exp":"Fuel, lubricants, tyres and repairs/maintenance."},{"q":"Diesel fuel costs €36,000 for a group of vehicles over a month during which they cover 90,000 km. What is the fuel cost per kilometre?","options":["40 c/km","25 c/km","36 c/km","50 c/km"],"correct":0,"exp":"Cost per km = cost ÷ km = 36,000 ÷ 90,000 = €0.40 per km (40 cents)."},{"q":"A vehicle has a fuel consumption of 3 km per litre and pre-VAT diesel costs €1.20 per litre. What is the fuel cost per km?","options":["40 c/km","25 c/km","36 c/km","48 c/km"],"correct":0,"exp":"Fuel per km = price per litre ÷ km per litre = 1.20 ÷ 3 = €0.40 per km. Careful: not the other way round."},{"q":"A 10-wheeled vehicle requires 10 tyres costing €340 each. The estimated life of each tyre is 50,000 km. What is the tyre cost in cents per kilometre?","options":["6.8 c/km","3.4 c/km","10.0 c/km","12.0 c/km"],"correct":0,"exp":"Tyres per km = (no. of tyres × price) ÷ km of life = (10 × 340) ÷ 50,000 = €0.068 = 6.8 cents per km."},{"q":"A coach incurs €60,000 for fuel, €1,000 for lubricants, €12,000 for maintenance, and €3,000 for tyres over 200,000 km. What is the total running cost in cents per kilometre?","options":["38.0 c/km","32.0 c/km","36.0 c/km","40.0 c/km"],"correct":0,"exp":"Add up all the variable costs: 60,000 + 1,000 + 12,000 + 3,000 = 76,000, and divide by the km: 76,000 ÷ 200,000 = €0.38 = 38 cents per km."},{"q":"How should drivers' overtime, night-out subsistence allowances, and toll charges generally be treated in quotation calculations?","options":["Added separately as extra expenses","Included in the cents-per-km running cost","Taken off the vehicle standing costs","Deducted from the company's profit margin"],"correct":0,"exp":"They are added separately as specific additional expenses."},{"q":"How is Return on Capital Employed (ROCE) calculated?","options":["(Net profit before tax x 100) / Capital employed","(Net profit after tax x 100) / Turnover","(Gross profit x 100) / Capital employed","(Total assets x 100) / Current liabilities"],"correct":0,"exp":"Net profit before tax × 100 ÷ Capital Employed."},{"q":"A transport business has capital employed of €500,000 and total vehicle costs of €800,000. If the required profit on capital employed is 20% (€100,000), what percentage profit mark-up must be added to vehicle costs?","options":["10.0%","12.5%","15.0%","20.0%"],"correct":1,"exp":"Mark-up = target profit × 100 ÷ total costs = 100,000 × 100 ÷ 800,000 = 12.5%. Divide by the costs, not by the capital."},{"q":"Why is a vehicle assumed to operate for 225 days per year (45 weeks at 5 days/week) rather than 365 days when calculating daily standing costs?","options":["Weekends, holidays, leave, testing and repairs","Irish law limits coaches to 225 days a year","To increase the profit margin artificially","Because fuel cannot be bought at weekends"],"correct":0,"exp":"Weekends, bank holidays, holidays, roadworthiness tests and maintenance downtime."},{"q":"An operator has total annual standing costs of €58,500. Based on a vehicle utilisation of 225 working days per year, what is the daily standing cost?","options":["€160.27 / day","€225.00 / day","€260.00 / day","€300.00 / day"],"correct":2,"exp":"Fixed cost per day = annual fixed cost ÷ working days = 58,500 ÷ 225 = €260 a day."},{"q":"An operator purchases a new vehicle for €52,000 with initial tyres valued at €4,000. If estimated resale value in 5 years is €6,000, what is the annual straight-line depreciation?","options":["€7,000","€8,000","€8,400","€10,400"],"correct":2,"exp":"Straight-line depreciation = (price − tyres − residual value) ÷ years = (52,000 − 4,000 − 6,000) ÷ 5 = €8,400 a year."},{"q":"Estimated annual kilometres for a vehicle are 45,000 km and vehicle utilisation is 225 days. What is the minimum daily distance needed to recover full standing costs?","options":["150 km per day","200 km per day","225 km per day","300 km per day"],"correct":1,"exp":"Minimum km per day = km per year ÷ working days = 45,000 ÷ 225 = 200 km a day."},{"q":"What is an 'Open Book' or 'Cost Plus' contract?","options":["Customer sees actual costs and pays them plus a fee","A contract where the operator works for free","A fixed cash price with no receipts given","A contract with variable fuel prices only"],"correct":0,"exp":"Visible actual costs + a separately agreed management fee."},{"q":"What is the primary purpose of drawing up a Rate Quotation Schedule in a transport office?","options":["Up-to-date cost rates for quoting prices","To send to the RSA for licence approval","To calculate drivers' PAYE deductions","To register the company for VAT purposes"],"correct":0,"exp":"Providing up-to-date rates to quote profitable prices."},{"q":"For a passenger coach operator selling individual tickets on an excursion, how should ticket prices be calculated if 53 seats are available but expected occupancy is 35 passengers?","options":["Divide costs plus profit by 35","Divide costs plus profit by 53","Charge double the standard train fare","Sell at cost price with no profit"],"correct":0,"exp":"Divide by 35 (expected occupancy), not by 53."},{"q":"What is the risk of using an arbitrary percentage surcharge on operating costs to cover administration overheads without detailed calculation?","options":["It may under-recover overheads and cause losses","It always guarantees the maximum profit","It automatically lowers the fleet's motor tax","It is prohibited by the NTA for bus operators"],"correct":0,"exp":"It may not cover the real overheads and may generate losses."}]},"15":{"title":"Topic 15 - Vehicle Taxation (buses and coaches)","questions":[{"q":"Unlike goods vehicles, how is motor tax calculated for passenger buses and coaches (PSVs) in Ireland?","options":["Number of passenger seats","Unladen weight of the vehicle","Engine power output in kW","Annual vehicle mileage"],"correct":0,"exp":"For PSVs it is calculated by the number of seats."},{"q":"Motor tax for commercial goods vehicles or passenger buses in Ireland may be paid for which of the following time periods?","options":["1 month, 2 months, or 12 months","3 months, 6 months, or 12 months","6 months or 12 months only","4 months or 8 months"],"correct":1,"exp":"Motor tax can be paid for 3, 6 or 12 months, which helps to spread the cost."},{"q":"What is the indicative annual motor tax for a bus with 21 to 40 passenger seats (2026 rates)?","options":["€175 – €202","€133","€349 – €403","€900"],"correct":0,"exp":"Bus tax by seats (2026): 9 to 20 seats, €133; 21 to 40, €175–€202; 41 to 60, €349–€403; 61 and over, €349–€403. The €900 figure is for lorries over 12 t.\n📍 Book M15 p.3"},{"q":"What is the indicative annual motor tax for a coach with 41 to 60 passenger seats (2026 rates)?","options":["€349 – €403","€133","€175 – €202","€500"],"correct":0,"exp":"Coaches with 41 to 60 seats are in the upper band: €349–€403 a year. The more seats, the more tax.\n📍 Book M15 p.3"},{"q":"What is the annual motor tax rate for a small bus/minibus with 9 to 20 seats?","options":["€133","€202","€349","€403"],"correct":0,"exp":"Buses with 9 to 20 seats pay the lowest rate (about €133 a year). The more seats, the more tax."},{"q":"When a new or imported vehicle is first brought into the State or used in Ireland, it must be registered with Revenue and:","options":["Pay Vehicle Registration Tax where due","Pay customs excise duty at the port","Get an EU Community Licence at once","Be inspected by the NTA within 24 hours"],"correct":0,"exp":"They must pay VRT (Vehicle Registration Tax) if it applies."},{"q":"Where is vehicle registration for imported commercial vehicles normally completed in Ireland?","options":["An authorised NCTS centre","The local Garda station","Department of Transport headquarters","All of the above"],"correct":0,"exp":"An imported vehicle is registered (and pays VRT) after an inspection at an approved NCTS centre, within the legal deadline."},{"q":"Who normally registers a brand-new bus or coach that has never been registered before?","options":["The dealer or manufacturer, via Revenue","The National Transport Authority","The Garda PSV Officer in the area","The operator's insurance company"],"correct":0,"exp":"A new bus is usually registered by the dealer or manufacturer through the Revenue system, which assigns the Irish registration number. If it is imported, a VRT inspection at an NCTS centre is needed.\n📍 Book M15 p.1"},{"q":"Which documents must an operator be able to produce to tax a passenger vehicle (bus or coach)?","options":["Registration cert, insurance and a valid CRW","A goods declaration and a weighbridge docket","The driver's CPC card and a tachograph printout","The NTA timetable and the fare table"],"correct":0,"exp":"To pay a bus's tax: registration certificate, valid commercial insurance and roadworthiness certificate (CRW) where applicable. The RF111A and the weighbridge ticket are for lorries.\n📍 Book M15 p.3"},{"q":"What document serves as a legal prerequisite confirming a commercial vehicle meets minimum mechanical safety standards before it can be taxed?","options":["Certificate of Roadworthiness after a CVRT","Tachograph calibration certificate","Category D licence of the main driver","The operator licence transport disc"],"correct":0,"exp":"The CRW (after the CVRT) is the prior legal requirement."},{"q":"Commercial goods vehicles and passenger buses over one year old must undergo Commercial Vehicle Roadworthiness Testing (CVRT):","options":["Every 12 months","Every 6 months","Every 2 years","Every 5 years"],"correct":0,"exp":"Buses and coaches over one year old must pass the CVRT (the roadworthiness test for commercial vehicles) every year."},{"q":"Where may applications for FIRST motor tax discs for Public Service Vehicles (PSVs) be made in Ireland?","options":["The local Motor Tax Office only","The local Garda station only","Any Post Office counter","The NTA online portal only"],"correct":0,"exp":"Only at the Local Motor Tax Office."},{"q":"If a vehicle will NOT be used or kept in a public place for a period, what action must the registered owner take?","options":["Simply stop paying motor tax and inform the council afterwards","Submit an Off-Road / Non-Use Declaration in advance to avoid arrears","Transfer ownership to a family member temporarily","Park the vehicle on a public road untaxed"],"correct":1,"exp":"Submitting a Declaration of Non-Use in advance."},{"q":"What happens if an operator fails to submit a Non-Use Declaration in advance for an untaxed vehicle?","options":["Motor tax arrears will accrue for the untaxed period","The vehicle registration is permanently cancelled","The operator licence is automatically revoked","The vehicle is declared scrap"],"correct":0,"exp":"If a vehicle is not going to be used, the declaration of non-use must be submitted BEFOREHAND; otherwise, the tax debt builds up."},{"q":"What restriction applies to a vehicle that is subject to an active Non-Use Declaration?","options":["It must not be used or kept in a public place","It may be driven on public roads at weekends","It can be driven within 5 km of the depot","It can carry goods but not passengers"],"correct":0,"exp":"It cannot be used or parked on a public road while the declaration is in force."},{"q":"Which of the following penalties may apply if an untaxed vehicle is used or kept in a public place?","options":["1 and 2 only","3 and 4 only","1, 2, and 3 only","1, 2, 3, and 4"],"correct":3,"exp":"All of them: fixed fines, prosecution, seizure and payment of arrears."},{"q":"What is the standard rate of Value Added Tax (VAT) applied to commercial transport services, vehicle purchases, fuel, and repairs in Ireland?","options":["9%","13.5%","21%","23%"],"correct":3,"exp":"The standard VAT rate in Ireland is 23%."},{"q":"Under what condition can a VAT-registered transport operator reclaim VAT paid on commercial vehicles, fuel, and maintenance?","options":["If the vehicle is used mainly for business","If a part-time driver drives the vehicle","If the company runs more than 10 vehicles","Never: that VAT can never be reclaimed"],"correct":0,"exp":"If the vehicle is used exclusively or mainly for the business."},{"q":"Which authority in Ireland issues Public Service Vehicle (PSV) licences for buses and coaches?","options":["Revenue Commissioners","Road Safety Authority (RSA)","National Transport Authority (NTA)","Health and Safety Authority (HSA)"],"correct":2,"exp":"PSV licences for buses and coaches are issued by the National Transport Authority (NTA)."},{"q":"Which core responsibility lies with the Transport Manager regarding vehicle taxation?","options":["Keep all vehicles taxed, insured and tested","Inspect tyres personally every morning","Conduct driving tests for new drivers","Issue VAT invoices to fuel suppliers"],"correct":0,"exp":"Ensuring the fleet always has valid tax, insurance and CRW."},{"q":"What is the minimum period for which a motor tax disc can be purchased for a passenger coach (PSV)?","options":["1 month","3 months","6 months","12 months"],"correct":1,"exp":"Tax can be paid for a minimum of 3 months (also for 6 or 12)."},{"q":"What documentation is required to re-tax a passenger bus online or at the motor tax office?","options":["Registration cert, insurance and current CRW","Driver's CPC card and tachograph charts","Company annual accounts and VAT returns","The Transport Manager's passport and PPS"],"correct":0,"exp":"Registration certificate, valid insurance and current CRW."},{"q":"If an operator's coach tax disc expires at the end of October and the vehicle will be stored until March, what is the proper procedure?","options":["Send a non-use declaration in advance","Pay the tax for November and December only","Leave it untaxed without telling anyone","Sell the vehicle to another company"],"correct":0,"exp":"Submitting a Declaration of Non-Use in advance."},{"q":"What is required if an operator imports a commercial vehicle from the UK or an EU Member State?","options":["VRT inspection at an NCTS centre and pay VRT","Drive it on foreign plates for 12 months","Pay no tax of any kind on the vehicle","Register it with An Garda Síochána only"],"correct":0,"exp":"VRT inspection at the NCTS, proof of purchase and payment of the VRT due."},{"q":"Can an untaxed commercial vehicle be legally parked on a public street outside the depot?","options":["No, even keeping it there is an offence","Yes, provided it is not driven at all","Yes, if it is only parked overnight","Yes, if it has valid motor insurance"],"correct":0,"exp":"It is an offence to use it OR keep it on a public road without tax."},{"q":"How often must a commercial vehicle over 1 year old obtain a Certificate of Roadworthiness (CRW)?","options":["Every 12 months","Every 6 months","Every 24 months","Only on change of owner"],"correct":0,"exp":"Commercial vehicles over one year old, buses included, take the CVRT every 12 months and receive a new Certificate of Roadworthiness (CRW)."},{"q":"Is a Certificate of Roadworthiness (CRW) required before a commercial vehicle can be issued a motor tax disc?","options":["Yes, a valid CRW is needed before taxing","No, a CRW is optional for motor tax","Only for vehicles carrying dangerous goods","Only for vehicles over 20 years old"],"correct":0,"exp":"Without a valid CRW, motor tax cannot be paid on a commercial vehicle: it is a prior legal requirement."},{"q":"Which entity collects Vehicle Registration Tax (VRT) in Ireland?","options":["Road Safety Authority (RSA)","Revenue Commissioners","Department of Transport","National Transport Authority (NTA)"],"correct":1,"exp":"VRT (registration tax) is collected by Revenue when the vehicle is first registered in Ireland."},{"q":"If a transport company operates a coach carrying passengers for hire and reward, what additional licence is required besides Motor Tax and Operator Licence?","options":["A Large Public Service Vehicle licence","A heavy machinery operating permit","A local council parking permit","A customs clearance certificate"],"correct":0,"exp":"To carry passengers for money, as well as the tax and the operator licence, each large vehicle needs its LPSV (PSV) licence."},{"q":"What is the annual motor tax rate for a large passenger coach with 53 seats?","options":["€349 to €403","€133 to €202","€202 to €349","€403 to €900"],"correct":0,"exp":"A 53-seat coach is in the 41 to 60 seat band: €349–€403 a year."},{"q":"What must a Transport Manager do to manage vehicle taxation effectively across a fleet?","options":["Keep a register of tax, insurance and CVRT dates","Pay motor tax from a personal bank account","Tax vehicles only after a Garda warning","Keep tax discs in a safe, not on display"],"correct":0,"exp":"Keeping a register of tax, insurance and CVRT expiry dates."},{"q":"What is the legal status of an operator licence if fleet vehicles are repeatedly operated untaxed and without valid CRWs?","options":["Good repute is at risk; suspension or revocation","Unaffected, as long as drivers hold CPCs","The NTA pays the tax arrears for the operator","The vehicles are moved to zero-tax status"],"correct":0,"exp":"It can compromise the operator's good repute, with a risk of suspension/revocation."}]},"16":{"title":"Topic 16 - Transport Ancillaries & Contracts of Carriage (PSV)","questions":[{"q":"When an organisation wishes to transport passengers, what are the two broad options available?","options":["Domestic transport and international transport","Owned transport and hired transport","Public scheduled services and private charter only","Registered transport and unregistered transport"],"correct":1,"exp":"Own-account (owned) or contracted (hired) transport."},{"q":"Owned transport acquired through a hire purchase agreement legally belongs to the operator:","options":["When the final payment is made","On the day the agreement is signed","When half of the instalments are paid","Only if it is registered as a goods vehicle"],"correct":0,"exp":"When the FINAL payment is made to the finance company."},{"q":"Which of the following is an advantage of owned transport?","options":["Full control over specification and disposal","Avoids tying up company capital in assets","Exemption from the operator licensing rules","Maintenance costs disappear completely"],"correct":0,"exp":"Full control over specification, construction and sale."},{"q":"What is the main financial disadvantage of owned transport?","options":["Capital is tied up, which may strain cash flow","The vehicles cannot carry company livery","Capital tax allowances cannot be claimed","Motor tax must be paid at double rates"],"correct":0,"exp":"Capital is tied up in fixed assets, causing cash flow problems."},{"q":"What is the simplest way for a business to obtain passenger transport without investing in vehicles or staff?","options":["Contracting out to a professional operator","Buying vehicles through hire purchase deals","Running its own-account fleet of minibuses","Buying second-hand minibuses at auction"],"correct":0,"exp":"The simplest option for a company that needs transport is to hire it from a professional operator: it does not have to buy vehicles or hire drivers."},{"q":"Under a straightforward finance lease agreement for transport vehicles, who retains ownership of the vehicles?","options":["The transport operator","The finance / leasing organisation","The National Transport Authority (NTA)","The driver"],"correct":1,"exp":"Under a finance lease, the vehicle still belongs to the leasing company; the operator only uses it in exchange for payments."},{"q":"What is 'Contract Hire' in commercial passenger transport?","options":["Leasing with management and maintenance included","A short daily rental with no maintenance","A contract between a driver and a passenger","An agreement to sub-contract route licences"],"correct":0,"exp":"Leasing with added services: management, maintenance, breakdown assistance."},{"q":"The legal terms and conditions under which a passenger transport operator agrees to carry passengers are known as:","options":["Articles of Association","Conditions of Carriage","Bill of Lading","Standard Operating Procedures"],"correct":1,"exp":"Conditions of Carriage: the legal conditions under which the operator agrees to carry passengers (luggage, liability, cancellations…)."},{"q":"For an operator's Conditions of Carriage to be legally enforceable against a passenger, they MUST be:","options":["Shown to customers before the contract is made","Registered with the Department of Transport","Printed on the back of each driver's CPC card","Approved by An Garda Síochána in advance"],"correct":0,"exp":"Brought to the customer's attention BEFORE the contract is formed."},{"q":"Can an operator include a clause in their Conditions of Carriage excluding liability for personal injury or death caused to passengers?","options":["No, liability for injury cannot be excluded","Yes, if it is printed in bold lettering","Yes, if the local authority agrees to it","Yes, but only on international journeys"],"correct":0,"exp":"No, it cannot exclude/limit that liability."},{"q":"How does liability for damaged passenger luggage differ from liability for passenger injury under Conditions of Carriage?","options":["The operator is free to set its luggage terms","Luggage liability is unlimited by EU law","Operators may not accept any luggage liability","The Road Traffic Act covers it up to €10,000"],"correct":0,"exp":"There are no legal requirements limiting how liability for luggage is specified."},{"q":"Which statute governs how passenger transport operators in Ireland must deal with lost property found on vehicles?","options":["Transport Act 1950","Road Traffic Act 1961","Consumer Protection Act 2007","Data Protection Act 2018"],"correct":1,"exp":"According to the book, the Road Traffic Act 1961 regulates how operators must deal with lost property found in their vehicles."},{"q":"What is a 'Sub-contractor' in passenger transport operations?","options":["An operator doing another operator's contract","An agent paid commission to find customers","A driver employed on a part-time basis","A garage that maintains the fleet's vehicles"],"correct":0,"exp":"An operator who agrees with another to carry out part/all of its contract."},{"q":"If Operator A sub-contracts a school transport contract to Operator B, and Operator B fails to run the service, who remains legally liable to the local authority client?","options":["Operator A, the original contractor","Operator B only, as it failed to run it","Neither: sub-contracting cancels liability","The driver assigned to the vehicle that day"],"correct":0,"exp":"A (the original contractor) remains fully responsible."},{"q":"Does the main operator have a legal duty to disclose to a sub-contractor the price being charged to the end customer?","options":["No, there is no need to reveal that price","Yes, the law requires full transparency","Only if the contract is over €50,000","Only if the NTA asks for it in writing"],"correct":0,"exp":"The main operator does not have to tell the subcontractor how much it charges the customer: they are two separate contracts."},{"q":"If a sub-contractor (Operator B) fails to complete a journey, can they sub-contract the work further to Operator C?","options":["Yes, unless the contract forbids it; B stays liable","No, sub-contracting again is always illegal","Yes, and all liability passes to Operator C","Only with written permission from the Minister"],"correct":0,"exp":"Yes, unless the contract prohibits it — but B remains responsible to A."},{"q":"Can an operator hold a Restricted PSV Licence and hire in a vehicle larger than 16 seats?","options":["Yes, if it is hired with a driver","Yes, with no restrictions at all","No, never in any circumstances","Only on public holidays and at weekends"],"correct":0,"exp":"With a restricted PSV licence, a vehicle with more than 16 seats can be used if it is hired WITH a driver, because that is subcontracting the service to another operator."},{"q":"What is the legal definition of an 'Agent' in transport contracts?","options":["Someone authorised to contract for a principal","A person employed to drive passenger vehicles","An official from the Road Safety Authority","A sub-contractor providing extra coaches"],"correct":0,"exp":"A person with authority to act on behalf of another (the principal)."},{"q":"How is an agent normally compensated for contract-making duties on behalf of a principal?","options":["Fixed monthly salary from the State","Payment of a commission","Direct shareholding in the principal's company","Exemption from road tolls"],"correct":1,"exp":"The agent normally charges a commission on the contracts it obtains for its principal."},{"q":"If an agent acts OUTSIDE the scope of their delegated authority when making a contract with a third party:","options":["The principal is not bound; the agent may be sued","The principal must honour the contract anyway","The contract is passed to the RSA to decide","The government pays the third party twice"],"correct":0,"exp":"The principal is NOT bound, and the agent can be sued."},{"q":"If an agent makes secret profits behind the back of the principal while carrying out activities on their behalf:","options":["The agent is entitled to keep the profits as bonus pay","The principal may sue the agent to recover the secret profits","The profit must be paid as corporate tax to Revenue","The contract becomes automatically void for the third party"],"correct":1,"exp":"The principal can sue them to recover those profits."},{"q":"Ace Transport contracts to carry sea anglers for Jack Ltd, but has no vehicles available and hires Ridgeway to do the work. Ridgeway is:","options":["A common carrier","An authorised agent","An alternative contractor","A sub-contractor"],"correct":3,"exp":"Ridgeway does the work that Ace had contracted with Jack Ltd, so it is a subcontractor. Ace remains answerable to Jack Ltd."},{"q":"Principals may reject a contract agreed by their authorised agents if:","options":["The principal does not wish to be bound by that particular contract","The agent acts outside his or her authority","The principal did not sign the contract before it was agreed","Whenever the principal wishes to"],"correct":1,"exp":"The principal is only bound by what the agent does within their authority; if the agent goes beyond it, the principal can reject the contract."},{"q":"Social Club B hires Operator A to carry passengers to a theatre. Operator A sub-contracts to Operator C, who fails to pick up the passengers. What is the legal position?","options":["B should sue A, who was the original contractor","B should sue C, who should have completed the work","B can sue both A and C since both were party to the movement","B will rely on A to sue C to recover damages"],"correct":0,"exp":"B must sue A (the original contractor)."},{"q":"A main contractor who sub-contracts work to a third party:","options":["Is not liable if the sub-contractor undertakes full responsibility","Remains fully liable to the customer for the completion of the contract","Is no longer liable to the customer","Is liable only if the sub-contract is in writing"],"correct":1,"exp":"They remain fully responsible to the customer."},{"q":"A local supporters' club hires 15 coaches from Bloggs Coaches. Bloggs sub-contracts 7 coaches to another operator, who fails to supply 4 coaches. The supporters' club has legal redress against:","options":["The football club","Bloggs Coaches","The sub-contractor directly","Both Bloggs Coaches and the sub-contractor"],"correct":1,"exp":"Against Bloggs Coaches (there is no direct contractual relationship with the subcontractor)."},{"q":"Operator Smith contracts with Jones for a journey at €300. Jones sub-contracts to Green at €220. Green discovers Jones was paid €300. Green:","options":["Has grounds to sue Jones for a secret profit","Has grounds to claim another €80 from Jones","Has grounds to claim another €80 from Smith","Has no grounds to claim against Jones"],"correct":3,"exp":"They have no right to claim (there is no obligation of price transparency)."},{"q":"If an operator's fleet is fully committed but additional work is accepted:","options":["Sub-contract it without revealing the price","Tell the sub-contractor the customer's price","Tell the customer the sub-contractor's price","Refuse: the job cannot be sub-contracted"],"correct":0,"exp":"They can subcontract without disclosing that price."},{"q":"An agent appointed to arrange carriage in the Midlands makes an unauthorized contract in Connaught for the operator. The operator:","options":["Need not honour it: the agent exceeded authority","Must honour the contract in every case","Need only honour it if it is in writing","Must honour it but cannot sub-contract it"],"correct":0,"exp":"They do not have to honour it, because the agent exceeded their authority."},{"q":"A passenger on a local bus service claims late running caused them to miss an appointment, incurring €100 costs. What is the operator's liability?","options":["Whatever its Conditions of Carriage say","Not liable under any circumstances","Liable for the full €100 in every case","Whatever a loss adjuster decides"],"correct":0,"exp":"It depends on what the Conditions of Carriage say (subject to legal limits)."},{"q":"Which TWO statements regarding the conduct of a driver on a one-person operated local bus service are correct? 1. The driver must ensure the correct route number and destination are displayed 2. At a changeover point, the driver may leave the vehicle unattended on a public road 3. It is not permissible for the driver to use force to remove an unruly passenger 4. If requested by an RSA examiner, the driver must provide the name and address of the operator","options":["1 and 4 only","2 and 3 only","1 and 3 only","2 and 4 only"],"correct":0,"exp":"1 and 4: clearly displaying the route/destination, and giving the operator's name/address if an examiner asks for it."},{"q":"A PSV driver arrives at a bus stop with a queue of passengers carrying pushchairs, but space allows for only some pushchairs to be stored safely. The driver should:","options":["Only those whose pushchairs fit the space","All of them, storing pushchairs at the rear","All of them, storing pushchairs at the front","None of the passengers with pushchairs"],"correct":0,"exp":"Only those that fit in the designated space."},{"q":"What is the status of PSV Conduct Regulations in Ireland?","options":["They bind drivers, conductors and passengers","They apply only to private hire tour operators","They apply only to international journeys","They are non-binding union guidelines"],"correct":0,"exp":"They apply to drivers, conductors, inspectors and passengers."},{"q":"Under PSV Conduct Regulations, can a bus driver use physical force to eject an unruly or disruptive passenger?","options":["No: ask them to leave or call the Gardaí","Yes, drivers have full immunity to use force","Yes, provided other passengers help","Only on double-deck buses at night"],"correct":0,"exp":"No, they must ask them to get off or call the Garda."},{"q":"Which of the following is a key advantage of relying on hired transport / carriers?","options":["No capital tied up and capacity is flexible","Full direct control over all the drivers","Depreciation can be claimed on the vehicles","The lowest market price is always guaranteed"],"correct":0,"exp":"No capital tied up, no licence of their own, and quick adjustment of capacity."},{"q":"What is the main risk of relying heavily on 'spot hire' carriers for passenger transport?","options":["Less control; dependence on the contractor","Registering every journey with Revenue","Automatic loss of the operator licence","Higher motor tax rates for the operator"],"correct":0,"exp":"Loss of operational control and dependence on the contractor."},{"q":"A clause in a contract of carriage stating that Irish courts have exclusive jurisdiction to settle disputes relates to:","options":["Severability","Law and Jurisdiction","Data Protection","Force Majeure"],"correct":1,"exp":"The clause that says which courts settle disputes (here, the Irish courts) is the 'Law and Jurisdiction' clause."},{"q":"What happens if a specific clause in an operator's Conditions of Carriage is held by a court to be illegal or unenforceable?","options":["That clause is removed; the rest stays valid","The whole contract becomes null and void","The operator must pay a €5,000 fine to the NTA","The passenger travels free for 12 months"],"correct":0,"exp":"That clause is removed (severability); the rest remains valid."},{"q":"What is the legal term for a party appointing an agent to negotiate contracts on their behalf?","options":["The Sub-contractor","The Principal","The Bailee","The Beneficiary"],"correct":1,"exp":"The person who appoints an agent to negotiate for them is the 'Principal'."},{"q":"When an operator displays a notice on bus tickets stating 'Passengers are carried subject to conditions', this serves to:","options":["Draws attention to the Conditions of Carriage","Exempts the operator from road safety laws","Replaces the need for commercial motor insurance","Cancels the passenger's right to a seat"],"correct":0,"exp":"It draws attention to the Conditions of Carriage, making them binding."}]},"17":{"title":"Topic 17 - Electronic Data","questions":[{"q":"What is 'software' in relation to electronic data systems?","options":["The physical computers and screens","The silicon microchips contained within computers","The programs and applications that run on computers","The printed output produced by printers"],"correct":2,"exp":"The programs and applications that run on the computer."},{"q":"What is 'hardware' in computer and fleet telematics terminology?","options":["The operational procedures written by the manager","The physical equipment, computers, sensors, and wiring","The mobile network subscription contract","The databases storing driver hours"],"correct":1,"exp":"The physical equipment: computers, sensors, wiring."},{"q":"Transport companies must comply with Data Protection legislation (GDPR / Data Protection Act 2018) if they store computer records containing:","options":["Personal data about living people","General financial budgets of the business","Registers of company shareholders","Non-personal vehicle specifications"],"correct":0,"exp":"Data protection (GDPR and the Data Protection Act 2018) applies when you keep personal data about living people: employees, drivers or passengers."},{"q":"What is the maximum time limit under GDPR for a data controller (employer) to respond to an employee's Subject Access Request (SAR)?","options":["30 days","7 days","14 days","90 days"],"correct":0,"exp":"A worker can request all their data (Subject Access Request) and the employer must reply within 1 month (30 days)."},{"q":"The term given to remote measurement of vehicle data using transmitters to send information back to a central base station is:","options":["Telephony","Telemetry","Psychometry","Numerology"],"correct":1,"exp":"Telemetry: measuring vehicle data remotely and sending it to the base by radio or over the mobile network."},{"q":"The technology fitted to vehicles that uses satellites to enable operators to track real-time vehicle location is known as:","options":["GPS / GNSS satellite tracking","Eurostat transport statistics","Real-time text messaging","Ordnance Survey Mapping"],"correct":0,"exp":"GPS (or GNSS) uses satellites to know in real time where each vehicle is."},{"q":"Modern passenger vehicles utilize an internal computer network connecting electronic control units, sensors, and actuators known as:","options":["Telemetry link","CANbus (Controller Area Network)","Electronic Data Interchange (EDI)","Internet Protocol (IP)"],"correct":1,"exp":"The CANbus is the vehicle's internal network that connects the electronic control units, sensors and actuators."},{"q":"Computer technologies that provide continuous streams of live operational data without delay are referred to as:","options":["Real-time systems","Batch processing systems","Barcode scanners","Offline archiving"],"correct":0,"exp":"Real-time systems: they give the data instantly, without delay; for example, where the bus is right now."},{"q":"Which TWO of the following technologies can be utilized by a bus operator to directly improve DRIVER security? 1. Closed Circuit Television (CCTV) on vehicles 2. Panic buttons / driver alert systems linked to telematics 3. Electronic arrival displays at bus stops 4. Off-bus ticketing applications","options":["1 and 2 only","3 and 4 only","2 and 3 only","1 and 4 only"],"correct":0,"exp":"On-vehicle CCTV + panic/alert buttons."},{"q":"In passenger transport, what is the primary operational advantage of Electronic Ticket Machines (ETMs) compared to manual ticket boxes?","options":["Fewer errors, correct fares and boarding data","They remove the need for motor insurance","They increase the vehicle's top speed","They pay the vehicle's motor tax online"],"correct":0,"exp":"They reduce fraud/error, calculate fares correctly and record boarding data."},{"q":"What is 'Telematics' in modern commercial vehicle fleet management?","options":["Telecoms and IT used to track remote vehicles","Paper logbooks used to record vehicle mileage","A legal duty to test emissions every month","The manual calculation of driver overtime"],"correct":0,"exp":"Integration of telecommunications and computing for remote vehicles."},{"q":"How does the CANbus system assist fleet managers in monitoring driver performance?","options":["Data on revving, gears, harsh braking, cruise","Photographs of the driver's driving licence","Automatic toll payments from the bank account","It replaces the need for tachograph cards"],"correct":0,"exp":"Data on engine revs, gear use, harsh braking and acceleration."},{"q":"What feature of Smart Tachograph Version 2 (GEN2 V2) relies on satellite communication (GNSS) technology?","options":["Recording border crossings and position","Remote engine shutdown by the Gardaí","Automatic washing of the windscreen","Wireless payment of passenger fares"],"correct":0,"exp":"Automatic recording of border crossings and position every 3h."},{"q":"How long must tachograph data and driver activity records generally be retained by operators under data protection and transport regulations?","options":["1 year; 2 years for working time rules","30 days, then it must be deleted","5 years, like the tax records","Indefinitely, with no time limit"],"correct":0,"exp":"At least 1 year (2 if they are used for Working Time)."},{"q":"What technology enables roadside enforcement officers (RSA/Gardai) to detect potential tachograph violations while the vehicle is in motion?","options":["DSRC short-range communication","Bluetooth Low Energy signals","FM radio broadcast signals","Roadside Wi-Fi hotspots"],"correct":0,"exp":"DSRC lets the Garda and the RSA read some smart tachograph data remotely while the vehicle is moving, to decide whom to stop."},{"q":"How can mobile app-based electronic driver walkaround check systems benefit a passenger transport operator?","options":["Real-time defect reports and a digital audit trail","They automatically fix defects on the road","They exempt the operator from annual CVRT tests","Drivers can skip checks when running late"],"correct":0,"exp":"They ensure the daily check is done, transmit defects and create an auditable digital trail."},{"q":"Under GDPR rules in Ireland, an employer holding driver performance and telematics data is legally categorized as a:","options":["Data Processor","Data Controller","Data Protection Officer","Data Subject"],"correct":1,"exp":"The employer who keeps drivers' data (telematics, performance) is the 'Data Controller' and is responsible for complying with the GDPR."},{"q":"What is the main purpose of CCTV cameras installed inside passenger buses pointing towards the driver's cab?","options":["Driver safety, deterring assaults, evidence","Watching driver expressions for marketing","Checking ticket prices charged to passengers","Checking that drivers follow uniform rules"],"correct":0,"exp":"Improving driver safety and providing evidence."},{"q":"Which system allows remote workshop technicians to diagnose vehicle engine fault codes without physically connecting diagnostic cables?","options":["Remote or over-the-air diagnostics","Manual pressure testing in the pit","Analogue telemetry by radio","Automated weighbridge readings"],"correct":0,"exp":"Remote diagnostics (OTA) let the workshop read engine fault codes remotely, without connecting cables."},{"q":"What is a key benefit of integrating fleet telematics with fuel management systems?","options":["Fuel use per vehicle and driver, spotting theft","Automatic reimbursement of VAT from Revenue","Diesel tax rates are reduced automatically","Engine oil changes are no longer needed"],"correct":0,"exp":"Tracking consumption by vehicle/driver to detect inefficiencies."},{"q":"What technology is used at passenger bus stops to display real-time arrival estimates to waiting passengers?","options":["Real-time passenger information","Paper timetables updated each year","Automated telephone answering machines","Manual radio announcements at stops"],"correct":0,"exp":"RTPI (Real-Time Passenger Information): the screens at stops calculate when the bus will arrive thanks to the vehicle's GPS."},{"q":"Smart cards used in passenger transport (such as TFI Leap Card) operate primarily on which technology principle?","options":["Contactless RFID / NFC smartcard chip reading","Magnetic tape swipe only","Paper barcode stamping","Manual visual inspection by the conductor"],"correct":0,"exp":"Cards such as the Leap Card are contactless (RFID/NFC): you just hold them near the reader."},{"q":"When deploying driver-facing inward cameras or AI-based fatigue monitoring tools, what extra GDPR requirement must operators satisfy?","options":["A Data Protection Impact Assessment","Written approval from the European Parliament","Exemption from all national privacy laws","Annual fees paid to the Data Protection Commission"],"correct":0,"exp":"A documented DPIA and clear privacy safeguards."},{"q":"What type of software system integrates order entry, route planning, fleet tracking, invoicing, and compliance management into a single platform?","options":["Transport Management System (TMS)","Electronic Point of Sale (EPOS)","Computer Aided Design (CAD)","Electronic Data Interchange (EDI)"],"correct":0,"exp":"A TMS (Transport Management System) brings together in one program orders, routes, fleet tracking, invoicing and regulatory compliance."},{"q":"What cybersecurity measure should transport operators implement to protect cloud-based TMS and telematics portals from unauthorized access?","options":["Multi-factor authentication","Passwords on printed sticky notes","Turning off all firewall protection","Open public Wi-Fi access to servers"],"correct":0,"exp":"To protect cloud portals: multi-factor authentication (password plus a code on the phone) and strong passwords."},{"q":"Automatic Number-Plate Recognition (ANPR) cameras used by enforcement authorities can instantly check:","options":["Tax, CRW status and the operator's risk rating","The driver's personal bank balance and loans","The exact number of passengers on board","The amount of fuel left in the vehicle's tank"],"correct":0,"exp":"CVRT/CRW, tax, and the operator's risk profile."},{"q":"What is the function of an Electronic Data Interchange (EDI) system in commercial transport operations?","options":["Computers exchanging orders and invoices","Printing tachograph charts automatically","Measuring tyre tread depth remotely","Regulating the engine coolant temperature"],"correct":0,"exp":"Exchange of standardised business documents without human intervention."},{"q":"In case study scenarios, if drivers fail to complete daily walkaround checks adequately leading to RSA warnings, what technology solution should the Transport Manager introduce?","options":["An app-based walkaround and defect system","Paper defect books kept in the office","GPS tracking units fitted to trailers","Automatic speed limiters on all vehicles"],"correct":0,"exp":"A daily check app with compulsory digital reporting."},{"q":"If a transport manager notices significant fuel economy differences between drivers operating identical vehicles, what system helps resolve the issue?","options":["Telematics data and targeted eco-drive training","Replacing all vehicle tyres every month","Increasing passenger fares to cover it","Fitting larger fuel tanks to the vehicles"],"correct":0,"exp":"Telematics linked to the CANbus and fuel management software."},{"q":"Under Data Protection law, an individual whose personal data is collected and stored by a transport company is known as the:","options":["Data Controller","Data Processor","Data Subject","Data Protection Officer"],"correct":2,"exp":"Data Subject = the person whose data is kept (driver, passenger). Data Controller = the company that keeps it and decides how it is used."},{"q":"How does real-time GPS tracking benefit traffic management offices during service disruptions or road closures?","options":["Re-route vehicles and update passengers' ETAs","It automatically clears traffic congestion","It cancels all passenger ticket refunds","It resets the drivers' tachograph hours"],"correct":0,"exp":"Rerouting vehicles dynamically and giving updated ETAs."},{"q":"What is a key advantage of cloud-based fleet software over traditional local desktop software?","options":["Secure access anywhere, with automatic backups","It works without any internet connection","It needs no passwords or security checks","It is completely exempt from GDPR rules"],"correct":0,"exp":"Secure access from anywhere, with automatic backup."},{"q":"What feature of modern ETMs allows operators to update fare structures across an entire fleet rapidly?","options":["Central remote programming of all machines","Replacing the ticket machine in every bus","Drivers re-keying fares at every stop","Posting paper fare charts to all drivers"],"correct":0,"exp":"Modern ticket machines (ETMs) are updated remotely, usually at night, without having to program them one by one."},{"q":"Video telematics systems combining forward-facing cameras and CANbus data are primarily used to:","options":["Evidence for claims and driver coaching","Streaming live entertainment to passengers","Measuring the vehicle's unladen weight","Issuing traffic fines to other road users"],"correct":0,"exp":"Evidence for insurance claims and safety coaching."},{"q":"What risk arises if an operator stores unencrypted employee personal data on unprotected laptop computers?","options":["Data breaches, GDPR fines and bad publicity","Lower fuel efficiency across the fleet","Loss of the vehicles' motor tax entitlement","Automatic failure of the tachographs"],"correct":0,"exp":"Serious risk of a data breach, GDPR fines and reputational damage."},{"q":"In the context of zero-emission electric buses, telematics systems monitor:","options":["State of charge, battery health and kWh/km","Engine oil viscosity and oil pressure","Exhaust gas recirculation and AdBlue levels","Diesel fuel density and injector timing"],"correct":0,"exp":"State of charge, battery health, consumption and regenerative braking."},{"q":"What is the legal obligation regarding data retention for employee HR and payroll records in Ireland?","options":["At least 6 years","At least 6 months","At least 30 days","At least 1 year"],"correct":0,"exp":"Personnel and payroll records are kept for at least 6 years, as required by Revenue and employment equality law."},{"q":"Why is 'Information for its own sake' considered a waste of time and money in fleet management?","options":["Data only adds value when it leads to decisions","Because technology is completely free","Data protection law bans storing any data","Transport managers may not view vehicle data"],"correct":0,"exp":"Data must be turned into useful management decisions."},{"q":"What type of card scanner technology is widely used in depot fuel dispensers to track fuel issued to specific vehicles and drivers?","options":["Smart card / RFID fob automated fuel issue systems","Manual paper signature pads only","Optical character readers for paper receipts","Coin-operated slot meters"],"correct":0,"exp":"Automatic systems with a smart card/RFID key fob."},{"q":"How does modern IT integration improve compliance with Operator Licensing requirements?","options":["Linking job cards, defect reports and tacho audits","Letting operators run vehicles without CRWs","Removing the need for a Transport Manager","Passing RSA premises audits automatically"],"correct":0,"exp":"Bringing together maintenance records, defect reports and tachograph audits in one dashboard."}]},"18":{"title":"Topic 18 - Weights and Dimensions of Passenger Vehicles","questions":[{"q":"What is the maximum permissible weight transmitted by a single axle (whether with single or twin tyres) on a passenger or commercial vehicle in Ireland?","options":["8.5 tonnes","10.0 tonnes","11.5 tonnes","12.0 tonnes"],"correct":1,"exp":"Maximum weight per single axle: 10 tonnes. If it is the only driving axle, with twin wheels and air suspension, 11.5 t."},{"q":"What is the maximum permissible weight for a sole driving axle fitted with twin tyres and air suspension (or an equivalent system)?","options":["10.0 tonnes","10.5 tonnes","11.5 tonnes","13.0 tonnes"],"correct":2,"exp":"Single driving axle with twin wheels and air suspension (or equivalent): 11.5 t. A normal axle: 10 t."},{"q":"What is the maximum gross vehicle weight (GVW) for a standard two-axle bus in Ireland?","options":["18.0 tonnes","19.0 tonnes","19.5 tonnes","25.0 tonnes"],"correct":2,"exp":"2-axle bus: maximum weight 19.5 t. 3-axle: 25 t (26 t in certain cases). 3-axle articulated: 28 t."},{"q":"What is the maximum gross vehicle weight (GVW) for a standard three-axle bus?","options":["25.0 tonnes","24.0 tonnes","28.0 tonnes","32.0 tonnes"],"correct":0,"exp":"25.0 tonnes (up to 26 under specific conditions)."},{"q":"What is the maximum gross vehicle weight for a three-axle articulated bus?","options":["25.0 tonnes","26.0 tonnes","28.0 tonnes","30.0 tonnes"],"correct":2,"exp":"3-axle articulated bus: 28 t. 2-axle rigid: 19.5 t; 3-axle rigid: 25 t."},{"q":"What is the maximum length permitted for a two-axle bus?","options":["12.0 meters","13.5 meters","15.0 meters","18.75 meters"],"correct":1,"exp":"Maximum lengths: 2-axle bus, 13.5 m; more than 2 axles, 15 m; articulated, 18.75 m."},{"q":"What is the maximum length permitted for a bus having more than two axles?","options":["13.5 meters","15.0 meters","16.5 meters","18.75 meters"],"correct":1,"exp":"Bus with more than 2 axles: 15 m. 2 axles: 13.5 m; articulated: 18.75 m."},{"q":"What is the maximum length permitted for an articulated bus?","options":["15.0 meters","16.5 meters","18.75 meters","20.0 meters"],"correct":2,"exp":"Articulated bus: 18.75 m long at most. 2-axle rigid: 13.5 m; more than 2 axles: 15 m."},{"q":"What is the maximum overall width permitted for passenger vehicles having a seating capacity for more than eight passengers (buses and coaches)?","options":["2.50 meters","2.55 meters","2.60 meters","2.75 meters"],"correct":1,"exp":"Maximum width of buses and coaches: 2.55 m."},{"q":"What is the maximum overall height permitted for commercial vehicles and buses in Ireland?","options":["4.00 meters","4.20 meters","4.65 meters","There is no maximum height limit specified"],"correct":2,"exp":"Maximum height in Ireland: 4.65 m. In many European countries the limit is lower (about 4 m), so it must be taken into account on trips abroad."}]},"19":{"title":"Topic 19 - Plating & Testing","questions":[{"q":"What is the primary objective of vehicle plating and statutory testing in Ireland?","options":["Safe vehicles kept within design weight limits","To set motor tax rates and fuel efficiency","To record ownership transfers with the Gardaí","To check drivers' CPC qualification cards"],"correct":0,"exp":"Ensuring vehicles are safe and operate within their design weight limits."},{"q":"Which authority holds primary legal responsibility for commercial vehicle roadworthiness and testing in Ireland?","options":["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"],"correct":1,"exp":"The RSA (Road Safety Authority) is responsible for commercial vehicles being roadworthy and for their roadworthiness test (CVRT)."},{"q":"What does 'Plating' certify on a commercial vehicle?","options":["The maximum permitted weights of the vehicle","The insurance category the vehicle falls into","The maximum passenger fare structure","The registration date of the imported chassis"],"correct":0,"exp":"Plating = certifying the vehicle's official maximum weights: the total weight (GVW), the weight of the combination with a trailer (GTW) and the weight on each axle."},{"q":"Where is the manufacturer's weight plate typically located on a passenger coach or commercial vehicle?","options":["Displayed on the rear bumper","Located in the cab, passenger doorway, or engine bay","Attached to the driver's seat","On the roof next to the air conditioning unit"],"correct":1,"exp":"In the cab, passenger door or engine compartment."},{"q":"What maximum weight figures are mandatory on a vehicle weight plate?","options":["GVW, GTW where relevant, and axle weights","Fuel tank, engine and oil capacities","Length, width and seating capacity only","Purchase price, depreciation and unladen weight"],"correct":0,"exp":"The weights plate must show the GVW, the GTW if it tows a trailer, and the maximum weight on each axle."},{"q":"What is the legal consequence of operating a vehicle in excess of its plated weight limits?","options":["Fines, penalty points, detention or prosecution","Only a verbal warning from the Gardaí","Passenger fares are suspended for a time","A compulsory free re-inspection of the vehicle"],"correct":0,"exp":"Fines, penalty points, detention, prohibition or prosecution."},{"q":"When is a re-plating certificate issued by the RSA required?","options":["After import or changes affecting weight or axles","Each time the vehicle passes its annual CVRT","When the vehicle's paint colour or logo is changed","Every 5 years when the licence is renewed"],"correct":0,"exp":"When importing, structurally modifying or changing the weight/axles."},{"q":"If a passenger coach has extra luggage racks and passenger comfort equipment fitted, increasing its unladen weight, what action must the Transport Manager take?","options":["Have it re-weighed and re-plated","Nothing, as long as the tyres are inflated","Remove 5 passenger seats automatically","Pay extra motor tax to the local council"],"correct":0,"exp":"If equipment is added that increases the unladen weight, the vehicle must be re-weighed and its plate updated (re-plating); otherwise, the insurance may not cover it."},{"q":"What regime governs statutory roadworthiness testing for commercial vehicles in Ireland?","options":["Commercial Vehicle Roadworthiness Test","National Car Test for all vehicles","RSA Maintenance Audit scheme","Garda Vehicle Inspection Scheme"],"correct":0,"exp":"The roadworthiness test for commercial vehicles in Ireland is the CVRT (Commercial Vehicle Roadworthiness Test)."},{"q":"Which passenger vehicles are subject to mandatory CVRT testing?","options":["Buses with more than 8 passenger seats","Private cars used for commuting to work","Taxis with fewer than 4 passenger seats","Motorcycles and light quadricycles"],"correct":0,"exp":"Hire and reward buses/coaches with more than 8 seats."},{"q":"How often must buses, coaches, and minibuses (more than 8 passenger seats) undergo CVRT testing?","options":["Every 12 months, from 1 year old","Every 6 months, from the first day","Every 2 years, from 4 years old","Every 3 years, from 3 years old"],"correct":0,"exp":"Buses, coaches and minibuses with more than 8 seats: CVRT every year, from when the vehicle is one year old."},{"q":"When is the FIRST statutory CVRT test required for a newly registered bus or commercial vehicle in Ireland?","options":["At 1 year old","At 6 months old","At 2 years old","Before first registration"],"correct":0,"exp":"The first CVRT is taken when the vehicle is 1 year old from its registration; after that, every year."},{"q":"What document is issued electronically and physically following a successful CVRT test?","options":["Certificate of Conformity","Certificate of Roadworthiness (CRW)","Operator Licence Disc","Vehicle Registration Certificate (VLC)"],"correct":1,"exp":"After passing the CVRT a Certificate of Roadworthiness (CRW) is issued, which the RSA records electronically."},{"q":"Is a valid Certificate of Roadworthiness (CRW) required to tax a commercial vehicle or bus in Ireland?","options":["Yes, a valid CRW is needed to tax it","No, a CRW is separate from motor tax","Only for vehicles over 10 years old","Only for vehicles operating internationally"],"correct":0,"exp":"Without a valid CRW you cannot pay motor tax or use the vehicle legally."},{"q":"What are the key areas examined during a standard CVRT test?","options":["Brakes, steering, tyres, lights and emissions","Ticket prices and driver uniform cleanliness","Audio systems and the upholstery colour","The company balance sheet and tax returns"],"correct":0,"exp":"Brakes, steering/suspension, tyres, lights, chassis, emissions, tachograph and speed limiter."},{"q":"Does passing an annual CVRT test exempt the operator from maintaining the vehicle between tests?","options":["No, the test is only a minimum standard","Yes, a pass guarantees compliance for a year","Yes, if daily mileage is under 100 km","Only if the vehicle is under warranty"],"correct":0,"exp":"It is only a periodic minimum standard; it does not replace ongoing maintenance."},{"q":"How are CVRT test failures categorised?","options":["Minor, major and dangerous defects","Low, medium and high defects","Retest, scrap vehicle or legal fine","Category A, Category B and Category C"],"correct":0,"exp":"CVRT defects: minor (pass with advice), major (fail and must be retested) and dangerous (the vehicle cannot be driven until it is repaired)."},{"q":"What must be done if a vehicle receives a 'Dangerous Defect' result during a CVRT or roadside inspection?","options":["It must not be driven until it is repaired","It may be driven back to base at low speed","The journey may go on if passengers agree","It must be fixed within 14 days, in service"],"correct":0,"exp":"It cannot be driven until the defect is repaired."},{"q":"Who has legal responsibility for ensuring fleet vehicles remain continuously roadworthy and compliant with plating and testing rules?","options":["The Transport Manager and the operator","The RSA test centre inspectors","The manufacturer of the vehicle","The fleet's insurance company"],"correct":0,"exp":"The transport manager and the operator are responsible for vehicles always being roadworthy, not just on test day."},{"q":"Under Regulation (EC) No 1071/2009, how can repeated failures in plating, testing, and vehicle maintenance affect a Transport Manager?","options":["Loss of good repute and disqualification","A small reduction in the TM's monthly salary","The TM must retake the driving test","It has no personal impact on the TM"],"correct":0,"exp":"It can compromise their good repute, with disqualification."},{"q":"Which enforcement bodies carry out roadside inspections of commercial passenger vehicles in Ireland?","options":["An Garda Síochána and RSA Vehicle Inspectors","Revenue Commissioners and Customs","Health and Safety Authority (HSA) only","Local County Council traffic wardens"],"correct":0,"exp":"Roadside inspections are carried out by the Garda and RSA inspectors."},{"q":"Who is legally authorised to stop a moving vehicle on a public road for a roadside compliance check?","options":["RSA Vehicle Inspectors acting alone","Members of An Garda Síochána","NTA Enforcement Officers","Workshop mechanics"],"correct":1,"exp":"Only the Garda can stop a moving vehicle on a public road. After that, RSA inspectors can check it."},{"q":"What sanctions can be imposed for operating a vehicle without a valid CRW or in a dangerously defective condition?","options":["Fines, penalty points, detention and prosecution","Free mechanical servicing at an RSA facility","A one-day suspension of the driver CPC","Cancellation of the motor insurance discount"],"correct":0,"exp":"Fixed fines, penalty points, detention/prohibition and prosecution."},{"q":"If two coaches in a fleet have Certificates of Roadworthiness expiring within the next month, what proactive step should the Transport Manager take?","options":["Book the CVRT tests now to avoid a lapse","Wait until the day of expiry to book","Take the vehicles off the road for 6 months","Ask the Gardaí for a 3-month extension"],"correct":0,"exp":"If two CRWs expire next month, the CVRT must be booked now: a vehicle with an expired CRW cannot work."},{"q":"If drivers report minor brake or lighting defects on daily walkaround check sheets, what action MUST be taken before placing the vehicle in service?","options":["Repair and record it before the vehicle is used","Keep it running until the next 6-week service","Tell drivers to drive slowly and brake gently","Ignore lighting defects during daylight hours"],"correct":0,"exp":"Take it out of service immediately and repair it before using it."},{"q":"Why are incomplete or missing maintenance records considered a serious compliance breach during an RSA audit?","options":["They fail to prove control of roadworthiness","Because maintenance records are optional","Because they double the annual motor tax","They cancel the Certificate of Incorporation"],"correct":0,"exp":"They must show continuous control; missing records breach the licence."},{"q":"For how long must an operator retain vehicle inspection, repair, and maintenance records at the operating base?","options":["15 months","6 months","12 months","10 years"],"correct":0,"exp":"Inspection, repair and maintenance records are kept at the base for at least 15 months (2 years according to some guidance)."},{"q":"In a Case Study exam scenario involving an imported coach whose weight plate does not match Irish registration documents, what is the required compliance response?","options":["Get official re-plating before using it","Remove the old plate and drive without one","Use it only on private hire work for now","Apply for a temporary goods vehicle licence"],"correct":0,"exp":"Checking the plating and obtaining official certification before operating."},{"q":"What is the legal status of an operator licence if an undertaking repeatedly operates vehicles with expired CRWs and unrectified defects?","options":["It may be suspended, curtailed or revoked","It is renewed automatically for 5 years","The Department takes over vehicle repairs","The company is limited to running minibuses"],"correct":0,"exp":"Using vehicles with an expired CRW or unrepaired defects can lead to loss of good repute, and with it the licence: suspension, curtailment or revocation."},{"q":"How does vehicle plating interact with vehicle taxation regulations?","options":["Its weights underpin tax class and weight limits","Plating determines the drivers' wages","Plating exempts vehicles from VAT reclaims","Plating is only used to work out toll fees"],"correct":0,"exp":"It certifies design weights, the basis of tax classification."},{"q":"Can an RSA inspector examine maintenance records during an unannounced premises audit at an operator's depot?","options":["Yes, they have statutory powers to inspect","No, audits need 30 days' written notice","Only if a judge accompanies the inspector","Only during national bank holiday weekends"],"correct":0,"exp":"Yes, they have statutory power to enter and inspect."},{"q":"What is a 'Prohibition Notice' issued during a roadside inspection?","options":["An order taking a defective vehicle off the road","A notice banning the driver's lunch break","A notice to change the vehicle's insurer","A permit allowing overweight transport"],"correct":0,"exp":"A legal order that takes a defective vehicle off the road."},{"q":"What document confirms that a vehicle modified with an additional axle meets structural safety standards?","options":["Manufacturer's declaration or RSA re-plating","Tachograph calibration certificate and seal","A category D1 driving licence for the driver","Commercial insurance policy endorsement"],"correct":0,"exp":"Manufacturer's declaration / Re-plating Certificate."},{"q":"Which Directive of the European Union sets standards for periodic roadworthiness testing of motor vehicles across Member States?","options":["EU Directive 2014/45/EU","EU Regulation 561/2006","GDPR Regulation 2016/679","EU Directive 2003/59/EC"],"correct":0,"exp":"Directive 2014/45/EU sets common rules for periodic roadworthiness testing in all EU countries."},{"q":"What is the primary purpose of displaying a valid CRW test disc on the vehicle windscreen?","options":["Visible proof of a valid CRW","To show that motor tax is paid","To identify the driver's name","Automatic gate access at bus stations"],"correct":0,"exp":"The CVRT disc on the windscreen shows the Garda and the RSA at a glance that the vehicle has a valid CRW."},{"q":"If a driver notices a crack in the windscreen in the driver's direct field of vision during a morning check, how is this defect classified?","options":["A major defect: fix it before driving","An advisory note for the next service","A cosmetic issue for the end of the lease","Ignored if it is under 50 mm long"],"correct":0,"exp":"A major/critical defect; it must be repaired before the vehicle is driven."},{"q":"What role does planned preventive maintenance play in relation to annual CVRT testing?","options":["CVRT is a snapshot; maintenance keeps it safe","Planned maintenance replaces the CVRT","CVRT is only needed if maintenance fails","They are completely unrelated legal ideas"],"correct":0,"exp":"The CVRT is only a periodic snapshot; maintenance ensures continuity."},{"q":"What information must be recorded on a vehicle maintenance inspection sheet?","options":["Odometer, checks, defects, repairs, signature","Fuel price per litre and the receipt number","The driver's home address and mobile number","The ticket revenue taken on the day"],"correct":0,"exp":"Registration number, odometer reading, items inspected, defects, repair, date and signature."},{"q":"Who is responsible for ensuring that hired or leased coaches used in a fleet have valid CRWs and correct plating?","options":["The operator using it under its licence","Only the manufacturer of the vehicle","The RSA inspector who approved the lease","The passengers who booked the trip"],"correct":0,"exp":"If a coach is hired or leased, whoever uses it under their licence is responsible for it having the correct CRW and weights plate."},{"q":"What is the conclusion required in a CILT Case Study answer regarding plating and testing compliance?","options":["Stress that continuous compliance is vital","Say testing is too expensive for small firms","Recommend sub-contracting all the vehicles","Suggest delaying maintenance until profits are known"],"correct":0,"exp":"Continuous compliance is vital for safety and for the licence."}]},"20":{"title":"Topic 20 - Fleet Inspection and Enforcement","questions":[{"q":"Which statutory body in Ireland administers the commercial vehicle fleet inspection and enforcement system under the Road Safety Authority (Commercial Vehicle Roadworthiness) Act 2012?","options":["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"],"correct":1,"exp":"The RSA (Road Safety Authority) runs the CVRT, roadside inspections and inspections at company premises."},{"q":"The Commercial Vehicle Roadworthiness Test (CVRT) regime applies to which of the following EU vehicle categories?","options":["N1-N3, M2, M3 and trailers over 750 kg","Passenger cars M1 and light trailers O1","Agricultural tractors and their trailers","Motorcycles, mopeds and quadricycles only"],"correct":0,"exp":"The CVRT covers goods vehicles (N1, N2, N3), passenger vehicles (M2 and M3, i.e. buses) and commercial trailers over 750 kg (O2 to O4). Cars (M1) take the NCT."},{"q":"Which passenger vehicles are legally subject to mandatory CVRT testing in Ireland?","options":["Buses with more than 8 passenger seats","All passenger cars with 4 seats","Private vehicles used only for family errands","Electric scooters and bicycles"],"correct":0,"exp":"All buses and coaches with more than 8 passenger seats used in commercial transport take the CVRT."},{"q":"When is a commercial vehicle or bus required to undergo its FIRST mandatory CVRT test?","options":["At 1 year old","At 6 months old","At 3 years old","On its first commercial journey"],"correct":0,"exp":"First CVRT: when the vehicle is 1 year old from its first registration."},{"q":"Following its first CVRT test at 1 year of age, how often must a commercial bus or coach be re-tested?","options":["Every 12 months","Every 6 months","Every 2 years","Every 5 years"],"correct":0,"exp":"After the first CVRT (at one year), the bus repeats the test every 12 months."},{"q":"What document is issued to certify that a vehicle has successfully passed its CVRT inspection?","options":["Operator Transport Disc","Certificate of Roadworthiness (CRW)","Certificate of Conformity (CoC)","Vehicle Registration Certificate (VRC)"],"correct":1,"exp":"After passing the CVRT you receive the Certificate of Roadworthiness (CRW)."},{"q":"What physical item must be displayed on a commercial vehicle or bus windscreen as visible proof of roadworthiness compliance?","options":["A CVRT test disc","A driver CPC card","A tachograph calibration sticker on the bumper","A company business card"],"correct":0,"exp":"The CVRT disc goes on the windscreen, the visible proof that the vehicle has a valid CRW."},{"q":"Is the annual CVRT test considered a full engineering or disassembly examination of the vehicle?","options":["No, it checks visible safety items at the time","Yes, it involves stripping engine and gearbox","Yes, it guarantees no hidden defects later","No, it only checks paintwork and seat fabric"],"correct":0,"exp":"A roadworthiness test focused on accessible and visible components."},{"q":"Which of the following items are tested during a statutory CVRT inspection?","options":["Braking systems, steering, and suspension","Tyres, wheels, wheel security, lights, and reflectors","Chassis condition, mirrors, glazing, visibility, tachograph functionality, and safety equipment","All of the above"],"correct":3,"exp":"The CVRT checks brakes, steering, suspension, tyres, lights, chassis, emissions, tachograph and speed limiter: everything on the list."},{"q":"How are CVRT test failure outcomes officially categorised under Irish and EU roadworthiness regulations?","options":["Minor, major and dangerous defects","Level 1, Level 2 and Level 3","Soft fail, medium fail and hard fail","Category A, Category B and Category C"],"correct":0,"exp":"Defects: minor (pass with advice), major (fail and must be retested) and dangerous (the vehicle is prohibited from being driven until repaired)."},{"q":"What is the legal consequence if a vehicle is identified with a 'Dangerous Defect' during an RSA inspection or CVRT test?","options":["A prohibition: it must not be driven until fixed","An advisory note allowing 14 more days' driving","A verbal warning from the tester to the driver","The operator must pay double motor tax"],"correct":0,"exp":"A Prohibition Notice; it cannot be driven until repaired."},{"q":"Does passing an annual CVRT test relieve an operator of their legal duty to maintain fleet vehicles continuously?","options":["No, it is only a minimum periodic standard","Yes, the CRW gives full immunity for 12 months","Yes, if it covers under 50,000 km a year","Only if an outside garage certifies it"],"correct":0,"exp":"Passing the CVRT is not enough: it is a minimum, once a year. The operator must have a preventive maintenance system throughout the year."},{"q":"What key daily procedure must drivers perform before operating a commercial vehicle on public roads?","options":["A walkaround check and defect reporting","A complete engine oil replacement","A high-pressure wash of the bodywork","A short speed test on the motorway"],"correct":0,"exp":"Daily check and immediate reporting of defects."},{"q":"What typical items should be checked during a driver's pre-use daily walkaround inspection?","options":["Tyres and wheel security, lights, indicators, and reflectors","Fluid leaks, windscreen, and mirror condition","Load security or bodywork condition, wipers, horn, and safety equipment","All of the above"],"correct":3,"exp":"The driver's daily check covers everything: wheels, lights, indicators, leaks, windscreen, mirrors, bodywork, wipers, horn and safety equipment."},{"q":"What system is strongly recommended by the RSA Guide to Maintaining Roadworthiness for daily walkaround reporting?","options":["A daily report, even when nothing is wrong","Verbal reports only when breakdowns occur","A summary email at the end of each month","Leave minor defects until the annual CVRT"],"correct":0,"exp":"'Nil defect' system: the driver hands in their check sheet every day even if they find no defects, writing 'NIL'. That way there is proof they did it."},{"q":"Roadside compliance inspections in Ireland are carried out jointly by:","options":["RSA inspectors and An Garda Síochána","Revenue customs officers and teachers","NTA inspectors and parking wardens","Insurance adjusters and bank auditors"],"correct":0,"exp":"Roadside inspections are carried out jointly by the RSA and the Garda."},{"q":"Who has the statutory legal authority to STOP a moving commercial vehicle on an Irish public road for a roadside inspection?","options":["RSA Vehicle Inspectors acting alone","Members of An Garda Síochána","Workshop mechanics","Any member of the public"],"correct":1,"exp":"Only the Garda has the authority to stop a moving vehicle. RSA inspectors check it afterwards."},{"q":"What items may be checked by officers during an RSA roadside inspection?","options":["Vehicle roadworthiness and valid CRW display","Tachograph records and drivers' hours compliance","Operator licensing documentation and Driver CPC qualification cards","All of the above"],"correct":3,"exp":"A roadside inspection can check the condition of the vehicle, the driver's records, the tachograph, the CRW, etc.: everything on the list."},{"q":"In addition to roadside checks, where else does the RSA conduct compliance inspections?","options":["At operator premises","At driving test centres only","At county council offices","At fuel filling stations only"],"correct":0,"exp":"The RSA also inspects the operator's premises (depots and offices) to check the maintenance system and records."},{"q":"What documents and records may RSA officers examine during a depot/premises inspection?","options":["Maintenance systems and planned inspection schedules","Driver daily walkaround check sheets and defect reporting logs","Inspection and repair records (job cards) and vehicle history files","All of the above"],"correct":3,"exp":"In a company inspection they can check the maintenance schedule, the daily check sheets, defect reports, job cards and each vehicle's history."},{"q":"What action can RSA inspectors take if a vehicle present at an operator's premises during an audit is found to be dangerously defective?","options":["Issue a Prohibition Notice for the vehicle","Give a verbal caution and leave the depot","Confiscate the driver's personal smartphone","Force the operator to sell the depot"],"correct":0,"exp":"If they find a vehicle with dangerous defects, they issue a Prohibition Notice: it cannot be driven until it is repaired."},{"q":"Under Irish fleet inspection law, what maximum fine can be imposed in court per offence for serious roadworthiness non-compliance?","options":["€5,000","€500","€1,000","€100,000"],"correct":0,"exp":"For serious maintenance breaches, the court can impose fines of up to €5,000 for each offence."},{"q":"In addition to fines, what penalties may be imposed by courts for severe or repeated vehicle maintenance breaches?","options":["Prosecution and possible imprisonment (up to 6 months)","Penalty points on driver/operator records","Vehicle detention or prohibition","All of the above"],"correct":3,"exp":"Serious or repeated offences can have several consequences at once, and all the options on the list are possible."},{"q":"If an operator hires a maintenance contractor to service fleet vehicles, who retains ultimate legal responsibility for the roadworthiness of those vehicles on public roads?","options":["The maintenance contractor / garage exclusively","The transport operator and the driver","The RSA inspector who tested the vehicle","The vehicle manufacturer"],"correct":1,"exp":"Even if an outside workshop does the maintenance, the person responsible for the vehicle being roadworthy on the road is still the operator (and the driver)."},{"q":"What system rates transport operators based on risk and compliance findings (such as CVRT results, roadside checks, and premises audits)?","options":["Commercial Vehicle Risk Rating","Operator Financial Standing Index","Driver CPC Points System","All of the above"],"correct":0,"exp":"The CVRR (Commercial Vehicle Risk Rating) scores each operator according to its CVRTs, roadside inspections and premises inspections."},{"q":"What happens to an operator who accumulates serious defects, failed CVRTs, or Prohibition Notices on their CVRR risk profile?","options":["Rating goes amber or red: more targeted checks","They receive automatic motor tax rebates","Their vehicles' speed limiters are removed","They become exempt from roadside inspections"],"correct":0,"exp":"With serious defects, failed CVRTs or prohibitions, the CVRR moves to amber or red, and the RSA inspects that company more."},{"q":"How does poor maintenance compliance impact an operator's standing before the Licensing Authority (Traffic Area Office / Dept of Transport)?","options":["Recorded against the licence; may block renewal","It has no impact on operator licensing","It increases drivers' holiday entitlement","It automatically grants extra vehicles"],"correct":0,"exp":"Prohibitions and serious defects are recorded against the operator's licence and can be used as grounds for objecting to its renewal or extension."},{"q":"Under Regulation (EC) No 1071/2009, what disciplinary action can the Licensing Authority take against an operator with unacceptable maintenance standards?","options":["Suspend the Operator Licence","Curtail (reduce) the number of authorized vehicles on the licence","Revoke the Operator Licence entirely","All of the above"],"correct":3,"exp":"Under Regulation 1071/2009, the authority can warn, suspend, curtail or revoke the licence: all the options are possible."},{"q":"What happens to a Transport Manager whose fleet repeatedly operates unroadworthy vehicles, lacks maintenance records, or ignores prohibition notices?","options":["Loss of good repute and disqualification","Automatic demotion to bus conductor","Paying motor tax out of personal funds","No action can be taken against the TM"],"correct":0,"exp":"They can lose their Good Repute and be disqualified."},{"q":"In Case Study 1, a vehicle on a Carlow to Limerick journey is stopped by the RSA and Gardaí, and an officer issues a prohibition for a defective suspension unit. Who is authorized to stop the vehicle?","options":["Gardaí, or RSA inspectors with the Gardaí","RSA inspectors acting completely alone","Local authority traffic wardens","National Transport Authority ticket checkers"],"correct":0,"exp":"An Garda Síochána (or RSA inspectors together with them)."},{"q":"In Case Study 1, once the prohibited defective vehicle is recovered back to base, what THREE steps must be taken before returning it to active service?","options":["Repair, re-inspect or clear, update records","Wash it, change the driver, carry on","Pay motor tax, replace tyres, new disc","Claim insurance, store it, sell the chassis"],"correct":0,"exp":"Repair, re-inspect and update the records."},{"q":"In Case Study 1, who under current regulations may be liable for prosecution due to the unroadworthiness of the stopped vehicle?","options":["The driver, the TM and the operator","Only the customer who booked the service","The RSA inspector who did the check","The driver of the recovery truck"],"correct":0,"exp":"The driver, the Transport Manager and the operator."},{"q":"In Case Study 2, a bus driver finds failed indicators and a truck driver finds tyre damage during morning walkaround checks. Can these vehicles be driven on public roads before repairs?","options":["No, they must be repaired before going out","Yes, if they are driven under 30 km/h","Yes, if the journey takes under 1 hour","Yes, if the office receptionist approves"],"correct":0,"exp":"An indicator that does not work or a damaged tyre are safety defects: they must be reported and repaired BEFORE the vehicle goes on the road."},{"q":"How long must an operator retain all vehicle safety inspection sheets, defect reports, and repair records at their operating base?","options":["15 months","6 months","12 months","5 years"],"correct":0,"exp":"Inspection, defect and repair records are kept for at least 15 months (2 years if they are used for working time)."},{"q":"What annual document must heavy commercial vehicle fleet operators submit to the RSA confirming compliance with maintenance and safety requirements?","options":["Annual Operator Self-Declaration","Annual Profit and Loss Account","Company Articles of Association","Driver CPC Renewal Form"],"correct":0,"exp":"Every year the operator gives the RSA a self-declaration (Annual Operator Self-Declaration) confirming that it complies with maintenance and safety requirements."},{"q":"If a driver identifies a minor defect during a daily check that does not render the vehicle unroadworthy (e.g., a minor interior cosmetic trim issue), what is the procedure?","options":["Record it; fix it at the next service","Stop the bus on the motorway immediately","Refuse to drive that bus for 30 days","Call the Gardaí to inspect the vehicle"],"correct":0,"exp":"Record it and schedule its repair, while continuing to operate."},{"q":"If an operator fails to maintain written records of daily driver walkaround checks and defect repairs, what is the legal position during an RSA audit?","options":["It cannot prove reasonable care: a serious breach","The RSA assumes checks were done verbally","The RSA extends the licence for 5 years","The operator gets immunity from prosecution"],"correct":0,"exp":"They fail to prove 'reasonable care', a serious breach."},{"q":"Why is 'time-based' scheduling (e.g., every 4, 6, or 8 weeks) preferred over 'mileage-only' scheduling for preventive maintenance inspections?","options":["Low-mileage vehicles still age and need checks","It is cheaper for the garage contractors","Digital tachographs cannot measure mileage","Irish law bans measuring distance in km"],"correct":0,"exp":"It ensures low-mileage vehicles are inspected too."},{"q":"What is the maximum recommended inspection interval for heavy commercial vehicles or buses over 12 years old, regardless of mileage?","options":["Every 12 weeks","Every 10 weeks","Every 6 weeks","Every 2 weeks"],"correct":2,"exp":"Vehicles over 12 years old: safety inspection at most every 6 weeks, whatever mileage they do."},{"q":"What is the ultimate goal of fleet inspection and enforcement regulations in Ireland?","options":["Road safety and preventing mechanical crashes","Maximising the revenue from court fines","Reducing the number of licensed operators","Forcing all operators to buy electric vehicles"],"correct":0,"exp":"Protecting road safety and ensuring fair competition."}]},"21":{"title":"Topic 21 - Driver Licensing & Driver CPC","questions":[{"q":"Which EU Directive governs the harmonised driving licence categories and mutual recognition across EU/EEA Member States?","options":["Directive 2003/59/EC","Directive 2006/126/EC","Directive 561/2006/EC","Directive 2014/45/EU"],"correct":1,"exp":"Directive 2006/126/EC harmonises licence categories in the EU/EEA and makes them recognised in all countries."},{"q":"Under Irish law, driving licences for professional categories (Group 2: Category C, D, etc.) are valid for a maximum period of:","options":["1 year","5 years","10 years","15 years"],"correct":1,"exp":"Professional licences (group 2: categories C, D…) last a maximum of 5 years."},{"q":"How often must the photograph on an Irish photocard driving licence be updated?","options":["Every 3 years","Every 5 years","Every 10 years","Never, once issued it is permanent"],"correct":2,"exp":"The photo on the plastic licence is renewed every 10 years."},{"q":"What driving licence category entitlement is required to drive a passenger carrying vehicle (PCV) with up to 8 passenger seats (excluding the driver)?","options":["Category B","Category D1","Category D","Category C1"],"correct":0,"exp":"Up to 8 passenger seats (not counting the driver), category B is enough."},{"q":"What driving licence category entitlement is required to drive a minibus carrying between 9 and 16 passenger seats (excluding the driver)?","options":["Category B","Category D1","Category D","Category C"],"correct":1,"exp":"9 to 16 passenger seats: category D1. More than 16: category D."},{"q":"What is the basic driving licence category required to drive large passenger carrying vehicles with 17 or more passenger seats (including articulated buses)?","options":["Category B","Category D1","Category D","Category C"],"correct":2,"exp":"More than 16 passenger seats, articulated buses included: category D."},{"q":"If a Category D bus driver wishes to tow a trailer with a Maximum Authorised Mass (MAM) NOT exceeding 750 kg, what additional entitlement is required?","options":["Nothing extra: up to 750 kg is allowed on D","Category D+E entitlement must be obtained","A Category B+E entitlement as well","A special towing permit from the NTA"],"correct":0,"exp":"No additional entitlement is needed for up to 750 kg."},{"q":"What entitlement must be added to a Category D licence to tow a trailer with a MAM EXCEEDING 750 kg?","options":["Category D1","Category D+E","Category C+E","Category B+E"],"correct":1,"exp":"To tow more than 750 kg with a category D bus you need D+E. Up to 750 kg, D is enough."},{"q":"Under EU rules, what is the standard minimum age for obtaining a full Category D driving entitlement without a Driver CPC?","options":["18 years","21 years","24 years","26 years"],"correct":2,"exp":"Minimum age for category D without the Driver CPC: 24. With the full CPC it drops to 21, or to 18 on regular services up to 50 km."},{"q":"What is the reduced minimum age for a driver holding a full Driver CPC to drive a Category D bus on regular passenger services where the route does NOT exceed 50 km?","options":["18 years","21 years","23 years","24 years"],"correct":0,"exp":"With the full Driver CPC you can drive a category D bus from age 18 on regular services up to 50 km."},{"q":"Under EU rules, a driver aged 21 holding a Category D entitlement and Driver CPC card can drive passenger vehicles on:","options":["All domestic and international routes","Regular routes of up to 50 km only","Regular services over 500 km only","Night tours and school runs only"],"correct":0,"exp":"All routes, without restriction, at 21 with the CPC."},{"q":"A driver passed a Category B (car) driving test prior to 1st January 1997 in Ireland. What preserved entitlement did they automatically receive?","options":["D1 for 9-16 seats, code 101: not for hire","Full Category D for unlimited passenger work","Unlimited Category D+E entitlement","No preserved entitlement at all"],"correct":0,"exp":"D1 limited with Code 101 (not for hire or reward)."},{"q":"A driver who passed Category B after 1st January 1997 wants to drive a 9-16 seat minibus for a non-commercial voluntary body on a Category B licence. What conditions must be met?","options":["Over 21, 2 years on B, max 3,500 kg, no hire","A driver of any age can drive any minibus","The minibus may weigh up to 7.5 tonnes","The driver must hold a Category D licence"],"correct":0,"exp":"Over 21, Cat B for 2+ years, ≤3,500kg (or 4,250kg with a wheelchair), no trailer and no payment."},{"q":"Holders of a full Category D driving licence in Ireland are legally permitted to drive a recovery vehicle, provided its unladen weight does not exceed:","options":["3.5 tonnes","7.5 tonnes","10.2 tonnes","18.0 tonnes"],"correct":2,"exp":"It is a licence exception: with category D you can drive a recovery vehicle (tow truck) of up to 10.2 t unladen weight."},{"q":"What does Driving Licence Information Code 101 signify?","options":["Not for hire or reward","Automatic transmission only","Subject to a certificate of competence","All of the above"],"correct":0,"exp":"Code 101 on the licence: 'Not for hire or reward', i.e. non-commercial use only."},{"q":"What does Driving Licence Information Code 78 signify?","options":["Automatic transmission vehicles only","Limited to a maximum of 16 passenger seats","Not to be used for hire or reward","Must wear corrective glasses or lenses"],"correct":0,"exp":"Code 78: they can only drive vehicles with automatic transmission."},{"q":"What medical report form must be completed by a registered medical practitioner when applying for a Group 2 (Category D1/D/D+E) licence?","options":["Form D501","Form D201","Form RF111A","All of the above"],"correct":0,"exp":"For a group 2 licence (D1, D, D+E) you must submit the D501 medical report, signed by a registered doctor."},{"q":"What mandatory procedure must applicants for Category D / D1 licences fulfill regarding previous driving/traffic offences?","options":["Declare relevant convictions on the form","Submit a tax clearance certificate from Revenue","No disclosure of driving offences needed","Provide 3 years of bank statements"],"correct":0,"exp":"On the application for a D or D1 licence you must declare relevant convictions: for road traffic, drivers' hours or vehicle condition."},{"q":"Which body in Ireland oversees driver testing, licensing, and Driver CPC requirements?","options":["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Social Protection","Health and Safety Authority (HSA)"],"correct":1,"exp":"The RSA is responsible for driving tests, licences and the Driver CPC."},{"q":"What are the four testing modules required for a new candidate to obtain Initial Driver CPC qualification for buses/coaches?","options":["Theory, case studies, driving test, walk-around","Essay, oral exam, fitness test, first aid","Mechanics, audit, road test, route planning","City, motorway, night and parking tests"],"correct":0,"exp":"Theory, Case studies, Practical driving test, Practical vehicle safety test."},{"q":"What is the pass mark for the computer-based Passenger Vehicle Driver Theory Test (100 multiple choice questions)?","options":["70 out of 100","80 out of 100","85 out of 100","95 out of 100"],"correct":2,"exp":"The passenger theory test has 100 questions and the pass mark is 85."},{"q":"Once passed, how long is the Driver Theory Test qualification valid for the candidate to complete the practical test?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"A passed theory test is valid for 2 years: the practical test must be taken within that time."},{"q":"What is the pass mark for the Driver CPC Case Studies test (Part 2), which contains 7 scenarios with 50 total marks?","options":["30 out of 50","35 out of 50","40 out of 50","45 out of 50"],"correct":2,"exp":"The Driver CPC case studies (7 cases, 50 marks) are passed with 40 out of 50."},{"q":"What is the minimum vehicle specification required for taking a Category D practical driving test?","options":["At least 10 m long with 24 or more seats","Any 16-seat minibus of any length","A double-deck bus over 12 metres","An articulated bus with 50 seats"],"correct":0,"exp":"For the category D practical test you need a vehicle at least 10 m long with 24 seats, not counting the driver."},{"q":"What is the minimum vehicle specification for taking a Category D1 practical driving test?","options":["MAM of at least 4,000 kg","MAM of at least 2,500 kg","Any 8-seat passenger car","At least 12 metres long"],"correct":0,"exp":"For the D1 practical test, the vehicle must have a GVW of at least 4,000 kg."},{"q":"What minimum trailer specification is required when conducting a Category D+E practical driving test?","options":["Box trailer: 1,250 kg MAM, 800 kg real weight","An empty trailer with a MAM of only 500 kg","Any single-axle trailer of more than 250 kg","A semi-trailer fitted with air suspension"],"correct":0,"exp":"A loaded trailer, GVW ≥1,250kg, actual weight ≥800kg."},{"q":"What core areas are examined during the Driver CPC Practical Walk-Around Test (Module 4)?","options":["Walkaround checks, passenger safety, emergencies","Engine rebuild procedures and gearbox repair","Calculating passenger ticket tariffs","Driving at 100 km/h on the motorway network"],"correct":0,"exp":"Daily check, safe loading, passenger safety and emergencies."},{"q":"How long is a Driver Qualification Card (DQC / Driver CPC Card) valid once issued by the RSA?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The Driver CPC card (DQC) lasts 5 years; to renew it, the 35 hours of periodic training must have been completed."},{"q":"How must a professional bus/coach driver maintain Periodic Driver CPC qualification over each 5-year cycle?","options":["35 hours: one 7-hour module a year","A full written exam at the end of each 5 years","Driving 100,000 km without an accident","A 1-day refresher course at the NDLS"],"correct":0,"exp":"Periodic CPC: 35 hours of training every 5 years, in 7-hour modules (one a year is recommended) at RSA-approved centres."},{"q":"Is a professional bus driver permitted to complete all 35 hours of Driver CPC training in the final week of the 5-year cycle?","options":["Yes, but one day a year is recommended","No, 35 hours in one year is illegal","Yes, provided it is all done online","No, it must be spread over 10 years"],"correct":0,"exp":"The 35 hours can be done at the end of the 5-year period, but the RSA recommends 1 day (7 hours) a year to stay up to date."},{"q":"If a driver holds both Category C (Truck) and Category D (Bus) entitlements, how many hours of Periodic Driver CPC training must they complete every 5 years?","options":["35 hours in total","70 hours in total","50 hours in total","105 hours in total"],"correct":0,"exp":"Even with a C and a D licence, the driver only does 35 hours every 5 years: the common modules count for both."},{"q":"What physical document must a professional driver carry while driving a commercial passenger vehicle to prove CPC compliance?","options":["Driver CPC card, or a licence with code 95","The original Certificate of Incorporation","Paper certificate from the training centre","The Transport Manager's CPC certificate"],"correct":0,"exp":"When driving, you must carry the CPC card (DQC) or the licence with code 95, if it is recorded on it."},{"q":"What information code on an EU photocard driving licence indicates that the holder satisfies professional Driver CPC requirements?","options":["Code 101","Code 78","Code 95","Code 50"],"correct":2,"exp":"Code 95 on the licence shows that the driver complies with the Driver CPC."},{"q":"A driver who holds Category D entitlement and CPC card is aged 18. What operation are they legally permitted to drive?","options":["Registered local bus service under 50 km length","International express route across Europe","53-seat coach on Irish day tours over 200 km","Night-time tour from Dublin to Cork"],"correct":0,"exp":"At 18, with a D licence and the full CPC, they can only drive regular services up to 50 km."},{"q":"A driver aged 21 holds Category D entitlement and Driver CPC card. Which of the following operations can they legally drive? 1. Registered local bus service of 45 km 2. Private hire journey of 40 km 3. Private hire journey of 80 km 4. School contract of 30 km","options":["1, 2, 3 and 4","1 only","2 and 3 only","2, 3 and 4 only"],"correct":0,"exp":"At 21 with the full CPC, there is no longer a distance restriction."},{"q":"An employer hires a French national residing in Ireland for 9 months who holds an EU Category D licence. What is the legal status of their driving licence?","options":["They can keep driving on it: EU recognition","They must re-take the Irish test after 6 months","Their licence expired when they moved here","They may only drive Category B cars"],"correct":0,"exp":"EU mutual recognition, without a test in Ireland."},{"q":"What is the minimum age for a driver holding Category D and CPC to operate a 49-seat coach on multi-day Irish tours (exceeding 50 km)?","options":["18 years","21 years","24 years","25 years"],"correct":1,"exp":"For journeys of more than 50 km (for example, tours around Ireland) with a D licence and the CPC, the minimum age is 21."},{"q":"What category of entitlement is required for a driver operating a 16-seat minibus towing a 1-tonne (1,000 kg) trailer for school trips?","options":["Category D1","Category D1+E","Category D","Category B+E"],"correct":1,"exp":"A 16-seat minibus (D1) with a trailer over 750 kg: you need D1+E."},{"q":"What is the penalty for an operator who knowingly employs a driver to operate a PSV without a valid driving licence or Driver CPC card?","options":["Fines, prosecution and risk to good repute","A verbal caution from the local council","Double motor tax on the vehicle for a year","Free CPC training provided by the RSA"],"correct":0,"exp":"Heavy fines, prosecution and risk to the licence."},{"q":"In Case Study 21P, Lax Travel Ltd operates minibuses, 53-seat buses (<50 km), 72-seat school buses, and 49-seat tour coaches. What is the minimum age required for drivers passing tests after Sept 2020 for the 49-seat ROI tour coach?","options":["18 years","21 years","24 years","25 years"],"correct":1,"exp":"With the CPC, the minimum age is 21 for coaches on journeys of more than 50 km; it only drops to 18 on regular services up to 50 km."}]},"22":{"title":"Topic 22 - Traffic Regulations & Speed Limits","questions":[{"q":"Which vehicle category is legally required to have a speed limiter fitted in Ireland and across the EU?","options":["Buses over 8 seats; goods vehicles over 3.5 t","All passenger cars and vans of any weight","Motorcycles and quads with engines over 250 cc","Agricultural tractors and their trailers"],"correct":0,"exp":"Buses/coaches with 8+ seats and goods vehicles over 3.5t must have a limiter."},{"q":"What is the maximum calibrated set speed for a speed limiter fitted to a passenger bus or coach (category M2/M3)?","options":["80 km/h","90 km/h","100 km/h","110 km/h"],"correct":2,"exp":"Speed limiter for buses and coaches (M2 and M3): 100 km/h. Those built for standing passengers, 65 km/h."},{"q":"What is the maximum set speed of the speed limiter on a coach with more than 8 passenger seats that is NOT designed for standing passengers?","options":["100 km/h","90 km/h","80 km/h","65 km/h"],"correct":0,"exp":"Since 2005, PSVs with more than 8 seats must have a limiter set to 100 km/h. Buses built for standing passengers are limited to 65 km/h.\n📍 Book M22 p.2"},{"q":"What is the maximum statutory speed limit on Irish motorways for a bus or coach NOT designed for standing passengers (and not towing a trailer)?","options":["80 km/h","90 km/h","100 km/h","120 km/h"],"correct":2,"exp":"100 km/h on the motorway for a bus with no standing places."},{"q":"What is the maximum statutory speed limit on Irish motorways for a bus or coach designed for standing passengers (urban/city bus)?","options":["50 km/h","65 km/h","80 km/h","100 km/h"],"correct":1,"exp":"A bus with standing passengers has a limit of 65 km/h on ALL roads, including the motorway."},{"q":"What is the speed limit on Irish motorways for ANY vehicle (including buses/coaches) towing a trailer, caravan, or horsebox?","options":["65 km/h","80 km/h","90 km/h","100 km/h"],"correct":1,"exp":"80 km/h for any vehicle towing something."},{"q":"What is the general speed limit for a bus/coach (not designed for standing passengers) on a dual carriageway in Ireland?","options":["100 km/h","80 km/h","90 km/h","120 km/h"],"correct":0,"exp":"100 km/h on a dual carriageway, unless there is a lower local limit."},{"q":"What is the speed limit for a bus/coach on single-carriageway national, regional, or local roads ('Other Roads') in Ireland?","options":["65 km/h","80 km/h","90 km/h","100 km/h"],"correct":1,"exp":"Bus or coach without standing passengers, on ordinary roads (not a motorway or dual carriageway): 80 km/h."},{"q":"What is the general default speed limit in built-up urban areas in Ireland?","options":["30 km/h","50 km/h","60 km/h","80 km/h"],"correct":1,"exp":"In built-up areas the general limit is 50 km/h, unless a sign says otherwise (for example, 30 zones)."},{"q":"In Germany, passenger coaches that meet strict safety and technical requirements can obtain a certificate to operate at 100 km/h on motorways. What is this certificate called?","options":["Vitesse 100","Tempo 100","Autobahn 100","SpeedCert 100"],"correct":1,"exp":"Tempo 100: a German certificate that allows coaches to travel at 100 km/h on motorways within Germany. In France it is called 'Vitesse 100'."},{"q":"In France, what certificate permits a qualified bus or coach to travel at speeds up to 100 km/h on motorways and dual carriageways?","options":["Vitesse 100","Tempo 100","Autoroute 100","Express 100"],"correct":0,"exp":"Vitesse 100: a French certificate that allows coaches to travel at 100 km/h on French motorways and dual carriageways. The original must be carried."},{"q":"What is a 'Dual purpose vehicle' as defined in Irish traffic regulations?","options":["Built to carry both goods and passengers","Powered by both diesel and electricity","Fitted with analogue and digital tachographs","Licensed for domestic and international routes"],"correct":0,"exp":"A vehicle built/adapted to carry goods and passengers."},{"q":"How are speeding offences generally penalised for commercial vehicle drivers in Ireland?","options":["Fixed charge with penalty points, or court","A 3-month licence suspension for a first offence","Instant impoundment of the vehicle by Gardaí","Loss of the operator licence on a first offence"],"correct":0,"exp":"A fixed fine (typically €160 and 3 penalty points) or prosecution."},{"q":"What plaque or plate must be affixed to a vehicle fitted with a mandatory speed limiter?","options":["A plaque with the set speed and the workshop","Only the manufacturer's plate on the chassis","A green RSA compliance badge on the grille","A sticker on the motor tax disc holder"],"correct":0,"exp":"The limiter has a calibration plate or seal with the date, the set speed, the tyre size and the workshop that calibrated it."},{"q":"Who is legally authorised to calibrate, seal, and issue calibration plaques for vehicle speed limiters?","options":["An RSA-authorised speed limiter workshop","Any licensed commercial vehicle driver","The Transport Manager, using a laptop","The local Garda station"],"correct":0,"exp":"A workshop/technician authorised and certified by the RSA."},{"q":"Operating a commercial vehicle with a defective, tampered, or uncalibrated speed limiter is classified as:","options":["A serious breach, with fines and prosecution","Only a minor administrative oversight","Allowed during peak travel hours only","Allowed on local roads under 50 km/h"],"correct":0,"exp":"A serious legal offence with fines, prosecution and loss of good repute."},{"q":"Where is parking strictly prohibited for ALL vehicles under Irish Traffic Regulations?","options":["Clearways, bus lanes, crossings, yellow lines","Off-street parking bays marked for coaches","Parking spaces inside the operator's depot","Designated coach bays outside hotels"],"correct":0,"exp":"Clearways, motorways, bus lanes, pedestrian crossings and yellow lines."},{"q":"What do double continuous yellow lines along the edge of a kerb/roadway signify?","options":["Parking restricted during business hours only","No parking 24 hours a day","Free parking for commercial vehicles","Loading bay for goods vehicles only"],"correct":1,"exp":"Double continuous yellow line along the kerb: no parking 24 hours a day. A single yellow line: no parking during the hours shown on the sign."},{"q":"What does a single continuous yellow line along a roadway indicate?","options":["No parking during the hours on the nearby plate","No parking at any time, 24 hours a day","Parking reserved for buses and coaches only","Parking allowed for electric vehicles only"],"correct":0,"exp":"No parking during specific hours (shown on nearby plates)."},{"q":"Are Large Public Service Vehicles (over 3.5 tonnes unladen weight) allowed to park on public roads at night in urban residential areas?","options":["No, it is heavily restricted by law","Yes, anywhere along public streets","Yes, if the hazard lights are left on","Yes, if it is parked on the footpath"],"correct":0,"exp":"Very restricted at night in residential areas."},{"q":"On European roads, what international road sign is represented by a yellow diamond with a broad white border?","options":["Priority road","End of speed limit zone","Hazardous materials route","No entry for commercial vehicles"],"correct":0,"exp":"'Priority Road' sign (right of way)."},{"q":"What item of equipment is mandatory for drivers travelling in France?","options":["An approved breathalyser kit","A fire extinguisher at every seat","A spare container of engine oil","All of the above"],"correct":0,"exp":"In France you must carry an approved breathalyser and, if the driver takes medication, an authenticated copy of the prescription."},{"q":"When travelling through France under conditions requiring snow chains ('équipements spéciaux obligatoires'), when must snow chains be fitted?","options":["When the special equipment signs are shown","Only after a breakdown has occurred","All through winter, whatever the weather","Only when driving faster than 80 km/h"],"correct":0,"exp":"When those official signs are displayed or the police indicate it."},{"q":"Which European countries strictly require drivers who wear spectacles/corrective lenses to carry a SPARE PAIR in the vehicle?","options":["France and Belgium","Germany and Spain","Netherlands and Denmark","UK and Ireland"],"correct":1,"exp":"In Germany and Spain, a driver who wears glasses must carry a spare pair in the vehicle."},{"q":"In most European countries, what safety equipment must be carried in commercial vehicles/coaches for crew members exiting the vehicle on highways?","options":["Warning triangles and hi-viz clothing","A first aid kit and nothing else","Spare engine belts and hoses","Torches fitted with red filters"],"correct":0,"exp":"Warning triangles and high-visibility reflective clothing."},{"q":"Can a bus designed to carry standing passengers operate at 100 km/h on a motorway?","options":["No, it is limited to 65 km/h","Yes, if the traffic is light","Yes, if all passengers hold the handrails","Yes, on an express interurban route"],"correct":0,"exp":"No: a bus with standing passengers has a limit of 65 km/h on all roads, including the motorway."},{"q":"What is the speed limit for a single or double-deck bus designed to carry standing passengers?","options":["65 km/h on all roads","80 km/h on all roads","100 km/h on motorways","50 km/h on all roads"],"correct":0,"exp":"Bus built to carry standing passengers: 65 km/h on all roads. If it does not carry standing passengers: 80 km/h on ordinary roads and 100 km/h on motorways and dual carriageways.\n📍 Book M22 p.1"},{"q":"What is the speed limit for a coach NOT designed for standing passengers on roads other than motorways or dual carriageways?","options":["80 km/h","65 km/h","100 km/h","90 km/h"],"correct":0,"exp":"Coach without standing passengers: 80 km/h on ordinary roads and 100 km/h on motorways and dual carriageways. With a trailer: 80 km/h on all of them.\n📍 Book M22 p.1"},{"q":"What type of penalty points accumulation leads to a driver qualification suspension in Ireland?","options":["12 points in 3 years; 7 for learners","6 points within 3 years for full licences","20 points within any 5-year period","Any 2 points suspend the licence at once"],"correct":0,"exp":"12 penalty points in 3 years (or 7 for novice drivers) suspend the entitlement."},{"q":"If a Transport Manager discovers a driver has tampered with a vehicle speed limiter to bypass the 100 km/h max setting:","options":["Withdraw it, repair it, discipline the driver","Treat it as a minor internal matter only","Let the driver finish the rest of the week","Raise ticket prices to cover any fines"],"correct":0,"exp":"Take the vehicle off the road immediately, correct the limiter and discipline the driver."},{"q":"Why are speed limiters compulsory on heavy passenger and goods vehicles?","options":["Safety, lower fuel use and lower emissions","Only to make tyre tread last longer","To reduce the toll fees paid on motorways","To simplify the drivers' tachograph records"],"correct":0,"exp":"Reducing fuel/emissions, improving safety and minimising the severity of collisions."},{"q":"What is the impact of speeding convictions on a transport operator's Commercial Vehicle Risk Rating (CVRR)?","options":["It worsens the risk score and triggers audits","It has no impact on the rating at all","It improves the operator's risk score","It cancels the fleet's motor tax obligations"],"correct":0,"exp":"It downgrades the risk rating, triggering RSA audits."},{"q":"When a bus is fitted with a speed limiter set to 100 km/h, can downhill gradient forces cause the vehicle to temporarily exceed 100 km/h?","options":["Yes, unless the driver uses retarders or brakes","No, limiters brake automatically downhill","No, limiters stop any gravity acceleration","It is illegal and shuts the engine down at once"],"correct":0,"exp":"On steep descents there can be 'overrun' unless retarders/brakes are used."},{"q":"Under Irish law, what is the consequence for an operator who knowingly permits a vehicle with a disabled speed limiter to carry passengers?","options":["Fines, prosecution, prohibition, licence risk","A verbal warning from the local council","The vehicle is re-registered as a taxi","Free recalibration of the limiter by the RSA"],"correct":0,"exp":"Heavy fines, prosecution, vehicle prohibition and risk of licence suspension."},{"q":"What document must be carried on an international coach journey through Germany to prove authorization for 100 km/h travel?","options":["Tempo 100 Certificate","Green Card Insurance","Community Licence original","Driver CPC Qualification Card only"],"correct":0,"exp":"To travel at 100 km/h in Germany you must carry the original Tempo 100 certificate and display the '100' sticker on the back."},{"q":"What document must be carried on an international coach journey through France to prove authorization for 100 km/h travel?","options":["Vitesse 100 Certificate","French Route Map","Letter of Attestation","Driver Logbook"],"correct":0,"exp":"To travel at 100 km/h in France you must carry the original Vitesse 100 certificate and display the '100' sticker on the back."},{"q":"What is the maximum speed limit for a coach towing a 1-tonne luggage trailer on an Irish motorway?","options":["100 km/h","90 km/h","80 km/h","65 km/h"],"correct":2,"exp":"Any vehicle with a trailer, including a coach, has a limit of 80 km/h on all roads, including the motorway."},{"q":"Can a passenger coach driver overtake in the outside (third) lane of a three-lane motorway in Ireland?","options":["No, buses over 3.5 t may not use that lane","Yes, at any time if traffic is slow","Yes, if it is travelling at 100 km/h","Only at weekends and on bank holidays"],"correct":0,"exp":"Heavy vehicles/buses over 3.5t are prohibited from using the outside right-hand lane."},{"q":"What is the primary responsibility of a Transport Manager regarding fleet speed limiters?","options":["All limiters working, calibrated and sealed","Driving test vehicles personally every month","Adjusting the limiters to suit the weather","Inspecting drivers' personal luggage"],"correct":0,"exp":"Ensuring limiters are working, calibrated, and have valid plates and seals."},{"q":"How often should speed limiter seals and plaques be inspected during fleet maintenance checks?","options":["At every periodic safety inspection","Only when the vehicle is first bought","Once every 10 years at a workshop","Never: limiters need no ongoing checks"],"correct":0,"exp":"At each periodic safety inspection it must be checked that the limiter seals and plate are intact and that the calibration is still valid."}]},"26":{"title":"Topic 26 - International Transport Documentation","questions":[{"q":"Which document serves as evidence of an operator's authorization to carry passengers for hire and reward across EU Member States and must have a certified true copy carried in every vehicle?","options":["National Road Passenger Transport Operator Licence","EU Community Licence","Certificate of Conformity","Interbus Authorisation"],"correct":1,"exp":"The Community Licence proves that the operator can carry passengers for money throughout the EU. A certified copy is carried in each vehicle."},{"q":"What document must be carried on board an authorised vehicle operating an international passenger service within the EU?","options":["A certified true copy of the Community Licence","The original EU Community Licence itself","The company's latest annual accounts","Only the Transport Manager's passport"],"correct":0,"exp":"A certified true copy of the Community Licence."},{"q":"What is the standard validity period for an EU Community Licence issued in Ireland by the Department of Transport?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The Community Licence lasts 5 years."},{"q":"Which international agreement governs occasional road passenger transport services (closed door tours, outward laden/return unladen) between the EU and certain non-EU countries (such as the UK, Switzerland, Montenegro, Western Balkans)?","options":["ASOR Agreement","Interbus Agreement","CMR Convention","TIR Convention"],"correct":1,"exp":"The Interbus agreement regulates occasional passenger services between the EU and some non-EU countries (such as the United Kingdom, Switzerland or the Balkans)."},{"q":"Under the Interbus Agreement, how is a 'Closed Door Tour' defined?","options":["Same group, same vehicle, back to start in 90 days","A journey with the doors locked in transit","A private charter service run only at night","A local sightseeing tour within one city"],"correct":0,"exp":"Same group/vehicle, returning to the point of departure within 90 days at most."},{"q":"What control document MUST be carried on board a coach operating an Occasional International Passenger Service within the EU?","options":["EU Journey Form","CMR consignment note","ATA Carnet","All of the above"],"correct":0,"exp":"An international occasional service within the EU must carry the Journey Form (EU waybill)."},{"q":"Who issues official Journey Form (Waybill) booklets for occasional international passenger services to operators in Ireland?","options":["Road Safety Authority (RSA)","National Transport Authority (NTA)","Department of Foreign Affairs (DFA)","An Garda Síochána"],"correct":1,"exp":"In Ireland, books of Journey Forms are issued by the NTA."},{"q":"Within how many days must completed duplicate Journey Form books for occasional international trips be returned to the NTA in Ireland?","options":["7 days","14 days","30 days","60 days"],"correct":2,"exp":"Completed books of Journey Forms are returned to the NTA within 30 days."},{"q":"How long must a transport operator retain top copies / records of completed EU Journey Forms (Waybills) at their operating base?","options":["12 months","6 months","2 years","5 years"],"correct":0,"exp":"The operator keeps copies of the Journey Forms at its base for at least 12 months."},{"q":"What document must be carried on board a vehicle operating a Regular International Passenger Service across EU Member States?","options":["EU route authorisation","Interbus waybill","ATA Carnet for the vehicle","All of the above"],"correct":0,"exp":"On an international regular service, the route authorisation is carried on board (on pink paper, with the timetable and fares)."},{"q":"What is the maximum validity period for an EU Regular International Passenger Service Route Authorisation?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The route authorisation for an international regular service lasts a maximum of 5 years."},{"q":"What document covers an 'Own Account' international passenger transport operation (e.g. non-commercial transport by a school or local authority using their own bus and driver)?","options":["Own-account certificate","EU Community Licence","Interbus waybill","All of the above"],"correct":0,"exp":"International own-account transport (for example, a school with its own bus) carries an International Own Account Certificate."},{"q":"Under EU Directive 98/41/EC and SOLAS Convention requirements, what passenger document MUST be compiled for ferry crossings over 20 miles from an EU port?","options":["A passenger list or manifest","Copies of passengers' driving licences","A tax clearance cert for each passenger","Passengers' employment contracts"],"correct":0,"exp":"On ferries that go more than 20 miles from an EU port, a passenger list must be made: surname, first name, sex, age and special needs if any."},{"q":"What certificate is required for a coach to operate at the maximum legal speed of 100 km/h on French motorways?","options":["Tempo 100","Vitesse 100","Autoroute 100","Eurovignette 100"],"correct":1,"exp":"To travel at 100 km/h in France, the coach needs the Vitesse 100 certificate."},{"q":"What certificate is required for an Irish passenger coach to travel at 100 km/h on German autobahns?","options":["Tempo 100 Certificate","Vitesse 100 Certificate","German Speed Permit","Autobahn Pass"],"correct":0,"exp":"To travel at 100 km/h in Germany, the coach needs the Tempo 100 certificate."},{"q":"If a driver has been absent from work due to illness or annual leave for 2 months prior to an international journey, what document should be carried to explain incomplete tachograph records?","options":["Attestation of activities form","A copy of the EU Community Licence","Certificate of Roadworthiness","The driver's EHIC or GHIC card"],"correct":0,"exp":"For days without records (sick leave, holidays) the attestation of activities form is used. Nowadays the normal practice is to enter them manually on the tachograph; the form is only used if that is not possible."},{"q":"What international vehicle registration identifier must be displayed on the rear of an Irish coach travelling outside Ireland?","options":["IRL plate, or EU-format plate with IRL","A GB sticker on the rear of the coach","A UK sticker beside the number plate","No badge required within Europe"],"correct":0,"exp":"An IRL plate or an EU-format number plate with the IRL code."},{"q":"What is the minimum recommended passport validity period required for Irish drivers travelling to non-EU destination countries?","options":["3 months beyond departure; 6 for some states","No minimum validity is required at all","At least 10 years left on the passport","At least 1 month from the date of departure"],"correct":0,"exp":"For non-EU countries, the passport must be valid for at least 3 months beyond departure (6 months in some countries)."},{"q":"Which document provides evidence of motor insurance cover for international road passenger operations abroad?","options":["Green Card or proof of EU insurance","Certificate of Incorporation","Driver CPC qualification card","Vehicle Registration Certificate"],"correct":0,"exp":"The Green Card, or proof of insurance valid in the EU, shows that the vehicle is insured abroad."},{"q":"When an Irish driver operates in Germany under minimum wage legislation (Mindestlohngesetz - MiLoG), what proof must be available?","options":["Proof the German minimum wage is paid","A certificate of Irish citizenship","A local German tax registration number","A bank guarantee of €50,000 for the trip"],"correct":0,"exp":"In Germany you must be able to prove that the driver is paid at least the German minimum wage for the hours worked there."},{"q":"What requirement applies to transport operators under French law regarding posted drivers carrying out passenger transport or cabotage in France?","options":["Online pre-declaration and a posting certificate","Registering with the French police within 2 hours","The driver must hold a French driving licence","Employing a French co-driver on every trip"],"correct":0,"exp":"In France, posted drivers are declared in advance to the French labour inspectorate (via an online portal) and the posting certificate is carried on board."},{"q":"Following Brexit, how are passenger transport operations between Ireland (EU) and Great Britain (England, Scotland, Wales) governed?","options":["The EU-UK TCA and the Interbus Agreement","Only the Irish domestic regulations","It is completely banned since Brexit","United Nations maritime rules only"],"correct":0,"exp":"After Brexit, journeys between Ireland and Great Britain are governed by the EU-UK agreement (TCA) and by the Interbus rules."},{"q":"Are separate non-EU route authorisations required for international regular bus services operating between Ireland and Northern Ireland post-Brexit?","options":["No, they continue under the EU framework","Yes, complex non-EU permits are needed","No, no transport may cross the border now","Yes, approval from US Customs is needed"],"correct":0,"exp":"No, they remain under the EU framework without non-EU formalities."},{"q":"What is the status of the Common Travel Area (CTA) between Ireland and the UK for professional coach drivers who are Irish or British citizens?","options":["No visas, but a passport is strongly advised","Travel with no identity documents at all","A work visa is needed for every trip","The CTA applies only to air travel"],"correct":0,"exp":"No visa, but carrying a passport is recommended."},{"q":"What is the legal requirement for drivers regarding passenger documentation checks on international trips?","options":["Check passengers have valid passports and visas","Keep every passenger's passport in the cab safe","Drivers have no responsibility for documents","Drivers must issue passports to passengers"],"correct":0,"exp":"Making sure passengers have a valid passport/visa."},{"q":"Under Irish Immigration law (Illegal Immigrants Act), what penalties can be imposed on a carrier/operator if undocumented passengers or illegal immigrants are found concealed in a vehicle?","options":["Up to €3,000 per person; prison for smuggling","A verbal reprimand from port officials","Cancellation of all driver CPC cards","Impoundment of the fuel tanks only"],"correct":0,"exp":"Up to €3,000 per passenger, or up to 10 years in prison."},{"q":"What constitutes a valid legal defense for a transport operator if an illegal immigrant is discovered hidden on board their coach at a border crossing?","options":["An effective security system, used properly","The bus doors were left open on purpose","The vehicle had passed its CVRT test","The driver was running behind schedule"],"correct":0,"exp":"An effective security system + no knowledge or suspicion."},{"q":"What international convention administered by the International Maritime Organization (IMO) regulates safety of life at sea, passenger manifests, and public address systems on passenger ferries?","options":["SOLAS Convention","CMR Convention","ADR Agreement","All of the above"],"correct":0,"exp":"SOLAS (Safety of Life at Sea) is the IMO convention on safety at sea: ferry passenger lists, life-saving and public address systems."},{"q":"Under the Package Travel, Package Holidays and Package Tours Regulations 1992, what combination defines a statutory 'Package Tour'?","options":["Two or more elements, one price, over 24 hours","Any single coach ticket bought in advance","A day trip of under 50 km with no meals included","Hiring a coach with driver for two hours"],"correct":0,"exp":"At least 2 elements, at an inclusive price, +24h."},{"q":"In Case Study 1 (EOS Coach Travel Ltd), the company plans a scheduled weekly coach service from Dublin to Paris (stopping in UK, Belgium, France). What primary licence and document are required?","options":["Community Licence copy and route authorisation","A national operator licence and a taxi disc","Only an Interbus waybill for each trip","A local Dublin bus permit and timetable"],"correct":0,"exp":"International licence + Community Licence + Route Authorisation."},{"q":"In Case Study 1, EOS Coach Travel Ltd plans a private tourist coach trip from Cork to France for 5 days. What document MUST be carried on board the vehicle for this occasional service?","options":["EU Journey Form, filled in before leaving","Regular service route authorisation","Special regular service contract","A bill of lading for the luggage"],"correct":0,"exp":"A private sightseeing trip to France is an occasional service: the Journey Form must be carried, filled in before departure."},{"q":"In Case Study 1, EOS Coach Travel Ltd plans a contracted service transporting Irish students to a college event in Belgium under a written contract. What document is required on board?","options":["Journey Form and a copy of the contract","A single ticket for each student","An International Driving Permit","Only the Green Card insurance"],"correct":0,"exp":"Carrying students under a written contract is a special regular service: Journey Form and a copy of the contract between the school and the carrier."},{"q":"In Case Study 1, EOS Coach Travel Ltd plans short passenger journeys between two French cities while the coach is in France. What is this operation legally called, and what are the conditions?","options":["Cabotage: temporary, within an international trip","Internal transit: prohibited in all cases","Domestic express: needs a French licence","Own-account transport: no documents needed"],"correct":0,"exp":"Bus cabotage, temporary, as part of an international service."},{"q":"In Case Study 2 (International Transport Documentation - Dublin to London coach service via Dublin-Liverpool ferry), what FIVE vehicle/service documents must be carried on board?","options":["Community Licence copy, permit, VRC, insurance, CRW","Birth cert, bank statements, receipts, lease, tax","Tacho certificate, CPC, passport, EHIC, ticket","Parking permit, NTA disc, logbook, toll tag, bill"],"correct":0,"exp":"Community Licence, authorisation, VRC, insurance and CRW."},{"q":"According to the CILT Case Study marking scheme for international transport documentation, what additional documents should be available for border/ferry compliance on a Dublin to London route?","options":["Passenger list, tachograph records, LPSV licence","Customs declarations for commercial goods","Drivers' personal tax clearance certificates","Import duty exemption certificates for the coach"],"correct":0,"exp":"Passenger manifest, tachograph and LPSV licence."},{"q":"Which international customs channel at Irish points of entry is used for intra-EU passenger/goods movements with no banned or restricted goods?","options":["Red Channel","Green Channel","Blue Channel","Yellow Channel"],"correct":2,"exp":"Blue channel: journeys within the EU with nothing to declare. Green: arriving from outside the EU with nothing to declare. Red: you have something to declare."},{"q":"What international driving document may be required for an Irish driver travelling through non-EU / non-EEA countries (e.g. Ukraine, Albania, or Russia)?","options":["An International Driving Permit","An Irish learner's provisional permit","A local council driving badge","Only the Driver CPC qualification card"],"correct":0,"exp":"Some countries outside the EU and EEA require an International Driving Permit (IDP)."},{"q":"What medical document is strongly recommended for Irish drivers travelling in EU Member States to access healthcare?","options":["European Health Insurance Card","A private dental insurance policy","A life insurance certificate","All of the above"],"correct":0,"exp":"The European Health Insurance Card (EHIC, or GHIC in the United Kingdom) gives access to public healthcare in other countries."},{"q":"What is the role of the Transport Manager regarding international transport documentation?","options":["Checklists, passports, waybills, licence copies","Personally driving every international route","Paying passengers' hotel bills personally","Granting customs exemptions to passengers"],"correct":0,"exp":"An international compliance checklist and document verification."},{"q":"What is the ultimate objective of international transport regulations and documentation compliance?","options":["Safe, smooth and legal cross-border travel","Maximising customs duties from tourists","Eliminating international coach travel in Europe","Restricting coaches to domestic routes"],"correct":0,"exp":"Facilitating cross-border movement and combating illegal immigration."}]},"28":{"title":"Topic 28 - Bus and Coach Operations","questions":[{"q":"Under Irish law, what requirement applies if a passenger transport vehicle carrying 8 or fewer passenger seats is used to carry passengers at separate fares?","options":["A licence, unless all pre-book and agree the fare","No licence is needed in any circumstances","It must be registered as a heavy goods vehicle","It needs an international maritime permit"],"correct":0,"exp":"It needs a licence, unless the booking/fare is agreed in advance and it is not a public service."},{"q":"How is 'Hire or Reward' legally defined in passenger transport operations in Ireland?","options":["Any payment, direct or indirect, for travel","Payments made in cash to the driver only","Payments of more than €1,000 per journey","Carrying family members free of charge"],"correct":0,"exp":"Any direct or indirect payment for the journey."},{"q":"If an employer operates a bus to transport employees to and from work and deducts money from their pay or requires a contribution, what is the legal requirement?","options":["It is hire or reward: licence and LPSV needed","It is exempt from all passenger licensing","The driver only needs a Category B licence","The bus is exempt from the annual CVRT"],"correct":0,"exp":"It is 'hire or reward' and requires an operator licence and an LPSV licence."},{"q":"If an employer contracts a specialized travel firm to transport employees to work at no charge to the employees, which entity is operating for hire or reward?","options":["The travel firm contracted for it","The employer paying the travel firm","The employees who travel on the bus","The local county council"],"correct":0,"exp":"The contracted travel company operates 'for hire or reward', because it is paid for the service, even though the workers pay nothing."},{"q":"Under Irish law, who is the statutory licensing authority for commercial public bus passenger services (scheduled routes) under the Public Transport Regulation Act 2009?","options":["Road Safety Authority (RSA)","National Transport Authority (NTA)","An Garda Síochána","Revenue Commissioners"],"correct":1,"exp":"The NTA is the authority that grants licences for regular bus services (Public Transport Regulation Act 2009)."},{"q":"Who issues the Large Public Service Vehicle (LPSV) licence required for vehicles carrying more than 8 passengers for hire or reward in Ireland?","options":["A PSV Officer of An Garda Síochána","The Department of Transport (RTOL Division)","The National Transport Authority (NTA)","The Health and Safety Authority (HSA)"],"correct":0,"exp":"The licence for each vehicle carrying more than 8 passengers (LPSV) is issued by a Garda PSV Officer."},{"q":"For how long is a Large Public Service Vehicle (LPSV) licence issued by An Garda Síochána valid?","options":["1 year","3 years","5 years","10 years"],"correct":1,"exp":"The Garda LPSV licence lasts 3 years."},{"q":"For how long is a standard Road Passenger Transport Operator Licence (National or International) valid in Ireland?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The passenger operator licence, national or international, lasts 5 years."},{"q":"What four core criteria must an undertaking satisfy to obtain and maintain a Road Passenger Transport Operator Licence under Regulation (EC) No 1071/2009?","options":["Good repute, appropriate financial standing, professional competence, and a stable and effective establishment in Ireland","Minimum fleet of 10 coaches, annual turnover of €1M, tax exemption, and Irish ownership","ISO 9001 certification, 5 years trading history, local depot planning permission, and clean driving record","Commercial building ownership, zero debt, driver CPC exemption, and private insurance cover"],"correct":0,"exp":"Good repute, financial standing, professional competence, stable establishment."},{"q":"What financial standing capital reserve must an operator demonstrate for a Road Passenger Transport Operator Licence?","options":["€5,000 for the first vehicle and €2,500 for each additional vehicle","€9,000 for the first vehicle and €5,000 for each additional vehicle","€12,000 for the first vehicle and €6,000 for each additional vehicle","Flat rate of €50,000 regardless of fleet size"],"correct":1,"exp":"€9,000 for the first vehicle, €5,000 for each additional one."},{"q":"What additional document is issued to an international passenger operator alongside their International Operator Licence to be kept at base?","options":["Community Licence","Journey Form Booklet","Route Authorisation Permit","Cabotage Certificate"],"correct":0,"exp":"With the international licence the Community Licence is also issued; the original is kept at the base."},{"q":"What document must be carried on board EVERY vehicle operating internationally within the EU under an International Operator Licence?","options":["A certified true copy of the Community Licence","The original Community Licence document itself","The company's latest audited balance sheet","Birth certificates of all the passengers on board"],"correct":0,"exp":"A certified true copy of the Community Licence."},{"q":"What defines a 'Regular International Passenger Service'?","options":["Set intervals, set route and stops, open to all","Ad-hoc charter trips for private sports clubs","School trips run under a written contract","Point-to-point carriage inside another state"],"correct":0,"exp":"Fixed intervals, predetermined route and stops, open to everyone."},{"q":"What authorization document is required to operate a Regular International Passenger Service across EU borders?","options":["EU route authorisation from the NTA","A journey form for each trip","A simple local council permit","A customs declaration form"],"correct":0,"exp":"An international regular service in the EU needs a route authorisation (EU Route Authorisation). In Ireland it is processed by the NTA, in agreement with the countries the route passes through."},{"q":"What is the maximum validity period for an EU Regular International Service Route Authorisation?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The route authorisation for an international regular service lasts a maximum of 5 years."},{"q":"How long do consulted Member State authorities have to notify their decision upon receiving an application for a Regular International Service Authorisation?","options":["1 month","2 months","4 months","6 months"],"correct":1,"exp":"The countries consulted have 2 months to reply to an application for an international regular service."},{"q":"What happens if a consulted Member State authority fails to reply within the 2-month statutory limit for a Regular International Service application?","options":["The application is automatically rejected","The authority is deemed to have given its agreement","The application is referred to the European Court of Justice","The operator must re-submit the application with extra fees"],"correct":1,"exp":"If a country consulted does not reply within 2 months, it is considered to agree."},{"q":"What defines an 'Occasional International Passenger Service'?","options":["Groups formed by the customer or the carrier","Daily scheduled interurban routes with stops","Shuttle services carrying workers daily","Urban commuter bus services at peak times"],"correct":0,"exp":"Groups formed on the initiative of the customer/carrier."},{"q":"What specific document MUST cover an Occasional International Passenger Service within the EU?","options":["A Journey Form booklet from the NTA","A route authorisation certificate","A special regular service contract","A cabotage permit for each country"],"correct":0,"exp":"An international occasional service within the EU must carry the Journey Form (waybill), from the book issued by the NTA."},{"q":"Within how many days must a completed Journey Form for an occasional international trip be returned to the NTA in Ireland?","options":["7 days","14 days","30 days","60 days"],"correct":2,"exp":"The completed Journey Form is returned to the NTA within 30 days."},{"q":"What defines a 'Special Regular International Service'?","options":["Contracted groups only, e.g. workers or pupils","Scheduled services open to the general public","One-off tourist excursions sold to anyone","Shared taxi services at airport terminals"],"correct":0,"exp":"Specific categories of passengers under contract."},{"q":"What document must be carried on board a vehicle operating a Special Regular International Service?","options":["A copy of the organiser-carrier contract","A book of blank Journey Forms for each trip","Individual tickets for every passenger","A letter from the Department of Education"],"correct":0,"exp":"A copy of the contract between the organiser and the carrier."},{"q":"How is 'Bus Cabotage' defined in European passenger transport law?","options":["Carrying passengers inside another EU state","Taking passengers from Dublin to Belfast","Domestic passenger transport within Ireland","Driving empty coaches across EU borders"],"correct":0,"exp":"Point-to-point transport within a host State."},{"q":"Under what conditions is passenger cabotage permitted within an EU host Member State?","options":["Temporary, during an international service","Unlimited domestic carriage, no restrictions","Only with vehicles weighing under 3.5 tonnes","Never: it is prohibited in every EU state"],"correct":0,"exp":"Temporary, as part of an authorised international service."},{"q":"What requirement applies to foreign operators carrying out cabotage operations in France for more than 8 days?","options":["Pre-declare the drivers to French labour inspectors","Re-register every vehicle on French number plates","Pay double motor tax to the French government","Employ only drivers of French nationality"],"correct":0,"exp":"Advance declaration to the French Labour Inspectorate."},{"q":"What defines an 'Own Account' passenger transport operation?","options":["Non-profit, ancillary carriage by own staff","Tour operators selling individual tickets","Sub-contracted school transport operations","Taxi services operating as private hire"],"correct":0,"exp":"Non-commercial and not-for-profit, an ancillary activity."},{"q":"Are 'Own Account' passenger transport operations required to hold a Road Passenger Transport Operator Licence?","options":["No, they are exempt from operator licensing","Yes, all passenger transport needs a licence","Only if they operate international routes","Only if the bus has more than 50 seats"],"correct":0,"exp":"Not-for-profit own-account transport (for example, a school taking its pupils in its own bus) does not need an operator licence."},{"q":"Under PSV Conduct Regulations in Ireland, what is a driver of a Large Public Service Vehicle legally required to do when picking up or setting down passengers?","options":["Stop the vehicle as close as possible to the kerb","Stop in the middle of the driving lane to block traffic","Sound the horn to alert passengers","Request passengers to jump onto the moving vehicle"],"correct":0,"exp":"When picking up or setting down passengers, the driver must stop as close as possible to the kerb, for safety."},{"q":"Under PSV Conduct Regulations, can a driver of an omnibus enter into conversation with passengers while the vehicle is moving or stopped in traffic?","options":["No, except where needed for safety","Yes, drivers should chat with passengers","Only on journeys at weekends","Only if a loudspeaker is used"],"correct":0,"exp":"No, unless it is necessary for safety/operational reasons."},{"q":"Under PSV Conduct Regulations, what power does a bus driver or Garda have regarding an unruly or offensive passenger?","options":["Exclude them or ask them to leave","Issue on-the-spot cash fines to them","Impound their luggage permanently","Revoke the passenger's driving licence"],"correct":0,"exp":"The driver (or the Garda) can refuse to carry a troublesome passenger or ask them to get off, using reasonable force if necessary or calling the Garda."},{"q":"Can a bus driver use physical force to eject a disruptive passenger from a vehicle?","options":["No violence: ask them to leave or call the Gardaí","Yes, drivers have unlimited rights to use force","Yes, if other passengers help to remove them","Only on double-deck buses late at night"],"correct":0,"exp":"They must avoid violence; ask them to get off or call the Garda."},{"q":"How must lost property found on a passenger bus be handled under Irish law?","options":["Per company policy and the statutory rules","Sold by the driver for cash straight away","Kept by whoever found it after 24 hours","Thrown away at the end of the driver's shift"],"correct":0,"exp":"According to company policy and the Road Traffic Act 1961."},{"q":"When an operator sub-contracts a passenger journey to another operator, who remains legally liable to the customer for full contract performance?","options":["The original operator, the main contractor","Only the sub-contractor that ran the trip","Neither, as liability is cancelled","The driver assigned on that day"],"correct":0,"exp":"If the operator subcontracts a journey, it remains answerable to the customer. Afterwards it can claim against the subcontractor."},{"q":"Does a main operator have a legal duty to disclose to a sub-contractor the exact price charged to the end customer?","options":["No, there is no duty to reveal that price","Yes, total financial disclosure is required","Only if the contract exceeds €10,000","Only if the Gardaí ask for it in writing"],"correct":0,"exp":"The main operator does not have to tell the subcontractor how much it charges the customer."},{"q":"What is the definition of an 'Agent' in transport contracts?","options":["Someone authorised to contract for a principal","A person employed to drive passenger coaches","An inspector from the Road Safety Authority","A garage that maintains the operator's fleet"],"correct":0,"exp":"A person with authority to act on behalf of another."},{"q":"If an agent acts outside their delegated authority when making a contract with a third party, is the principal bound by the contract?","options":["No: the agent may be sued instead","Yes, all agents' contracts must be honoured","The contract transfers to the NTA","The State compensates the third party"],"correct":0,"exp":"If the agent exceeds their authority, the principal is not bound by that contract, and the third party can sue the agent."},{"q":"If an agent makes 'secret profits' without the principal's knowledge while acting on their behalf, what legal remedy does the principal have?","options":["Sue the agent to recover the profits","None: secret profits are legal bonuses","The agent is awarded extra commission","The third party's contract becomes void"],"correct":0,"exp":"If the agent secretly makes money at their principal's expense, the principal can sue them to recover that money."},{"q":"What is the purpose of an operator's 'Conditions of Carriage'?","options":["The contract terms between operator and passenger","To exempt the operator from road safety laws","To override drivers' tachograph limits","To set the vehicles' motor tax rates"],"correct":0,"exp":"Setting the legal terms of the contract of carriage."},{"q":"Can an operator exclude liability for personal injury or death caused to passengers in their Conditions of Carriage?","options":["No, it cannot be excluded or restricted","Yes, by printing a clause on the tickets","Yes, if the local council approves it","Yes, but only on international routes"],"correct":0,"exp":"The conditions of carriage cannot exclude liability for death or injury caused by negligence: the law does not allow it."},{"q":"What is a 'Closed Door Tour' in international passenger transport?","options":["Same group, same vehicle, back to the start","A tour with doors locked from the outside","A private charter service run only at night","A local urban bus route with no stops at all"],"correct":0,"exp":"Same vehicle, same group, without picking up/setting down along the way."}]},"29":{"title":"Topic 29 - Competition Rules","questions":[{"q":"Which organization in Ireland has statutory responsibility for enforcing Irish and EU competition law across the transport sector under the Competition and Consumer Protection Act 2014?","options":["Road Safety Authority (RSA)","National Transport Authority (NTA)","Competition and Consumer Protection Commission (CCPC)","Chartered Institute of Logistics and Transport (CILT)"],"correct":2,"exp":"The CCPC (Competition and Consumer Protection Commission) enforces Irish and European competition law, including in transport."},{"q":"What are the two principal sources of competition law that govern passenger transport operators in Ireland?","options":["Competition Act 2002 and TFEU Articles 101/102","Road Traffic Act 1961 and Transport Act 1933","Directive 2006/126/EC and Regulation 561/2006","Consumer Rights Act 2022 and Data Protection Act"],"correct":0,"exp":"The two sources are Ireland's Competition Act 2002 and Articles 101 and 102 of the Treaty on the Functioning of the EU (TFEU)."},{"q":"Does the Competition and Consumer Protection Commission (CCPC) act as a transport regulator that sets passenger fares or bus timetables?","options":["No, it enforces competition law only","Yes, the CCPC sets all bus fares in Ireland","Yes, but only for international coaches","Yes, for school transport contracts only"],"correct":0,"exp":"No, it applies competition law; it does not set fares."},{"q":"Under Section 4 of the Competition Act 2002 and Article 101 TFEU, which of the following practices between independent transport operators is strictly PROHIBITED?","options":["Agreements to fix, harmonise, or coordinate fares (Price-fixing)","Agreements to divide or share customers, territories, routes, or tenders (Market-sharing)","Agreements to limit output or coordinate fleet deployment to reduce competition","All of the above"],"correct":3,"exp":"All of those on the list are prohibited: price fixing, sharing markets or customers, bid-rigging and other agreements between competitors."},{"q":"What is 'Bid-Rigging' in commercial passenger transport tendering (e.g., School Transport Scheme tenders)?","options":["Rivals agreeing not to bid against each other","Submitting a bid below the cost of fuel","Offering discounts for online bookings","Buying second-hand buses to enter a tender"],"correct":0,"exp":"Collusive agreements not to compete with each other."},{"q":"How is bid-rigging treated under Irish competition law?","options":["A serious criminal cartel offence","A minor administrative oversight","An acceptable local commercial practice","A civil dispute settled by the NTA"],"correct":0,"exp":"Bid-rigging is a serious cartel offence: it can lead to fines, civil lawsuits and criminal prosecution."},{"q":"What enforcement powers does the CCPC possess under the Competition Act 2002 (as amended by the Competition (Amendment) Act 2022)?","options":["Investigating suspected anti-competitive behavior and conducting unannounced 'dawn raids' on business premises","Imposing administrative fines on companies (subject to High Court approval) and issuing prohibition orders","Referring serious criminal cartel cases to the Director of Public Prosecutions (DPP)","All of the above"],"correct":3,"exp":"The CCPC has all the powers on the list: investigating, searching premises, taking documents and bringing cases to court."},{"q":"Under Irish and EU competition law, when can enforcement authorities categorise an operator as holding a 'Dominant Position' in a market?","options":["It can act without regard to customers or rivals","It controls more than 50% of national transport","It is a semi-state company like Bus Éireann","It owns a fleet of more than 100 coaches"],"correct":0,"exp":"It can act independently of normal competitive pressures."},{"q":"Is holding a dominant position in a transport market illegal in itself under Irish law?","options":["No, only abusing that position is illegal","Yes, dominance is strictly prohibited","Yes, if its market share exceeds 30%","Yes, but only on intercity express routes"],"correct":0,"exp":"What is prohibited is the ABUSE, not dominance itself."},{"q":"Which Section of the Competition Act 2002 and Article of the TFEU prohibit the ABUSE of a dominant position?","options":["Section 4 Competition Act 2002 and Article 101 TFEU","Section 5 Competition Act 2002 and Article 102 TFEU","Section 12 Companies Act 2014","Article 8 Regulation 561/2006"],"correct":1,"exp":"Abuse of a dominant position is prohibited by section 5 of the Competition Act 2002 and Article 102 TFEU. Section 4 and Article 101 prohibit agreements between companies."},{"q":"What is 'Predatory Pricing' in public passenger transport markets?","options":["Fares below cost to push a rival off a route","Free travel for older people under state schemes","Charging high fares in the peak holiday season","Offering group discounts to angling clubs"],"correct":0,"exp":"Prices below cost to eliminate a competitor."},{"q":"Under Irish and EU law, what TWO conditions must be proven for pricing to be legally classified as abusive 'predatory pricing'?","options":["Fares below cost, and intent to remove a rival","Fares advertised on social media and sold online","Fares above train fares, and drivers on overtime","Vehicles are leased, and routes exceed 50 km"],"correct":0,"exp":"A below-cost price + the intention of eliminating a competitor."},{"q":"Are all loss-making bus services automatically unlawful predatory pricing under competition law?","options":["No, not if there is no intent to remove rivals","Yes, any route run at a loss breaches the law","Yes, unless the CCPC subsidises the route","Only if it is run by a private company"],"correct":0,"exp":"No, as long as there is no intention of eliminating rivals."},{"q":"What is 'Excessive Pricing' by a dominant transport operator?","options":["Unfairly high fares where there is no alternative","Charging €2 for a short urban bus journey","Raising fares in line with diesel inflation","Charging more for luxury leather seats"],"correct":0,"exp":"Unfairly high fares relative to cost, with no real alternative."},{"q":"What is 'Cross-Subsidisation' in transport network operations?","options":["Using profits from one route to support another","Borrowing capital from an international bank","Paying driver wages from vehicle sale proceeds","Claiming VAT refunds on the diesel fuel bought"],"correct":0,"exp":"Using profits from one route to support another."},{"q":"Is cross-subsidisation generally permitted under Irish competition law?","options":["Yes, unless used to drive out a competitor","No, it is illegal in all circumstances","Only if Revenue approves it in advance","Only for rail transport, not for buses"],"correct":0,"exp":"Using the profits of one route to keep another going (cross-subsidy) is allowed, unless it is done only to drive out a competitor."},{"q":"Can two independent bus operators run connecting services (e.g. Route A to B and Route B to C) and coordinate timetables legally under competition law?","options":["Yes, it helps passengers and is lawful","No, any coordination with rivals is illegal","Yes, but only if they merge into one company","Only if An Garda Síochána authorises it"],"correct":0,"exp":"Yes, coordinating connecting timetables benefits the consumer."},{"q":"What THREE conditions must a cooperative agreement between transport operators satisfy to qualify for an exemption under Section 4(5) of the Competition Act 2002?","options":["Progress, a fair share for users, no undue limits","Written in Irish, CILT-approved, valid 10 years","Over 50 buses, routes under 50 km, no discounts","RSA-certified, CPC drivers, annual vehicle tests"],"correct":0,"exp":"An improvement, a fair benefit to the consumer, without eliminating competition."},{"q":"Unlike the UK, does Ireland use 'block exemptions' for multi-operator bus ticketing schemes?","options":["No; the NTA runs integrated ticketing like Leap","Yes, Ireland uses the same UK block exemptions","Yes, the CCPC issues block exemptions yearly","Only for cross-border routes to Northern Ireland"],"correct":0,"exp":"No, the NTA manages integrated ticketing under other legislation."},{"q":"What entity plans, regulates, and procures public bus services and Public Service Obligation (PSO) contracts in Ireland?","options":["The National Transport Authority","The Competition and Consumer Protection Commission","The Department of Enterprise, Trade and Employment","The Road Safety Authority"],"correct":0,"exp":"The NTA plans, regulates and procures public bus services and public service obligation (PSO) contracts."},{"q":"Does NTA planning and procurement of PSO bus services require a specific 'competition test' approval from the CCPC?","options":["No, but general competition law still applies","Yes, the CCPC must approve all NTA timetables","Yes, it must be approved every six months","Yes, but only for private hire coach tours"],"correct":0,"exp":"No, it acts under statutory obligations, although competition law still applies."},{"q":"What happens if two local bus companies enter into an informal verbal agreement to divide tourist excursion markets in Munster ('territory sharing')?","options":["An unlawful cartel, even if unwritten","A valid informal commercial understanding","Permitted if passenger numbers are low","A matter for county council bylaws"],"correct":0,"exp":"Sharing markets between competitors is a cartel prohibited by section 4 and Article 101, even if it is a verbal agreement that is not written down."},{"q":"Which of the following cooperative activities between tour operators is PERMITTED under competition law?","options":["Jointly marketing a wider range of tours that they could not offer individually","Sharing back-office costs or coordinating certain logistics","Establishing a separate jointly-owned company to run and market tours collectively (provided competition is not eliminated)","All of the above"],"correct":3,"exp":"All the forms of cooperation on the list are allowed, because they benefit the passenger without eliminating competition."},{"q":"In Case Study 29P (Lax Bus Services Ltd), Lax is approached by a competitor to develop a mutual multi-operator ticketing scheme. Is such a scheme legal under competition law?","options":["Yes, if strict rules are followed","No, all multi-operator ticketing is illegal","Only if Lax buys out the competitor","Only if the Minister for Transport approves"],"correct":0,"exp":"Yes, with strict fair competition rules."},{"q":"According to the official CILT Case Study marking scheme for Lax Bus Services Ltd, Rule 1 for a legal multi-operator ticketing scheme is:","options":["Voluntary and non-exclusive participation","All operators charge identical single fares","Fares must rise by 20% every single year","Tickets may be sold only at bus stations"],"correct":0,"exp":"Rule 1 of the case: participation must be voluntary and non-exclusive; nobody is obliged to join, anyone can leave and other operators can join on reasonable terms."},{"q":"Why must a multi-operator ticketing scheme satisfy the 'voluntary and non-exclusive' requirement?","options":["To avoid shutting out other operators","To reduce VAT payments to Revenue","To let drivers work without tachographs","To extend the vehicles' motor tax validity"],"correct":0,"exp":"Avoiding restricting competition or excluding third parties."},{"q":"According to Case Study 29P, Rule 2 regarding fares in a multi-operator ticketing scheme states:","options":["No fixing of individual fares outside the ticket","All individual route fares are fixed together","Individual fares must be banned entirely","The NTA sets the drivers' hourly wages"],"correct":0,"exp":"They can agree the price of the joint ticket, but they must set their individual fares separately."},{"q":"According to Case Study 29P, Rule 3 regarding revenue sharing in a multi-operator ticketing scheme requires:","options":["Fair sharing based on verifiable usage data","All revenue split 50/50 whatever the usage","All proceeds go to the largest operator","Cash is paid directly to the drivers"],"correct":0,"exp":"A transparent mechanism based on objective usage data."},{"q":"Why is a transparent, objective revenue-sharing mechanism required in a multi-operator ticketing scheme?","options":["It avoids hidden subsidies between operators","It removes the need for financial audits","It qualifies the fleet for free diesel","It replaces the Transport Manager CPC rule"],"correct":0,"exp":"A clear and objective revenue split avoids hidden subsidies and unfair advantages between operators."},{"q":"According to Case Study 29P, Rule 4 regarding information exchange between participating operators prohibits:","options":["Sharing sensitive data like costs or future prices","Exchanging route maps and leaflets for passengers","Printing joint timetables for connecting services","Displaying shared signs at bus stops"],"correct":0,"exp":"Exchange of commercially sensitive information."},{"q":"Why is the exchange of commercially sensitive information strictly forbidden between competitors in a ticketing scheme?","options":["It prevents collusion between competitors","It breaks the copyright on timetables","It increases the operators' phone bills","It causes delays to bus services"],"correct":0,"exp":"It prevents collusion and preserves independent competition."},{"q":"According to Case Study 29P, Rule 5 states that the ticketing scheme MUST:","options":["Directly benefit passengers","Raise operator profit margins by 30%","Force passengers to buy monthly passes","Exclude student and child discounts"],"correct":0,"exp":"Rule 5: the joint ticket must directly benefit the passenger (more convenience, more ticket options or simpler journeys)."},{"q":"According to Case Study 29P, Rule 6 regarding third-party operators requires:","options":["No exclusion of other operators","Blocking new entrants from the market","Making third operators pay double fees","Selling only to existing customers"],"correct":0,"exp":"Rule 6: other operators cannot be excluded; the scheme must be open to more joining in the future."},{"q":"What is the maximum score awarded for answering all six rules correctly in the CILT Case Study 29P question?","options":["84 marks","20 marks","50 marks","100 marks"],"correct":0,"exp":"The case study question is worth 84 marks: 14 for each of the 6 rules with its explanation."},{"q":"When an operator hires a vehicle to cover extra work, what licensing procedure MUST be completed before the vehicle is used on public roads?","options":["Add it to the operator licence via RTOL","Paint it in the company livery and colours","The driver must take a new driving test","No licensing change is needed for hired ones"],"correct":0,"exp":"A vehicle hired to cover extra work must first be added to the operator licence, through the RTOL."},{"q":"If an operator sub-contracts transport work to another licensed operator, who retains ultimate legal responsibility for compliance with drivers' hours, tachographs, and vehicle roadworthiness?","options":["The main contractor stays fully responsible","Only the sub-contractor doing the work","Neither operator, once it is sub-contracted","The company that leased out the vehicle"],"correct":0,"exp":"The main operator remains fully responsible."},{"q":"What risk does an operator face if their Transport Manager knowingly participates in anti-competitive cartel conduct or bid-rigging?","options":["Prosecution, fines and loss of good repute","A minor verbal reprimand from the CILT","Free legal representation from the CCPC","An automatic 2-year licence extension"],"correct":0,"exp":"Prosecution, fines and loss of Good Repute."},{"q":"If two local bus companies merge, and a rival operator believes the merger will substantially lessen competition to the detriment of passengers, to which body should the complaint be submitted?","options":["Competition and Consumer Protection Commission (CCPC)","Road Safety Authority (RSA)","Chartered Institute of Logistics and Transport (CILT)","Workplace Relations Commission (WRC)"],"correct":0,"exp":"Mergers that may reduce competition are reported to the CCPC."},{"q":"Under the Competition Act 2002, can informal 'understandings' or verbal 'gentlemen's agreements' between transport managers breach competition law?","options":["Yes, if they restrict competition","No, only signed written contracts can","Only if they are recorded on video","Only if a solicitor witnessed them"],"correct":0,"exp":"Yes, verbal agreements are also illegal."},{"q":"What is the ultimate objective of competition rules in the Irish road passenger transport sector?","options":["Fair competition and real choice for passengers","To force small operators out of business","To maximise government revenue from ticket taxes","To restrict passenger travel between counties"],"correct":0,"exp":"Protecting fair competition and ensuring choice/quality/fair prices."}]},"31":{"title":"Topic 31 - Fares, Revenue Collection and Tenders","questions":[{"q":"Which organization in Ireland is responsible for administering and regulating Public Service Obligation (PSO) tendered bus contracts under Regulation (EC) No 1370/2007?","options":["Competition and Consumer Protection Commission (CCPC)","National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Social Protection (DSP)"],"correct":1,"exp":"The NTA manages and regulates public service obligation (PSO) bus contracts, under Regulation 1370/2007."},{"q":"In Ireland, which government department administers the Free Travel Scheme for eligible passengers?","options":["Department of Transport","Department of Social Protection (DSP)","National Transport Authority (NTA)","Revenue Commissioners"],"correct":1,"exp":"The Free Travel Scheme (free travel for older people and other groups) is managed by the Department of Social Protection."},{"q":"What system is widely used on Irish urban and interurban bus networks for contactless, stored-value fare collection?","options":["TFI Leap Card","Oyster Card","Navigo Pass","Express Transit Pass"],"correct":0,"exp":"The TFI Leap Card is the rechargeable contactless card used on Irish buses."},{"q":"What is the primary function of an Electronic Ticket Machine (ETM) fitted on a modern bus?","options":["Issue tickets and record boarding data","Measuring the tread depth of the tyres","Controlling the engine cooling system","Renewing the motor tax automatically"],"correct":0,"exp":"Issuing tickets, recording boardings and reducing fraud/error."},{"q":"What risk is associated with traditional 'Cash on Bus' fare collection in One-Person-Operated (OPO) bus services?","options":["Fraud, cash security risks and delays","Buses driving faster to keep to time","Higher fuel use while the bus is waiting","Failure of the tachograph calibration"],"correct":0,"exp":"Taking cash on a driver-only bus has risks: fraud, security of the money and delays while change is given."},{"q":"How do modern Irish PSO bus operators mitigate cash handling risks on OPO vehicles?","options":["Sealed safes linked to the ETM; no counting","Drivers keep cash in their own pockets","Banning all cash payments completely","Passengers must pay with exact change"],"correct":0,"exp":"Sealed safes integrated with the ETM."},{"q":"What is the main commercial advantage of 'Pre-payment' ticketing systems (e.g. season tickets, period passes, multi-journey tickets) for transport operators?","options":["Better cash flow, loyalty and less fraud","It removes the need for motor insurance","Drivers need less CPC training each year","Buses can bypass their speed limiters"],"correct":0,"exp":"It improves cash flow and loyalty and reduces fraud."},{"q":"What feature is often incorporated into pre-paid period tickets or smartcards to prevent fraudulent misuse or sharing?","options":["Numbered tickets with matching photocards","A signature line for the driver to sign","A strip of magnetic recording tape","Scratch-off security panels on the back"],"correct":0,"exp":"Numbered tickets and matching numbered photo cards."},{"q":"Which of the following is NOT a primary function of a bus ticket issued to a passenger?","options":["Authorisation to travel","Receipt for monies paid","Source of market research and revenue protection data","Exemption from wearing seatbelts"],"correct":3,"exp":"Exempting from wearing a seatbelt — that is not a function of the ticket."},{"q":"What is a 'Graduated or Tapered Fare' scale?","options":["Pay more for longer trips, but less per km","A flat rate charged whatever the distance","A fare that doubles in rainy weather","A free travel pass given to all students"],"correct":0,"exp":"The price per km decreases as the distance increases."},{"q":"On a tapered fare scale, if a 1 km journey costs 50 cents (50c/km) and a 4 km journey costs €1.30, what is the effective cost per km for the 4 km passenger?","options":["50 cents / km","40 cents / km","32.5 cents / km","25 cents / km"],"correct":2,"exp":"Cost per km = price ÷ km = 1.30 ÷ 4 = 32.5 cents per km. With a tapering fare, each km is cheaper the further you go."},{"q":"What is a 'Coarse Scale Taper' in bus fare structures?","options":["A large drop in price per km as distance grows","A fare structure with no price differences","A fare structure used only on school buses","A flat fare charged across an entire city"],"correct":0,"exp":"A fare with a 'coarse scale taper': the price per km falls sharply as the distance increases."},{"q":"What is a 'Flat Rate Fare'?","options":["One fixed price whatever the distance","A fare rising by 10c for every kilometre","A fare charged only on flat terrain","A discounted fare for night shift workers"],"correct":0,"exp":"A single fixed price, whatever the distance."},{"q":"What feature of smartcard ticketing (like TFI Leap Card) stops a passenger from being charged further once they reach a defined daily or weekly spend limit?","options":["Fare capping","Overdraft protection","Automatic refund","All of the above"],"correct":0,"exp":"Fare capping puts a ceiling on daily or weekly spending: once the limit is reached, further journeys in that period are not charged."},{"q":"What is a 'Zonal Fare' structure?","options":["Flat fares within zones set by the NTA","A fare based on vehicle seating capacity","A fare agreed between driver and passenger","A ticket valid only in airport zones"],"correct":0,"exp":"Flat fares within defined geographical zones."},{"q":"What operational challenge arises from 'Peak Requirements' in commuter bus services?","options":["Extra buses and crews at peaks, idle off-peak","Engines overheating in the summer months","Higher fuel prices at the pumps at night-time","Lower tachograph driving limits at rush hour"],"correct":0,"exp":"High demand at peak times with under-use off-peak."},{"q":"How can operators mitigate the financial impact of peak fleet requirements?","options":["Cheaper off-peak fares, or hiring in at peaks","Charging double fares during off-peak hours","Cancelling every off-peak service on the route","Letting buses carry standing passengers only"],"correct":0,"exp":"Reduced off-peak fares or subcontracting at peak times."},{"q":"What are 'Concessionary Fares'?","options":["Free or reduced fares for certain groups","Fares charged only to foreign tourists","Fares paid by drivers to operate buses","Fares charged on bank holiday weekends"],"correct":0,"exp":"Discounted/free fares for specific categories."},{"q":"Which concessionary fare categories are compulsory under Irish legislation/NTA rules?","options":["Free Travel, Companion, Young Adult and Child","Corporate executive and business discounts","Passes for airline and airport staff","Passes for guests of local hotels"],"correct":0,"exp":"Free Travel, Companion Pass, Young Adult, Child/Student."},{"q":"How are operators reimbursed for carrying DSP Free Travel scheme passengers on PSO routes in Ireland?","options":["DSP/NTA formulas based on recorded boardings","Cash handed directly to drivers by inspectors","Fuel tax rebates paid by the Revenue","Free vehicle maintenance from the council"],"correct":0,"exp":"DSP/NTA formulas based on recorded boardings."},{"q":"What EU Regulation governs Public Service Obligations (PSO) and the tendering of public passenger transport services by rail and road?","options":["Regulation (EC) No 561/2006","Regulation (EC) No 1370/2007","Regulation (EU) No 165/2014","Directive 2006/126/EC"],"correct":1,"exp":"Regulation 1370/2007 regulates public service obligations (PSO) and the tendering of public passenger transport."},{"q":"What is the standard maximum contract duration for a local bus service PSO contract awarded by the NTA?","options":["5 years","3 years","15 years","25 years"],"correct":0,"exp":"According to the book, a local bus PSO contract normally lasts 5 years, and can reach 10 if the operator invests heavily in vehicles."},{"q":"Under Irish tendering rules, what is the absolute legal maximum length permitted for a local bus service contract?","options":["5 years","8 years","12 years","20 years"],"correct":1,"exp":"The book gives 8 years as the maximum legal duration in Ireland for a local bus contract."},{"q":"What is a 'Gross Cost Contract' in public transport tendering?","options":["Operator gets a fixed fee; authority keeps fares","Operator keeps all revenue and gets no subsidy","The operator sets ticket prices freely","A contract paid according to fuel consumption"],"correct":0,"exp":"The operator charges a fixed fee; the authority keeps the revenue."},{"q":"What is a 'Net Cost Contract' in public transport tendering?","options":["Operator keeps fares and gets a balancing subsidy","The authority keeps all of the fare revenue","No subsidy is paid under any circumstances","The operator carries no financial risk at all"],"correct":0,"exp":"The operator keeps the revenue and receives a balancing subsidy."},{"q":"Under a Gross Cost Contract, who bears the commercial revenue/traffic risk?","options":["The tendering authority","The transport operator","The bus drivers","The vehicle manufacturer"],"correct":0,"exp":"Gross cost: the NTA keeps the fare revenue and pays the operator a fixed amount, so the revenue risk lies with the authority."},{"q":"Under a Net Cost Contract, who bears the revenue risk (including competition risk)?","options":["The transport operator","The tendering authority (NTA)","The Department of Social Protection","The passengers"],"correct":0,"exp":"Net cost: the operator keeps the fares and receives a subsidy, so the revenue risk is theirs."},{"q":"Under Irish procurement law, must the NTA automatically accept the lowest financial bid when awarding a public service contract?","options":["No, it looks for the best value for money","Yes, the lowest bid must always be chosen","Yes, unless the bidder is a foreign company","No, contracts are awarded by lottery"],"correct":0,"exp":"Best value for money, not just the lowest price."},{"q":"What is a key duty of tendering authorities (NTA/local authorities) to ensure fair competition during public bus service tenders?","options":["Not favouring large operators, e.g. smaller lots","Banning small operators from the tenders","Forcing all bidders to use the same depot","Fixing driver wages across all companies"],"correct":0,"exp":"Not restricting competition or artificially favouring large operators."},{"q":"Under Regulation (EC) 1370/2007 (Article 5), what is the 'De Minimis' direct-award contract limit for standard public passenger transport contracts?","options":["Under €1 million a year or 300,000 km a year","Under €5 million a year in average value","Under 50,000 km of services each year","A flat rate of €100,000 for each contract"],"correct":0,"exp":"De minimis (direct award without a tender): an average of less than €1 million a year OR less than 300,000 km a year."},{"q":"For small and medium-sized operators (SMEs operating not more than 23 vehicles), to what threshold can the De Minimis direct-award limits be increased?","options":["Under €2 million or 600,000 km a year","Under €10 million in average annual value","Up to 1,500,000 kilometres per year","No increase is permitted for SMEs"],"correct":0,"exp":"For SMEs with 23 vehicles or fewer, the limits rise to €2 million OR 600,000 km a year."},{"q":"Does operating under a De Minimis direct-award contract exempt an operator from vehicle licensing and safety rules?","options":["No, all licensing and safety rules still apply","Yes, de minimis contracts are unregulated","Only if they operate minibus services","Only during the first year of operation"],"correct":0,"exp":"No, it must fully comply with all the rules."},{"q":"Under what circumstances can the NTA directly award a bus service contract without a full competitive tendering process?","options":["Emergencies, no suitable tender, or de minimis","Whenever an operator asks for extra funding","Only during years of national elections","For all international coach tours and trips"],"correct":0,"exp":"Emergencies, unforeseen demand, no suitable bids, or De Minimis."},{"q":"What information must tendering authorities publish following the award of a public service contract?","options":["Scope, winner, reasons, highest and lowest bids","Bank account details of the operator's directors","Names and home addresses of all bus drivers","The exact fuel prices the operator paid"],"correct":0,"exp":"Scope, winner, justification and bid amounts."},{"q":"What document records all ticket sales, boarding stages, and cash collected by a driver at the start and end of a shift?","options":["Duty waybill","Running board","Driver logbook","Tachograph chart"],"correct":0,"exp":"The shift waybill records the tickets sold, the stops and the money collected at the start and end."},{"q":"In Stage Test questions, which system is considered the most secure against fraudulent misuse of pre-paid period tickets?","options":["Numbered tickets with matching photocards","Unnumbered tickets and unnumbered cards","Verbal declarations made by the passengers","Plain paper receipts issued by the driver"],"correct":0,"exp":"Numbered tickets with matching numbered photo cards."},{"q":"Why is 'Cross-Subsidisation' used within public transport networks?","options":["Profitable routes support needed rural routes","To avoid paying corporation tax on profits","To reduce the cost of vehicle maintenance","To get rid of overtime pay for drivers"],"correct":0,"exp":"Profitable routes support necessary rural routes."},{"q":"What type of contract fee arrangement is used when an operator is paid a fixed sum per kilometre or per day to operate a service regardless of passenger numbers?","options":["Gross Cost Contract","Net Cost Contract","Spot Hire Agreement","Open Book Management Contract"],"correct":0,"exp":"Paying the operator a fixed amount per km or per day, however many passengers there are, is a gross cost contract."},{"q":"What state support in Ireland provides financial funding to operators upgrading fleets to low-emission or zero-emission electric buses?","options":["SEAI supports and NTA procurement","A Revenue VAT rebate scheme only","Local county council grants only","Road Safety Authority grants"],"correct":0,"exp":"SEAI supports / NTA procurement frameworks."},{"q":"What is the ultimate objective of fare regulation, revenue collection auditing, and competitive tendering in Irish public transport?","options":["Transparency, no fraud, value for public money","Maximising ticket prices for private operators","Driving small bus companies out of the market","Reducing the number of bus routes in Ireland"],"correct":0,"exp":"Financial transparency, preventing fraud and giving good value for public money."}]},"32":{"title":"Topic 32 - Route Planning, Timetabling & Frontier Crossings","questions":[{"q":"What is the first essential tool required by a transport manager when planning a new bus or coach route?","options":["A clear, detailed map of the area","A tachograph calibration sheet","A list of local hotels","A fuel price comparison app"],"correct":0,"exp":"A clear map with origin/destination points, ferry terminals and main roads."},{"q":"Why might taking the shortest geographic route sometimes take the longest travel time for a passenger coach?","options":["Congestion, steep hills or weight limits","Toll charges are higher on shorter roads","Sat-nav does not work on short routes","Drivers need extra breaks on short routes"],"correct":0,"exp":"It may pass through congested or restricted areas."},{"q":"Which of the following physical road restrictions MUST be checked before dispatching a vehicle on an international or domestic route?","options":["Height restrictions on tunnels, hotel canopies, and terminal buildings","Weight restrictions on bridges and access roads","Vehicle manoeuvrability restrictions in historic inner cities or accommodation complexes","All of the above"],"correct":3,"exp":"Before sending a vehicle, all the restrictions on the list must be checked: heights, weights, widths, bans, etc."},{"q":"What vehicle technical specifications must be matched to steep mountain gradients on alpine or hilly routes?","options":["Engine power, gearing and retarders","Seat fabric and upholstery quality","On-board Wi-Fi router speed","Paint colour and livery finish"],"correct":0,"exp":"Engine power, gearbox ratios and secondary braking."},{"q":"What equipment is legally required when travelling through mountainous areas or designated winter zones under adverse weather conditions ('équipements spéciaux')?","options":["Snow chains or winter tyres","Air conditioning units","Spare seat cushions and blankets","Extra rolls of ticket paper"],"correct":0,"exp":"Approved snow chains or winter tyres."},{"q":"Which major alpine tunnel links France and Italy directly through the Alps?","options":["Fréjus and Mont Blanc tunnels","Channel Tunnel and Øresund Link","St Gotthard and Arlberg tunnels","Somport and Vielha tunnels"],"correct":0,"exp":"Between France and Italy, through the Alps, are the Fréjus and Mont Blanc tunnels."},{"q":"What is the length of the shuttle train journey through the Channel Tunnel (Le Shuttle) between Folkestone (UK) and Calais (France)?","options":["80 minutes","30 minutes","45 minutes","120 minutes"],"correct":0,"exp":"According to the book, the Le Shuttle journey through the Channel Tunnel, from leaving Folkestone to arriving in Calais, takes about 80 minutes."},{"q":"What are the maximum vehicle dimensions accepted on Le Shuttle passenger trains in the Channel Tunnel?","options":["Up to 12 metres long, 2.5 metres wide, and 3.8 metres high","Up to 18 metres long, 2.6 metres wide, and 4.2 metres high","Unlimited length, width, and height","Up to 15 metres long, 2.55 metres wide, and 4.0 metres high"],"correct":1,"exp":"Le Shuttle accepts vehicles up to 18 m long, 2.6 m wide and 4.2 m high."},{"q":"Which major European link consists of a tunnel, a bridge, and a man-made island connecting Copenhagen (Denmark) and Malmö (Sweden)?","options":["Øresund Link","Mont Blanc Tunnel","Channel Tunnel","All of the above"],"correct":0,"exp":"The Øresund link joins Copenhagen and Malmö: a tunnel, an artificial island and a bridge, 16 km in total."},{"q":"What international road numbering system was developed under the United Nations Economic Commission for Europe (UNECE) using the 'E' prefix?","options":["The AGR route numbering system","The TEN-T core network","The Schengen route system","The Interbus route network"],"correct":0,"exp":"European 'E' roads follow the UN (UNECE) AGR system."},{"q":"Under the AGR European route numbering system, how are main North-South routes identified?","options":["Route numbers ending with a 0","Route numbers ending with a 5","Route numbers ending with an odd digit","Route numbers prefixed with the letter 'N'"],"correct":0,"exp":"Your book (M32 p.3) says that the main north-south routes end in 0 and the east-west ones in 5: give that answer in the exam. Note: in reality it is the other way round (the E20 and the E30 run west to east)."},{"q":"Under the AGR European route numbering system, how are principal East-West routes identified?","options":["Route numbers ending with a 0","Route numbers ending with a 5","Route numbers ending with an even digit","Route numbers prefixed with 'M'"],"correct":1,"exp":"Your book (M32 p.3) says that the main east-west routes end in 5 and the north-south ones in 0: give that answer in the exam. Note: in reality it is the other way round."},{"q":"What is the EU initiative developed to build upon UNECE work to ensure speedy movement of goods and passengers across Europe?","options":["TEN-T transport networks","The SOLAS Convention","The Schengen Agreement","The AETR Agreement"],"correct":0,"exp":"The Trans-European Transport Network (TEN-T) is the EU's plan to connect Europe with good routes for people and goods."},{"q":"How can transport operators utilize ferry journeys to optimize driver productivity and compliance with EU Regulation 561/2006?","options":["Drivers take daily or weekly rest on board","Drivers keep driving on the ferry deck","Ferry time is not recorded on tachographs","Ferry travel never counts towards rest"],"correct":0,"exp":"They can take their daily/weekly rest on board, with suitable cabins."},{"q":"What is the definition of 'Headway' in bus timetabling terminology?","options":["The interval between buses on a route","The total time taken for a round trip","The maximum speed reached by a coach","The layover time spent at the terminus"],"correct":0,"exp":"Headway: minutes between one bus and the next on the same route (for example, one every 15 minutes)."},{"q":"What is the definition of 'Frequency' in bus timetabling?","options":["Buses passing a point in a given time","The distance between two bus stops","The time spent cleaning the vehicle","The total length of a driver's shift"],"correct":0,"exp":"Frequency: how many buses pass a point in a given time (for example, 4 an hour). Frequency = 60 ÷ headway."},{"q":"What is the mathematical relationship between a 20-minute Headway and Frequency?","options":["It equals a frequency of 3 buses per hour","It equals a frequency of 5 buses per hour","It equals a frequency of 2 buses per hour","Headway and frequency are not related at all"],"correct":0,"exp":"Frequency = 60 ÷ headway = 60 ÷ 20 = 3 buses an hour."},{"q":"What is 'Layover Time' (or 'Stand Time') at a bus terminus?","options":["Terminus time for blinds, waybills and breaks","Time spent driving in heavy city traffic","Time spent refuelling at the depot pumps","Time spent in the workshop for maintenance"],"correct":0,"exp":"Time to change the destination, complete the waybill and take breaks."},{"q":"What is 'Recovery Time' in bus scheduling?","options":["Spare time to absorb traffic delays","Time allowed to repair a broken engine","Time spent resting overnight in a hotel","Time taken to recover unpaid fares"],"correct":0,"exp":"Recovery time: a margin built into the timetable to absorb traffic delays so the next journey leaves on time."},{"q":"What is 'Running Time'?","options":["Time for one journey between termini","Time the bus spends idling in the garage","The total hours a driver works in a week","Time taken to fill the diesel tank"],"correct":0,"exp":"Total time for a journey between two terminals."},{"q":"What is the standard formula used to calculate the Number of Vehicles required to operate a scheduled bus service?","options":["(Running time + stand time) x 2 ÷ headway","(Running time + headway) x 2 ÷ stand time","Route distance ÷ average speed x 2","Total passengers ÷ seats per vehicle"],"correct":0,"exp":"No. of vehicles = (journey time + layover) × 2 ÷ headway, rounded up."},{"q":"Using the standard formula, if a single journey Running Time is 45 minutes, Stand Time is 15 minutes, and Headway is 15 minutes, how many buses are required?","options":["8 buses","4 buses","6 buses","10 buses"],"correct":0,"exp":"(45 + 15) × 2 = 120 minutes per round trip; 120 ÷ a 15-minute headway = 8 buses."},{"q":"What formula is used to calculate the time taken between bus stops?","options":["(Distance x 60) / Average Speed","(Distance / 60) x Speed","Headway / Frequency","Running Time + Layover Time"],"correct":0,"exp":"Minutes between stops = distance × 60 ÷ average speed. Example: 10 km at 40 km/h = 15 minutes."},{"q":"What formula is used to calculate the number of driver duties required to operate a bus service?","options":["(Buses x hours each bus works) ÷ shift length","(Buses x shift length) ÷ hours each bus works","Total revenue ÷ average fare per passenger","Total fleet size x 2 drivers per bus"],"correct":0,"exp":"(No. of buses × hours of operation) ÷ length of shift."},{"q":"What historical agreement created a 29-country borderless area across Europe where internal border checks were abolished?","options":["Schengen Agreement","Interbus Agreement","SOLAS Convention","CMR Convention"],"correct":0,"exp":"The Schengen agreement removed checks at internal borders. Ireland is not in Schengen."},{"q":"Did Ireland sign the Schengen Agreement to abolish border checks?","options":["No, it kept border checks, partly for the CTA","Yes, Ireland was one of the founding members","Yes, Ireland joined Schengen in 2020","It is an associate member with no border checks"],"correct":0,"exp":"No, Ireland keeps border controls for security and because of the CTA with the UK."},{"q":"What minimum remaining validity is required on a passport for Irish drivers travelling to non-EU destination countries?","options":["3 months beyond departure; 6 for some states","No minimum validity is required at all","At least 5 years left on the passport","At least 12 months from the date of departure"],"correct":0,"exp":"For non-EU countries, the passport must be valid for at least 3 months beyond departure (6 months in some countries)."},{"q":"Which customs channel at Irish points of entry must be selected when travelling from a country outside the EU with no banned/restricted goods within allowance?","options":["Red Channel","Green Channel","Blue Channel","Yellow Channel"],"correct":1,"exp":"Green channel: you are arriving from outside the EU and have nothing to declare. Blue: you are coming from another EU country. Red: you have something to declare."},{"q":"Which customs channel at points of entry is selected when travelling within the EU with no banned or restricted goods?","options":["Red Channel","Green Channel","Blue Channel","Yellow Channel"],"correct":2,"exp":"Blue channel: arriving from another EU country with nothing prohibited or restricted."},{"q":"Under Irish immigration law, what maximum penalties can be imposed on both driver and operator if illegal immigrants are discovered hidden in a coach?","options":["Up to €3,000 each, or up to 10 years in prison","Only a verbal warning from the port officials","Immediate revocation of the vehicle registration","A €100 fine for each passenger carried"],"correct":0,"exp":"Up to €3,000 per person, or up to 10 years in prison."},{"q":"What are the THREE legal defenses available to an operator or driver facing conviction for carrying concealed illegal immigrants?","options":["Unaware, effective security system, used correctly","CVRT passed, driver on time, fuel tank full","Cash fares, leased vehicle, route under 50 km","Poor weather, heavy traffic, double-deck bus"],"correct":0,"exp":"No knowledge/suspicion, and an effective security system that is working properly."},{"q":"What technology facility deployed at ferry ports uses passive millimetric waves to detect stowaways in moving vehicles up to 10 mph (16 km/h)?","options":["Passive millimetric wave scanner","DSRC roadside transponder","Tachograph motion sensor","GPS tracking unit"],"correct":0,"exp":"PMMW (Passive Millimetric Wave): it detects stowaways inside vehicles passing slowly (up to 16 km/h) at ferry ports."},{"q":"What international convention administered by the International Maritime Organization (IMO) governs passenger lists, life-saving appliances, and public address systems on ferries?","options":["SOLAS Convention","Interbus Agreement","AGR Agreement","All of the above"],"correct":0,"exp":"SOLAS (Safety of Life at Sea) regulates passenger lists, life-saving equipment and public address systems on ferries."},{"q":"Under the Package Holidays and Travel Trade Act 1995 (Package Travel Regulations), what defines a statutory 'Package Tour'?","options":["Two or more elements, one price, over 24 hours","Any standard coach ticket bought in advance","A day trip under 24 hours with no hotel stay","Private hire of a taxi for three hours"],"correct":0,"exp":"Package holiday: at least 2 elements (transport, accommodation or other significant tourist services), sold together at an inclusive price, lasting more than 24 hours or including a night."},{"q":"In Case Study 32P (Manchester Excursions), Excursion A leaves Dublin at 11:00 for a rock concert at 20:00, departs Manchester at 00:00, and returns to Dublin at 07:00. Is Excursion A a 'Package Tour'?","options":["No: under 24 hours and no accommodation","Yes, because concert tickets are included","Yes, all ferry trips count as packages","Only if passengers buy food on board"],"correct":0,"exp":"No, it lasts less than 24h and does not include accommodation."},{"q":"In Case Study 32P, Excursion B leaves Dublin at 07:00 with theatre tickets, an overnight stay in a hotel, and returns to Dublin at 15:00 the next day. Is Excursion B a 'Package Tour'?","options":["Yes: over 24 hours with hotel and theatre","No, because it lasts under 48 hours","No, theatre tickets cancel the package rules","Only if a foreign company operates it"],"correct":0,"exp":"Yes, it lasts more than 24h and combines transport, accommodation and a tourist service."},{"q":"According to Case Study 32P, what TWO major consumer protection requirements MUST an operator provide under Package Travel Regulations?","options":["Security for clients' money and a clear brochure","Free meals for passengers and sunny weather","Unlimited luggage and free taxi transfers","Cash refunds for delays and double seats"],"correct":0,"exp":"Protection of the customer's money and a detailed brochure/contract."},{"q":"What rule applies to price increases for an agreed package tour under Package Travel Regulations?","options":["None in the last 30 days; others per the contract","Prices can be doubled at any time without notice","Prices may rise freely up to the day of departure","Prices are set each year by the NTA"],"correct":0,"exp":"Prohibited in the 30 days before, and they must be provided for in the contract."},{"q":"What action must an operator take if a driver encounters unexpected tunnel height restrictions or road closures on a route?","options":["Use planned diversions and update passengers","Force the vehicle through whatever its height","Abandon the vehicle and cancel the trip","Exceed the speed limiter to make up time"],"correct":0,"exp":"Use pre-planned alternative routes and give notice of the new ETA."},{"q":"What is the ultimate objective of effective route planning, timetabling, and frontier crossing management?","options":["Safe, efficient, legal and smooth journeys","Maximising the toll payments collected","Eliminating break periods for the drivers","Restricting coaches to single cities"],"correct":0,"exp":"Safety, efficiency, regulatory compliance and customer protection."}]},"101":{"title":"Mock Exam 1","questions":[{"q":"What happens to sales and profitability during the 'Maturity' stage of a product life cycle?","options":["Sales growth slows and profits start to fall","Development costs are incurred for the first time","Profits rise fast with no competition","Sales fall to zero almost immediately"],"correct":0,"exp":"- Correct option (A): In the maturity stage, sales slow down because the initial market demand has already been met, and profits start to fall due to increased competition.\n- Incorrect options: (B) Happens in the 'Development' stage. (C) Happens in the 'Growth' stage. (D) Happens in the 'Decline' stage."},{"q":"What does 'Market share' measure?","options":["The total seating capacity of the fleet","Fixed assets as a ratio of current liabilities","The % of the total market a business holds","The % of share capital owned by directors"],"correct":2,"exp":"- Correct option (C): Market share is the percentage of sales or customers a company has in relation to the total market in its sector and region.\n- Incorrect options: (A) Measures operational capacity, not the market. (B) Is a financial liquidity/solvency ratio. (D) Refers to the ownership structure (shares), not the commercial market."},{"q":"Why is face-to-face selling primarily reserved for large contracts?","options":["Travelling salesmen are required for shops by law","Selling by phone is prohibited by the WRC","Direct mail always has a 100% conversion rate","It is costly, so only worth it for big deals"],"correct":3,"exp":"- Correct option (D): Personal selling involves travel costs, subsistence and the salesperson's time, so it is a very expensive strategy that only pays off when high-value contracts are being negotiated.\n- Incorrect options: (A) There is no such legal requirement. (B) Telephone selling is legal and common. (C) Direct mail actually has a very low conversion rate."},{"q":"How is market segmentation defined?","options":["Splitting a market into groups with similar needs","Splitting company shares among shareholders","Calculating the total national turnover of a firm","Merging rival transport firms into one group"],"correct":0,"exp":"- Correct option (A): Segmentation means dividing the overall market into smaller groups (niches) that share similar needs (e.g. school transport, luxury tourism).\n- Incorrect options: (B) Is distributing dividends or shares. (C) Is calculating turnover. (D) Is a merger or acquisition of companies."},{"q":"What is the primary purpose of conducting marketing research?","options":["To reduce the company's tax bill to zero","To base decisions on facts, not guesswork","To recruit qualified professional drivers","To agree terms with the trade unions"],"correct":1,"exp":"- Correct option (B): The aim of market research is to collect real data in order to make informed business decisions, reducing uncertainty and assumptions.\n- Incorrect options: (A) Taxes are handled by accounting/advisers. (C) Is a Human Resources task. (D) Is an Industrial Relations task."},{"q":"What is secondary data in marketing research?","options":["Information from brand-new postal surveys","Information that already exists somewhere","Confidential data held only by the Revenue","Unverified rumours heard about competitors"],"correct":1,"exp":"- Correct option (B): Secondary data is data that has already been collected (e.g. past sales reports, government censuses) and only needs to be extracted.\n- Incorrect options: (A) Would be primary research (primary data). (C) Is not accessible for marketing. (D) Rumours are not valid research data."},{"q":"What does General Transit Feed Specification (GTFS) data provide for public transport operators?","options":["Balance sheet audits for the Revenue Commissioners","Calibration records for driver tachographs","Timetable and route data for journey-planning apps","Direct debit mandates for fuel purchases"],"correct":2,"exp":"- Correct option (C): The GTFS format allows transport companies to share their timetables and routes in real time with third-party apps (such as Google Maps).\n- Incorrect options: (A) Is a financial matter. (B) Is drivers' hours legislation. (D) Is a purchasing and accounting matter."},{"q":"What does 'Physical evidence' refer to when marketing a service like road transport?","options":["The delivery receipt signed by the consignee","Visible items such as offices and logos","The weight limits of a bridge on the route","The mechanical condition of the brake pads"],"correct":1,"exp":"- Correct option (B): In the services marketing mix (7 Ps), \"physical evidence\" is everything the customer can see or touch that gives them confidence (uniforms, clean buses, logo, website).\n- Incorrect options: (A) Is a delivery note. (C and D) Are technical and maintenance specifications."},{"q":"Dismissal of an employee on what grounds is automatically deemed 'unfair' by the WRC, regardless of length of service?","options":["Redundancy through a fair selection process","Incompetence after training","Trade union membership and activities","Retirement at age 65 with objective justification"],"correct":2,"exp":"- Correct option (C): Dismissing someone for being a trade union member is an \"inadmissible reason\" and is automatically considered unfair dismissal from the first day of work.\n- Incorrect options: (A, B and D) Are legal and fair grounds for dismissal (fair dismissals) if the correct procedure is followed."},{"q":"What is the minimum threshold of proposed redundancies over a 30-day period that triggers collective redundancy rules in an establishment of 50 to 99 employees?","options":["3 or more redundancies","5 or more redundancies","30 or more redundancies","10 or more redundancies"],"correct":3,"exp":"- Correct option (D): By law, if a company has between 50 and 99 employees, planning 10 or more redundancies within 30 days triggers the collective redundancy rules.\n- Incorrect options: (A) Is not a legal threshold. (B) Is the threshold for companies with 21-49 employees. (C) Is the threshold for companies with more than 300 employees."},{"q":"Within how many days must an employer notify a new employee of their core terms of employment via the 'Day 5 Statement'?","options":["Within 14 days","Within 5 days","Within 1 month","Within 3 months"],"correct":1,"exp":"- Correct option (B): The law requires the 5 core terms (job, pay, hours, etc.) to be given within the first 5 days.\n- Incorrect options: (A and D) Are not legal deadlines. (C) Is the maximum deadline for giving the full contract (Written Statement of Terms), not the initial core terms."},{"q":"What is the maximum duration generally permitted for successive fixed-term contracts before objective justification is required?","options":["1 year","2 years","4 years","5 years"],"correct":2,"exp":"- Correct option (C): In Ireland, successive fixed-term contracts are limited to a maximum of 4 years. After that, the worker becomes permanent or an objective justification is required.\n- Incorrect options: (A, B and D) Are incorrect periods under the Fixed-Term Work Act 2003."},{"q":"A driver has been employed by a transport company for 15 years. How much notice must they give as a minimum if they wish to resign?","options":["One week","Twelve weeks","Fifteen weeks","None"],"correct":0,"exp":"- Correct option (A): The minimum legal notice the EMPLOYEE must give when resigning is always 1 week (after 13 weeks of work), regardless of their years of service.\n- Incorrect options: (B, C and D) The 8 weeks would apply if it were the COMPANY dismissing a worker with more than 15 years of service."},{"q":"Which of the following items must be submitted to the Companies Registration Office (CRO) when forming a limited company?","options":["Name of accountants and Corporation Tax registration","Compliance and capital statements, memo and articles","Driver CPC certificates of all the drivers","The logbooks of all company vehicles"],"correct":1,"exp":"- Correct option (B): To register a company with the CRO, Form A1 (which includes declarations of compliance and capital) and the constitution (Memorandum & Articles) are required.\n- Incorrect options: (A) Tax registration goes to Revenue, not the CRO. (C and D) Are transport operating documents, not company documents."},{"q":"When distributing money raised by the disposal of assets during a liquidation, which of the following has the highest priority for payment?","options":["Preferential debts (wages)","Liquidator's fees and expenses","Unsecured debts","Fixed-Charge (secured) creditors"],"correct":3,"exp":"- Correct option (D): Creditors with security over specific assets (fixed charge) are the first to be paid.\n- Incorrect options: (A) Preferential debts come after the liquidator's costs. (B) Are the second to be paid. (C) Unsecured creditors are the last."},{"q":"A statement confirming that shareholders have limited liability can be found in the company's:","options":["Memorandum of Association","Statement of Capital","Certificate of Incorporation","Articles of Association"],"correct":3,"exp":"- Correct option (D): The Articles of Association contain the internal rules and the express clause limiting the shareholders' liability to what they have invested.\n- Incorrect options: (A) Only expresses the wish to form the company. (B and C) Certify the capital and the incorporation, but do not contain the internal liability rules."},{"q":"What is the fundamental difference between a debenture holder and a shareholder?","options":["Shareholders get fixed interest, not dividends","Debenture holders get dividends and a vote","Debenture holders get interest and have no vote","Debenture holders own the company and vote"],"correct":2,"exp":"- Correct option (C): A 'debenture holder' is a lender (creditor), so they receive fixed interest and have no voting rights.\n- Incorrect options: (A) Shareholders receive variable dividends. (B and D) Shareholders are the ones who vote and the real owners of the company."},{"q":"For a valid contract to exist, which of the following factors must be present?","options":["Written offer, acceptance, consideration","Offer, acceptance and consideration","Verbal offer and written acceptance","Two directors signatures"],"correct":1,"exp":"- Correct option (B): The three compulsory legal elements of a contract are offer, acceptance and \"consideration\" (an exchange of value).\n- Incorrect options: (A and C) A contract does not have to be in writing to be valid; it can be verbal. (D) Is not a basic legal requirement."},{"q":"What is the key rule regarding dividend payments for ordinary and preference shares?","options":["Ordinary shareholders are paid before preference ones","Ordinary and preference shareholders are paid equally","Preference shareholders are paid before ordinary ones","Preference shareholders never receive a dividend"],"correct":2,"exp":"- Correct option (C): Preference shares have priority over ordinary shares when profits are distributed.\n- Incorrect options: (A, B and D) Contradict the legal definition of the priority of preference shares."},{"q":"Which of the following must be included on the business letters (headed stationery) of a limited company?","options":["The registered office address","The Company Secretary's name","The home address of all directors","The company's bank account details"],"correct":0,"exp":"- Correct option (A): The law requires company letterhead to include the company's registered address, its CRO number and its country of registration.\n- Incorrect options: (B) The secretary is not compulsory. (C) Personal addresses are not included. (D) Is not a CRO legal requirement."},{"q":"For what period is a Road Passenger Transport Operator Licence normally valid?","options":["3 years","5 years","Indefinitely","10 years"],"correct":1,"exp":"- Correct option (B): The passenger transport operator licence is normally valid for a period of 5 years.\n- Incorrect options: Licences are not indefinite and do not last 3 or 10 years under the European standard."},{"q":"Where a Transport Manager ceases to act in that role, what is the maximum period allowed to appoint a new one?","options":["1 year","3 months","1 month","6 months"],"correct":3,"exp":"- Correct option (D): The competent authority can grant a maximum of 6 months to replace the Transport Manager.\n- Incorrect options: (A, B and C) Do not reflect the grace period laid down by the regulation (Regulation EC 1071/2009)."},{"q":"In the case of a contracted Transport Manager, what are the restrictions regarding the undertakings and vehicles they can manage?","options":["4 transport undertakings with a maximum combined fleet of 50 vehicles","2 transport undertakings with a maximum combined fleet of 50 vehicles","4 transport undertakings with a maximum combined fleet of 100 vehicles","5 transport undertakings with a maximum combined fleet of 100 vehicles"],"correct":0,"exp":"- Correct option (A): An external (contracted) transport manager can manage a maximum of 4 different companies with a combined total fleet of up to 50 vehicles.\n- Incorrect options: They exceed the legal limits set to prevent a manager taking on more than they can effectively control."},{"q":"Which one of the following is exempt from the requirement to have a Road Passenger Transport Operator Licence?","options":["Transport for hire or reward of school students","Private hire transport for one-off events","Transport for hire or reward of passengers to charity events","Taking employees to work in the employer's vehicles"],"correct":3,"exp":"- Correct option (D): Own-account transport, such as an employer carrying its own employees in its own vehicles, is exempt.\n- Incorrect options: (A, B and C) Any passenger transport for \"hire or reward\" requires a commercial licence."},{"q":"An operator is proposing to run a local bus service with a single journey time of 40 minutes and 5 minutes stand time at each end. How many vehicles are required if the frequency is every 5 minutes?","options":["9 vehicles","10 vehicles","18 vehicles","20 vehicles"],"correct":2,"exp":"- Correct option (C): The outward journey is 40m + 5m layover = 45m. The return journey is another 45m. The total round trip time = 90 minutes. If a bus leaves every 5 minutes: 90 / 5 = 18 vehicles needed.\n- Incorrect options: (A, B and D) Are wrong calculations for this route."},{"q":"When a fare scale is tapered, the longer distance passenger is charged:","options":["Less per mile than the short distance passenger","The same per mile as the short distance passenger","More per mile than the short distance passenger","A flat rate per mile irrespective of distance travelled"],"correct":0,"exp":"- Correct option (A): A tapered fare means the total price rises, but the cost per kilometre or mile falls the longer the journey is.\n- Incorrect options: (B) Would be a standard linear fare. (C) Would penalise long journeys. (D) Is an unrealistic flat fare."},{"q":"Which one of the following is likely to be the most secure system of pre-paid tickets to prevent fraud?","options":["Unnumbered tickets and unnumbered photocards","Uniquely numbered tickets and matching numbered photocards","Uniquely numbered tickets and unnumbered photocards","Unnumbered tickets and uniquely numbered photocards"],"correct":1,"exp":"- Correct option (B): To prevent fraud, both the ticket and the photo identity card (photocard) must have unique numbers that match each other, preventing several people from using the same pass.\n- Incorrect options: (A, C and D) Leave security gaps because they do not link the ticket directly to the holder's identity."},{"q":"Jack Smith worked for Bloggs Ltd for ten years. Bloggs Ltd is bought by Lax Transport plc. Jack's continuous employment service will be calculated from when:","options":["Lax Transport took control","Lax Transport issued a new contract","Bloggs Ltd was removed from the register","He started work for Bloggs Ltd"],"correct":3,"exp":"- Correct option (D): Under the Transfer of Undertakings rules (TUPE), the worker's rights and length of service are kept and calculated from their original start date with the first company.\n- Incorrect options: (A, B and C) Would unfairly reset the worker's length of service, which is illegal."},{"q":"A pregnant employee employed for six months is entitled to:","options":["Maternity leave of up to 42 weeks","Maternity benefit irrespective of PRSI","Maternity leave of only 26 weeks","52 weeks of fully paid leave"],"correct":0,"exp":"- Correct option (A): She is entitled to 26 weeks of standard leave plus 16 additional unpaid weeks (42 weeks maximum in total).\n- Incorrect options: (B) The State benefit requires PRSI contributions. (C) Leaves out the 16 extra weeks. (D) That right does not exist in Ireland."},{"q":"What legal status does industrial action have if it is lawfully organized by a trade union following a proper ballot?","options":["It is classed as a 'wildcat strike' and unprotected","It converts employee contracts into fixed-term agreements","It is automatically prohibited by the WRC","It is regarded as 'protected' under the Unfair Dismissals Acts"],"correct":3,"exp":"- Correct option (D): If the strike is legal and was voted on in a secret ballot (proper ballot), the workers have legal immunity and cannot be dismissed for taking part in it (\"protected action\").\n- Incorrect options: (A) Wildcat strikes are unlawful. (B and C) Make no legal sense in this context."},{"q":"What is the general continuous service requirement for an employee to bring an ordinary claim of unfair dismissal to the WRC?","options":["6 months","1 month","1 year","2 years"],"correct":2,"exp":"- Correct option (C): As a general rule, 1 year (52 weeks) of continuous service is required to be able to claim ordinary unfair dismissal.\n- Incorrect options: (A and B) Are not enough. (D) The requirement is 1 year, not 2."},{"q":"Which document is essential for international bus or coach services within the EU?","options":["National Transport Authority permit","Community Licence","CVRT certificate","Driver CPC card"],"correct":1,"exp":"- Correct option (B): The Community Licence is the key operating document that authorises companies to carry out international passenger transport throughout the EU.\n- Incorrect options: (A) Is only for Ireland. (C) Is the vehicle's technical certificate (roadworthiness test), not a route permit. (D) Is the driver's qualification, not the company's authorisation."},{"q":"\"Closed Door Tours\" must be completed within a time limit of no more than:","options":["21 days","30 days","60 days","90 days"],"correct":1,"exp":"- Correct option (B): Occasional services known as 'Closed Door Tours' (the same bus carries the same group for the whole journey and returns to the point of departure) must be completed within a maximum of 30 days.\n- Incorrect options: (A, C and D) Are not the periods laid down by the European rules on occasional services."},{"q":"Which of the following international conventions deals with the creation and maintenance of a network of key road systems?","options":["Schengen Agreement","AGR","SOLAS","Interbus"],"correct":1,"exp":"- Correct option (B): The AGR Agreement (European Agreement on Main International Traffic Arteries) governs the construction and numbering of the main European road network (the \"E\" routes).\n- Incorrect options: (A) Deals with borders and visas. (C) Deals with maritime safety. (D) Deals with international occasional passenger transport."},{"q":"What is the purpose of the Schengen Agreement?","options":["Vehicles circulating freely within the EU","Harmonising tax-free goods at borders","No passport checks at internal EU borders","Allowing temporary importation of vehicles"],"correct":2,"exp":"- Correct option (C): The Schengen Area abolished systematic border checks at the internal borders of the signatory countries, allowing travel without passport checks.\n- Incorrect options: (A, B and D) Mix up customs, common market and vehicle rules, not the movement of people."},{"q":"Which document permits a coach to travel at up to 100 km/h on motorways in Germany?","options":["Community Licence","Vitesse 100 certificate","Eurovignette","Tempo 100 certificate"],"correct":3,"exp":"- Correct option (D): The Tempo 100 certificate is a German approval certifying that the bus meets the safety standards to travel at 100 km/h.\n- Incorrect options: (B) Is the French equivalent. (A) Is the European licence. (C) Is the toll system for heavy lorries."},{"q":"In France, the road sign \"equipements speciaux obligatoires\" requires drivers to:","options":["Give way to traffic approaching from the right","Beware of melting snow","Reduce speed in adverse weather conditions","Fit snow chains to the vehicle"],"correct":3,"exp":"- Correct option (D): \"Compulsory special equipment\" in French mountain areas indicates the legal obligation to fit snow chains or use winter tyres.\n- Incorrect options: (A, B and C) Do not reflect the mandatory equipment order."},{"q":"In Austria, coaches and other vehicles over 3.5 tonnes pay distance-based tolls using which on-board unit?","options":["GO-Box","eFlow tag","AutoPASS","LKW-Maut card"],"correct":0,"exp":"In Austria, vehicles over 3.5 t, coaches included, pay a toll per km with the GO-Box device. eFlow is the M50 in Ireland and AutoPASS is Norway's."},{"q":"Buses and coaches over one year old must generally undergo:","options":["An annual CVRT test","A driving test every two years","Emissions testing only","No testing once insured"],"correct":0,"exp":"- Correct option (A): Heavy commercial vehicles in Ireland must pass the CVRT inspection (the Irish roadworthiness test for commercial vehicles) every year from their first year.\n- Incorrect options: (B, C and D) The tests are not every two years, nor are they limited to emissions."},{"q":"On which of the following pieces of Irish road infrastructure are tolls charged to coaches? 1. M50 Motorway 2. Dublin Port Tunnel 3. Jack Lynch Tunnel 4. M1 Motorway 5. Limerick Tunnel","options":["1 and 2 only","2, 3 and 4 only","1, 2, 4 and 5 only","1, 2, 3, 4 and 5"],"correct":2,"exp":"- Correct option (C): In Ireland there are commercial tolls on the M50 (barrier-free), the Dublin Port Tunnel (free for heavy lorries at some times, but subject to a toll structure), the M1 and the Limerick Tunnel. The Jack Lynch Tunnel in Cork has NO toll.\n- Incorrect options: (A, B and D) Include the Jack Lynch Tunnel or leave out key toll motorways of the network."}]},"102":{"title":"Mock Exam 2","questions":[{"q":"For what period is a Road Passenger Transport Operator Licence normally valid?","options":["3 years","5 years","Indefinitely","10 years"],"correct":1,"exp":"- Correct option (B): The passenger transport operator licence in Ireland (and in the EU) is normally issued for a period of 5 years.\n- Incorrect options: (A, C, D) Are not the standard renewal periods set by the NTA and European rules."},{"q":"Where a Transport Manager ceases to act in that role for a road passenger transport undertaking, what is the maximum period allowed for the undertaking to appoint a new Transport Manager?","options":["1 year","3 months","1 month","6 months"],"correct":3,"exp":"- Correct option (D): If a Transport Manager resigns, dies or stops working, the competent authority can grant a maximum grace period of 6 months for the company to hire a new one.\n- Incorrect options: (A, B, C) Are incorrect periods under Regulation (EC) 1071/2009."},{"q":"In the case of a contracted Transport Manager, certain restrictions apply regarding the total number of undertakings and vehicles that he/she is allowed to manage. Which one of the following describes these restrictions?","options":["4 transport undertakings with a maximum combined fleet of 50 vehicles","2 transport undertakings with a maximum combined fleet of 50 vehicles","4 transport undertakings with a maximum combined fleet of 100 vehicles","5 transport undertakings with a maximum combined fleet of 100 vehicles"],"correct":0,"exp":"- Correct option (A): An external Transport Manager can only manage up to 4 different companies, as long as the total number of vehicles across all of them does not exceed 50.\n- Incorrect options: (B, C, D) Do not reflect the legal limit set to ensure the manager can exercise real and effective control."},{"q":"Which one of the following is exempt from the requirement to have a Road Passenger Transport Operator Licence for national operations?","options":["Transport for hire or reward of school students","Private hire transport for one-off events","Transport for hire or reward of passengers to charity events","Taking employees to work in the employer's vehicles"],"correct":3,"exp":"- Correct option (D): Carrying employees in vehicles owned by the company (own-account transport) has no direct commercial purpose (hire or reward), so it is exempt from the operator licence.\n- Incorrect options: (A, B, C) Any transport where there is payment or profit (hire or reward) requires a licence."},{"q":"In Ireland, motor tax for buses and coaches is primarily based on:","options":["Engine size","CO2 emissions","Seating capacity","Gross vehicle weight"],"correct":2,"exp":"- Correct option (C): Unlike cars (CO2/engine) or lorries (gross weight), motor tax for buses in Ireland is calculated in bands according to seating capacity.\n- Incorrect options: (A, B, D) Are tax bases for other types of vehicle, not for passenger buses."},{"q":"Which body issues PSV (Public Service Vehicle) licences in Ireland?","options":["Revenue Commissioners","Road Safety Authority (RSA)","National Transport Authority (NTA)","Department of Transport"],"correct":2,"exp":"- Correct option (C): The NTA (National Transport Authority) is the body responsible for regulating public transport and issuing PSV licences in Ireland.\n- Incorrect options: (A) Collects taxes. (B) Is responsible for road safety and driver tests (CVRT). (D) Is the government department, but it does not issue the operating licence directly."},{"q":"Interworking is the name given to which of the following activities?","options":["Using a driver to cover more than one route","Using a vehicle to cover more than one route","Two or more operators providing vehicles for one route","Two or more operators providing drivers for one route"],"correct":1,"exp":"- Correct option (B): \"Interworking\" in timetable planning means using the same bus (vehicle) to operate more than one route during the day, making the best use of the fleet.\n- Incorrect options: (A, C, D) Are incorrect definitions of this technical planning term."},{"q":"A local bus service operator runs two services. Both operate every 15 minutes. Service X has a single journey time of 44 minutes and 4 minutes stand time at the end. Service Y has a single journey time of 29 minutes and 4 minutes stand time. What is the minimum number of buses needed to operate these two services combined?","options":["10 buses","11 buses","12 buses","13 buses"],"correct":2,"exp":"- Correct option (C): Service X: (44+4) = 48m per trip x 2 = 96m round trip. At a 15m frequency, 96/15 = 6.4 (7 buses needed). Service Y: (29+4) = 33m x 2 = 66m round trip. 66/15 = 4.4 (5 buses needed). Total: 7 + 5 = 12 buses.\n- Incorrect options: (A, B, D) Are wrong calculations."},{"q":"An operator offering a 'package tour' must provide evidence of security for the refund of money and repatriation in the event of insolvency. Which of the following would be an acceptable means? 1. Bonding 2. Putting money into a subsidiary 3. Putting money into the control of a trustee","options":["1 and 3 only","1, 2 and 3","1 and 2 only","2 and 3 only"],"correct":0,"exp":"- Correct option (A): Package travel law requires the customer's money to be protected by a bond/insurance (bonding) or held by an independent trustee.\n- Incorrect options: (2) Putting it in a subsidiary company with the same owner does not protect the money if the company goes bust."},{"q":"Which type of passenger service normally requires an EU route authorisation?","options":["Occasional service","Special regular service under contract","Regular scheduled service","Private non commercial transport"],"correct":2,"exp":"- Correct option (C): International regular services (with fixed timetables and stops for the general public) are the ones that require an EU Route Authorisation.\n- Incorrect options: (A, B) Are usually covered simply by the Community Licence and a waybill or contract. (D) Is not commercial transport."},{"q":"Cabotage in passenger transport is best described as:","options":["Permanent domestic services in another state","Limited services within another EU state","Own-account passenger transport abroad","Domestic services within Ireland only"],"correct":1,"exp":"- Correct option (B): Cabotage allows an operator to carry out temporary and limited national transport within the borders of another EU country other than the one where it is established.\n- Incorrect options: (A) If it is permanent, it requires setting up a company in that country. (C and D) Are not definitions of cabotage."},{"q":"From which organisation may an operator obtain waybills for an occasional international service?","options":["Coach Tourism & Transport Council of Ireland (CTTC)","National Driver Licence Service (NDLS)","Interbus, Geneva","National Transport Authority (NTA)"],"correct":3,"exp":"- Correct option (D): In Ireland, the NTA is the competent authority that supplies the books of waybills needed for international occasional journeys under the Community Licence.\n- Incorrect options: None of the other organisations issues these official documents."},{"q":"Which of the following links would facilitate coach travel between France and Italy? 1. St Gotthard Tunnel 2. St Bernard Tunnel 3. Frejus Tunnel 4. Mont Blanc Tunnel","options":["1 only","2 and 3 only","3 and 4 only","1, 2 and 4 only"],"correct":2,"exp":"- Correct option (C): The Fréjus and Mont Blanc tunnels connect France directly with Italy.\n- Incorrect options: The St Gotthard and St Bernard mainly connect with Switzerland; they are not direct France-Italy crossings."},{"q":"An Irish driver would need a visa to enter which of the following countries?","options":["Ukraine","Poland","Romania","Bulgaria"],"correct":0,"exp":"- Correct option (A): Historically (and according to the CPC manuals for this exam), as Ukraine is not in the EU or the Schengen area, a visa is required to enter.\n- Incorrect options: (B, C, D) Are European Union countries, so Irish citizens have freedom of movement without a visa."},{"q":"Which authority administers the Commercial Vehicle Roadworthiness Test (CVRT) in Ireland?","options":["National Transport Authority","Road Safety Authority","Department of Transport","All of the above"],"correct":1,"exp":"- Correct option (B): The Road Safety Authority (RSA) is the State body that manages and supervises roadworthiness tests for commercial vehicles (CVRT).\n- Incorrect options: The NTA (A) regulates licences. Revenue (D) collects taxes. The Department (C) makes the laws."},{"q":"When is a commercial passenger vehicle generally required to undergo its first CVRT?","options":["When it reaches 6 months old","When it is first taxed","When it is 1 year old","After 3 years in service"],"correct":2,"exp":"- Correct option (C): Unlike private cars, which take 4 years, commercial passenger vehicles (buses) must pass their first roadworthiness test (CVRT) when they are one year old.\n- Incorrect options: (A, B, D) Are incorrect periods under Irish commercial vehicle law."},{"q":"VAT related records must be kept for a minimum period specified by law. This minimum period is:","options":["1 year","3 years","5 years","6 years"],"correct":3,"exp":"- Correct option (D): The Revenue Commissioners' rules in Ireland require all tax-related records (including VAT) to be kept for a minimum of 6 years.\n- Incorrect options: Shorter periods (A, B, C) expose the company to penalties in the event of an audit."},{"q":"A vehicle is designed to carry 15 passengers. Which classification is most likely to apply?","options":["Motor car","Minibus","Large bus","Heavy motor car"],"correct":1,"exp":"- Correct option (B): A vehicle with capacity for more than 8 passengers but not as large as a full-size bus, like this 15-seater, is classed as a Minibus (category D1).\n- Incorrect options: (A and D) Cars carry a maximum of 8 passengers. (C) A \"large bus\" usually has more than 22 seats or is a heavy vehicle."},{"q":"A two-part passenger vehicle allows passengers to move between the connected sections. Which classification best fits this description?","options":["Dual purpose vehicle","Articulated bus","Motor car","Long distance coach"],"correct":1,"exp":"- Correct option (B): An articulated bus is one made up of two sections joined by an articulated mechanism through which passengers can walk freely.\n- Incorrect options: (A) Refers to van-type goods/passenger vehicles. (D) Coaches are not usually articulated."},{"q":"Operators must keep copies of all maintenance records relating to licensed vehicles for a minimum period of:","options":["6 months","12 months","15 months","3 years"],"correct":2,"exp":"- Correct option (C): Irish transport law states that maintenance records (inspections, defects, repairs) for commercial vehicles must be kept for 15 months.\n- Incorrect options: Careful: tachograph records are kept for 12 months and tax records for 6 years, but maintenance is exactly 15 months."},{"q":"Since what date have speed limiters been mandatory in Ireland on PSVs with more than 8 passenger seats?","options":["1 January 2005","1 January 1995","1 January 2015","1 January 2020"],"correct":0,"exp":"Since 1 January 2005, PSVs with more than 8 seats (not counting the driver) must have a speed limiter: 100 km/h, or 65 km/h if they carry standing passengers.\n📍 Book M22 p.2"},{"q":"A driver has been ill and absent from work for two months. When starting back to work on a journey to France, which document should they carry to explain their incomplete tachograph records?","options":["Community Licence","Digital tachograph card","GHIC","Letter of attestation"],"correct":3,"exp":"- Correct option (D): The \"Letter of attestation of activities\" is the standard EU form the employer signs to explain that a driver has no driving records because they were on sick leave, on holiday or doing other work.\n- Incorrect options: (B) The card alone does not explain a two-month gap. (C) Is the health card. (D) Is for the company."},{"q":"A coach is fitted with 6 tyres costing €300 each. The tyres have a life of 80,000 km. What is the running cost of tyres per kilometre?","options":["2.25 c","0.0225 c","3.75 c","22.5 c"],"correct":0,"exp":"Tyres per km = (no. × price) ÷ km of life = (6 × 300) ÷ 80,000 = €0.0225 = 2.25 cents per km.\n📍 Book M14 p.9"},{"q":"Which of the following vehicle costs are both direct and fixed? 1. Vehicle Tax 2. Lubricants 3. Insurance 4. Tyres 5. Maintenance","options":["1 and 3 only","2 and 5 only","1, 4 and 5 only","2, 3 and 4 only"],"correct":0,"exp":"- Correct option (A): Motor tax and insurance are paid every year no matter what (fixed costs) and are allocated to a specific vehicle (direct).\n- Incorrect options: Tyres, lubricants and maintenance (2, 4 and 5) are VARIABLE costs, because they depend directly on how many kilometres the bus covers."},{"q":"Which organisation has responsibility under Competition laws to ensure fair and open competition in the bus industry in Ireland?","options":["The Chartered Institute of Logistics and Transport","The Department of Transport","The Road Safety Authority","Competition and Consumer Protection Commission"],"correct":3,"exp":"- Correct option (D): The CCPC is the State body that monitors monopolies and price-fixing agreements and protects consumer rights in all sectors, including transport.\n- Incorrect options: The other bodies deal with logistics, infrastructure legislation or road safety, not economic competition."},{"q":"A passenger on a local bus service claims that due to the late running of a journey, they missed an appointment and incurred costs of €100. What is the liability of the bus operator?","options":["The operator is not liable for the costs incurred by the passenger","The operator is liable for the whole costs incurred","Whatever is stated in the operator's conditions of carriage","A loss adjuster will determine liability"],"correct":0,"exp":"- Correct option (A): In public transport, operators are not liable for consequential losses (such as missing an appointment or a flight) caused by delays, as this is excluded in the conditions of service.\n- Incorrect options: (B, C, D) Contradict the legal principle that limits the liability of regular transport operators."},{"q":"The driver of a PSV operating a local service arrives at a stop with a queue including passengers with pushchairs. There is not enough room on the vehicle to store all pushchairs, and they cannot be placed on seats. What action should the driver take?","options":["All passengers, with pushchairs at the rear","All passengers, with pushchairs at the front","Only those whose pushchairs fit the space safely","None of them, to avoid any discrimination"],"correct":2,"exp":"- Correct option (C): For road safety and evacuation reasons, aisles cannot be blocked. The driver can only accept the buggies that fit in the designated storage areas.\n- Incorrect options: (A and B) Travelling with loose buggies would be illegal and unsafe. (D) Refusing access to the first ones is unjustified and inappropriate."},{"q":"For hire and reward passenger services, which of the following must be in place?","options":["Road Passenger Transport Operator Licence","Appropriate driver licence category","Compliance with EU drivers' hours rules","All of the above"],"correct":3,"exp":"- Correct option (D): Carrying out commercial passenger transport requires meeting all of these requirements: company licence, category D driving licence and use of the tachograph (drivers' hours rules).\n- Incorrect options: Choosing A, B or C would leave out compulsory legal requirements."},{"q":"If an employer agrees to pay drivers a nightly subsistence rate in excess of the Revenue civil service rates:","options":["The excess is regarded as emoluments, is considered income, and taxable","The rate must be agreed in advance and employees taxed on the excess","Neither the employer nor drivers have any additional tax liability","The drivers must repay any excess into a pension"],"correct":0,"exp":"- Correct option (A): The State allows subsistence to be paid tax-free up to an official ceiling. Anything the employer pays above that ceiling counts as part of salary (emoluments) and is taxed (income tax, PRSI).\n- Incorrect options: (C) Is false, it must be taxed. (B and D) Are not the procedures set by Revenue."},{"q":"An international service which carries passengers along specified routes, picking up and setting down at predetermined points, and is available to the general public is an:","options":["Open door service","International special regular service","International regular service","Occasional service"],"correct":2,"exp":"- Correct option (C): This is the exact legal definition of an \"International Regular Service\" (such as a bus from Dublin to London with fixed stops).\n- Incorrect options: (D) Occasional services are for closed groups (tours). (B) Special regular services carry only one category of people (e.g. workers)."},{"q":"Once passed, the Driver CPC Theory Test qualification is \"live\" for what maximum period of time before the practical test must be completed?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"- Correct option (C): The certificate for passing the theory test is valid for 2 years. If you do not pass the practical driving test within that time, you have to take the theory test again.\n- Incorrect options: (A, B, D) Do not match the RSA rule."},{"q":"Which of the following countries require drivers engaged on tour operations to carry proof that they are being paid at least the minimum wage?","options":["Germany","Netherlands","Portugal","Belgium"],"correct":0,"exp":"- Correct option (A): Under the 'MiLoG' law, Germany was one of the first (along with France) to require foreign carriers to carry documentary proof on the bus that their drivers are paid at least the German minimum wage while travelling through its territory.\n- Incorrect options: The other countries have not historically applied this strict on-board inspection rule in the same way."},{"q":"Assessment of a company's Corporation Tax is based on which of the following?","options":["Adjusted net profit","Capital gains","Fixed assets","Adjusted gross profit"],"correct":0,"exp":"- Correct option (A): Corporation tax (12.5% in Ireland) is paid on the company's net profit once adjustments for deductions or allowances have been made (adjusted net profit).\n- Incorrect options: (B) Separate capital gains taxes are paid. (C) Are company property. (D) Gross profit does not deduct all expenses."},{"q":"Under EU drivers' hours rules, what is the maximum permitted weekly driving time?","options":["45 hours","48 hours","56 hours","90 hours"],"correct":2,"exp":"- Correct option (C): A driver can drive a maximum of 56 hours in a single week (e.g. 4 days of 9 hours and 2 days of 10 hours).\n- Incorrect options: (A and B) Are rest or working time directive limits, not driving limits. (D) 90 hours is the driving limit for TWO consecutive weeks."},{"q":"Under EU drivers' hours rules, what is the maximum accumulated driving time allowed in any two consecutive weeks?","options":["90 hours","100 hours","112 hours","56 hours"],"correct":0,"exp":"- Correct option (A): Although the limit for one week is 56, in two consecutive weeks 90 hours cannot be exceeded. If you do 56 in week 1, in week 2 you can only drive 34.\n- Incorrect options: (C) Would be 56x2, which is prohibited to avoid chronic fatigue."},{"q":"What is the regular daily rest period a driver must take in a 24-hour period under EU rules?","options":["9 hours","11 hours","24 hours","45 hours"],"correct":1,"exp":"- Correct option (B): The regular daily rest must be an uninterrupted period of at least 11 hours.\n- Incorrect options: (A) 9 hours is the \"reduced\" daily rest. (D) 45 hours is the regular weekly rest."},{"q":"If a local bus service has a single journey time of 40 minutes, with a 5 minute stand time at each end, which frequency (headway) will make the BEST use of resources without extending standing time?","options":["Every 20 minutes","Every 25 minutes","Every 30 minutes","Every 40 minutes"],"correct":2,"exp":"- Correct option (C): A round trip takes 90 min (40+5+40+5). To optimise, the frequency must divide 90 exactly. 90/30 = 3 buses working continuously without adding unnecessary idle time.\n- Incorrect options: 90 cannot be divided exactly by 20, 25 or 40, which would force drivers to wait idle at the stops for longer."},{"q":"Under the Package Travel Regulations, a service is considered a 'package' if it pre-arranges transport and combines it with:","options":["Nothing else, just transport","A concert ticket returning the same day under 24 hours","Accommodation or lasts for more than 24 hours","A hot meal served on board"],"correct":2,"exp":"- Correct option (C): The law defines a \"package\" as two or more travel elements (transport, hotel, event) sold at an inclusive price that lasts more than 24 hours OR includes overnight accommodation.\n- Incorrect options: Excursions of less than 24 hours without a hotel are not considered packages."},{"q":"\"Closed Door Tours\" must be completed within a time limit of no more than:","options":["21 days","30 days","60 days","90 days"],"correct":1,"exp":"- Correct option (B): In international occasional services, a \"Closed Door Tour\" (same passengers, same bus throughout the journey) is limited to a maximum of 30 continuous days.\n- Incorrect options: Are false periods under the European rules."},{"q":"The Competition laws, as it applies to bus services, permits which of the following agreements between bus operators? 1. Agreeing to pool revenue 2. Agreeing to charge identical fares 3. Agreeing to participate in an area-wide ticketing scheme 4. Agreeing to display the same service numbers","options":["2 only","3 and 4 only","1 and 4 only","1, 2 and 3 only"],"correct":1,"exp":"- Correct option (B): Operators can agree to have a joint ticketing system (to benefit the user) or use the same route numbering to avoid confusion.\n- Incorrect options: Agreeing to share out the money (1) or agreeing to charge the same price (2) are considered price-fixing cartels, which are illegal and penalised by the CCPC."}]},"103":{"title":"Mock Exam 3","questions":[{"q":"Which financial statement shows a company's financial position at a specific point in time?","options":["Cash Flow Statement","Profit and Loss Account","Balance Sheet","Operating Budget"],"correct":2,"exp":"- Correct option (C): The Balance Sheet shows the company's assets, liabilities and equity on a given date.\n- Incorrect options: (A) Measures cash inflows and outflows over a period. (B) Measures income and expenses over an accounting period. (D) Is an internal budget estimate."},{"q":"Which of the following is classified as a variable (running) cost in vehicle operation?","options":["Vehicle road tax","Driver's basic salary","Fuel consumption","Annual vehicle insurance premium"],"correct":2,"exp":"- Correct option (C): Fuel consumption varies directly with the kilometres covered by the bus (running cost).\n- Incorrect options: (A, B and D) Are fixed costs (standing costs), since they must be paid periodically regardless of the distance covered."},{"q":"In Ireland, what is the standard rate of VAT applicable to most taxable goods and services?","options":["13.5%","23%","0%","9%"],"correct":1,"exp":"- Correct option (B): The standard rate of Value Added Tax (VAT) in Ireland is 23%.\n- Incorrect options: (A) Is the reduced rate (it applies to sectors such as construction or domestic fuel). (C and D) Are super-reduced or exempt rates."},{"q":"What is the primary advantage of debt factoring for a transport operator?","options":["It removes the need to pay Corporation Tax","Immediate cash by selling invoices to a factor","It guarantees 100% profit on all routes","It reduces vehicle depreciation rates"],"correct":1,"exp":"- Correct option (B): Debt factoring lets you get immediate cash by selling unpaid invoices to a finance company.\n- Incorrect options: (A) Does not change the company's tax obligations. (C) Does not affect operating profit margins. (D) Depreciation is an accounting calculation for the vehicle."},{"q":"What is a major advantage of operating a transport business as a Private Limited Company (LTD) compared to a Sole Trader?","options":["The company pays no taxes","Shareholders have limited liability for company debts","Directors are exempt from EU drivers' hours rules","No annual financial returns are required"],"correct":1,"exp":"- Correct option (B): In a limited company (LTD), the members' liability for debts is limited to the capital they contributed, protecting their personal assets.\n- Incorrect options: (A) It pays Corporation Tax. (C) The driving rules apply to everyone equally. (D) Filing annual accounts with the CRO is compulsory."},{"q":"Which element is essential for a contract to be legally binding under Irish law?","options":["It must be registered with the CRO","Consideration must be present","It must be signed in front of a Garda","It must involve at least €10,000"],"correct":1,"exp":"- Correct option (B): \"Consideration\" (a real exchange of value) is essential for a contract to be valid, along with offer and acceptance.\n- Incorrect options: (A, C and D) Are not essential requirements and are not required by contract law."},{"q":"What is the statutory minimum level of motor insurance required for a passenger transport vehicle operating on Irish public roads?","options":["Comprehensive cover","Third Party, Fire and Theft","Third Party cover","Fleet liability cover"],"correct":2,"exp":"- Correct option (C): The law requires at least Third Party cover, which pays for injury or damage caused to third parties.\n- Incorrect options: (A and B) Are voluntary commercial extensions, not the minimum required by road traffic law."},{"q":"Which form must be submitted annually by a limited company to the Companies Registration Office (CRO)?","options":["Form A1 for incorporation","Annual Return, Form B1","VAT3 return to Revenue","P45 form for each employee"],"correct":1,"exp":"- Correct option (B): Form B1 is the Annual Return that every company must file with the CRO.\n- Incorrect options: (A) Is the form for setting up the company. (C) Is for VAT returns to Revenue. (D) Is a payroll tax document."},{"q":"Under Irish Safety, Health and Welfare at Work legislation, who has the primary duty of care to ensure workplace safety?","options":["The HSA inspector","The employer","The trade union representative","The vehicle manufacturer"],"correct":1,"exp":"- Correct option (B): The law gives the main responsibility (duty of care) to the employer to ensure the safety of their workers.\n- Incorrect options: (A) The HSA monitors and inspects. (C and D) Are not legally responsible for the workplace."},{"q":"An accident at work resulting in an employee being absent from work for more than how many consecutive days must be reported to the Health and Safety Authority (HSA)?","options":["1 day","3 consecutive days","7 consecutive days","14 consecutive days"],"correct":1,"exp":"- Correct option (B): Every accident that causes a worker to be off work for more than 3 consecutive days (not including the day of the accident) must be reported to the HSA.\n- Incorrect options: (A, C and D) Do not match the legal reporting threshold."},{"q":"Under Irish statutory provisions, Statutory Sick Pay (SSP) requires employers to pay sick pay for up to how many days per calendar year?","options":["1 day","5 days","10 days","20 days"],"correct":1,"exp":"- Correct option (B): The Statutory Sick Pay law in Ireland sets the minimum legal entitlement at 5 days a year per eligible employee.\n- Incorrect options: (A, C and D) Are periods that do not match the legal minimum."},{"q":"What is the maximum compensation the Workplace Relations Commission (WRC) can award for an unfair dismissal claim based on financial loss?","options":["6 months' remuneration","1 year's remuneration","2 years' remuneration","5 years' remuneration"],"correct":2,"exp":"- Correct option (C): The WRC can award maximum compensation of up to 2 years' pay (104 weeks) if the worker proves financial loss from unfair dismissal.\n- Incorrect options: (A, B and D) Are incorrect limits under the Unfair Dismissals Act."},{"q":"What is the minimum statutory redundancy payment for an eligible employee in Ireland?","options":["1 week's pay per year of service plus 1 bonus week","2 weeks' pay per year of service plus 1 bonus week","4 weeks' pay per year of service","Half a week's pay per year of service"],"correct":1,"exp":"- Correct option (B): Statutory redundancy pay is 2 weeks' pay per year worked plus 1 additional week (bonus week).\n- Incorrect options: (A, C and D) Do not follow the legal formula laid down in the Redundancy Payments Act."},{"q":"Under the Organization of Working Time Act, what is the maximum average weekly working hours limit for employees?","options":["39 hours","48 hours","56 hours","60 hours"],"correct":1,"exp":"- Correct option (B): The law states that average weekly working time cannot exceed 48 hours.\n- Incorrect options: (A) Is a standard contractual working week, not the legal maximum. (C) Is the weekly driving limit on the tachograph, not the overall working time limit."},{"q":"To satisfy the requirement of 'professional competence', a passenger transport undertaking must:","options":["Own at least 10 brand-new coaches","Employ a TM who holds a CPC","Register as a public limited company","Have a turnover of over €1,000,000"],"correct":1,"exp":"- Correct option (B): Professional competence is proved only by having a qualified Transport Manager who holds the official CPC qualification.\n- Incorrect options: (A, C and D) Are not conditions required by Regulation (EC) 1071/2009."},{"q":"To meet the 'Financial Standing' requirement for a Road Passenger Transport Operator Licence, an operator must demonstrate available capital/reserves of how much for the first vehicle and for each additional vehicle?","options":["€9,000 for the first vehicle and €5,000 for each additional vehicle","€5,000 for the first vehicle and €2,500 for each additional vehicle","€15,000 for the first vehicle and €10,000 for each additional vehicle","€1,000 per vehicle regardless of fleet size"],"correct":0,"exp":"- Correct option (A): Financial reserves of €9,000 for the first bus and €5,000 for each additional bus must be proved.\n- Incorrect options: (B, C and D) Are wrong and insufficient amounts under the European regulation."},{"q":"Which body in Ireland has the authority to revoke an Operator's Licence if the operator loses their 'Good Repute'?","options":["An Garda Síochána","The Department of Transport","The Health and Safety Authority","The Workplace Relations Commission"],"correct":1,"exp":"- Correct option (B): The Department of Transport is the issuing body with the power to withdraw or revoke the operator licence.\n- Incorrect options: (A) Carries out traffic checks. (C and D) Supervise safety and labour inspection matters."},{"q":"A Large Public Service Vehicle (LPSV) licence issued by An Garda Síochána to a passenger vehicle is valid for how long?","options":["1 year","3 years","5 years","10 years"],"correct":1,"exp":"- Correct option (B): As stated explicitly in the Module 10 slides of your course, the LPSV vehicle licence issued by the Garda is valid for 3 years.\n- Incorrect options: (A) Is the validity of the CVRT. (C) Is the validity of the Operator Licence."},{"q":"Under the Public Transport Regulation Act 2009, which authority regulates commercial bus service routes and issues Public Bus Passenger Service Licences in Ireland?","options":["Road Safety Authority","National Transport Authority","Revenue Commissioners","All of the above"],"correct":1,"exp":"- Correct option (B): The NTA is the authority responsible for regulating urban and inter-urban bus routes and granting public service licences.\n- Incorrect options: (A) The RSA is responsible for road safety and technical inspections. (C) Is the tax authority. (D) Not all of them: only the NTA issues these licences."},{"q":"Under EU Regulation 561/2006, after how many hours of continuous driving must a driver take an uninterrupted break of at least 45 minutes?","options":["3.5 hours","4.5 hours","5 hours","9 hours"],"correct":1,"exp":"- Correct option (B): After 4.5 hours of continuous driving, the driver must take an uninterrupted break of at least 45 minutes.\n- Incorrect options: (A, C and D) Do not match the legal tachograph limits."},{"q":"When a 45-minute driving break is split into two parts under EU rules, what is the correct order and minimum duration of these breaks?","options":["First break at least 30 mins, second break at least 15 mins","First break at least 15 mins, second break at least 30 mins","Two equal breaks of 22.5 mins","First break at least 20 mins, second break at least 25 mins"],"correct":1,"exp":"- Correct option (B): If the break is split, it must be taken in this order: first a block of at least 15 minutes, followed by a block of at least 30 minutes.\n- Incorrect options: (A) Reversing the blocks (30+15) is prohibited by law. (C and D) Are illegal splits."},{"q":"Under EU drivers' hours rules, a reduced weekly rest period must be at least how many hours?","options":["24 hours","36 hours","45 hours","11 hours"],"correct":0,"exp":"- Correct option (A): The reduced weekly rest requires a minimum of 24 uninterrupted hours (compared with 45 hours for the regular weekly rest).\n- Incorrect options: (C) Is the regular weekly rest. (D) Is the regular daily rest."},{"q":"How often must a digital tachograph system in a commercial vehicle be recalibrated and inspected by an authorized workshop?","options":["Every 6 months","Every 1 year","Every 2 years","Every 5 years"],"correct":2,"exp":"- Correct option (C): Inspection and recalibration of a digital tachograph at an approved workshop is required every 2 years.\n- Incorrect options: (A, B and D) Are incorrect periods for periodic tachograph inspections."},{"q":"What is the maximum validity period of a Driver Tachograph Card issued in Ireland?","options":["1 year","2 years","5 years","10 years"],"correct":2,"exp":"- Correct option (C): The digital Driver Card issued by the RSA is valid for 5 years.\n- Incorrect options: (A, B and D) Do not match the legal period of validity."},{"q":"Which driving licence category is required to drive a minibus designed to carry up to 16 passengers in addition to the driver?","options":["Category B","Category C1","Category D1","Category CE"],"correct":2,"exp":"- Correct option (C): Category D1 entitles you to drive minibuses designed to carry 9 to 16 passengers.\n- Incorrect options: (A) Allows up to 8 passengers. (B and D) Are goods lorry licences."},{"q":"How long is a Pass Statement/CVRT Certificate valid for a commercial passenger vehicle over one year old?","options":["6 months","1 year","2 years","3 years"],"correct":1,"exp":"- Correct option (B): The commercial roadworthiness test (CVRT) must be passed every year (valid for 1 year).\n- Incorrect options: (A, C and D) Commercial vehicles do not have two-yearly or three-yearly inspections."},{"q":"Buses and coaches (Category D vehicles) must have speed limiters fitted and set to a maximum speed of:","options":["80 km/h","90 km/h","100 km/h","110 km/h"],"correct":2,"exp":"- Correct option (C): Speed limiters for buses and coaches (Category D) are legally set at 100 km/h.\n- Incorrect options: (B) 90 km/h is the setting for goods vehicles (lorries)."},{"q":"Who bears the immediate daily responsibility for conducting a pre-journey walkaround inspection of a commercial passenger vehicle?","options":["The Transport Manager","The Workshop Mechanic","The Driver","The RSA Inspector"],"correct":2,"exp":"- Correct option (C): The driver has a daily obligation to check the vehicle (walkaround check) before going out on the road.\n- Incorrect options: (A) The manager supervises the overall maintenance systems. (B) The mechanic carries out the repairs."},{"q":"What does 'Gross Vehicle Weight' (GVW) refer to?","options":["The weight of the vehicle empty, without fuel","Maximum total weight, including load and people","The weight of the luggage compartment only","The weight carried by the front axle only"],"correct":1,"exp":"- Correct option (B): The Gross Vehicle Weight (GVW) is the maximum total permitted mass of the vehicle loaded with passengers, load, fuel and driver.\n- Incorrect options: (A) Is the unladen weight. (C and D) Are partial or component weights."},{"q":"In Ireland, what is a primary advantage of stored-value smartcards like the TFI Leap Card for bus operators?","options":["It removes all vehicle maintenance costs","Shorter stop times and less cash handling","It exempts drivers from CPC training","It lets vehicles exceed speed limits"],"correct":1,"exp":"- Correct option (B): Smart cards speed up fare collection, reducing the time spent at stops (dwell time) and minimising the risk of handling cash.\n- Incorrect options: (A, C and D) Have nothing to do with transport cards."},{"q":"In public transport operations, 'Cross-subsidisation' occurs when:","options":["Profits from one route support a needed one","Drivers work for two rival companies at once","Fuel taxes are refunded by the government","Passengers pay for two tickets and get three"],"correct":0,"exp":"- Correct option (A): \"Cross-subsidisation\" uses the profits from very profitable commercial routes to fund other loss-making routes of public interest.\n- Incorrect options: (B, C and D) Are concepts unrelated to balancing revenue between routes."},{"q":"In passenger transport scheduling, what does the term 'Headway' mean?","options":["The maximum speed of a coach on a motorway","The interval between buses on a route","The total distance of a bus journey","The height clearance under a bridge"],"correct":1,"exp":"- Correct option (B): \"Headway\" is the frequency or interval of time between two consecutive buses on the same route.\n- Incorrect options: (A, C and D) Confuse the planning term with speed, route length or clearance."},{"q":"In the service marketing mix (7 Ps), which 'P' relates to the physical environment and tangible elements where the service is delivered?","options":["Process","People","Physical Evidence","Promotion"],"correct":2,"exp":"- Correct option (C): \"Physical Evidence\" covers everything tangible that the customer sees and perceives (clean buses, uniform, station design).\n- Incorrect options: (A) Refers to workflow/processes. (B) Is the human factor. (D) Is advertising."},{"q":"Conducting a customer satisfaction survey among passengers onboard a coach is an example of:","options":["Primary market research","Secondary market research","Financial auditing","Predatory pricing"],"correct":0,"exp":"- Correct option (A): Getting first-hand information by asking customers directly is Primary research.\n- Incorrect options: (B) Secondary research uses previously existing studies. (C and D) Are accounting audits or illegal pricing tactics."},{"q":"The Interbus Agreement governs which type of international passenger transport services between contracting states?","options":["Scheduled urban bus routes","Occasional coach services","Freight transport only","Domestic cabotage in Ireland"],"correct":1,"exp":"- Correct option (B): The Interbus Agreement governs international occasional (private hire/tourist) passenger transport by coach between the EU and third countries that signed it.\n- Incorrect options: (A) Are fixed regular services. (C) Is for goods. (D) Cabotage is domestic transport."},{"q":"What document must be carried on board an international coach performing an occasional service under the Interbus Agreement or EU rules?","options":["A Journey Form book","A Carnet de Passages","A CMR consignment note","An NTA local service permit"],"correct":0,"exp":"- Correct option (A): Every international occasional journey requires the Waybill (Feuille de Route) to be carried on board.\n- Incorrect options: (B) Is a customs passport for vehicles. (C) Is the consignment note for international carriage of goods."},{"q":"When crossing an international border with customs controls, what does selecting the 'Red Channel' signify?","options":["Nothing at all to declare to customs officers","Goods to declare, subject to duty or limits","Priority status for an emergency vehicle","The coach is running empty with no passengers"],"correct":1,"exp":"- Correct option (B): At customs, the Red Channel means you are carrying goods subject to taxes, duties or declaration restrictions.\n- Incorrect options: (A) Corresponds to the Green Channel. (C and D) Are unrelated situations."},{"q":"Under the Package Travel Regulations, a package tour combining transport and accommodation must span a minimum duration of:","options":["12 hours, or a meal included","24 hours, or an overnight stay","48 hours, or two overnight stays","7 days, or a full week away"],"correct":1,"exp":"- Correct option (B): To legally count as a \"Package Tour\", the offer must last more than 24 hours OR include overnight accommodation.\n- Incorrect options: Same-day return excursions (with no hotel night) are exempt from this law."},{"q":"Passenger cabotage carried out in another EU Member State by an Irish operator must be:","options":["Permanent and unlimited in duration","Temporary and compliant with EU rules","Fully tax-exempt in all jurisdictions","Carried out without an operator licence"],"correct":1,"exp":"- Correct option (B): Cabotage allows passenger transport services to be provided in another country on a strictly temporary basis.\n- Incorrect options: (A) If it is permanent, a company must be set up in that country. (C and D) It requires the Community Licence."},{"q":"According to Irish Competition Law (enforced by the CCPC), what is 'predatory pricing'?","options":["Charging high prices in peak holiday periods","Prices below cost to eliminate a competitor","Offering group discounts on weekend trips","Charging identical fares on all urban routes"],"correct":1,"exp":"- Correct option (B): Predatory pricing means deliberately selling below operating cost to drive out or ruin the competition, which is an offence under competition law (CCPC).\n- Incorrect options: (A) Is demand-based pricing. (C) Is a legitimate commercial discount. (D) Is a standard price structure."}]},"104":{"title":"Mock Exam 4","questions":[{"q":"What is the main role of the Workplace Relations Commission (WRC)?","options":["Promoting good workplace relations","Prosecuting criminal driving offences","Issuing road transport operator licences","Collecting Corporation Tax from companies"],"correct":0,"exp":"The WRC is responsible for promoting good employment practice and giving support and guidance to both employers and employees."},{"q":"Which body provides a forum for the adjudication of industrial disputes and offers resolutions for effective industrial relations?","options":["The Labour Court (LC)","The Revenue Commissioners","The Road Safety Authority (RSA)","The National Transport Authority (NTA)"],"correct":0,"exp":"The Labour Court is the forum responsible for adjudicating on industrial disputes and issuing employment rulings and decisions."},{"q":"Within how many days must an employer provide a written statement of reasons for dismissal after receiving a valid request from a qualifying employee?","options":["7 days","14 days","21 days","30 days"],"correct":1,"exp":"By law, if an employee requests it, the employer has a strict deadline of 14 days to give them the reasons for their dismissal in writing."},{"q":"How many consecutive hours of daily rest is each worker entitled to within every 24-hour period under working time legislation?","options":["8 consecutive hours","9 consecutive hours","11 consecutive hours","12 consecutive hours"],"correct":2,"exp":"The general working time rules set a minimum entitlement of 11 consecutive hours of daily rest."},{"q":"What mandatory rest break must be provided to a worker scheduled for a shift lasting 6 hours or more?","options":["15 minutes","20 minutes","30 minutes","45 minutes"],"correct":2,"exp":"A worker is entitled to a compulsory 30-minute break when their shift reaches 6 hours."},{"q":"What is the statutory deadline for an employer to provide the full written statement of terms of employment to a new employee?","options":["Within 5 days","Within 14 days","Within 1 month","Within 6 months"],"correct":2,"exp":"Although the core terms must be given within 5 days (Day 5 Statement), the full written contract or statement of employment terms must be given within the first month."},{"q":"Which of the following statements regarding Statutory Sick Pay (SSP) in Ireland is correct?","options":["It requires at least 13 weeks of continuous service","It is payable for a maximum of 10 days per calendar year","It is payable at 100% of the normal daily earnings","It only applies to staff at management level"],"correct":0,"exp":"To be entitled to SSP, the worker must have at least 13 weeks of continuous service with the company. Currently a maximum of 5 days a year is paid at 70% of salary."},{"q":"What percentage of normal daily earnings is paid under Statutory Sick Pay (SSP), subject to a daily cap?","options":["50%","60%","70%","100%"],"correct":2,"exp":"Statutory Sick Pay (SSP) is 70% of the employee's normal daily wage, with a maximum ceiling of €110 a day."},{"q":"How many weeks of statutory Parent's Leave are available to each relevant parent within the first two years of a child's life?","options":["2 weeks","5 weeks","9 weeks","26 weeks"],"correct":2,"exp":"The law currently gives 9 weeks of Parent's Leave to each parent in the first two years."},{"q":"Under Irish employment legislation, how many weeks of standard statutory maternity leave are qualifying employees entitled to?","options":["16 weeks","24 weeks","26 weeks","42 weeks"],"correct":2,"exp":"Standard maternity leave is 26 weeks. (Mothers can request 16 extra unpaid weeks, but the standard legal basis is 26.)"},{"q":"What is the minimum continuous service required for an employee to qualify for statutory redundancy payments?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"An employee must have a minimum of 2 years' continuous service with the employer to qualify for statutory redundancy pay."},{"q":"Dismissal of an employee on what grounds is automatically deemed 'unfair' by the WRC, regardless of length of service?","options":["Incompetence after training","Trade union membership and activities","Redundancy through a fair selection process","Gross misconduct"],"correct":1,"exp":"Dismissing an employee for their trade union membership or activity is an \"inadmissible reason\" and the dismissal is automatically considered unfair."},{"q":"What is the maximum compensation limit if an unfairly dismissed employee incurred NO financial loss?","options":["No compensation can be awarded","1 week's remuneration","4 weeks' remuneration","10 weeks' remuneration"],"correct":2,"exp":"If an employee is unfairly dismissed but finds work immediately and suffers no financial loss, the maximum compensation is 4 weeks' pay."},{"q":"Are employees entitled to paid time off for ante-natal care medical appointments regardless of their length of service?","options":["Yes, regardless of length of service","No, ante-natal care is always unpaid","No, 12 months' service is needed first","Only if the WRC approves it in writing"],"correct":0,"exp":"The right to paid time off for ante-natal care appointments applies to all pregnant employees from day one, with no length-of-service requirement."},{"q":"How many days of paid domestic violence leave is an employee legally entitled to take in any 12-month period?","options":["1 day","3 days","5 days","10 days"],"correct":2,"exp":"Workers have a legal right to up to 5 days of paid leave a year for reasons of domestic violence."},{"q":"Once an employee has completed 13 weeks of service, what is the statutory minimum notice they must give to their employer if they intend to leave?","options":["None","1 week","2 weeks","4 weeks"],"correct":1,"exp":"The employee is only legally obliged to give 1 week's notice to resign, and this period does not increase however many years they have been with the company."},{"q":"An employee has 15 years of continuous service. What is the statutory minimum notice period the employer must give them before termination?","options":["2 weeks","4 weeks","6 weeks","8 weeks"],"correct":3,"exp":"According to the notice scale, employees with 15 years' service or more are entitled to a minimum of 8 weeks' notice from the company."},{"q":"What is the maximum permitted working week for employees, averaged out over a 4-month period?","options":["39 hours","40 hours","48 hours","56 hours"],"correct":2,"exp":"The Working Time Directive sets a legal maximum of 48 working hours a week on average (normally calculated over a 4-month reference period)."},{"q":"Under Industrial Action rules, how soon must industrial action be commenced after the date of the ballot?","options":["Within 1 week","Within 2 weeks","Within 4 weeks","Within 6 months"],"correct":2,"exp":"Once the union holds the ballot, the strike or industrial action must start within the following 4 weeks."},{"q":"Which of the following is legally entitled to picket at the premises of an employer other than their own?","options":["Any member of the main trade union","A trade union official accompanying employees from that workplace","A trade union member from a different works in the same town","Anyone who sympathizes with the strike"],"correct":1,"exp":"Picketing can only take place near the workers' own workplace. However, union officials are allowed to accompany their members on picket lines."},{"q":"What does 'Cash Flow' specifically measure in a business?","options":["The depreciation of fixed assets over time","Money received into and paid out by a business","The market share of the company","The number of active bank accounts"],"correct":1,"exp":"Cash flow measures only the money coming into (receipts) and going out of (payments) a company."},{"q":"What is 'Debt Factoring'?","options":["Selling invoices to a factor for immediate cash","Buying vehicles through a hire purchase deal","Declaring bankruptcy to avoid creditors","Working out the interest on a bank loan"],"correct":0,"exp":"Debt factoring means \"selling\" your unpaid invoices to a finance company to get cash immediately and improve cash flow."},{"q":"A transport manager budgets £6,150 for tyres, but the actual cost is £6,500. How is the percentage variance calculated?","options":["Budgeted amount divided by actual cost","Variance divided by budgeted amount x 100","Actual cost multiplied by budgeted amount","Variance divided by actual cost x 100"],"correct":1,"exp":"The formula for calculating the percentage budget variance is: (Variance / Budgeted Amount) x 100."},{"q":"In the marketing mix, the '4 core Ps' stand for:","options":["Package, Price, Presentation, People","Product, Price, Place, Promotion","Product, Performance, Place, Profit","Price, Process, Promotion, Public Relations"],"correct":1,"exp":"The four core elements of the classic marketing mix are: Product (the service offered), Price, Place and Promotion."},{"q":"Marketing objectives should be SMART. What does 'SMART' stand for?","options":["Specific, Measurable, Achievable, Relevant, Time-bound","Sales, Marketing, Advertising, Research, Targeting","Simple, Modern, Attractive, Reliable, Tangible","Strategic, Meaningful, Actionable, Realistic, Timely"],"correct":0,"exp":"SMART is an acronym for setting effective objectives: Specific, Measurable, Achievable, Relevant and Time-bound."},{"q":"Which of the following is a method of gathering 'Primary data' for market research?","options":["Personal and telephone interviews","Reading government statistics","Reviewing old company reports","Looking at trade directories"],"correct":0,"exp":"Primary data is data you collect yourself first-hand. Personal or telephone interviews and direct surveys are primary research methods."},{"q":"What is the standard rate of VAT applicable to most goods and services in Ireland?","options":["9%","13.5%","21%","23%"],"correct":3,"exp":"The standard Value Added Tax (VAT) rate for most goods and services in Ireland is 23%."},{"q":"At what turnover threshold for the supply of SERVICES is VAT registration compulsory in Ireland?","options":["€10,000","€37,500","€42,500","€85,000"],"correct":2,"exp":"The compulsory threshold for registering for VAT if your company supplies services (such as passenger transport) is turnover of more than €42,500."},{"q":"If an Irish transport operator provides an international journey for a business customer based in another EU country, what is the correct VAT procedure?","options":["Charge VAT at the standard Irish rate","No VAT is charged; the customer organises VAT payment in their own country","Charge VAT at 0% and pay it to the Irish Revenue","The Irish operator must register for VAT in the customer's country"],"correct":1,"exp":"In cross-border B2B transactions within the EU, VAT is not charged on the invoice. The European customer applies the \"reverse charge\" mechanism and accounts for the VAT in their own country."},{"q":"For how long must VAT records be kept by a business?","options":["At least 1 year","At least 3 years","At least 6 years","Indefinitely"],"correct":2,"exp":"Revenue requires all VAT-related records and books of account to be kept for a minimum of 6 years."},{"q":"Which Irish motorway operates a barrier-free electronic toll system (eFlow)?","options":["M1 (Gormanston)","M4 (Kilcock)","M50 Orbital Motorway","M8 (Rathcormac)"],"correct":2,"exp":"Dublin's M50 motorway is known for its eFlow system, which has no physical barriers and reads vehicles' number plates or electronic tags without them having to stop."},{"q":"What barrier-free electronic toll system operates on the M50 motorway around Dublin?","options":["eFlow","GO-Box","LKW-Maut","AutoPASS"],"correct":0,"exp":"eFlow is the barrier-free toll on the M50: cameras read the number plate. GO-Box is Austria's, LKW-Maut is Germany's (lorries) and AutoPASS is Norway's."},{"q":"Which of the following is one of the four main criteria required to hold a Road Passenger Transport Operator Licence?","options":["Good Repute","Minimum fleet size of 10 vehicles","100% Market Share","Registration as a Public Limited Company"],"correct":0,"exp":"The four pillars for holding an operator licence are: Good Repute, Financial Standing, Professional Competence and a real Establishment in Ireland."},{"q":"When assessing an operator's 'Good Repute', the Minister will consider convictions relating to serious offences within what time frame?","options":["The previous 1 year","The previous 3 years","The previous 5 years","The previous 10 years"],"correct":2,"exp":"To maintain good repute, the Department will check whether the operator or manager has committed serious offences in the last 5 years."},{"q":"To meet the 'Financial Standing' requirement, how much reserves must an operator demonstrate for their first vehicle?","options":["€1,500","€5,000","€9,000","€15,000"],"correct":2,"exp":"Financial standing requires proving a financial cushion of €9,000 for the first authorised vehicle."},{"q":"To meet the 'Financial Standing' requirement, how much reserves must an operator demonstrate for EACH ADDITIONAL vehicle after the first?","options":["€2,000","€3,000","€5,000","€9,000"],"correct":2,"exp":"For each additional bus added to the licence (after the first), the company must prove an additional €5,000 of financial reserves."},{"q":"If a driver receives a serious conviction while employed, what are their obligations regarding the operator?","options":["They must resign immediately","They must disclose the conviction to the operator","They do not need to say anything unless asked by the Gardaí","They must pay a fine to the transport manager"],"correct":1,"exp":"The Good Repute rules require the driver to report (disclose) to their employer (the operator) if they receive a serious conviction."},{"q":"Within how many days must an employer notify a new employee of their core terms of employment (like job title and pay) via the 'Day 5 Statement'?","options":["Within 5 days","Within 1 day","Within 14 days","Within 1 month"],"correct":0,"exp":"As the name says, the 5 core terms of the contract must be given in writing within the first 5 days of work."},{"q":"What is the minimum threshold of proposed redundancies over a 30-day period that triggers collective redundancy rules in an establishment of 50 to 99 employees?","options":["5 or more redundancies","10 or more redundancies","20 or more redundancies","30 or more redundancies"],"correct":1,"exp":"With a workforce of between 50 and 99 workers, planning 10 or more redundancies within 30 days triggers the collective redundancy consultation laws."},{"q":"For how many minimum days must an employer engage in an information and consultation process with employee representatives during collective redundancies?","options":["14 days","21 days","30 days","60 days"],"correct":2,"exp":"If a collective redundancy is triggered, the company is legally obliged to open a consultation and information period of at least 30 days with the trade union or worker representatives before any redundancy takes effect."}]},"105":{"title":"Mock Exam 5","questions":[{"q":"An operator buys a new vehicle for €90,000. The value of the original tyre equipment is €2,500. The vehicle has an expected life of 5 years and an estimated residual value of €22,500. If the reducing balance method of depreciation is used at a rate of 20%, the amount allocated for depreciation in the first year of the vehicle's life will be:","options":["€20,000","€18,000","€17,500","€13,000"],"correct":2,"exp":"To calculate the vehicle's depreciation, you must first subtract the cost of the original tyres (because tyres are a variable running cost, not a fixed asset). €90,000 - €2,500 = €87,500. 20% of €87,500 is €17,500."},{"q":"An operator has annual standing costs of €60,000, running costs of 40 cents per kilometre and a profit mark up on costs of 20%. A customer has asked the operator to quote an \"all in\" price per kilometre covering 50,000 kilometres per year. What price per kilometre should the operator quote?","options":["€1.92","€1.60","€1.48","€1.20"],"correct":0,"exp":"1. Fixed cost per km = €60,000 / 50,000 km = €1.20 per km.\n2. Total cost per km = €1.20 (fixed) + €0.40 (variable/running) = €1.60.\n3. Profit margin (20%) = 20% of €1.60 = €0.32.\n4. Price to quote = €1.60 + €0.32 = €1.92."},{"q":"Which of the following vehicle costs are both direct and fixed?\n1. Vehicle Tax 2. Lubricants 3. Insurance 4. Tyres 5. Maintenance","options":["1 and 3 only","2 and 5 only","1, 4 and 5 only","2, 3 and 4 only"],"correct":0,"exp":"Motor tax and insurance are fixed costs (paid by time, not by use) and direct (allocated to a specific vehicle). Lubricants, tyres and maintenance are variable costs (running costs)."},{"q":"Under the Road Passenger Transport Operator Licensing system, a vehicle is classified as a Public Service Vehicle (PSV) if it is operated for hire and reward and carries how many passengers?","options":["8 or more, not counting the driver","5 or more, counting the driver","12 or more, not counting the driver","16 or more, counting the driver"],"correct":0,"exp":"A vehicle requires a PSV licence and an operator licence when it carries 8 or more passengers (not counting the driver) for commercial purposes (hire and reward)."},{"q":"A Large Public Service Vehicle (LPSV) Licence issued by the PSV Officer of An Garda Síochána is valid for what period?","options":["1 year","2 years","3 years","5 years"],"correct":2,"exp":"The LPSV vehicle licence issued by An Garda Síochána is valid for 3 years. (Not to be confused with the company's Operator Licence, which lasts 5 years.)"},{"q":"What specific licence is required to operate a regular public passenger service between specified terminals or a specified route?","options":["A Public Bus Passenger Service Licence","A standard Community Licence only","An Interbus authorisation from the EU","A CVRT certificate for each bus"],"correct":0,"exp":"To operate a national regular route (with fixed timetables and terminals) in Ireland, you need a public bus service licence issued by the NTA."},{"q":"Operators must download/copy data from their drivers' digital tachograph cards at intervals not exceeding:","options":["14 days","21 days","28 days","90 days"],"correct":2,"exp":"European rules require the data on the digital driver card to be downloaded at least every 28 days to prevent driving information being lost or overwritten."},{"q":"If the digital tachograph breaks down on a journey, it must be repaired 'en route' if the vehicle is unable to return to its base within:","options":["2 days of the breakdown","5 days of the breakdown","1 week of the breakdown","2 weeks of the breakdown"],"correct":2,"exp":"The law allows a maximum of 1 week. If the vehicle cannot return to its base within one week of the tachograph breaking down, it must be repaired on the road at an approved workshop."},{"q":"Digital tachographs must be recalibrated at intervals of not more than:","options":["1 year","2 years","5 years","6 years"],"correct":1,"exp":"All tachographs fitted to commercial vehicles must be inspected and recalibrated by an approved workshop every 2 years."},{"q":"A company card to be used in connection with digital tachographs has a maximum validity of:","options":["1 year","2 years","3 years","5 years"],"correct":3,"exp":"Like the driver card, the Company Card that is inserted in the tachograph to lock and download data is valid for 5 years."},{"q":"When asked by an Irish enforcement official at the roadside, drivers using an analogue or digital tachograph must be able to produce records for the current day and how many preceding days?","options":["7 days","15 days","21 days","28 days"],"correct":3,"exp":"By law, the driver must be able to produce the driving records (analogue charts, digital card or printouts) for the current day and the previous 28 calendar days."},{"q":"Under EU Regulation 165/2014, operators are legally obliged to retain completed tachograph records (charts and digital data) at their premises for at least:","options":["6 months","12 months","2 years","3 years"],"correct":1,"exp":"Transport companies must keep tachograph records (analogue charts and digital downloads) in chronological order for a minimum of 12 months (1 year) after use."},{"q":"Which document permits a coach to travel at up to 100 km/h on motorways in Germany?","options":["Community Licence","Vitesse 100 certificate","Eurovignette","Tempo 100 certificate"],"correct":3,"exp":"The \"Tempo 100\" certificate is the German technical approval that allows a bus to travel at 100 km/h on its motorways (the general limit for heavy buses is usually 80 km/h without this certificate)."},{"q":"In many European countries, the typical speed limit for commercial vehicles in built-up (urban) areas is:","options":["30 km/h","40 km/h","50 km/h","60 km/h"],"correct":2,"exp":"As a general harmonised rule in Europe, the standard speed limit in built-up areas or towns is 50 km/h."},{"q":"Which statement best summarises Irish motorway speed limits for the listed vehicle types?","options":["All buses and coaches are limited to 100 km/h","All goods vehicles are limited to 80 km/h","Vehicles towing are limited to 80 km/h","Standing passenger buses may travel at 90 km/h"],"correct":0,"exp":"In Ireland, buses and coaches (category D passenger vehicles) have a maximum legal motorway speed limit of 100 km/h."},{"q":"On which of the following pieces of Irish road infrastructure are tolls charged to coaches and other vehicles via a barrier-free electronic system?","options":["M1 Motorway","Dublin Port Tunnel","M50 Motorway","Limerick Tunnel"],"correct":2,"exp":"The M50 motorway in Dublin uses the eFlow system, a barrier-free electronic toll system that reads number plates or tags."},{"q":"Assessment of a company's corporation tax is based on which of the following?","options":["Adjusted net profit","Capital gains","Fixed assets","Adjusted gross profit"],"correct":0,"exp":"The 12.5% Corporation Tax in Ireland is applied to adjusted net profit after the deductions and expenses allowed by law."},{"q":"Which document is essential for international bus or coach services within the EU?","options":["National Transport Authority permit","Community Licence","CVRT certificate","Driver CPC card"],"correct":1,"exp":"The Community Licence is the basic document that grants the right of access to the European market and allows international passenger transport in the EU."},{"q":"Which type of passenger service normally requires an EU route authorisation?","options":["Occasional service","Special regular service under contract","Regular scheduled service","Private non commercial transport"],"correct":2,"exp":"International regular services (those that follow a fixed route, timetable and stops for the public) need a specific EU route authorisation, as well as the Community Licence."},{"q":"Cabotage in passenger transport is best described as:","options":["Limited services within another EU state","Permanent domestic services in another state","Own-account passenger transport abroad","Domestic services within Ireland only"],"correct":0,"exp":"Cabotage allows a foreign carrier to carry out national transport services temporarily within the borders of another Member State."},{"q":"\"Closed Door Tours\" must be completed within a time limit of no more than:","options":["21 days","30 days","60 days","90 days"],"correct":1,"exp":"In international transport, closed-door tours (the same bus carries the same group throughout the journey) have a legal maximum duration of 30 days."},{"q":"What type of passenger fare scale does the following represent? (Distance increases, but the cost per km decreases incrementally)","options":["Standard fare scale","Zonal fare scale","Flat fare scale","Tapered fare scale"],"correct":3,"exp":"A \"tapered\" fare means that, although the total ticket is more expensive, the amount charged to the passenger for each additional kilometre falls as the journey gets longer."},{"q":"As a deterrent to fraudulent use, which one of the following is likely to be the most secure system of pre-paid tickets?","options":["Uniquely numbered tickets and matching numbered photocards","Uniquely numbered tickets and unnumbered photocards","Unnumbered tickets and uniquely numbered photocards","Unnumbered tickets and unnumbered photocards"],"correct":0,"exp":"Matching a unique number on the pass or ticket with the same unique number on the passenger's photo identity card prevents several people from fraudulently sharing the same pass."},{"q":"In a gross cost (supply side) tendering system, the fares are set by the:","options":["Office of Fair Trading","Operator","Tendering Authority","Traffic Warden"],"correct":2,"exp":"In a \"gross cost\" tender contract, the Tendering Authority (e.g. the NTA) takes the revenue risk, sets the fares and keeps the takings, paying the operator a fixed amount for providing the bus and the driver."},{"q":"An operator is proposing to run a local bus service that has a single journey time of 40 minutes, and will have five minutes stand time at each end of the route. How many vehicles will be required for the service, if the frequency (headway) is every five minutes?","options":["9 vehicles","10 vehicles","18 vehicles","20 vehicles"],"correct":2,"exp":"1. Outward journey time = 40 min + 5 min layover = 45 min.\n2. Round trip = 45 + 45 = 90 minutes.\n3. Required frequency = 1 bus every 5 minutes.\n4. Total buses = 90 / 5 = 18 vehicles."},{"q":"Interworking is the name given to which of the following activities?","options":["Using a driver to cover more than one route","Using a vehicle to cover more than one route","Two or more operators providing vehicles for one route","Two or more operators providing drivers for one route"],"correct":1,"exp":"\"Interworking\" in fleet planning (timetabling) means assigning the same bus to cover more than one route during the day, making the most of it."},{"q":"If a local bus service has a single journey time of 40 minutes, with stand time at each end of five minutes, which one of the following frequencies (headways) will make the best use of resources, without extending the standing time?","options":["Every 20 minutes","Every 25 minutes","Every 30 minutes","Every 40 minutes"],"correct":2,"exp":"The round trip takes 90 minutes. For the resources to fit perfectly with no idle time, the frequency must divide the round trip exactly. 90 divided by 30 minutes = 3 buses rotating perfectly. (90 cannot be divided exactly by 20, 25 or 40.)"},{"q":"The WRC has the power to hear cases connected with which of the following work-place issues?\n1. Employees' rights to time off work to carry out trade union duties\n2. Alleged discrimination on the basis of sexual orientation\n3. PAYE contributions\n4. Failure to report an accident to the HSA\n5. Equal pay complaints","options":["1 and 4 only","2 and 3 only","1, 2 and 5 only","3, 4 and 5 only"],"correct":2,"exp":"The Workplace Relations Commission (WRC) hears cases on trade union rights, discrimination and equal pay. (PAYE problems are for Revenue, and failing to report to the HSA is a health and safety offence, not a WRC employment matter.)"},{"q":"What is the legal definition of 'night work' under Irish working time regulations?","options":["Work performed on weekends and public holidays","Work done between midnight and 7:00 AM","Work done between 8:00 PM and 4:00 AM","Any shift exceeding 10 hours in length"],"correct":1,"exp":"Irish working time law strictly defines \"night work\" as work done between midnight (12:00 AM) and 7:00 AM."},{"q":"How many statutory public holidays are employees in Ireland generally entitled to receive?","options":["7 public holidays","9 public holidays","10 public holidays","12 public holidays"],"correct":2,"exp":"Following the introduction of the St Brigid's Day holiday in 2023, workers in Ireland are legally entitled to 10 paid public holidays a year."},{"q":"What is the maximum duration generally permitted for successive fixed-term contracts before objective justification is required?","options":["1 year","2 years","4 years","5 years"],"correct":2,"exp":"To prevent abuse, the law limits successive fixed-term contracts to a maximum of 4 years. After that period, the contract is considered permanent (unless there is an objective justification)."},{"q":"Changes to an employee's terms and conditions of employment must be confirmed in writing by the employer no later than:","options":["By the date the changes take effect","1 month before the changes take effect","Within 3 months of the changes","Within 4 months of the changes"],"correct":0,"exp":"If the terms of the contract are changed, the employer must give notice in writing no later than the day the changes take effect."},{"q":"What are the sequential stages of the product life cycle in marketing?","options":["Development, Growth, Maturity, Saturation, Decline","Introduction, Expansion, Peak, Plateau, Decline","Design, Testing, Launch, Growth, Retirement","Launch, Growth, Profit, Saturation, Loss"],"correct":0,"exp":"In marketing, the life cycle of a service or product has 5 formal stages: Development, Growth, Maturity, Saturation and Decline."},{"q":"Why is a 'pilot study' conducted prior to launching a full market research survey?","options":["To test the questions on a small sample first","To calculate the annual profit and loss account","To train drivers in vehicle maintenance","To register the company with the CRO"],"correct":0,"exp":"A pilot study is a \"trial run\" with a small group of people to check that the survey questions are well understood before spending money on launching it widely."},{"q":"How is marketing officially defined in business management?","options":["Identifying and satisfying customer needs profitably","Planning transport logistics and routing","Raising prices as high as the market allows","Filing the company's tax returns with Revenue"],"correct":0,"exp":"The classic Chartered Institute of Marketing (CIM) definition states that marketing is the management process that identifies, anticipates and satisfies customer requirements profitably."},{"q":"What does SEO stand for in the context of digital marketing for transport operators?","options":["Social Employee Organisation","Secure Earnings Operation","Search Engine Optimisation","Standard Economic Outlay"],"correct":2,"exp":"SEO (Search Engine Optimisation) is the set of techniques used to make the transport company's website appear as high as possible in the free results on Google or other search engines."},{"q":"A driver has been employed by the Ace Transport Company for 15 years. How much notice must they give AS A MINIMUM if they wish to leave to take up another job?","options":["None","One week","Twelve weeks","Fifteen weeks"],"correct":1,"exp":"Read the question carefully: it asks how much notice THE DRIVER (employee) must give to leave. The law requires a minimum of 1 week for the employee, however many years they have been working. (The 8 or more weeks would apply if it were the company dismissing them.)"},{"q":"Under the general Working Time Regulations, what is the maximum average weekly working hours limit for non-driving employees?","options":["39 hours","40 hours","48 hours","56 hours"],"correct":2,"exp":"The European Directive and Irish law state that the working week must not exceed an average of 48 hours."},{"q":"Jack Smith has worked for Bloggs Limited for ten years. Bloggs Limited is then bought by Lax Transport plc. With regard to the legal provisions concerning continuous employment (TUPE), Jack's service will be calculated from when:","options":["Lax Transport took control","Bloggs Limited was officially removed from the register","Lax Transport issued him with a new contract","He started work for Bloggs Limited"],"correct":3,"exp":"Under the TUPE rules (Transfer of Undertakings), when a company is bought by another, the employees keep all their rights and their length of service still counts from the first day they started at the original company."},{"q":"Under Irish statutory provisions, Statutory Sick Pay (SSP) requires employers to pay sick pay for a maximum of how many days per calendar year?","options":["3 days","5 days","7 days","10 days"],"correct":1,"exp":"Currently, the legal limit for sick pay paid by the employer (SSP) is set at 5 days per calendar year."}]},"106":{"title":"Mock Exam 6","questions":[{"q":"For what period is a Road Passenger Transport Operator Licence normally valid?","options":["3 years","5 years","Indefinitely","10 years"],"correct":1,"exp":"The Road Passenger Transport Operator licence is normally valid for a period of 5 years."},{"q":"Where a Transport Manager ceases to act in that role for a road passenger transport undertaking, what is the maximum period allowed for the undertaking to appoint a new Transport Manager?","options":["1 year","3 months","1 month","6 months"],"correct":3,"exp":"If the Transport Manager stops carrying out their duties, the competent authority can give the company a grace period of up to 6 months to appoint a replacement."},{"q":"In the case of a contracted Transport Manager, certain restrictions apply regarding the total number of undertakings and vehicles that he/she is allowed to manage. Which one of the following describes these restrictions?","options":["4 transport undertakings with a maximum combined fleet of 50 vehicles","2 transport undertakings with a maximum combined fleet of 50 vehicles","4 transport undertakings with a maximum combined fleet of 100 vehicles","5 transport undertakings with a maximum combined fleet of 100 vehicles"],"correct":0,"exp":"An external (contracted) transport manager is limited by law to managing a maximum of 4 transport companies, whose combined fleet does not exceed 50 vehicles."},{"q":"Which one of the following is exempt from the requirement to have a Road Passenger Transport Operator Licence for national operations?","options":["Taking employees to work in the employer's vehicles","Transport for hire or reward of school students","Private hire transport for one-off events","Transport for hire or reward of passengers to charity events"],"correct":0,"exp":"Carrying employees to or from work in vehicles owned by their own employer (own-account transport) is exempt from needing an operator licence."},{"q":"To obtain a National or International Road Passenger Transport Operator Licence, an applicant must satisfy four main criteria. These are Professional Competence, a Stable and Effective Establishment, Financial Standing, and:","options":["Good Repute","Minimum 10 years of driving experience","Public Limited Company status","A fleet of at least 5 buses"],"correct":0,"exp":"The four pillars required by the EU to obtain the licence are: Good repute, Financial standing, Professional competence and a stable and effective Establishment."},{"q":"When determining if an operator satisfies the requirement of 'Good Repute', the Minister will generally consider offences and convictions that occurred within the previous:","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"To assess good repute, the Department checks whether the operator or manager has been convicted of serious offences in the last 5 years."},{"q":"In relation to 'Hire or Reward', if an employer operates a bus to convey staff to work and deducts money from their pay for this service, how is this classified?","options":["Hire and reward: PSV licence if over 8 seats","Free staff travel, exempt from all licensing","Private, non-commercial transport for staff","A charity operation that needs no licence"],"correct":0,"exp":"If the employer deducts money from the workers' wages for the transport, the service is then considered \"hire or reward\". If the vehicle has more than 8 seats, it will require a PSV licence."},{"q":"An operator of a public scheduled service wishing to change a registered service timetable for holiday periods (e.g., Bank Holidays) must:","options":["Tell the NTA in advance","Tell the passengers only","Tell An Garda Síochána","Pay a holiday tax to Revenue"],"correct":0,"exp":"Any change to the timetables of regular routes because of public holidays must be notified to and approved by the National Transport Authority (NTA) in advance."},{"q":"Under the Public Transport Regulation Act 2009, which body is responsible for licensing commercial bus services, addressing routes, stopping places, and service frequency?","options":["The Road Safety Authority (RSA)","Local County Councils","The National Transport Authority (NTA)","The Department of Transport"],"correct":2,"exp":"The NTA is the official authority in Ireland responsible for granting licences for commercial bus services and regulating their routes and stops."},{"q":"To demonstrate a 'Stable and Effective Establishment', an operator must have a fixed place of business in Ireland, suitable operating premises, core business documents retained there, and:","options":["A taxed, insured and roadworthy vehicle","At least three directors on the board","A registered trademark for the company","A mechanical workshop on the same site"],"correct":0,"exp":"To meet the establishment requirement, the company must have at its disposal at least one vehicle that complies with all the rules (tax, insurance, roadworthiness test)."},{"q":"What is a key distinguishing feature of 'Public Scheduled Coach Operators' compared to private hire?","options":["Open to the public on a regular, published basis","They may carry only tourists on day trips","They do not need an operator licence","They only operate during the summer season"],"correct":0,"exp":"Public regular services are different because they are open to the general public, follow a published timetable and require a specific route licence from the NTA."},{"q":"In international passenger transport, excursions that carry passengers from one or more places and back generally operate:","options":["Only with a regular service route licence","Without any formalities, based purely on passenger bookings","Exclusively under bilateral treaties with non-EU countries","With a mandatory Garda escort"],"correct":1,"exp":"The vast majority of occasional excursions and tours are run without major formalities; the operator advertises them and, depending on bookings, runs or cancels the trip."},{"q":"Which of the following is typically required when taxing a commercial goods or passenger vehicle in Ireland?\n1. Vehicle Registration Certificate 2. Goods-only / PSV declaration 3. A valid insurance certificate 4. Certificate of Roadworthiness (CVRT) where required","options":["1 only","2 and 3 only","1, 2 and 3 only","1, 2, 3, and 4"],"correct":3,"exp":"To pay motor tax on a commercial vehicle, all of these documents are required: registration certificate, declaration of use, valid insurance and a current roadworthiness test (CVRT)."},{"q":"Commercial vehicles over one year old must generally undergo:","options":["Annual CVRT testing","A driving test every two years","Emissions testing only, with no certificate","No testing once insured"],"correct":0,"exp":"All heavy commercial or passenger vehicles (buses) more than one year old are required by law to pass the CVRT inspection every year."},{"q":"A Category D1 driving licence entitlement allows the holder to drive Passenger Carrying Vehicles (PCVs) having:","options":["More than 8 but not more than 16 seats","No more than 8 passenger seats","More than 16 but not more than 30 seats","Any number of passenger seats"],"correct":0,"exp":"Category D1 is a specific sub-category for minibuses that allows more than 8 passengers to be carried, but with a maximum limit of 16 seats."},{"q":"Under EU rules, what is the standard minimum age at which a driver may obtain a full Category D entitlement (without CPC exemptions for restricted routes)?","options":["18","21","24","25"],"correct":2,"exp":"The standard age for obtaining a full bus licence (Category D) is 24. (It can be lowered to 21 if the driver holds the CPC and is limited to regular routes of less than 50 km.)"},{"q":"When is a \"+E\" entitlement required to be added to a Category D or D1 driving licence?","options":["To tow a trailer over 750 kg MAM","When luggage is carried in the lockers","Whenever the bus is driven at night","When crossing international borders"],"correct":0,"exp":"The \"+E\" entitlement (e.g. D+E) is only compulsory if you are going to tow a heavy trailer whose maximum authorised mass (MAM) exceeds 750 kg."},{"q":"A driver who passed their Category B (car) test AFTER 1 January 1997 may drive a minibus with 9-16 seats on that entitlement ONLY IF specific conditions are met. Which of the following is ONE of those conditions?","options":["The vehicle is used for hire and reward","The driver is under 21 years of age","The vehicle is used by a non-commercial body for social purposes","The GVW of the vehicle exceeds 4,250kg without specialist equipment"],"correct":2,"exp":"Drivers with a car licence obtained after 1997 can exceptionally drive minibuses of up to 16 seats if it is for non-commercial social use, they are over 21, have 2 years' experience and the vehicle weighs less than 3,500 kg."},{"q":"Which one of the following is a core Transport Manager responsibility relating to vehicle taxation?","options":["Monitoring tax, insurance and CRW expiry dates","Repairing the suspension units personally","Testing the drivers' eyesight each year","Designing and running the company website"],"correct":0,"exp":"It is the direct responsibility of the Transport Manager to keep track of the expiry dates of tax, insurance and roadworthiness tests to ensure the fleet is always legal."},{"q":"In Ireland, the term \"separate fares\" covers payments made by individual passengers even if not made directly to the driver. Vehicles of 8 passenger seats or less can be used at separate fares (exempt from full PSV licensing) PROVIDED THAT:","options":["Passengers book ahead and agree to share the cost","They pick up passengers at random at bus stops","The journey is less than 10 kilometres long","The vehicle is driven by its registered owner"],"correct":0,"exp":"A car or van with up to 8 seats can charge passengers separately without being considered a public regular bus service ONLY if all the passengers book in advance and agree to share the cost of the journey."},{"q":"The basic category of driving entitlement for driving large PCVs (buses/coaches with over 16 seats) is:","options":["Category B","Category C","Category D","Category D1"],"correct":2,"exp":"Category D is the main, general licence for driving large passenger vehicles with no limit on seats."},{"q":"What does 'Cash Flow' specifically measure in a business?","options":["The depreciation of fixed assets over time","Money received into and paid out by a business","The market share of the company","The number of active bank accounts"],"correct":1,"exp":"Cash flow measures the actual money coming into (receipts) and going out of (payments) a company over a period of time."},{"q":"What is the primary advantage of debt factoring for a transport operator?","options":["Immediate cash by selling invoices to a factor","It removes the need to pay Corporation Tax","It guarantees 100% profit on all routes","It reduces vehicle depreciation rates"],"correct":0,"exp":"Factoring lets you get immediate cash by selling unpaid invoices to a finance company, instead of waiting for the customer to pay."},{"q":"Under the Organization of Working Time Act, what is the maximum average weekly working hours limit for employees?","options":["39 hours","40 hours","48 hours","60 hours"],"correct":2,"exp":"Irish law states that average weekly working time (including all work tasks, not just driving) cannot exceed 48 hours."},{"q":"Under EU Regulation 561/2006, after how many hours of continuous driving must a driver take an uninterrupted break of at least 45 minutes?","options":["3.5 hours","4.5 hours","5.5 hours","9 hours"],"correct":1,"exp":"The basic tachograph rule prohibits driving for more than 4.5 hours in a row. After that time, a 45-minute break is compulsory."},{"q":"When a 45-minute driving break is split into two parts under EU rules, what is the correct order and minimum duration of these breaks?","options":["First break at least 30 mins, second break at least 15 mins","First break at least 15 mins, second break at least 30 mins","Two equal breaks of 22.5 mins","First break at least 20 mins, second break at least 25 mins"],"correct":1,"exp":"If you split the 4.5h break, the law strictly requires the first break to be at least 15 minutes and the second at least 30 minutes, ALWAYS in that order."},{"q":"Under EU drivers' hours rules, what is the maximum permitted weekly driving time?","options":["45 hours","48 hours","56 hours","90 hours"],"correct":2,"exp":"The maximum time a driver can spend at the wheel (driving) in a single week is 56 hours."},{"q":"Under EU drivers' hours rules, what is the maximum accumulated driving time allowed in any TWO consecutive weeks?","options":["90 hours","100 hours","112 hours","56 hours"],"correct":0,"exp":"Although you can drive 56 hours in one week, the total driving hours in two consecutive weeks can never exceed 90 hours."},{"q":"What is the regular daily rest period a driver must take in a 24-hour period under EU rules?","options":["9 hours","11 hours","12 hours","45 hours"],"correct":1,"exp":"The normal (uninterrupted) daily rest a driver must take within a 24-hour period is 11 hours."},{"q":"How often must a digital tachograph system in a commercial vehicle be recalibrated and inspected by an authorized workshop?","options":["Every 6 months","Every 1 year","Every 2 years","Every 5 years"],"correct":2,"exp":"Digital tachographs must have an official inspection and calibration at an approved workshop every 2 years."},{"q":"Which driving licence category is required to drive a minibus designed to carry up to 16 passengers in addition to the driver?","options":["Category B","Category C1","Category D1","Category CE"],"correct":2,"exp":"As we saw earlier in the theory, the D1 licence is the specific category for minibuses (between 9 and 16 seats)."},{"q":"Who bears the immediate daily responsibility for conducting a pre-journey walkaround inspection of a commercial passenger vehicle?","options":["The Transport Manager","The Workshop Mechanic","The Driver","The RSA Inspector"],"correct":2,"exp":"The driver is mainly responsible for doing the daily visual check (walkaround check) before starting the vehicle, to make sure it is safe to drive."},{"q":"In passenger transport scheduling, what does the term 'Headway' mean?","options":["The interval between buses on a route","The maximum speed of a coach on a motorway","The total distance of a bus journey","The height clearance under a bridge"],"correct":0,"exp":"\"Headway\" or frequency is the time between two consecutive buses on the same route passing (for example, one bus every 15 minutes)."},{"q":"In the service marketing mix (7 Ps), which 'P' relates to the physical environment and tangible elements where the service is delivered?","options":["Process","People","Physical Evidence","Promotion"],"correct":2,"exp":"\"Physical Evidence\" covers everything the customer can see or touch, such as how clean the bus is, the driver's uniform or the design of the tickets."},{"q":"What document must be carried on board an international coach performing an occasional service under the Interbus Agreement or EU rules?","options":["A Journey Form book","A Carnet de Passages","A CMR consignment note","An NTA local service permit"],"correct":0,"exp":"For international occasional services (such as a sightseeing tour), the waybill (Feuille de Route) must be carried on board."},{"q":"What is the maximum compensation the Workplace Relations Commission (WRC) can award for an unfair dismissal claim based on financial loss?","options":["2 years' remuneration","6 months' remuneration","1 year's remuneration","5 years' remuneration"],"correct":0,"exp":"The WRC can order a company to pay the worker up to a maximum of 2 years' salary (104 weeks) if it is shown that the dismissal was unfair and caused financial loss."},{"q":"Which form must be submitted annually by a limited company to the Companies Registration Office (CRO)?","options":["Annual Return, Form B1","Form A1 for incorporation","VAT3 return to Revenue","P45 form for each employee"],"correct":0,"exp":"Form B1 (Annual Return) is the compulsory annual document that every company must file with the Companies Registration Office (CRO)."},{"q":"What is a major advantage of operating a transport business as a Private Limited Company (LTD) compared to a Sole Trader?","options":["The company pays no taxes","Shareholders have limited liability for company debts","Directors are exempt from EU drivers' hours rules","No annual financial returns are required"],"correct":1,"exp":"The main advantage of becoming a limited company (LTD) is that the members are not liable with their personal assets for the company's debts (limited liability)."},{"q":"In Ireland, what is the standard rate of VAT applicable to most taxable goods and services?","options":["13.5%","23%","0%","9%"],"correct":1,"exp":"The standard rate of Value Added Tax (VAT) in Ireland is 23%."},{"q":"An accident at work resulting in an employee being absent from work for more than how many consecutive days must be reported to the Health and Safety Authority (HSA)?","options":["1 day","3 consecutive days","7 consecutive days","14 consecutive days"],"correct":1,"exp":"Occupational health and safety law requires any accident that causes more than 3 consecutive days off work (not counting the day of the accident) to be reported to the HSA."}]},"107":{"title":"Mock Exam 7","questions":[{"q":"Under EU drivers' hours rules, what is the maximum permitted daily driving time?","options":["9 hours, or 10 hours twice a week","8 hours, which can never be exceeded","10 hours every day of the week","12 hours, including other work"],"correct":0,"exp":"The maximum daily driving time is 9 hours, which can exceptionally be extended to 10 hours a maximum of twice a week."},{"q":"Under EU rules, what is the maximum continuous driving period allowed before a mandatory break must be taken?","options":["3 hours","4 hours","4.5 hours","6 hours"],"correct":2,"exp":"After a maximum of 4 and a half hours of continuous driving, the driver must take an uninterrupted break of at least 45 minutes."},{"q":"When a 45-minute driving break is split into two parts under EU rules, what is the correct sequence of durations?","options":["30 minutes followed by 15 minutes","15 minutes followed by 30 minutes","Two equal parts of 22.5 minutes","20 minutes followed by 25 minutes"],"correct":1,"exp":"If the break is split, the first part must be at least 15 minutes and the second at least 30 minutes, in that order."},{"q":"What is the maximum weekly driving time permitted under EU rules?","options":["45 hours","48 hours","56 hours","90 hours"],"correct":2,"exp":"The maximum time at the wheel in a single week is 56 hours."},{"q":"What is the maximum accumulated driving time allowed in any two consecutive weeks?","options":["56 hours","90 hours","112 hours","120 hours"],"correct":1,"exp":"In two consecutive weeks of driving, the accumulated total cannot exceed 90 hours (for example, 56 hours in week 1 and 34 hours in week 2)."},{"q":"What is the standard regular daily rest period required within a 24-hour period?","options":["9 hours","11 hours","12 hours","24 hours"],"correct":1,"exp":"The regular daily rest must be at least 11 continuous hours (it can be reduced to 9 hours a maximum of three times a week)."},{"q":"How often must an operator download data from a driver's digital tachograph card?","options":["Every 14 days","Every 21 days","Every 28 days","Every 3 months"],"correct":2,"exp":"Companies must download and back up driver card data at least every 28 days to prevent data being overwritten."},{"q":"How long must a transport undertaking retain completed tachograph charts, printouts, and downloaded digital files?","options":["6 months","12 months","2 years","5 years"],"correct":1,"exp":"Physical and digital tachograph records must be kept in order at the company for a minimum of 12 months (1 year)."},{"q":"At what maximum interval must a digital tachograph system be inspected and recalibrated by an approved workshop?","options":["Every 1 year","Every 2 years","Every 3 years","Every 5 years"],"correct":1,"exp":"Digital tachographs require an official calibration inspection at an approved workshop every 2 years."},{"q":"If a digital tachograph breaks down on a journey, how long does the operator have to get it repaired if the vehicle cannot return to base?","options":["24 hours","48 hours","1 week from the breakdown","1 month from the breakdown"],"correct":2,"exp":"If the device fails and the vehicle does not return to its base within 1 week, it must be repaired immediately on the road."},{"q":"When requested by roadside enforcement authorities (like the RSA or Gardaí), how many days of records must a driver be able to produce?","options":["Current day and the previous 7 days","Current day and the previous 14 days","Current day and the previous 28 days","Current day and the previous 56 days"],"correct":2,"exp":"At an inspection, the driver must produce the data for the current day and the previous 28 days (extended to 56 days in general checks under EU control rules). Note: in the classic test questions of this manual, the 28-day standard still applies to the card."},{"q":"Which document permits a coach to travel at speeds up to 100 km/h on motorways in Germany?","options":["Community Licence","Tempo 100 certificate","Eurovignette","Vitesse 100 permit"],"correct":1,"exp":"The special Tempo 100 certificate is the German technical approval that allows a coach to travel at 100 km/h on motorways."},{"q":"What is the typical general speed limit for commercial vehicles in built-up (urban) areas across many European countries?","options":["30 km/h","50 km/h","60 km/h","80 km/h"],"correct":1,"exp":"The general standard limit in built-up areas or towns in Europe is 50 km/h."},{"q":"Which statement best summarises Irish motorway speed limits for buses and coaches?","options":["All buses and coaches: 100 km/h at most","Buses are limited to 80 km/h on all roads","Coaches may travel at 120 km/h like cars","Standing passenger buses may do 110 km/h"],"correct":0,"exp":"In Ireland, buses and coaches (category D) have a maximum motorway speed limit legally set at 100 km/h."},{"q":"In France, what does the road sign stating \"équipements spéciaux obligatoires\" instruct drivers to do?","options":["Give way to traffic approaching from the right","Turn back due to road closure","Fit snow chains to the vehicle tyres","Switch off headlights in tunnels"],"correct":2,"exp":"This French mountain sign means it is absolutely compulsory to fit snow chains or suitable winter tyres."},{"q":"Which of the following countries requires drivers engaged in international transport or tours to carry proof of minimum wage compliance (such as the Loi Macron or MiLoG)?","options":["Germany and France","Ireland and UK only","Spain only","Poland exclusively"],"correct":0,"exp":"Countries such as Germany (MiLoG) and France (Loi Macron) require foreign companies to provide documents proving that the driver is paid at least those countries' minimum wage while travelling through."},{"q":"Which international agreement governs the main network of international traffic arteries (E-roads)?","options":["AGR Agreement","AETR Agreement","Interbus Agreement","All of the above"],"correct":0,"exp":"The European AGR agreement regulates the naming and technical features of the main international road network (the well-known \"E\" routes)."},{"q":"What is the primary purpose of the Schengen Agreement regarding travel?","options":["No systematic passport checks at internal borders","Standardising commercial vehicle fuel taxes","Regulating drivers' tachograph working hours","Setting vehicle dimensions and weights"],"correct":0,"exp":"The Schengen area abolished border checks at the internal borders of the signatory states to make free movement of people easier."},{"q":"Which document is absolutely essential for an Irish operator performing international scheduled or regular passenger transport services within the EU?","options":["National Transport Authority Local Permit","Community Licence and Route Authorisation","CMR consignment note","National CVRT pass sheet"],"correct":1,"exp":"To operate international regular passenger services in the EU, the Community Licence and an official route authorisation are required."},{"q":"What is 'Cabotage' in the context of international passenger transport?","options":["Temporary domestic services in another EU state","Moving goods across sea borders without customs","Running a business without a registered office","Carrying employees in company-owned vehicles"],"correct":0,"exp":"Cabotage means carrying out national transport services temporarily within another European Union country other than the company's country of origin."},{"q":"What is the maximum duration permitted for a \"Closed Door Tour\" (occasional international service where the same group travels together)?","options":["7 days","14 days","30 days","90 days"],"correct":2,"exp":"Closed Door Tours under the rules on international occasional services have a maximum duration of 30 continuous days."},{"q":"From which organization must an Irish operator obtain official Waybills (Journey Forms / Feuille de Route) for international occasional passenger services?","options":["The Road Safety Authority (RSA)","The National Transport Authority (NTA)","The Revenue Commissioners","An Garda Síochána"],"correct":1,"exp":"In Ireland, the NTA is the competent authority that supplies the official books of waybills for international occasional journeys."},{"q":"Which of the following mountain tunnels provides a direct road link between France and Italy?","options":["Gotthard Tunnel","Brenner Pass","Mont Blanc Tunnel","Eurotunnel"],"correct":2,"exp":"The Mont Blanc tunnel (and the Fréjus tunnel) directly connect the road networks of France and Italy through the Alps."},{"q":"An Irish driver would need a visa or entry clearance to drive into which of the following countries?","options":["France","Ukraine","Germany","Spain"],"correct":1,"exp":"As it is not part of the European Union or the Schengen area, Ukraine requires a visa and special border formalities for foreign professional drivers."},{"q":"When crossing an international border with customs control channels, what does entering the 'Green Channel' signify?","options":["Nothing to declare at customs","Goods subject to heavy import tariffs","Transporting hazardous materials","Cash of over €50,000 on board"],"correct":0,"exp":"The green channel at customs is for travellers or vehicles that are not carrying goods subject to taxes or declaration restrictions."},{"q":"Under EU drivers' hours rules, what is the definition of a 'Break'?","options":["Time for recuperation only, with no work","Any time spent sleeping in a sleeper cab","Time spent on office paperwork for the TM","Driving under 30 km/h in city traffic"],"correct":0,"exp":"A break is a period of time during which the driver cannot do any driving or other work, used solely for rest."},{"q":"Can a driver take their mandatory daily or weekly rest period inside a moving vehicle?","options":["No, not in a moving vehicle","Yes, if sleeping on a proper mattress","Yes, if the second driver is driving","Yes, under emergency exemptions"],"correct":0,"exp":"Taking daily or weekly rest periods while the vehicle is moving is strictly prohibited."},{"q":"Under EU rules, what is the minimum duration of a 'Reduced Weekly Rest' period?","options":["9 hours","11 hours","24 hours","45 hours"],"correct":2,"exp":"The reduced weekly rest allows the rest to be shortened to a minimum of 24 uninterrupted hours (requiring compensation later)."},{"q":"If a multi-manning crew operates a coach, what is the maximum continuous driving period before a changeover or break under EU rules?","options":["3 hours","4.5 hours","9 hours","10 hours"],"correct":1,"exp":"Even with multi-manning, the limit on continuous driving before a 45-minute break is still 4.5 hours for each driver."},{"q":"What is the main objective of the AETR agreement?","options":["EU-style hours rules for non-EU countries","Harmonising vehicle weights worldwide","Regulating air quality in European cities","Free medical insurance for drivers abroad"],"correct":0,"exp":"The AETR agreement regulates the driving and rest hours of crews of vehicles engaged in international road transport in the non-EU countries that signed it, aligning them with EU rules."},{"q":"What is the minimum age requirement to drive a regular scheduled bus route exceeding 50 km with a full Category D licence (assuming completion of Driver CPC)?","options":["18 years old","21 years old","23 years old","24 years old"],"correct":1,"exp":"With the initial Driver CPC qualification, the minimum age for driving category D buses on regular routes of more than 50 km is reduced to 21 (instead of the general 24)."},{"q":"Which authority in Ireland is responsible for issuing Driver CPC Qualification Cards?","options":["National Transport Authority (NTA)","Road Safety Authority (RSA)","Department of Transport","Revenue Commissioners"],"correct":1,"exp":"The RSA manages and issues driver qualification cards (Driver CPC) in Ireland."},{"q":"How often must professional drivers undergo periodic CPC training (Continuing Training) to maintain their vocational qualification?","options":["Every 1 year","Every 3 years","Every 5 years","Every 10 years"],"correct":2,"exp":"Driver CPC refresher training requires completing 35 hours of periodic training every 5 years."},{"q":"Under what circumstances is a driver exempt from the EU drivers' hours rules while operating a passenger vehicle?","options":["Regular services on routes up to 50 km","When driving on a motorway at night","Carrying passengers on international tours","If the vehicle has fewer than 30 seats"],"correct":0,"exp":"Regular passenger services whose route does not exceed 50 kilometres are exempt from the European Regulation 561/2006 on driving and rest times."},{"q":"What type of tachograph recording equipment must be fitted in all newly registered commercial vehicles since June 2019 / August 2023?","options":["Smart tachographs","Analogue paper charts only","Magnetic cassette tapes","All of the above"],"correct":0,"exp":"New commercial transport vehicles must be fitted with the latest generation of smart tachographs with satellite positioning."},{"q":"Who is legally responsible for ensuring that drivers comply with EU rules on driving hours and rest periods?","options":["The operator and the driver","The vehicle manufacturer","The roadside traffic warden","The fuel station attendant"],"correct":0,"exp":"Legal responsibility lies jointly with both parties: the operator (company) must organise the work legally and supervise it, and the driver must comply individually."},{"q":"What is the maximum permitted weight on a single non-driving axle of a bus or coach in Ireland?","options":["6 tonnes","7.5 tonnes","10 tonnes","11.5 tonnes"],"correct":2,"exp":"The default legal weight limit for a single non-driven steering axle in Ireland is usually 10 tonnes (and up to 11.5 tonnes for single driving axles in certain configurations)."},{"q":"What is the primary purpose of vehicle 'Plating'?","options":["To certify the maximum permitted weights","To set the insurance premium category","To record the purchase price of the chassis","To name the vehicle's leasing company"],"correct":0,"exp":"The official plate (plating) certifies the maximum authorised and design weights legally permitted for the vehicle."},{"q":"When an operator replaces an existing vehicle on their licence, within what timeframe must they notify the licensing authority (Department of Transport)?","options":["Promptly, within the licence conditions","Within 5 years of the change","Only when renewing the licence","No need to notify vehicle changes"],"correct":0,"exp":"Any change to the make-up of the fleet linked to the licence must be notified to the competent authority within the regulatory deadlines."},{"q":"What is a 'Multimanning' operation in relation to drivers' hours?","options":["Two or more drivers available between rests","Mechanics travelling on board every bus","Several transport managers for one branch","Three drivers sharing one tachograph card"],"correct":0,"exp":"Multi-manning is when there are at least two drivers in the vehicle to take turns driving during the daily rest periods."}]},"108":{"title":"Mock Exam 8 - Summaries A (passenger)","questions":[{"q":"Which of the following are minimum requirements for a public limited company (PLC)?\n1. At least 2 members (shareholders)\n2. At least 2 directors\n3. Nominal and issued share capital of at least €25,000\n4. No company secretary is required","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"A PLC needs at least 2 members, 2 directors, a secretary and capital of at least €25,000. Statement 4 is false: it does need a secretary.\n📍 Summary M2 p.15 · book p.6 (5.1)"},{"q":"In a 'members voluntary' winding up of a limited company:","options":["The company must be solvent and the shareholders control the process","The company cannot pay its debts and the creditors control the process","The courts control the process","Revenue appoints the liquidator and controls the process"],"correct":0,"exp":"Members' voluntary: solvent company, the shareholders are in charge. Creditors' voluntary: it cannot pay, the creditors are in charge. Compulsory: controlled by the courts.\n📍 Summary M2 p.16 · book p.12 (9.)"},{"q":"What is the maximum entitlement to Statutory Sick Pay (SSP)?","options":["5 days at 70% of normal pay, capped at €110","10 days at 50% of normal pay","3 days at 100% of normal pay","5 days at 100% of normal pay, capped at €200"],"correct":0,"exp":"SSP: a maximum of 5 days at 70% of normal pay, capped at €110. It is only paid after 13 weeks with the company and for days the employee was due to work.\n📍 Summary M3 p.28 · book p.13 (3.10)"},{"q":"Which of the following are inadmissible (unfair) reasons for dismissal?\n1. Trade union membership or activities\n2. The employee's conduct\n3. Pregnancy\n4. Membership of the traveller community","options":["1, 3 and 4 only","1 and 3 only","2 and 4 only","All of the above"],"correct":0,"exp":"The employee's conduct is one of the 4 FAIR grounds for dismissal (capability, conduct, redundancy, other substantial reason). Trade union membership, pregnancy or being a member of the Traveller community are inadmissible grounds.\n📍 Summary M3 p.28 · book p.20 (4.6)"},{"q":"Of the five key steps in a risk assessment, which is the first?","options":["Identify potential hazards","Record your findings and implement them","Decide who may be harmed and how","Review the assessment on a regular basis"],"correct":0,"exp":"The 5 steps: 1) identify the hazards, 2) who might be harmed and how, 3) evaluate the risks and decide on precautions, 4) record and implement, 5) review regularly.\n📍 Summary M4 p.15 · book p.9 (5.)"},{"q":"The acid test (quick assets) ratio is calculated as:","options":["Current assets less stock, divided by current liabilities","Current assets divided by current liabilities","Fixed assets less stock, divided by current liabilities","Current assets plus stock, divided by current liabilities"],"correct":0,"exp":"Acid test = (current assets − stock) ÷ current liabilities. The others are the current ratio, capital employed and ROCE.\n📍 Summary M5 p.22 · book p.10 (8.3)"},{"q":"Which of the following is a short-term (less than one year) source of funds?","options":["An overdraft","Debentures","Shares","Revenue reserve (ploughed back profit)"],"correct":0,"exp":"Short term: creditors, overdrafts, short-term loans and taxes due. Shares, debentures and retained profits are long term.\n📍 Summary M5 p.21 · book p.3 (3.3)"},{"q":"What is debt factoring?","options":["Selling invoices to a factor who collects them","Borrowing against the value of the vehicles","Writing off debts customers will never pay","Paying suppliers in monthly instalments"],"correct":0,"exp":"With factoring you 'sell' your invoices to the bank or a factoring company, which collects the debt. It gives you cash straight away.\n📍 Summary M5 p.22 · book p.13 (10.3)"},{"q":"A credit note is used to:","options":["Correct an overcharge on an invoice","Correct an undercharge on an invoice","Request goods or services from a supplier","Give a rough, often verbal, costing"],"correct":0,"exp":"A credit note corrects an OVERcharge; a debit note corrects an UNDERcharge. A request to buy is an 'order' and an approximate price is an 'estimate'.\n📍 Summary M6 p.7 · book p.3 (3.)"},{"q":"Which of the following are advantages of a flat hierarchy?\n1. Fewer layers of management, so lower costs\n2. Better vertical communication\n3. More opportunities for promotion\n4. Delegation is encouraged","options":["1, 2 and 4 only","1 and 3 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"More promotion opportunities is an advantage of the TALL structure. In the flat structure there are fewer possible promotions.\n📍 Summary M8 p.7 · book p.1 (2.)"},{"q":"What is the standard rate of Corporation Tax on trading income in Ireland?","options":["12.5%","25%","23%","10%"],"correct":0,"exp":"12.5% on trading profits; 25% on non-trading income (e.g. investments). 23% is the standard VAT rate.\n📍 Summary M9 p.21 · book p.1 (2.)"},{"q":"An operator carries passengers for hire or reward, only within the 26 counties, in vehicles with more than 8 passenger seats. Which licence does the undertaking need from the Department of Transport?","options":["A National Road Passenger Transport Operator Licence","An International Road Passenger Transport Operator Licence with a Community Licence","Only a Public Bus Passenger Service Licence","No licence, as long as the vehicles are taxed"],"correct":0,"exp":"Only within the 26 counties: NATIONAL passenger operator licence. For the EU, the United Kingdom or Northern Ireland you need the International one with a Community Licence.\n📍 Summary M10 p.27 · book p.1"},{"q":"A Public Bus Passenger Service Licence (formerly a 'Route Licence') for a regular service on a specified route is issued by:","options":["The National Transport Authority (NTA)","The Department of Transport","A PSV Officer of An Garda Síochána","The Road Safety Authority (RSA)"],"correct":0,"exp":"The route licence is issued by the NTA. The operator licence by the Department of Transport; the vehicle's Large PSV Licence by a Garda PSV Officer.\n📍 Summary M10 p.27 · book p.1"},{"q":"To obtain and hold a Road Passenger Transport Operator Licence, the undertaking must satisfy which of the following?\n1. Good repute\n2. Financial standing\n3. Professional competence\n4. A stable and effective establishment in Ireland","options":["All of the above","1, 2 and 3 only","1 and 3 only","2, 3 and 4 only"],"correct":0,"exp":"They are the 4 requirements: good repute, financial standing, professional competence (someone with the passenger CPC as transport manager) and a stable establishment in Ireland.\n📍 Summary M10 p.27 · book p.6 (Criteria)"},{"q":"Under EU Regulation 561/2006, what is the maximum driving time before a break must be taken?","options":["4½ hours","5½ hours","4 hours","6 hours"],"correct":0,"exp":"EU: 4½ h and then a 45 min break (or 15 + 30 min). The 5½ h is the Irish DOMESTIC rule.\n📍 Summary M11 p.17 · book p.2 (2.2)"},{"q":"Under EU Regulation 561/2006, which of the following statements are correct?\n1. Maximum daily driving is 9 hours, extendible to 10 hours twice per week\n2. Maximum weekly driving is 56 hours\n3. Maximum fortnightly driving is 100 hours\n4. Normal daily rest is 11 hours","options":["1, 2 and 4 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"In two consecutive weeks the maximum is 90 h, not 100. The rest is correct.\n📍 Summary M11 p.17 · book p.2–3 (2.4–2.7)"},{"q":"Under the domestic drivers' hours rules (vehicles exempt from 561/2006), what is the maximum daily spreadover?","options":["16 hours","13 hours","15 hours","12 hours"],"correct":0,"exp":"Domestic rules: 5½ h before a break, 10 h of driving a day, 16 h spreadover, minimum break of 30 min and 10 h of daily rest.\n📍 Summary M11 p.18 · book p.10 (5.)"},{"q":"How often must data be downloaded from a driver card?","options":["At least every 28 days","At least every 90 days","At least every 7 days","Once a year"],"correct":0,"exp":"Driver card: at least every 28 days. Vehicle unit (VU): every 90 days. Everything downloaded is kept for at least 1 year.\n📍 Summary M12 p.15 · book p.5 (3.9)"},{"q":"If a driver card is lost or stolen, what is the maximum period a driver may drive without a replacement card?","options":["15 calendar days","7 calendar days","28 calendar days","5 working days"],"correct":0,"exp":"A maximum of 15 calendar days, telling the RSA as soon as possible and taking printouts from the VU at the start and end of each day.\n📍 Summary M12 p.15 · book p.3 (3.4)"},{"q":"For how long must records of vehicle defects and their rectification be kept?","options":["15 months","12 months","2 years","6 months"],"correct":0,"exp":"Defects and their repair, like all maintenance records, are kept for 15 months.\n📍 Summary M13 p.15 · book p.5 (5.3)"},{"q":"Which of the following are standing costs?\n1. Vehicle tax\n2. Fuel\n3. Drivers' wages\n4. Depreciation","options":["1, 3 and 4 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"The 5 standing costs: vehicle tax, insurance, drivers' wages, depreciation and administration. Fuel is a running cost.\n📍 Summary M14 p.19 · book p.2 (3.)"},{"q":"Over how many working days per year do operators often try to recover their vehicle costs?","options":["225","365","260","200"],"correct":0,"exp":"225 days (45 weeks × 5 days), because weekends, bank holidays and breakdowns prevent working all 365.\n📍 Summary M14 p.20 · book p.12 (6.1)"},{"q":"For passenger buses and coaches in Ireland, motor tax is based on:","options":["Seating capacity","Engine size","Unladen weight","CO2 emissions"],"correct":0,"exp":"Buses: according to the number of seats. Heavy goods vehicles pay according to unladen weight.\n📍 Summary M15 (PSV section) p.10 · book p.2 (5.)"},{"q":"Under the GDPR, if an individual asks to see the personal data held about them, the data holder must generally make it available within:","options":["30 days","7 days","60 days","90 days"],"correct":0,"exp":"As a general rule, within 30 days. Anyone who keeps personal data must have a data controller.\n📍 Summary M17 p.7 · book p.5 (6.)"},{"q":"What is the maximum width of a passenger vehicle for more than 8 passengers?","options":["2.55 metres","2.50 metres","2.60 metres","2.65 metres"],"correct":0,"exp":"Maximum width: 2.55 m. The maximum height is 4.65 m.\n📍 Summary M18 p.5 · book p.2"},{"q":"What does the 'plating' of a vehicle certify?","options":["The vehicle's maximum permitted weights","That the vehicle has passed its annual roadworthiness test","The vehicle's registration and ownership","That the vehicle's tachograph has been calibrated"],"correct":0,"exp":"'Plating' certifies the maximum weights (GVW, GTW and per axle). Exceeding them is an offence. A passed CVRT gives the Certificate of Roadworthiness (CRW).\n📍 Summary M19 p.5 · book p.1 (2.)"},{"q":"When must a bus have its first CVRT, and how often after that?","options":["At one year old, then annually","At three years old, then every two years","At four years old, then annually","Only when it is sold"],"correct":0,"exp":"Lorries, buses and trailers: first CVRT at one year old and then every year.\n📍 Summary M20 p.5 · book p.1 (4.)"},{"q":"What is the minimum age to drive a large bus (Category D), and how can it be lowered?","options":["24, lowered to 21 with a Driver CPC","21, lowered to 18 with a Driver CPC","24, and it cannot be lowered","18 for all buses"],"correct":0,"exp":"Category D: 24, which drops to 21 with the Driver CPC. Category D1 (small buses): 21.\n📍 Summary M21 p.9 · book p.2 (2.2)"},{"q":"After the age of 65, how often must a vocational (bus) licence be renewed?","options":["Every year","Every 5 years","Every 3 years","Every 10 years"],"correct":0,"exp":"The first licence lasts a maximum of 5 years and is renewed every 5 years; from age 65, every year.\n📍 Summary M21 p.10 · book p.6 (5.)"},{"q":"What is the motorway speed limit in Ireland for a bus or coach NOT designed for standing passengers?","options":["100 km/h","90 km/h","80 km/h","65 km/h"],"correct":0,"exp":"Motorway: coach without standing passengers, 100; lorry over 3,500 kg, 90; with a trailer, 80; bus with standing passengers, 65 km/h.\n📍 Summary M22 p.7 · book p.1 (3.)"},{"q":"Under section 106 of the Road Traffic Act 1961, an accident has occurred where a vehicle is involved and:\n1. Damage is caused to another vehicle\n2. Injury is caused only to the driver of that vehicle\n3. Damage is caused to property on or next to the road\n4. Injury is caused to a dog","options":["1, 3 and 4 only","1 and 3 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"What counts is injury to a person OTHER than the driver. The dog is one of the animals on the list (horse, cattle, ass, mule, sheep, pig, goat, dog).\n📍 Summary M23 p.7 · book p.1 (2.1)"},{"q":"Which type of motor insurance is the minimum legal requirement for every vehicle used on a public road in Ireland?","options":["Third-party motor insurance","Goods in transit insurance","Fidelity guarantee insurance","Consequential loss insurance"],"correct":0,"exp":"The compulsory minimum is third-party insurance: it covers damage to other people (passengers included) and their property. The other insurances are optional.\n📍 Book M24 p.1"},{"q":"From what date did Euro 6 emission standards become compulsory?","options":["1 January 2014","1 January 2009","1 January 2020","1 January 2012"],"correct":0,"exp":"Euro 6 has been compulsory since 1 January 2014 (SCR and EGR technologies, particulate filters, hybrids).\n📍 Summary M25 p.12 · book p.7 (8.)"},{"q":"A coach driver is going on a tour to France. Which of the following should the driver carry?\n1. Passport\n2. Driving licence and DQC\n3. A certified copy of any current prescriptions\n4. A minimum wage document","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"The certified copy of prescriptions is required by France; the minimum wage document is for GERMANY.\n📍 Summary M26 p.9 · book p.1 (2.)"},{"q":"A Regular Service Authorisation issued by IRFO for a regular international service is valid for:","options":["5 years","1 year","3 years","10 years"],"correct":0,"exp":"International regular services are applied for to IRFO, which issues a Regular Service Authorisation valid for 5 years.\n📍 Summary M28 p.14 · book p.5 (4.)"},{"q":"On an Interbus waybill, which box is used for a closed door tour?","options":["Box A","Box B","Box C","Box C1"],"correct":0,"exp":"A = closed door tour; B = outward with passengers and return empty; C = outward empty and return with passengers (C1, C2 and C3 are variants of C).\n📍 Summary M28 p.14 · book p.9 (9.3)"},{"q":"Which of the following are examples of abuse of a dominant position?\n1. Predatory pricing\n2. Excessive pricing\n3. Refusing rivals access to essential facilities such as depots or stops\n4. Simply holding a dominant position","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"Having a dominant position is NOT illegal; what is illegal is abusing it.\n📍 Summary M29 p.10 · book p.4 (3.2)"},{"q":"In timetabling, the 'headway' is:","options":["The time interval between buses","The number of buses passing a point each hour","Terminus time to change blinds and do waybills","Time built in to allow for heavy traffic"],"correct":0,"exp":"Headway = minutes between buses. The others are frequency, layover time and recovery time.\n📍 Summary M30 p.13 · book p.2 (3.)"},{"q":"Under a gross cost contract for a tendered bus service:","options":["The operator bids on cost; the authority keeps fares","The operator keeps all revenue and asks for subsidy","The lowest tender must always be the one accepted","The operator is paid nothing until the contract ends"],"correct":0,"exp":"Gross cost: the operator is paid its cost and the authority keeps the takings. Net cost: the operator keeps the takings and asks for a subsidy. You do not always have to choose the cheapest bid, but the one with the best value for money.\n📍 Summary M31 p.7 · book p.4 (3.)"},{"q":"For international journeys, drivers need a current valid passport with at least how much remaining validity?","options":["3 months","6 months","1 month","12 months"],"correct":0,"exp":"A current passport with at least 3 months' validity remaining. A visa is needed for most former USSR countries, Turkey and the Middle East.\n📍 Summary M32 p.10 · book p.5 (9.)"}]},"109":{"title":"Mock Exam 9 - Summaries B (passenger)","questions":[{"q":"Which of the following are essentials of a valid contract?\n1. Offer and acceptance\n2. Consideration\n3. Capacity and intention\n4. Legality","options":["All of the above","1 and 2 only","1, 2 and 3 only","2, 3 and 4 only"],"correct":0,"exp":"The essential elements are: offer, acceptance, consideration, capacity, intention, legality and formalities. They are all there.\n📍 Summary M2 p.15 · book p.1 (2.)"},{"q":"For what minimum period must company accounts be kept?","options":["6 years","2 years","10 years","12 months"],"correct":0,"exp":"The company's accounts are kept for at least 6 years.\n📍 Summary M2 p.16 · book p.9 (7.4)"},{"q":"What is the statutory minimum notice an employer must give an employee with 5 to 10 years' service?","options":["4 weeks","2 weeks","6 weeks","8 weeks"],"correct":0,"exp":"Notice: less than 13 weeks, none; up to 2 years, 1 week; 2 to 5 years, 2; 5 to 10 years, 4; 10 to 15 years, 6; more than 15 years, 8 weeks. The employee always gives 1 week.\n📍 Summary M3 p.28 · book p.14 (3.11)"},{"q":"How many weeks of maternity leave are all employees entitled to, regardless of length of service?","options":["42 weeks","26 weeks","16 weeks","52 weeks"],"correct":0,"exp":"42 weeks of leave regardless of length of service. The benefit (Statutory Maternity Pay) covers a maximum of 26 weeks and requires contributions (PRSI).\n📍 Summary M3 p.27 · book p.8 (3.7)"},{"q":"Health and Safety Authority (HSA) inspectors may issue which of the following?\n1. An Improvement Plan\n2. An Improvement Notice\n3. A Prohibition Notice\n4. An operator licence suspension notice","options":["1, 2 and 3 only","2 and 3 only","1 and 3 only","All of the above"],"correct":0,"exp":"The HSA issues Improvement Plans, Improvement Notices and Prohibition Notices. The operator licence is not its business.\n📍 Summary M4 p.16 · book p.11 (6.)"},{"q":"Working capital is calculated as:","options":["Current assets minus current liabilities","Total assets minus current liabilities","Current assets ÷ current liabilities","Turnover minus direct costs"],"correct":0,"exp":"Working capital = current assets − current liabilities. Total assets − current liabilities is capital employed, and turnover − direct costs is gross profit.\n📍 Summary M5 p.22 · book p.10 (8.1)"},{"q":"In stock control, the 'lead time' is:","options":["The time between placing an order and receiving the goods","The time an item stays in stock before it is used","The time allowed to pay a supplier","The time taken to count the stock"],"correct":0,"exp":"Lead time = the time between placing an order and receiving it. It must be taken into account to know when to reorder.\n📍 Summary M5 p.22 · book p.15 (12.)"},{"q":"Which document is used when payment in advance is required?","options":["A pro-forma invoice","A debit note","A statement of account","A quotation"],"correct":0,"exp":"A pro-forma invoice is used when payment in advance is required.\n📍 Summary M6 p.7 · book p.2 (2.5)"},{"q":"VAT registration is required when turnover from services is expected to exceed:","options":["€42,500","€85,000","€37,500","€75,000"],"correct":0,"exp":"Services: €42,500. Goods: €85,000. Below that you can register voluntarily. VAT is usually paid every quarter.\n📍 Summary M9 p.22 · book p.6 (4.3)"},{"q":"A National Road Passenger Transport Operator Licence is normally valid for:","options":["5 years","1 year","3 years","10 years"],"correct":0,"exp":"Both the national and the international licence normally last 5 years.\n📍 Summary M10 p.27 · book p.1"},{"q":"Which of the following are typically exempt from needing a Road Passenger Transport Operator Licence?\n1. Carrying employees to and from work in vehicles owned by their employer\n2. Not-for-profit carriage in vehicles owned by voluntary organisations\n3. A hotel's complimentary transport service for its guests\n4. A coach tour sold to the public for a fare","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"An excursion sold to the public is transport for hire or reward and needs a licence. The other three are examples of exemptions.\n📍 Summary M10 p.27 · book p.4 (Part A)"},{"q":"Under EU rules, regular weekly rest is 45 hours. To what minimum can it be reduced?","options":["24 hours","36 hours","33 hours","11 hours"],"correct":0,"exp":"It can be reduced to 24 h, compensating before the end of the 3rd following week, and a full 45 h rest must be taken every 2 weeks.\n📍 Summary M11 p.17 · book p.3 (2.9)"},{"q":"Under the working time rules for EU-regulated drivers, what is the maximum average working week?","options":["48 hours, averaged over 17 weeks","60 hours, averaged over 4 months","56 hours, averaged over 2 weeks","40 hours, with no averaging allowed"],"correct":0,"exp":"An average of 48 h, normally over a 17-week period, with a maximum of 60 h in a single week.\n📍 Summary M11 p.17 · book p.6 (3.2)"},{"q":"As a standard requirement, how long must an operator keep completed analogue tachograph charts?","options":["12 months","28 days","6 months","6 years"],"correct":0,"exp":"12 months, or 2 years if the working time rules require it. The driver carries the current day and the previous 28 days.\n📍 Summary M12 p.16 · book p.10 (4.5)"},{"q":"Which of the following traces are recorded on an analogue tachograph chart?\n1. The driver's activity\n2. Distance\n3. Speed\n4. Engine temperature","options":["1, 2 and 3 only","1 and 3 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"Three traces: driver activity (the thickness of the line changes), distance (each 'V' is 10 km) and speed (in km/h).\n📍 Summary M12 p.15 · book p.8 (4.3)"},{"q":"Under the Guide to Maintaining Roadworthiness, who must carry out the daily walkround check, and when?","options":["The driver, every time before use","The workshop staff, once a week","The transport manager, once a day","An RSA inspector, at the annual test"],"correct":0,"exp":"The driver does it every time, before using the vehicle; it can be several times a day if different drivers use it. The 'nil defect' system is recommended.\n📍 Summary M13 p.15 · book p.2 (5.1)"},{"q":"Straight line depreciation:","options":["Takes away the same amount each year over the vehicle's life","Takes away more in the early years and less later on","Is calculated from the vehicle's fuel consumption","Only applies to the original set of tyres"],"correct":0,"exp":"Straight line: the same amount every year. Reducing balance: more at the start and less afterwards. In both cases the tyres are deducted first.\n📍 Summary M14 p.19 · book p.3 (3.4)"},{"q":"Which of the following is a variable cost?","options":["Fuel","Vehicle tax","Vehicle insurance","Office staff wages"],"correct":0,"exp":"Variable = it changes with use (fuel, tyres, maintenance). Tax and insurance are fixed, and office salaries are indirect costs.\n📍 Summary M14 p.19 · book p.1 (2.)"},{"q":"What is the annual motor tax for a passenger bus with 9 to 20 seats (rates as at 2026)?","options":["€133","€175","€333","€349"],"correct":0,"exp":"Buses, by seats: 9 to 20, €133; 21 to 40, €175–202; 41 and over, €349–403. The €333 figure is the rate for a light goods van.\n📍 Summary M15 (PSV section) p.10 · book p.2 (5.1)"},{"q":"When an operator sub-contracts work, which statement is correct?","options":["The operator remains responsible for the performance of the contract","The sub-contractor becomes responsible to the client instead","The operator must tell the sub-contractor the price the client is paying","Sub-contracting is never allowed"],"correct":0,"exp":"Work can be subcontracted unless the contract prohibits it, but the operator remains responsible. It does not have to tell the subcontractor how much the customer pays.\n📍 Summary M16 p.11 · book p.4 (7.)"},{"q":"What is the maximum gross weight of a 2-axle bus?","options":["19.5 tonnes","18 tonnes","26 tonnes","16 tonnes"],"correct":0,"exp":"2-axle bus: 19.5 t. 3-axle buses weigh more, and it can rise by 1 t if it runs on alternative fuel or 2 t if it is zero-emission.\n📍 Summary M18 p.5 · book p.2"},{"q":"After passing the CVRT, a vehicle is issued with:","options":["A Certificate of Roadworthiness","A new plating certificate","A Community Licence copy","A Green Card for insurance"],"correct":0,"exp":"The CRW is carried in the vehicle or kept available for inspection, and the RSA also records it electronically.\n📍 Summary M19 p.6 · book p.2 (5.)"},{"q":"For non-compliance such as operating without a valid CVRT, operators or drivers may face:","options":["Fines up to €5,000 and up to 6 months' prison","A fixed fine of €1,000 and nothing more","Fines up to €50,000 and 5 years' prison","Penalty points on the licence only"],"correct":0,"exp":"Fines of up to €5,000, possible prison of up to 6 months, penalty points and a ban on using the vehicle.\n📍 Summary M20 p.6 · book p.3 (9.)"},{"q":"What is the maximum validity of an initial vocational (bus) licence?","options":["5 years","10 years","3 years","Until the age of 65"],"correct":0,"exp":"The first licence lasts a maximum of 5 years; after that it is renewed every 5 years, and every year from age 65.\n📍 Summary M21 p.10 · book p.6 (5.)"},{"q":"To gain a vocational (bus) licence, a candidate must pass:\n1. A theory test\n2. A hazard perception test\n3. The Driver CPC case studies\n4. A practical test","options":["All of the above","1 and 4 only","1, 2 and 4 only","2, 3 and 4 only"],"correct":0,"exp":"All four must be passed: theory, hazard perception, Driver CPC case studies and the practical test.\n📍 Summary M21 p.9 · book p.4 (4.)"},{"q":"A Category D1 licence covers buses with:","options":["9 to 16 passenger seats","More than 16 passenger seats","Up to 8 passenger seats","Any bus towing a trailer over 750 kg"],"correct":0,"exp":"D1: 9 to 16 passenger seats. D: more than 8 seats. Trailers over 750 kg need '+E'.\n📍 Summary M21 p.9 · book p.1 (2.)"},{"q":"A speed limiter must be fitted to all vehicles with more than 8 passenger seats and set to a maximum of:","options":["100 km/h","90 km/h","80 km/h","110 km/h"],"correct":0,"exp":"Vehicles with more than 8 seats: limiter set to 100 km/h.\n📍 Summary M22 p.7 · book p.2 (4.)"},{"q":"Double continuous yellow lines in the gutter, parallel to the kerb, mean:","options":["No parking 24 hours a day","No parking during the times shown on a nearby sign","Loading only","Buses only"],"correct":0,"exp":"Double continuous line: no parking 24 hours a day. Single line: for a shorter period, as shown.\n📍 Summary M22 p.8 · book p.3 (9.)"},{"q":"The European Accident Statement is:","options":["A joint form both drivers sign and send to insurers","A Garda report to be completed within 24 hours","A form sent to the RSA after every accident abroad","A statement needed only when someone is injured"],"correct":0,"exp":"It is the European Accident Statement: both drivers sign it, each keeps a copy and sends it to their insurer when they get back.\n📍 Summary M23 p.7 · book p.5 (8.5)"},{"q":"If a driver cannot produce a certificate of insurance when asked by the Gardaí, how long is allowed to produce it at a nominated Garda station?","options":["10 days","7 days","14 days","24 hours"],"correct":0,"exp":"10 days to produce it in person at the Garda station named. The Garda can also check it on the IMID database.\n📍 Summary M24 p.15 · book p.2 (2.5)"},{"q":"Fidelity guarantee insurance covers:","options":["The dishonesty of employees","Storm and flood damage to property","The loss of client data","Death, injury or disease of employees"],"correct":0,"exp":"Fidelity guarantee = employee dishonesty. The other options are storm and flood insurance, cyber insurance and employer's liability insurance.\n📍 Summary M24 p.16 · book p.12 (5.5)"},{"q":"Which of the following are included in a vehicle's whole life costs?\n1. Fuel economy\n2. Maintenance costs\n3. Downtime\n4. Depreciation","options":["All of the above","1 and 2 only","1, 2 and 4 only","2, 3 and 4 only"],"correct":0,"exp":"The whole-life cost includes consumption, maintenance, tyre life, downtime, depreciation and insurance.\n📍 Summary M25 p.12 · book p.9 (9.)"},{"q":"Which document is required for all sea journeys with passengers?","options":["A passenger list","A Green Card","A minimum wage document","An International Driving Permit"],"correct":0,"exp":"A passenger list is needed on all sea crossings; the SOLAS convention also requires it.\n📍 Summary M26 p.9 · book p.5–7 (3.)"},{"q":"Cabotage occurs when:","options":["Temporary trips inside another country","Trips between two different EU countries","A service run entirely in its own country","Passengers carried free of charge"],"correct":0,"exp":"Cabotage = carrying within ANOTHER country, temporarily. In the EU the international licence is needed and the host country's rules must be followed.\n📍 Summary M28 p.14 · book p.10 (10.)"},{"q":"A 'closed door tour' is an occasional service in which:","options":["The same group goes out and comes back with it","Passengers are picked up at stops on a fixed route","The coach goes out full and comes back empty","Passengers are collected in the destination country"],"correct":0,"exp":"Closed door tour: the same passengers on the outward and return journeys, within 90 days at most. On the Interbus waybill it is box A.\n📍 Summary M28 p.14 · book p.8 (9.)"},{"q":"Which of the following are true of special regular international services?\n1. They are a sub-category of regular services\n2. They carry a defined group of passengers, such as students or employees\n3. A certified copy of the contract and an EU waybill must be carried on the vehicle\n4. They do not need any authorisation","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","All of the above"],"correct":0,"exp":"They are applied for to IRFO in the same way as regular services, so they do need authorisation.\n📍 Summary M28 p.14 · book p.7 (7.)"},{"q":"Which body enforces Irish and EU competition law in Ireland?","options":["The Competition and Consumer Protection Commission","The Office of the Director of Corporate Enforcement","The Commission for Communications Regulation","The National Transport Authority"],"correct":0,"exp":"The CCPC investigates, carries out surprise searches (dawn raids), prohibits and fines. It does not regulate transport or set fares; the NTA manages integrated ticketing.\n📍 Summary M29 p.9 · book p.1"},{"q":"Which formula gives the number of vehicles needed to run a service?","options":["(Running time + stand time) × 2 ÷ headway","(Number of buses × working time) ÷ shift length","(Distance × 60) ÷ average speed","(Headway × frequency) ÷ 60"],"correct":0,"exp":"Vehicles = (one-way journey time + layover at one end) × 2 ÷ headway. The second option gives the number of shifts and the third the time between stops.\n📍 Summary M30 p.13 · book p.3 (4.)"},{"q":"Tendering authorities must publish details of:\n1. All tenders received\n2. The amounts of the highest and lowest tenders\n3. The amount of the successful tender\n4. The name of the successful tenderer","options":["All of the above","1 and 3 only","3 and 4 only","1, 3 and 4 only"],"correct":0,"exp":"All of that is published, and the decision is based on the best value for money, not necessarily the cheapest bid.\n📍 Summary M31 p.7 · book p.6 (3.5)"},{"q":"The Schengen Agreement:","options":["Travel inside the area without border checks","It sets the rules for safety of life at sea","Removes customs duties on all goods worldwide","Allows cabotage everywhere without a licence"],"correct":0,"exp":"Schengen: 29 countries (25 from the EU plus Iceland, Liechtenstein, Norway and Switzerland) without internal border checks. Safety at sea is the SOLAS convention.\n📍 Summary M32 p.9 · book p.4 (8.)"}]},"110":{"title":"Mock Exam 10","questions":[{"q":"Under the Road Transport Act 2011, which of the following national operations is EXEMPT from needing a Road Passenger Transport Operator Licence?","options":["Carrying pupils to or from school in vehicles owned by the school","A coach company running paid private hire trips for a football club","A tour operator charging per seat for day trips","An operator running a paid contract service for a hotel chain"],"correct":0,"exp":"Exemptions in the book: carrying workers in their company's vehicles, pupils in school vehicles, not-for-profit transport by voluntary organisations and purely non-commercial transport. If a charge is made, a licence is needed.\n📍 Book M10 p.4"},{"q":"A hotel runs a complimentary 12-seat minibus between the railway station and the hotel for its guests. No fare is charged. Does the hotel need a Road Passenger Transport Operator Licence?","options":["No, because the passengers are not paying for the transport","Yes, because the vehicle has more than 8 passenger seats","Yes, but only a Community Licence","Yes, a Public Bus Passenger Service Licence from the NTA"],"correct":0,"exp":"If the operator does not charge for carrying the passengers, it does not need an operator licence. The book gives exactly this example: a hotel with free transport for its guests.\n📍 Book M10 p.4"},{"q":"Good repute, appropriate financial standing and professional competence are three of the four requirements for a Road Passenger Transport Operator Licence. What is the fourth?","options":["A stable and effective establishment in Ireland","A fleet of at least five authorised vehicles","A Public Bus Passenger Service Licence","Membership of a recognised trade association"],"correct":0,"exp":"The 4 EU requirements: good repute, financial standing, professional competence (CPC) and a stable and effective establishment in Ireland. They must be met for the whole life of the licence.\n📍 Book M10 p.6"},{"q":"An operator applies for authorisation of 6 vehicles. What minimum capital and reserves must it demonstrate?","options":["€34,000","€30,000","€54,000","€39,000"],"correct":0,"exp":"€9,000 for the first vehicle + €5,000 for each additional one: 9,000 + 5 × 5,000 = €34,000.\n📍 Book M10 p.8"},{"q":"An operator authorised for 4 coaches wants to increase to 7. By how much must its demonstrated financial standing increase?","options":["€15,000","€9,000","€27,000","€24,000"],"correct":0,"exp":"Each additional vehicle requires €5,000 more: 3 vehicles × €5,000 = €15,000. (With 4 coaches it had to show €24,000; with 7, €39,000.)\n📍 Book M10 p.8"},{"q":"Which statement about tax clearance and the operator licence is correct?","options":["Part of good repute: losing it can cost the licence","It is only needed for international licences","It is only checked when the licence is renewed","It only applies to limited companies, not traders"],"correct":0,"exp":"The tax clearance certificate is part of good repute. Without it the application is refused, and if it is withdrawn later, the licence can be suspended or revoked.\n📍 Book M10 p.8"},{"q":"A director of a licensed coach company is convicted of a listed offence. Within what period must the licence holder notify the Minister in writing?","options":["Within 3 months of the appeal time running out","Within 14 days of the date of conviction","Within 6 months of the offence being committed","Only at the next licence renewal"],"correct":0,"exp":"It must be reported in writing within 3 months of the end of the appeal period (or of the appeal being decided or withdrawn). Failing to do so is an offence with a class A fine.\n📍 Book M10 p.8"},{"q":"When the applicant is a company, which of the following is NOT a 'relevant person' for good repute purposes?","options":["A coach driver employed by the company","The secretary of the company","A director of the company","The nominated transport manager"],"correct":0,"exp":"Relevant persons in a company: the company itself, the secretary, the directors and the transport manager. Drivers are not, although the operator should try to find out about their serious convictions and declare them.\n📍 Book M10 p.8"},{"q":"A contracted (external) transport manager is permitted to manage the transport activities of:","options":["No more than 4 undertakings, with a combined fleet of no more than 50 vehicles","No more than 2 undertakings, with a combined fleet of no more than 20 vehicles","Any number of undertakings, provided each has fewer than 10 vehicles","Only one undertaking"],"correct":0,"exp":"Contracted transport manager (with no real link to the company): a maximum of 4 companies and 50 vehicles in total, and they must work solely in the interest of each company.\n📍 Book M10 p.10"},{"q":"To meet the 'stable and effective establishment' requirement, which documents must the undertaking keep at its place of business in Ireland?","options":["Accounts, personnel files and driving time records","Only the operator licence and the transport discs","Only the insurance certificates for each vehicle","None: they may be kept by an accountant abroad"],"correct":0,"exp":"'Letterbox companies' (just a mailbox) are prohibited. The premises must hold the accounts, personnel documents, driving and rest time records and whatever the Department or the RSA requests.\n📍 Book M10 p.10"},{"q":"By what date each year must an undertaking tell the licensing authority how many employees it had on 31 December of the previous year?","options":["31 March","31 January","30 June","31 December"],"correct":0,"exp":"Before 31 March each year, the company reports how many employees it had on the previous 31 December.\n📍 Book M10 p.10"},{"q":"Which of the following are conditions of a Road Passenger Transport Operator Licence?\n1. Every vehicle used must be roadworthy, taxed and insured for hire or reward in the holder's name\n2. The holder must comply with EU rules on tachographs, driving time, breaks and rest\n3. The licence is personal to the holder and not transferable without Department authorisation\n4. The holder must provide adequate parking and operating premises within the State","options":["1, 2, 3 and 4","1 and 2 only","1, 2 and 3 only","2, 3 and 4 only"],"correct":0,"exp":"All four are licence conditions. Others: carrying the certified copy and the disc in each vehicle, showing the licence to the Garda or the RSA, and giving data to the statistics office (CSO) if it asks.\n📍 Book M10 p.11-12"},{"q":"Before issuing a Large Public Service Vehicle (LPSV) licence, the Garda PSV Officer must be satisfied of all of the following EXCEPT:","options":["That the operator holds a Public Bus Passenger Service Licence","That the applicant is a fit and proper person to hold the licence","That the vehicle is safe for the carriage of passengers","That carrying passengers for hire or reward is covered by insurance"],"correct":0,"exp":"For the LPSV licence the Garda checks: that the applicant is a suitable person, that the vehicle is safe, that it complies with section 11 of the Road Traffic Act 1961 and that there is insurance for carrying fare-paying passengers. It lasts 3 years, with an annual inspection.\n📍 Book M10 p.13"},{"q":"A Special Regular International Service (for example, carrying workers between home and work) does NOT require an authorisation when:","options":["It runs under an organiser-carrier contract","The whole journey is shorter than 50 km","Fewer than 16 passengers are carried","A Journey Form is filled in before departure"],"correct":0,"exp":"Special regular services (workers, students, military) do not need authorisation if they are carried out under a contract between the organiser and the carrier. They can only carry the people named in the contract.\n📍 Book M10 p.20"},{"q":"Under the Working Time rules for drivers subject to Regulation 561/2006, a break must be taken after no more than:","options":["6 hours of work","4.5 hours of work","9 hours of work","10 hours of work"],"correct":0,"exp":"There are two rules at the same time: the driving rule (break after 4 h 30 of driving) and the working time rule (break after 6 hours of work, whether driving or not). Whichever comes first applies.\n📍 Book M11 p.5 and p.7"},{"q":"A driver's working day lasts 10 hours. What is the minimum total working time break required?","options":["45 minutes","30 minutes","15 minutes","60 minutes"],"correct":0,"exp":"Working time: between 6 and 9 hours, a 30-minute break; more than 9 hours, 45 minutes. They can be split into parts of at least 15 minutes.\n📍 Book M11 p.7"},{"q":"A coach driver drives 07.00-10.00, unloads passengers and baggage 10.00-12.00, then drives 12.00-13.00. What must happen at 13.00?","options":["A working time break, after 6 hours of work","Nothing, as only 4 hours of driving are done","A 45-minute EU driving break must start","A daily rest period must start at 13.00"],"correct":0,"exp":"They have only driven 4 hours (no driving break is due yet), but they have worked 6 hours, so a working time break is due. This is example 1 in the book.\n📍 Book M11 p.5"},{"q":"A coach driver does some work between 01.00 and 05.00. Unless a collective or workforce agreement says otherwise, what is the maximum working time for that 24-hour period?","options":["10 hours","8 hours","9 hours","12 hours"],"correct":0,"exp":"For passenger drivers, doing any work between 01:00 and 05:00 makes you a night worker: a maximum of 10 hours of work in those 24 hours, unless there is a collective agreement.\n📍 Book M11 p.9"},{"q":"On a multi-manned coach that is moving, how may the driver who is not driving record their time?","options":["45 minutes as a break; the rest as availability","All of it as daily rest in the passenger seat","All of it as other work, like a conductor","All of it as driving time, shared with the driver"],"correct":0,"exp":"The co-driver can count the first 45 minutes without driving as a break; the rest, as availability (POA). With the vehicle moving it is never daily rest.\n📍 Book M11 p.3"},{"q":"On a multi-manned journey, when must the second driver be on board?","options":["From the end of the first hour of the journey","From the very first minute of the journey","Only after the first 4.5 hours of driving","Only during the night, from 22.00 to 06.00"],"correct":0,"exp":"During the first hour it is optional for both to be on board (so the second driver can be picked up on the way); after the first hour it is compulsory.\n📍 Book M11 p.3"},{"q":"A coach on a single international occasional service uses the 12-day derogation and is driven between 22.00 and 06.00 by one driver. What is the maximum driving before a break?","options":["3 hours","4.5 hours","2 hours","5.5 hours"],"correct":0,"exp":"Under the 12-day rule, if driving between 22:00 and 06:00 you need multi-manning, or with a single driver a break every 3 hours instead of every 4 h 30.\n📍 Book M11 p.4"},{"q":"After completing a journey under the 12-day derogation, what weekly rest must the driver take?","options":["Two regular, or one regular plus one reduced","One reduced weekly rest of 24 hours only","A single regular weekly rest of 45 hours","Twelve consecutive days off before driving"],"correct":0,"exp":"Before the trip: a regular weekly rest of 45 h. After: two regular rests in a row (90 h) or one regular and one reduced (at least 69 h), compensating the reduction within 3 weeks.\n📍 Book M11 p.4"},{"q":"A coach is stuck in a motorway traffic jam caused by a serious accident. To reach a suitable stopping place the driver will exceed the daily driving limit. Which statement is correct?","options":["Emergency rule may apply; record why by arrival","Stop on the hard shoulder and rest there","It also covers delays from long-standing roadworks","Written operator permission is needed first"],"correct":0,"exp":"The emergency exception only applies to the unforeseeable (a traffic jam caused by a serious accident), not to known roadworks. The reason is noted on the chart or printout, at the latest on arrival at the stopping place.\n📍 Book M11 p.4"},{"q":"Under Irish domestic rules, as an alternative to the straight 5.5-hour driving limit, within any period of 8.5 hours a driver may:","options":["Breaks of 45 min in total, plus 30 min at the end","Drive the full 8.5 hours without a break","Take a single 15-minute break in the middle","Take breaks adding up to 20 minutes in all"],"correct":0,"exp":"Domestic alternative: within 8 h 30, breaks adding up to at least 45 minutes (they can be the layovers at the terminus) and a 30-minute break at the end. The book gives the example of a 7-minute layover at each end of the route.\n📍 Book M11 p.11"},{"q":"Under domestic regulations, a part-time driver is exempt from the drivers' hours rules if they drive for no more than:","options":["4 hours a day","2 hours a day","5.5 hours a day","6 hours a day"],"correct":0,"exp":"Anyone who drives 4 hours or less a day is exempt from the domestic rules. They can exceed 4 hours twice a week, without going over 10 hours of driving or a 16-hour working day.\n📍 Book M11 p.11"},{"q":"A driver does both EU and domestic driving on the same day. Which statement is correct?","options":["EU driving counts towards the domestic limits","Domestic driving can count as an EU break","The 16-hour spreadover does not apply that day","Domestic driving is logged as rest on the card"],"correct":0,"exp":"In mixed driving: time driven under EU rules counts towards the domestic limits, and domestic driving never counts as an EU break or rest (it is recorded as other work). That day the 10 h driving and 16 h working day limits apply.\n📍 Book M11 p.12"},{"q":"Gardaí and RSA officers may prohibit a driver from continuing to drive when:\n1. The driver has breached the EU or Irish domestic rules\n2. The driver will break the rules if they continue to drive\n3. The driver's tachograph chart appears to be fraudulent","options":["1, 2 and 3","1 only","1 and 2 only","2 and 3 only"],"correct":0,"exp":"The Garda and the RSA can stop a moving vehicle, check the records and prohibit further driving in all three cases.\n📍 Book M11 p.12"},{"q":"According to the module, which organisation is responsible for enforcing the Working Time provisions?","options":["The Workplace Relations Commission (WRC)","The National Transport Authority (NTA)","The Competition and Consumer Protection Commission (CCPC)","The Revenue Commissioners"],"correct":0,"exp":"Driving hours are enforced by the Garda and the RSA; working time, according to the book, by the WRC.\n📍 Book M11 p.12"},{"q":"A coach costs €240,000 including tyres worth €6,000. Its expected life is 8 years and its residual value €42,000. What is the annual straight-line depreciation?","options":["€24,000","€24,750","€29,250","€30,000"],"correct":0,"exp":"Straight line = (price − tyres − residual) ÷ years = (240,000 − 6,000 − 42,000) ÷ 8 = 192,000 ÷ 8 = €24,000. The other results forget to subtract the tyres or the residual value.\n📍 Book M14 p.3"},{"q":"A coach costs €150,000 including tyres of €5,000 and is depreciated at 20% on the reducing balance. What is the depreciation in year 2?","options":["€23,200","€29,000","€24,000","€30,000"],"correct":0,"exp":"Starting balance without tyres: 145,000. Year 1: 20% = 29,000, leaving 116,000. Year 2: 20% of 116,000 = €23,200. The % is applied to what is left.\n📍 Book M14 p.4"},{"q":"A fleet of 12 similar coaches carries €96,000 of administration overheads. Using the number of vehicles basis, how much is allocated to each coach?","options":["€8,000","€9,600","€12,000","€7,200"],"correct":0,"exp":"Per vehicle: 96,000 ÷ 12 = €8,000. For similar buses, the book says this is the simplest allocation.\n📍 Book M14 p.5 and p.8"},{"q":"A coach has annual standing costs of €63,000 and works 5 days a week for 45 weeks a year. What is the daily standing cost?","options":["€280","€252","€172.60","€315"],"correct":0,"exp":"Working days = 5 × 45 = 225. Fixed cost per day = 63,000 ÷ 225 = €280. (172.60 comes from dividing by 365, which is a typical mistake.)\n📍 Book M14 p.12"},{"q":"Diesel costs €1.32 per litre and a coach averages 3.3 km per litre. What is the fuel cost per kilometre?","options":["€0.40","€0.44","€2.50","€0.25"],"correct":0,"exp":"Fuel per km = price per litre ÷ km per litre = 1.32 ÷ 3.3 = €0.40.\n📍 Book M14 p.8"},{"q":"A coach has 6 tyres costing €450 each, with an expected life of 90,000 km. What is the tyre cost per kilometre?","options":["3.0 cents","0.5 cents","5.0 cents","30 cents"],"correct":0,"exp":"Tyres per km = (6 × 450) ÷ 90,000 = 2,700 ÷ 90,000 = €0.03 = 3 cents.\n📍 Book M14 p.9"},{"q":"A day trip uses a coach for 1 day (standing cost €280 per day) and covers 300 km at a running cost of €0.60 per km. Tolls and parking cost €45. What is the total cost of the trip?","options":["€505","€460","€325","€685"],"correct":0,"exp":"Cost = days × €/day + km × €/km + expenses = 280 + (300 × 0.60) + 45 = 280 + 180 + 45 = €505.\n📍 Book M14 p.13-14"},{"q":"The trip in the previous question costs €505. The operator adds a profit margin of 15% on all costs. What is the price to the customer?","options":["€580.75","€520.15","€594.12","€575.70"],"correct":0,"exp":"Price = cost × 1.15 = 505 × 1.15 = €580.75. (594.12 comes from dividing by 0.85, which is a different method from the one the book uses.)\n📍 Book M14 p.11"},{"q":"A tour is priced at €1,200 including profit. The operator expects to sell 40 seats on a 53-seat coach. What fare should be charged per passenger?","options":["€30.00","€22.64","€26.67","€40.00"],"correct":0,"exp":"Price per passenger = total price ÷ tickets you expect to sell = 1,200 ÷ 40 = €30. Dividing by the 53 seats only works if the coach is full.\n📍 Book M14 p.15"},{"q":"An operator has capital employed of €400,000 and wants a 15% return on capital employed. Its total annual costs are €1,200,000. What profit surcharge should be added to costs?","options":["5%","15%","3.75%","6.67%"],"correct":0,"exp":"Target profit = 15% of 400,000 = €60,000. Mark-up = 60,000 × 100 ÷ 1,200,000 = 5%.\n📍 Book M14 p.10-11"},{"q":"Which of the following are standing (fixed) costs of a coach?\n1. Motor tax\n2. Vehicle insurance\n3. Depreciation\n4. Fuel","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"correct":0,"exp":"Fixed costs: tax, insurance, wages, depreciation and administration (they are paid even if the vehicle does not move). Fuel is variable: it depends on the km.\n📍 Book M14 p.2-8"},{"q":"A UK customer wants a quote in sterling. Your costs total €2,640 and the exchange rate is £1 = €1.10. What is the cost in sterling?","options":["£2,400","£2,904","£2,376","£2,640"],"correct":0,"exp":"If you are given '£1 = €1.10', to convert euros to pounds you divide: 2,640 ÷ 1.10 = £2,400.\n📍 Book M14 p.16-17"}]},"111":{"title":"Mock Exam 11","questions":[{"q":"To qualify for Statutory Sick Pay, an employee must have worked for the employer for at least:","options":["13 continuous weeks","4 continuous weeks","6 months","1 year"],"correct":0,"exp":"To receive sick pay from the employer (SSP) you need 13 continuous weeks with the company and a medical certificate from the first day. It is 5 days a year, at 70% and with a maximum of €110 a day.\n📍 Book M3 p.14"},{"q":"An employee has 7 years' continuous service. What is the minimum notice the employer must give to end the employment?","options":["4 weeks","2 weeks","6 weeks","1 week"],"correct":0,"exp":"Minimum notice: less than 13 weeks, none; up to 2 years, 1 week; 2 to 5, 2; 5 to 10, 4; 10 to 15, 6; more than 15, 8 weeks. With 7 years: 4 weeks.\n📍 Book M3 p.14"},{"q":"An employee with 10 weeks' service is dismissed. What is the minimum statutory notice?","options":["Nil","1 week","2 weeks","4 weeks"],"correct":0,"exp":"With less than 13 weeks' service there is no legal minimum notice. From 13 weeks, 1 week.\n📍 Book M3 p.14"},{"q":"A coach company normally employing 80 people proposes 12 redundancies within 30 days. Which statement is correct?","options":["Collective: consult 30 days and notify the Minister","Not collective, as fewer than 30 jobs are involved","The employer only needs to tell the WRC in writing","Notices may go out during the consultation period"],"correct":0,"exp":"With 50 to 99 employees, 10 or more redundancies within 30 days is a collective redundancy. There must be at least 30 days of consultation, the Minister must be notified, no dismissal letters can be given during the consultation, and 30 days must pass from the notification.\n📍 Book M3 p.13"},{"q":"For collective redundancy purposes, the number of employees 'normally employed' is:","options":["The average over the previous 12 months","The number on the day of the announcement","The highest number in the last 5 years","The number of full-time staff only"],"correct":0,"exp":"The average number of employees in each of the 12 months before the first redundancy is used.\n📍 Book M3 p.13"},{"q":"A driver with 9 years and 8 months' continuous service, earning €700 a week gross, is made redundant. What is the statutory redundancy payment?","options":["€11,400","€13,300","€10,800","€12,000"],"correct":0,"exp":"Only complete years count: 9. Weeks = (2 × 9) + 1 = 19. Pay is capped at €600, so 19 × 600 = €11,400. (13,300 forgets the cap.)\n📍 Book M3 p.13 (case answer, p.34)"},{"q":"Which category of worker is NOT protected by the unfair dismissal provisions?","options":["An independent contractor, not an employee","A part-time driver with 2 years' service","A pregnant employee with 3 months' service","A trade union member with 6 months' service"],"correct":0,"exp":"Not protected: the self-employed with a contract for services, those who normally work outside Ireland, the Garda, the army, share fishermen and anyone with less than 1 year's service (except for prohibited grounds such as pregnancy or trade union membership).\n📍 Book M3 p.22"},{"q":"A driver with 4 months' service is dismissed. For which reason could they still complain to the WRC?","options":["Because of her pregnancy","Because of poor driving capability","Because of genuine redundancy","Because of proven misconduct"],"correct":0,"exp":"'Inadmissible' grounds (pregnancy, trade union, race, religion, age, disability…) can be claimed without the year of service.\n📍 Book M3 p.21-22"},{"q":"An operator hires a temporary driver to cover an employee on maternity leave. When the employee returns, dismissing the replacement is fair only if:","options":["They were told in writing it was temporary","They have less than one year's service","The WRC approves the dismissal in advance","They are given at least 4 weeks' notice"],"correct":0,"exp":"Dismissing the replacement is fair only if they were told in writing, when hired, that the job was temporary and why.\n📍 Book M3 p.22"},{"q":"In an unfair dismissal case where the dismissal itself is not disputed, who must show that it was for a fair reason?","options":["The employer","The employee","The Adjudication Officer","The trade union"],"correct":0,"exp":"The employee only has to prove there was a dismissal if this is disputed. It is up to the employer to show that the dismissal was for a fair reason.\n📍 Book M3 p.23"},{"q":"Force majeure leave (paid leave for urgent family emergencies) is limited to:","options":["3 days in 12 months or 5 in 36 months","5 days in 12 months or 10 in 36 months","2 days in 12 months or 4 in 24 months","1 day a month, up to 12 a year"],"correct":0,"exp":"Force majeure leave: paid, for urgent family emergencies (illness or injury of a close relative), a maximum of 3 days in 12 months or 5 in 36. It is not for bereavements.\n📍 Book M3 p.12"},{"q":"Under the general working time rules, a worker on a shift of 4.5 hours or more must be given a minimum break of:","options":["15 minutes","30 minutes","45 minutes","No break is required"],"correct":0,"exp":"General law: 15 minutes after 4 h 30 and 30 minutes after 6 hours. Drivers subject to 561/2006 also have their own rules.\n📍 Book M3 p.18"},{"q":"Under the general working time rules, night workers should not work more than how many hours in any 24-hour period (averaged over 4 months)?","options":["8 hours","10 hours","11 hours","12 hours"],"correct":0,"exp":"General law: night worker, a maximum of 8 hours in every 24 (on average). Note: drivers under the transport rules have a 10-hour limit.\n📍 Book M3 p.18"},{"q":"Which statement about WRC mediation is correct?","options":["Voluntary, confidential; any deal is signed","It is compulsory before any WRC hearing","Its decisions can only go to the High Court","It must always take place in person"],"correct":0,"exp":"WRC mediation is voluntary and confidential, by phone or in person. If there is agreement, it is signed and the case ends; if not, it goes to Adjudication.\n📍 Book M3 p.23"},{"q":"According to the RSA Guide, how should the interval between vehicle safety inspections be expressed?","options":["In time, in weeks","In kilometres travelled","In engine hours","All of the above"],"correct":0,"exp":"The RSA guide insists that inspections are scheduled by time (every X weeks), not by km, so that vehicles that do few km are also checked.\n📍 Book M13 p.5"},{"q":"Who should carry out the daily walkround check?","options":["The driver, before each use, and each later driver","A qualified fitter, once a week for each vehicle","The transport manager, once a day for the fleet","Only the first driver who uses it that day"],"correct":0,"exp":"The daily check is done by the driver (or another responsible person) before each use. If the vehicle changes driver during the day, each one repeats it.\n📍 Book M13 p.2"},{"q":"A 'red line item' found during a walkround check is:","options":["A defect making the vehicle unroadworthy","A cosmetic defect for the next service","An item checked only at the annual CVRT","A defect to be reported within 7 days"],"correct":0,"exp":"A 'red line item' is a serious defect: with it, the vehicle cannot go out until it is repaired.\n📍 Book M13 p.3"},{"q":"In a 'Nil' defect reporting system, drivers:","options":["Fill in a sheet daily, defect or not","Report only when they find a defect","Phone the office with a report once a week","Leave the reporting to the fitters"],"correct":0,"exp":"With the 'Nil' system, the driver hands in their sheet every day, even if there are no defects ('NIL'). That way the operator can show that the checks were done and that it took reasonable care.\n📍 Book M13 p.3 and p.8"},{"q":"An owner-driver has no one else in the organisation to receive defect reports. For how long must defect records still be kept?","options":["At least 2 years","6 months","15 months","5 years"],"correct":0,"exp":"Even if they are self-employed and have no one to hand the reports to, they must record all defects and keep the records for at least 2 years.\n📍 Book M13 p.5"},{"q":"To whom should drivers' defect reports be given?","options":["A responsible person with authority to act","The drivers' trade union representative","The RSA's local enforcement office","The customer who hired the vehicle"],"correct":0,"exp":"Defect reports go to someone with authority to have them repaired, usually the workshop manager or the supervisor.\n📍 Book M13 p.5"},{"q":"Which statement about staff carrying out safety inspections is correct?","options":["Competent, and not expected to repair during it","They must always repair defects while inspecting","They should be the drivers who use the vehicle","They must be employed directly by the RSA"],"correct":0,"exp":"Inspections are carried out by technically competent staff, who should not be asked to repair at the same time: first inspect, then repair.\n📍 Book M13 p.5"},{"q":"Which of the following is an advantage of in-house maintenance?","options":["Closer control, flexibility and cost control","No need for any workshop space or premises","No capital outlay on tools or equipment","No need to train any maintenance staff"],"correct":0,"exp":"Advantages of an in-house workshop: more control and flexibility, better cost control, repairs without waiting and own decisions on parts. Disadvantages: space, investment, staff and safety rules.\n📍 Book M13 p.6"},{"q":"Which of the following is a disadvantage of in-house maintenance?","options":["Capital outlay and overheads for the workshop","Less control over maintenance standards","Longer waits for repairs to be carried out","Paying a profit margin to an outside provider"],"correct":0,"exp":"An in-house workshop requires investing in premises, diagnostic equipment and tools, and hiring and training staff. The other options are disadvantages of subcontracting.\n📍 Book M13 p.6"},{"q":"An operator contracts out all maintenance to a commercial garage. Who remains responsible for roadworthiness and for producing the maintenance records?","options":["The operator","The garage only","The RSA","The vehicle manufacturer"],"correct":0,"exp":"Even if the workshop is external (with a written contract), the operator is still responsible for the roadworthiness of the vehicles and for the records.\n📍 Book M13 p.7"},{"q":"Which factors should be considered when deciding the frequency of servicing and inspections?\n1. Manufacturers' recommendations\n2. Age of the vehicles\n3. Type of operation\n4. Average distance covered","options":["1, 2, 3 and 4","1 and 2 only","1, 3 and 4 only","2 and 4 only"],"correct":0,"exp":"The book lists all of these and more: fleet size, type of vehicles, utilisation, facilities, staff qualifications and the standard to be achieved.\n📍 Book M13 p.2"},{"q":"A driver's defect report must allow the recording of:","options":["Defect, date, vehicle, repair and both signatures","Only the driver's name and the date of the check","Only the fuel used and the mileage covered","Only the numbers of passengers carried"],"correct":0,"exp":"The defect report contains: date, vehicle, driver, defect, driver's signature, repair carried out and signature of the person who did it.\n📍 Book M13 p.8"},{"q":"What is the aim of the EU Common Formula (Directive 2006/22/EC), implemented from November 2025?","options":["Equal enforcement across the EU, sharing risk scores","To set a common EU fuel tax for all operators","To replace the CVRT with a single EU-wide test","To fix a common EU minimum wage for all drivers"],"correct":0,"exp":"The EU Common Formula standardises how companies' risk is scored so that they all receive the same treatment in checks and penalties, and so those scores can be shared between countries.\n📍 Book M13 p.9"},{"q":"On an Irish driving licence, information code 111 means:","options":["Limited to a maximum of 16 passenger seats","Restricted to automatic transmission","Not for hire or reward","Vehicle not more than 5.5 m long"],"correct":0,"exp":"Licence codes: 78 automatic; 101 not for hire or reward; 103 subject to a certificate of competence; 105 no more than 5.5 m; 107 no more than 8,250 kg; 111 maximum 16 seats.\n📍 Book M21 p.3"},{"q":"A driver aged 43, who obtained D entitlement after 19 January 2013, renews it. What must they do regarding medical fitness?","options":["Sign a self-declaration of medical fitness","See a doctor who completes a D4 form","Renew the entitlement every year from now","Retake the theory test at a test centre"],"correct":0,"exp":"On renewal: under 45, a self-declaration is enough; over 45, a medical check with form D4; over 65, renewal every year with a check.\n📍 Book M21 p.6"},{"q":"A driver aged 50 renews their Category D entitlement. What is required?","options":["A medical exam with a D4 form","Only a signed self-declaration","Nothing, if there are no penalty points","A new practical driving test"],"correct":0,"exp":"From age 45 a self-declaration is not enough: a medical check with form D4 is needed.\n📍 Book M21 p.6"},{"q":"Since staged testing began on 1 January 1997, a Category B licence holder who wants D+E entitlement must:","options":["Pass a D test first, then a separate D+E test","Take the D+E test directly, with no D test","Pass only the D+E theory test","Pass a D1 test and then the D+E test"],"correct":0,"exp":"Since 1997 you cannot go directly from B to D+E: first D and then D+E.\n📍 Book M21 p.3"},{"q":"To obtain provisional D1 or D entitlement, the applicant must already hold:","options":["A full Category B entitlement","A full Category D1 entitlement","A Category C entitlement","An International Driving Permit"],"correct":0,"exp":"For a D1 or D learner permit you must hold a full B licence.\n📍 Book M21 p.3"},{"q":"How long are candidates allowed for the computer-based Driver CPC Case Studies test?","options":["1½ hours","30 minutes","45 minutes","2½ hours"],"correct":0,"exp":"Driver CPC case studies: 7 scenarios, 50 marks, 1 h 30, pass mark 40.\n📍 Book M21 p.4"},{"q":"How long is allowed for the Driver CPC Practical Walk-Around Test (Module 4)?","options":["Half an hour","1½ hours","2 hours","10 minutes"],"correct":0,"exp":"Module 4 (vehicle check, safe loading, emergencies) lasts half an hour and can be taken on the same day as the practical test or separately.\n📍 Book M21 p.5"},{"q":"When a learner with provisional D entitlement is being trained, which is correct?","options":["Accompanied by a full D holder, with L plates","No accompanying driver or L plates needed","Any car licence holder may accompany them","They may only drive on motorways with L plates"],"correct":0,"exp":"The learner is accompanied by someone with a full licence in that category and displays L-plates (red letter on a white background) front and back.\n📍 Book M21 p.5"},{"q":"In which situation is the Driver CPC qualification NOT required?","options":["Road testing after maintenance or repair","When carrying children on school runs","When doing occasional private hire work","When the driver works only part-time hours"],"correct":0,"exp":"The Driver CPC is not needed, for example, to test the vehicle after a repair, take it to an official test or prepare for the exams.\n📍 Book M21 p.6"},{"q":"In which of these countries is an Irish driving licence NOT accepted, so that an International Driving Permit is required?","options":["Albania and Ukraine","France and Germany","Spain and Italy","Belgium and the Netherlands"],"correct":0,"exp":"The Irish licence is not valid in Albania, Ukraine and most of the Middle East. Russia requires the IDP or an official translation.\n📍 Book M21 p.7"},{"q":"An Irish operator uses a non-EU resident (for example a Ukrainian national) to drive internationally. What must the driver carry?","options":["A driver attestation, valid up to 5 years","Only an International Driving Permit","A letter of approval from An Garda Síochána","No extra document is needed within the EU"],"correct":0,"exp":"A non-EU driver carries a 'driver attestation' from the Department of Transport (up to 5 years). Without it, in other countries they may be treated as an illegal immigrant.\n📍 Book M21 p.7"},{"q":"For how long is an International Driving Permit valid?","options":["1 year","3 years","5 years","10 years"],"correct":0,"exp":"The IDP lasts 1 year, it is issued by the NDLS, and you must be at least 18 and hold a valid Irish licence.\n📍 Book M21 p.7"},{"q":"A Category B (car) entitlement allows the holder to drive vehicles of up to:","options":["3.5 tonnes MAM with no more than 8 passenger seats","7.5 tonnes MAM with up to 16 passenger seats","3.5 tonnes MAM with up to 16 passenger seats","Any size of minibus for private use"],"correct":0,"exp":"Licence B: up to 3.5 t and a maximum of 8 passenger seats. For more you need a professional licence (D1 or D).\n📍 Book M21 p.2"}]},"112":{"title":"Mock Exam 12","questions":[{"q":"A local service has a single journey running time of 25 minutes, a layover of 5 minutes at each terminal and a headway of 10 minutes. How many buses are required?","options":["6","5","3","7"],"correct":0,"exp":"Buses = (journey + layover) × 2 ÷ headway = (25 + 5) × 2 ÷ 10 = 60 ÷ 10 = 6.\n📍 Book M30 p.3"},{"q":"A service has a running time of 40 minutes each way, a layover of 5 minutes at each terminal and a headway of 12 minutes. How many buses are required?","options":["8","7","7.5","6"],"correct":0,"exp":"(40 + 5) × 2 = 90 ÷ 12 = 7.5. There is no such thing as half a bus: round up to 8, and the time left over is shared out as 'excess layover'.\n📍 Book M30 p.3-4"},{"q":"When the round trip time does not divide exactly by the headway, extra time is added at the terminals so that it does. What is this extra time called?","options":["Excess layover time","Recovery time","Dead running","Spreadover"],"correct":0,"exp":"Excess layover: the extra time at the terminus so that the full round trip is a multiple of the headway. It is wasted time, which can be reduced by combining routes (interworking).\n📍 Book M30 p.4"},{"q":"A circular route takes 50 minutes to go round once, with a single layover of 10 minutes. The headway is 15 minutes. How many buses are required?","options":["4","8","3","5"],"correct":0,"exp":"On a circular route there is only one layover and you do not multiply by 2: (50 + 10) ÷ 15 = 60 ÷ 15 = 4 buses.\n📍 Book M30 p.3"},{"q":"A service runs every 12 minutes. What is its frequency, and what type of timetable is it?","options":["5 buses per hour, a clockface timetable","12 buses per hour, a tidal timetable","4 buses per hour, a clockface timetable","5 buses per hour, a differential timetable"],"correct":0,"exp":"Frequency = 60 ÷ headway = 60 ÷ 12 = 5 an hour. If the interval divides the hour into equal parts, it is a 'clockface' timetable (easy to remember).\n📍 Book M30 p.3"},{"q":"Two stops are 6 km apart and the bus averages 24 km/h. How long does the bus take between them?","options":["15 minutes","4 minutes","25 minutes","10 minutes"],"correct":0,"exp":"Minutes = distance ÷ speed × 60 = 6 ÷ 24 × 60 = 15 minutes.\n📍 Book M30 p.9"},{"q":"A depot must cover 40 duties each day Monday to Friday, 25 on Saturday and 15 on Sunday. Drivers work a 5-day week. How many drivers are needed (before holiday cover)?","options":["48","40","56","34"],"correct":0,"exp":"Shifts in the week = (40 × 5) + 25 + 15 = 240. Drivers = 240 ÷ 5 days = 48.\n📍 Book M30 p.8"},{"q":"A depot has 100 drivers who each take 4 weeks' holiday, spread evenly through the year. How many extra drivers are needed for holiday cover?","options":["9","8","4","10"],"correct":0,"exp":"Holiday weeks = 100 × 4 = 400. Each driver works 52 − 4 = 48 weeks. 400 ÷ 48 = 8.33, and as there is no such thing as half a driver, round up to 9.\n📍 Book M30 p.8"},{"q":"A roster has 40 lines and every driver works a 5-day week. The depot operates 22 duties on Saturday and 8 on Sunday. How many duties can be covered each day Monday to Friday?","options":["34","40","44","30"],"correct":0,"exp":"Shifts in the week = 40 routes × 5 days = 200. Minus Saturday and Sunday: 200 − 22 − 8 = 170. Over 5 days: 170 ÷ 5 = 34 a day.\n📍 Book M30 p.8"},{"q":"A duty made up of two separate periods of work, usually covering the morning and evening peaks with free time in between, is called:","options":["A split duty","An early duty","A middle duty","A late duty"],"correct":0,"exp":"Types of shift: early (from the start of service and the morning peak), middle (starts mid-morning or midday), late (until the end of service) and split (divided in two).\n📍 Book M30 p.7"},{"q":"Which document shows all the work for a particular vehicle for the day and stays with the vehicle until it returns to the garage?","options":["The running board","The waybill","The crew roster","The Journey Form"],"correct":0,"exp":"The 'running board' sets out all the vehicle's work for the day (journeys, layovers, empty km) and stays on the bus. The waybill records the tickets sold.\n📍 Book M30 p.2 and p.6"},{"q":"An operator runs 3-day coach tours. If they depart every Monday and every Thursday, how many coaches are needed?","options":["1","2","3","4"],"correct":0,"exp":"The one leaving on Monday returns on Wednesday and can leave on Thursday (returning on Saturday). One coach is enough. If they left on Monday and Wednesday, 2 would be needed.\n📍 Book M30 p.9"},{"q":"Switching a vehicle from one route to another, for example between two services sharing a common terminal, to use fewer vehicles is known as:","options":["Interworking","Drop back","Tidal flow","Layover"],"correct":0,"exp":"Interworking: combining two routes that share a terminus. In the book's example, two routes that needed 0.8 and 1.12 buses are covered with 2 instead of 3.\n📍 Book M30 p.4-6"},{"q":"Under the Package Travel rules, when may the price of a package be increased after the contract is made?","options":["Contract allows it, over 2%, and 30+ days before","At any time before the day of departure","Only if the change is less than 5% of the price","Up to 14 days before departure, without limits"],"correct":0,"exp":"The price can only be increased if the contract allows it and explains how (fuel, taxes, exchange rate), if the change is more than 2% and never in the 30 days before departure.\n📍 Book M30 p.11"},{"q":"How can a package organiser provide security for customers' pre-payments?\n1. Placing clients' money in a trust fund until the trip is completed\n2. Insuring each payment with an authorised insurer\n3. Depositing a bond with an approved body\n4. Keeping the money in the operator's current account","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"correct":0,"exp":"Ways to protect customers' money: a trust fund, insurance of each payment, or a bond with an approved body. Leaving it in the company's normal account protects nothing.\n📍 Book M30 p.10"},{"q":"From what date did digital tachographs become compulsory on new passenger vehicles?","options":["1 May 2006","1 January 2005","1 January 2014","1 January 1997"],"correct":0,"exp":"Since 1 May 2006, all new vehicles within the EU rules have a digital tachograph.\n📍 Book M12 p.2"},{"q":"What colour is the tachograph company card?","options":["Yellow","White","Red","Blue"],"correct":0,"exp":"Cards: driver, white; company, yellow; workshop, red; control, blue. All are issued by the RSA.\n📍 Book M12 p.3-4"},{"q":"A driver card is lost. How quickly must the RSA issue the replacement card?","options":["Within 15 days","Within 7 days","Within 28 days","Within 5 days"],"correct":0,"exp":"The driver tells the RSA within 7 days at most, and the RSA must issue the new card within 15 days. In the meantime, they print out at the start and end of each day.\n📍 Book M12 p.3"},{"q":"What is the main purpose of the company card?","options":["A key to download the VU and lock company data","To let the driver record their activities","To calibrate the tachograph at a workshop","To let the Gardaí read the vehicle unit"],"correct":0,"exp":"The company card is used to download the vehicle unit (VU) memory and to lock the company's data ('lock in') and unlock it at the end ('lock out'). It lasts 5 years.\n📍 Book M12 p.4"},{"q":"An operator hires in a coach for a week. How should it use its company card?","options":["Lock in on collection, lock out at the end","It is not needed for hired vehicles","Lock out on collection, lock in at the end","Only download data at the end of the year"],"correct":0,"exp":"When collecting a hired vehicle, you 'lock in' so that only your company sees your drivers' data; when returning it, you 'lock out'.\n📍 Book M12 p.4"},{"q":"On a double-manned journey with a digital tachograph, what must the drivers do when they change over?","options":["Swap cards so the new driver is in slot 1","Leave both cards where they are in the slots","Remove both cards until the next break","Use the first driver's card for both drivers"],"correct":0,"exp":"When changing driver, the cards must be swapped: the one driving in slot 1; the other in slot 2.\n📍 Book M12 p.5"},{"q":"A digital tachograph records all activities in UTC. In summer, Irish local time is:","options":["One hour ahead of UTC","The same as UTC","Two hours ahead of UTC","One hour behind UTC"],"correct":0,"exp":"The tachograph always records in UTC (Greenwich time). In summer Ireland is one hour ahead. France, Germany, the Netherlands and Spain are always one hour ahead of Ireland.\n📍 Book M12 p.5"},{"q":"An analogue chart shows '125 km/h' next to its centre hole. What does this mean?","options":["Its speed range, which must match the tachograph","The vehicle must never go faster than 125 km/h","The chart can be used for up to 125 hours","The chart is only for vehicles over 12.5 tonnes"],"correct":0,"exp":"It is the chart's speed scale: it must match the tachograph's, otherwise the record is not valid.\n📍 Book M12 p.8"},{"q":"How does an analogue chart show that the tachograph head was opened?","options":["A mark by the styluses on all three traces","A red stamp printed on the centre field","A small hole punched through the chart","It cannot be shown on an analogue chart"],"correct":0,"exp":"If the tachograph is opened, the three styluses leave a mark on the three traces of the chart, and this is visible to whoever checks it.\n📍 Book M12 p.8"},{"q":"At the START of the working day, which details must the driver write in the centre field of the analogue chart?","options":["Name, start place, date, registration, odometer","Only the registration number and the date","Only the closing odometer and the end place","The operator's licence and driver's PPS number"],"correct":0,"exp":"At the start: first name and surname, place and date of starting, registration number and starting km. At the end: place and date of finishing and final km.\n📍 Book M12 p.9"},{"q":"Which of the following are legal responsibilities of the operator regarding analogue charts?\n1. Issue enough blank charts to drivers, including spares\n2. Provide copies of record sheets to drivers who ask for them\n3. Make sure completed charts are returned within 42 days\n4. Serially number every chart issued","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"correct":0,"exp":"The law does not require charts to be numbered; many operators do it for control. What is compulsory: providing enough charts, giving copies if requested, getting them back within 42 days and keeping them for 12 months (2 years if they are used for working time).\n📍 Book M12 p.10"},{"q":"An analogue tachograph fails on a journey and the coach cannot return to base within one week from the day of the breakdown. What must happen?","options":["The tachograph must be repaired en route, and manual records kept in the meantime","The coach may continue until it returns to base, however long that takes","The driver may stop keeping records until the repair","The repair can wait until the next 2-year inspection"],"correct":0,"exp":"If it breaks down on the road, the driver records their activity by hand. It is repaired on return to base; if the vehicle cannot return within a week, it must be repaired on the way.\n📍 Book M12 p.11"},{"q":"How often must an analogue tachograph be inspected and recalibrated?","options":["Every 2 years; recalibrated every 6 years","Inspected and recalibrated every year","Recalibrated every 2 years and never inspected","Only when the vehicle is sold or exported"],"correct":0,"exp":"Analogue: inspection every 2 years and full calibration every 6, or whenever the seals are broken. The digital one is calibrated every 2 years.\n📍 Book M12 p.11"},{"q":"During a fixed week, a driver drives an in-scope coach on some days but not on others. What is required?","options":["A manual record for each non-driving day","Nothing at all for the non-driving days","A letter from the employer at the year end","A new driver card for each driving day"],"correct":0,"exp":"On the days of that week when they do not drive a vehicle with a tachograph, the driver makes a manual record on a chart so that there are no gaps.\n📍 Book M12 p.11"},{"q":"Under domestic regulations, what must the operator do with the driver's weekly record book?","options":["Check, countersign, keep the duplicate, return it","Send the whole book to the RSA every week","Destroy the book once the month has ended","Keep the original; give the driver no copy"],"correct":0,"exp":"Every week the driver hands in the book; the company checks it, signs it, keeps the copy and gives the book back.\n📍 Book M12 p.12"},{"q":"Which of the following are advantages of a tall hierarchy?\n1. Clear lines of responsibility\n2. Close supervision\n3. More opportunities for promotion\n4. Lower employment costs","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"correct":0,"exp":"Tall hierarchy: clear responsibilities, close supervision and more promotion. But it is expensive (many levels), communicates poorly from top to bottom and resists change.\n📍 Book M8 p.2"},{"q":"Which of the following is a disadvantage of a tall hierarchy?","options":["Poor communication through the many levels","Too few opportunities for promotion","Each manager supervises too many staff","Unclear lines of responsibility and authority"],"correct":0,"exp":"The big problem with many levels is that information gets lost going up and down. The other options are disadvantages of the flat hierarchy or are not true.\n📍 Book M8 p.2"},{"q":"Which of the following is a disadvantage of a flat hierarchy?","options":["Wide spans of control and fewer promotions","High employment costs from many managers","Poor communication between the levels","Strong resistance to any change"],"correct":0,"exp":"Flat hierarchy: cheaper and with better vertical communication, but each manager supervises a lot of people, there are few promotions, horizontal communication is worse and it is hard to motivate the base.\n📍 Book M8 p.2"},{"q":"On a typical organisation chart, how are support staff such as a Clerical Assistant or Stores Person shown?","options":["Side branches under a manager, with no staff","At the top of the chart, above the directors","On a separate chart of their own","They are not shown on the chart at all"],"correct":0,"exp":"Support staff are drawn as a horizontal branch: they report to a manager (for example, the workshop manager) but have no one under them.\n📍 Book M8 p.3"},{"q":"In a matrix organisation structure, each worker has:","options":["Two bosses: line manager and project manager","No boss at all while the project lasts","Only the General Manager as their boss","Three bosses: line, project and finance"],"correct":0,"exp":"Matrix: used in projects. Each person reports to their usual manager and to the project manager. Advantage: teams with several points of view. Risk: conflicts between the two managers over staff.\n📍 Book M8 p.3"},{"q":"What is the main disadvantage of a matrix structure?","options":["Line and project managers may clash over staff","It creates too many layers of management","It stops departments working together","It cannot be used for one-off projects"],"correct":0,"exp":"As each worker has two bosses, they can clash over who uses that person and when.\n📍 Book M8 p.3"},{"q":"A fleet of 50 coaches each covers 200,000 km a year. Fuel costs €1.20 per litre and the fleet averages 2.5 km per litre. What is the annual fuel bill?","options":["€4.8 million","€3.0 million","€12 million","€480,000"],"correct":0,"exp":"Total km = 50 × 200,000 = 10 million. Litres = 10,000,000 ÷ 2.5 = 4 million. Cost = 4,000,000 × 1.20 = €4.8 million. Each 1% saving is €48,000.\n📍 Book M8 p.4"},{"q":"According to the module, what is the accepted way to use KPIs in a business?","options":["Pick the vital ones, set targets, measure often","Measure one KPI on its own once a year","Use KPIs only to discipline the drivers","Copy a rival's KPIs without setting targets"],"correct":0,"exp":"A single KPI says little. You have to choose the key indicators, set targets for them and measure regularly (weekly, monthly and annual reports, charts).\n📍 Book M8 p.4"},{"q":"Benchmarking shows that an operator's return on capital employed is much lower than that of similar operators. What should the operator do?","options":["Find out why and act to correct the results","Ignore it, as every business is different","Stop measuring ROCE so the gap disappears","Raise all fares at once by the same percentage"],"correct":0,"exp":"Benchmarking is used to spot where you are worse than others; if profitability is low, the cause must be investigated and corrected.\n📍 Book M8 p.5"},{"q":"What does an organisation chart show?","options":["Roles, status and lines of reporting","Only the names of the directors","The company's profit and loss account","The vehicle maintenance schedule"],"correct":0,"exp":"The organisation chart shows how staff are organised: jobs, level, who each person reports to, how many each manager supervises and possible promotions.\n📍 Book M8 p.2-3"}]},"113":{"title":"Mock Exam 13","questions":[{"q":"The NTA grants an Event or Venue-Specific Licence for bus services to a festival venue. Which statement is correct?","options":["Not renewable; for the event or up to 12 months","Valid for 3 years and renewed automatically","Valid for 5 years like the operator licence","Valid 1 year with priority at future events"],"correct":0,"exp":"NTA licences: for events or venues, not renewable (the event or 12 months); regular, 3 years; demand-responsive, 1 year.\n📍 Book M10 p.13-14"},{"q":"For an International Road Passenger Transport Operator Licence, what additional requirement applies to the designated transport manager?","options":["An International CPC in road transport","At least 10 years' management experience","Be a director or shareholder of the company","Hold a Category D driving licence"],"correct":0,"exp":"The requirements are like those for the national licence, but the transport manager must hold the international CPC.\n📍 Book M10 p.15"},{"q":"An operator applies for an authorisation for a regular international coach service. Unless other issues arise, within what time must the authorising authority decide?","options":["4 months","2 months","6 months","12 months"],"correct":0,"exp":"The countries consulted have 2 months to give their view; the authority decides within 4 months. If it cannot, the case goes to the European Commission, which decides within 6 months.\n📍 Book M10 p.19"},{"q":"Which of the following is NOT, on its own, a valid reason for refusing an application for a regular international service authorisation?","options":["Lower prices, or the route is already served","It lacks the equipment to provide the service","It has seriously breached road transport law","It does not meet the international conditions"],"correct":0,"exp":"Offering lower prices or another company already running that route is not enough to refuse the authorisation. It is refused if the applicant does not have vehicles to run it or has seriously broken the rules.\n📍 Book M10 p.19-20"},{"q":"A transport manager must meet several conditions. Which of the following is one of them?","options":["Be resident in the EU, which excludes the UK","Hold a UK CPC issued in Northern Ireland","Be at least 25 years of age on appointment","Hold a full Category D driving licence"],"correct":0,"exp":"The transport manager must hold an EU CPC (UK ones are no longer valid), be of good repute, be over 18, be resident in the EU and be designated in writing to the Minister.\n📍 Book M10 p.9-10"},{"q":"Under what conditions may a driver take a daily rest in the vehicle?","options":["If it has suitable beds and is stationary","Only if the vehicle is multi-manned","Never: it must always be in a hotel","If it is moving on a motorway at night"],"correct":0,"exp":"Daily rest can be taken in the vehicle if it has a suitable bunk and is stationary.\n📍 Book M11 p.3"},{"q":"On a multi-manned vehicle, each driver needs at least 9 hours' rest in a 30-hour period. How many hours are left in that period for driving and other work?","options":["Up to 21 hours","Up to 15 hours","Up to 18 hours","Up to 24 hours"],"correct":0,"exp":"30 hours − 9 of rest (with the vehicle stationary) = up to 21 hours for driving and working, always complying with the other rules.\n📍 Book M11 p.3"},{"q":"A driver reduces daily rest to 9 hours on three occasions between two weekly rests. Must these reductions be compensated?","options":["No, they no longer need to be compensated","Yes, within the same week as the reduction","Yes, by the end of the third week after","Yes, with an extra 45-hour rest period"],"correct":0,"exp":"A reduction of the daily rest (to 9 h, up to 3 times) no longer has to be compensated. A reduction of the weekly rest does.\n📍 Book M11 p.3"},{"q":"Which statement about operators' liability under Regulation 561/2006 is correct?","options":["Liable for drivers' breaches, even abroad","Never liable for their drivers' breaches","Only the driver is liable for breaches abroad","Agencies have no responsibility at all"],"correct":0,"exp":"The operator, subcontractors and even employment agencies must make sure the rules are followed. The operator can be liable for its drivers' offences, even abroad.\n📍 Book M11 p.5"},{"q":"A driver arrives at an airport and is told the passengers will not be ready for 2 hours. The driver is free to use the time as they wish. How is this time classed?","options":["Period of availability, not working time","Working time, as the driver is on duty","A daily rest period, as the driver is free","Driving time, as the coach is in service"],"correct":0,"exp":"If the driver knows in advance how long the wait will last and can use that time freely, it is availability (POA) and does not count as work. If they have to keep moving the vehicle in a queue, it is work.\n📍 Book M11 p.6"},{"q":"A coach has annual standing costs of €72,000, covers 90,000 km a year and has running costs of €0.55 per km. What is the total cost per kilometre?","options":["€1.35","€0.80","€1.25","€0.55"],"correct":0,"exp":"Fixed per km = 72,000 ÷ 90,000 = €0.80. Total = 0.80 + 0.55 = €1.35 per km.\n📍 Book M14 p.16"},{"q":"Using the figures in the previous question (€1.35 per km), what rate per km should be charged to include a 12.5% profit margin?","options":["€1.52","€1.48","€1.35","€1.69"],"correct":0,"exp":"1.35 × 1.125 = 1.51875, which is rounded to €1.52 per km.\n📍 Book M14 p.16"},{"q":"A coach must cover 90,000 km a year and works 225 days. What is the minimum distance it must cover each working day to recover its standing costs?","options":["400 km","225 km","300 km","246 km"],"correct":0,"exp":"Km per day = km per year ÷ working days = 90,000 ÷ 225 = 400 km. (246 comes from dividing by 365, a typical mistake.)\n📍 Book M14 p.16"},{"q":"For a fleet of passenger vehicles of similar size, which method of apportioning administration costs does the module describe as the simplest?","options":["An equal amount per vehicle","By the number of seats multiplied by the kilometres","By the unladen weight in tonnes","By the value of each vehicle's fuel use"],"correct":0,"exp":"With similar buses, the simplest and fairest approach is to share administration equally between the vehicles.\n📍 Book M14 p.8"},{"q":"A coach bought for €200,000, including tyres worth €8,000, is depreciated at 25% on the reducing balance. What is the depreciation in year 1?","options":["€48,000","€50,000","€38,400","€36,000"],"correct":0,"exp":"Take off the tyres: 200,000 − 8,000 = 192,000. 25% = €48,000. With reducing balance the residual value is not subtracted.\n📍 Book M14 p.4"},{"q":"A driver with 4 years and 11 months' service earns €540 a week and is made redundant. What is the statutory redundancy payment?","options":["€4,860","€5,400","€4,320","€5,346"],"correct":0,"exp":"Complete years: 4. Weeks = (2 × 4) + 1 = 9. As they earn less than €600, their own pay is used: 9 × 540 = €4,860.\n📍 Book M3 p.13 (case answer, p.34)"},{"q":"A depot normally employs 250 people. What is the minimum number of redundancies in 30 days that makes it a collective redundancy?","options":["25 (10%)","30","10","5"],"correct":0,"exp":"With 100 to 299 employees, the threshold is 10%: 10% of 250 = 25. With 50 to 99 it is 10; with 300 or more, 30.\n📍 Book M3 p.13"},{"q":"Which of the following are fair reasons for dismissal?\n1. Capability or qualifications of the employee\n2. Conduct of the employee\n3. Redundancy\n4. Membership of the travelling community","options":["1, 2 and 3 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"correct":0,"exp":"Being a member of the Traveller community is a prohibited ground: that dismissal is always unfair. The other three are fair reasons, along with a legal prohibition and some other substantial reason.\n📍 Book M3 p.20-21"},{"q":"Under the general working time rules, over what reference period is the 48-hour average week normally calculated?","options":["4 months","1 month","1 week","2 years"],"correct":0,"exp":"An average of 48 hours calculated over 4 months; it can be extended to 6 in specific cases or to 12 with a collective agreement.\n📍 Book M3 p.18"},{"q":"Under the general working time rules, what weekly rest must a worker receive?","options":["24 hours in a row every 7 days, plus daily rest","At least 11 hours in a row in every week","At least 45 hours in a row every single week","None, as long as the daily rest is taken"],"correct":0,"exp":"Every 7 days, 24 consecutive hours of rest, which cannot overlap with the 11 hours of daily rest.\n📍 Book M3 p.18"},{"q":"Which of the following documents might be found in a vehicle history file?\n1. The RSA plating certificate\n2. The annual RSA test certificate (CRW)\n3. Tachograph calibration details","options":["1, 2 and 3","1 only","1 and 2 only","2 and 3 only"],"correct":0,"exp":"Each vehicle's history file keeps the weights certificate, the CVRT certificate, the tachograph calibration details and other certificates.\n📍 Book M13 p.8"},{"q":"Which of the following is NOT one of the objectives of a planned maintenance programme listed in the module?","options":["Maximum kilometres between inspections","Minimum disruption to company operations","Maximum vehicle availability","Satisfying the requirements of the legislation"],"correct":0,"exp":"Objectives: safety, minimum disruption, maximum availability, minimum cost, good administration and complying with the law. Extending the km between inspections is not an objective: inspections are based on time.\n📍 Book M13 p.2"},{"q":"After a roadside inspection finds a badly maintained coach, what are the possible consequences for the operator?\n1. The vehicle may be directed to a test centre for further inspection\n2. An objection to future licence applications or fleet increases\n3. Revocation, suspension or curtailment of the operator licence","options":["1, 2 and 3","1 only","2 only","1 and 3 only"],"correct":0,"exp":"Poor maintenance can lead to an inspection at a test centre, objections to future extensions and suspension, curtailment or revocation of the licence.\n📍 Book M13 p.1"},{"q":"According to the module, who should carry out vehicle maintenance inspections?","options":["A suitably qualified person","Any driver of the vehicle","Only RSA inspectors","The transport manager personally"],"correct":0,"exp":"The law does not set the frequency, but it does say that inspections must be carried out by a qualified person.\n📍 Book M13 p.1"},{"q":"What is the minimum age to drive Category D1 vehicles?","options":["21, or 18 with a Driver CPC for some work","18, in all cases and for all work","24, or 21 with a Driver CPC for some work","17, if they hold a Category B licence"],"correct":0,"exp":"D1: 21, or 18 with the Driver CPC for certain work. D: 24, or 21 with the CPC, or 18 with the CPC on regular services up to 50 km.\n📍 Book M21 p.2"},{"q":"Which document is strongly advised for drivers on international journeys, and is a legal requirement in countries such as France and Germany?","options":["A company letter authorising the driver","A copy of the company's annual accounts","A letter of good conduct from the Gardaí","The original purchase invoice of the vehicle"],"correct":0,"exp":"The driver must carry a letter from the company authorising them to drive that vehicle (with the registration number and description). It is recommended to have it translated into French and German.\n📍 Book M21 p.7"},{"q":"Which statement about employers and driving licences is correct?","options":["Employers commit an offence if they permit it","Only the driver commits any offence","Licences need checking only at recruitment","Employers have no duty about drivers' licences"],"correct":0,"exp":"An employer who lets someone drive without the correct licence commits an offence. That is why they must check licences when hiring and regularly afterwards.\n📍 Book M21 p.7"},{"q":"Which of the following is NOT a requirement for the vehicle used in a Category D practical driving test?","options":["It must have at least 50 passenger seats","It must be at least 10 m long","It must be capable of 80 km/h","It must have anti-lock brakes, seat belts and a tachograph"],"correct":0,"exp":"Vehicle for the category D practical test: at least 10 m long and 2.4 m wide, capable of 80 km/h, with ABS, seatbelts, a tachograph and a seat for the examiner (and 24 seats). 50 are not needed.\n📍 Book M21 p.4-5"},{"q":"A service has a running time of 30 minutes, a layover of 6 minutes at each terminal and a headway of 8 minutes. How many buses are needed?","options":["9","8","4.5","10"],"correct":0,"exp":"(30 + 6) × 2 = 72 ÷ 8 = exactly 9 buses.\n📍 Book M30 p.3"},{"q":"Two routes share Cork Bus Station and both have a 120-minute headway. One needs 0.8 of a bus and the other 1.12 buses. By interworking, how many buses are needed in total?","options":["2","3","1","4"],"correct":0,"exp":"0.8 + 1.12 = 1.92, so with interworking 2 buses are enough instead of 3 (one for one route and two for the other).\n📍 Book M30 p.5-6"},{"q":"What is 'drop back' in bus scheduling?","options":["Adding a bus so the others get a break","Running more buses in the peak direction","Running empty back to the depot after a trip","Cutting a service short due to low demand"],"correct":0,"exp":"Drop back: an extra bus is put on the route and the others 'drop back' one turn, so that each one gets a break. It is used on very long or very frequent routes.\n📍 Book M30 p.7"},{"q":"Which of the following timetabling aims is listed in the module?\n1. Match passenger demand\n2. Provide capacity for specific peaks\n3. Integrate with other services on shared sections of route\n4. Satisfy marketing requirements, such as easily remembered timetables","options":["1, 2, 3 and 4","1 and 2 only","1, 2 and 3 only","3 and 4 only"],"correct":0,"exp":"All four are objectives of a timetable. After that come vehicle scheduling, crew scheduling and rosters.\n📍 Book M30 p.1"},{"q":"Which vehicles are out of scope of the EU tachograph rules?\n1. Vehicles on regular passenger services where the route does not exceed 50 km\n2. Vehicles with 9 to 16 passenger seats used exclusively for non-commercial carriage\n3. All coaches used for private hire","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"correct":0,"exp":"Outside the EU rules: regular services up to 50 km and non-commercial vehicles with 9 to 16 seats. Private hire coaches do have a tachograph.\n📍 Book M12 p.1"},{"q":"Which of the following are visible components of a digital tachograph vehicle unit?\n1. A display screen\n2. Card slots for two crew members\n3. A download interface\n4. A printer","options":["1, 2, 3 and 4","1 and 2 only","1, 2 and 3 only","2 and 4 only"],"correct":0,"exp":"The vehicle unit (VU) has a screen, two card slots, activity and eject buttons, a download connector and a printer.\n📍 Book M12 p.2"},{"q":"Which of the following could appear in the 'events and infringements' section of a digital tachograph printout?","options":["Driving without a card, overspeeding, power cuts","The driver's salary and overtime for the day","The names and seat numbers of passengers","The price paid for fuel at each refill"],"correct":0,"exp":"The printout uses pictograms to show incidents: driving without a card, speeding, power interruptions, etc.\n📍 Book M12 p.6"},{"q":"Legally, who owns a driver card?","options":["The RSA, though the driver keeps it","The employer who paid the fee","The driver alone, as it is personal","The tachograph manufacturer"],"correct":0,"exp":"Legally the card belongs to the RSA, although in practice it is the driver's (it is in their name and has their photo), even if the company paid for it.\n📍 Book M12 p.3"},{"q":"What does the pyramid drawing of a tall hierarchy show?","options":["Many layers, with more people at the bottom","Every level has the same number of staff","The organisation has only two levels","How the annual profit is shared out"],"correct":0,"exp":"The pyramid shows how many levels there are and that there are more people at the bottom than at the top (more guards than sergeants, in the police example).\n📍 Book M8 p.1"},{"q":"Why might an organisation remove some management layers?","options":["Better communication, lower costs, faster response","To create more opportunities for promotion","To increase the number of supervisory levels","To make supervision of every task closer"],"correct":0,"exp":"Removing levels (moving to a flatter hierarchy) improves communication, reduces costs and makes the company more agile. In return there are fewer promotions and each manager supervises more people.\n📍 Book M8 p.2"},{"q":"How should KPI performance be monitored, according to the module?","options":["Regular weekly, monthly and annual reports","Only once every five years, at renewal","Only when the RSA asks for a report","Only by the drivers, on their own records"],"correct":0,"exp":"KPIs are tracked with regular reports (weekly, monthly, annual) and charts, to see which areas need to improve.\n📍 Book M8 p.4"},{"q":"In a case study, you are asked to draw an organisation chart for a company. What should it show?","options":["All the staff, their roles and reporting lines","Only the names and roles of the directors","The fleet list with registration numbers","The company's timetable and route map"],"correct":0,"exp":"In the exam, the organisation chart must include ALL the staff in the case, with their job and who they report to. Each missing person or line loses marks.\n📍 Book M8 p.2-3 (case answer, p.10)"}]},"114":{"title":"Mock Exam 14 - TMCPC 30 MCQ (course questions)","questions":[{"q":"What is the minimum nominal and issued share capital required by law to form a Public Limited Company (PLC) in Ireland?","options":["€1,000","€10,000","€25,000","€100,000"],"correct":2,"exp":"A PLC needs nominal and issued share capital of at least €25,000. A private limited company (Ltd) has no minimum.\n📍 Book M2 p.6"},{"q":"In an insolvent company liquidation, in what order of priority are available funds distributed to creditors?","options":["Liquidator - preferential - unsecured - shareholders","Shareholders - liquidator - unsecured - preferential","Preferential - trade creditors - liquidator - Revenue","Trade creditors first, then everyone else equally"],"correct":0,"exp":"Order of payment: first the liquidator's costs, then preferential debts (mainly wages), then non-preferential debts (Revenue, suppliers) and finally, if anything is left, the shareholders.\n📍 Book M2 p.13"},{"q":"Within what timeframe from the start of employment must an employer provide an employee with written particulars of employment?","options":["Within 7 calendar days","Within 1 month","Within 2 months","By the end of the probationary period"],"correct":1,"exp":"5 core terms within the first 5 days and the full written statement of terms within the first month.\n📍 Book M3 p.5"},{"q":"Under the Minimum Notice and Terms of Employment Act, what is the statutory minimum notice an employer must provide to an employee who has been continuously employed for 3 years?","options":["1 week","2 weeks","4 weeks","6 weeks"],"correct":1,"exp":"2 to 5 years' service: 2 weeks. Table: less than 13 weeks, none; up to 2 years, 1; 2-5, 2; 5-10, 4; 10-15, 6; more than 15, 8 weeks.\n📍 Book M3 p.14"},{"q":"What is an employee's maximum entitlement under Statutory Sick Pay (SSP)?","options":["3 days at 50% of normal pay capped at €80/day","5 days at 70% of normal pay capped at €110/day","10 days at 100% of normal pay","14 days at 75% of normal pay capped at €150/day"],"correct":1,"exp":"SSP: 5 days a year, at 70% of daily pay, with a maximum of €110 a day, after 13 weeks' service and with a medical certificate.\n📍 Book M3 p.13-14"},{"q":"An inspector from the Health and Safety Authority (HSA) identifies an activity in a transport depot that involves an immediate risk of serious personal injury. Which statutory notice will the inspector issue?","options":["Improvement Plan","Improvement Notice","Prohibition Notice","Environmental Rectification Order"],"correct":2,"exp":"If there is a risk of serious injury, a Prohibition Notice: the activity stops. An Improvement Notice gives a deadline to correct something that does not comply.\n📍 Book M4 p.11"},{"q":"What is the recognised third step in the 5-step workplace risk assessment process?","options":["Identify potential hazards","Decide who may be harmed and how","Evaluate the risks and decide on precautions","Record your findings and implement them"],"correct":2,"exp":"The 5 steps: 1) identify the hazards; 2) decide who might be harmed and how; 3) evaluate the risks and decide on the measures; 4) record and implement them; 5) review.\n📍 Book M4 p.10"},{"q":"How is a company's Working Capital calculated on the balance sheet?","options":["Total Assets minus Total Liabilities","Current Assets minus Current Liabilities","Gross Profit minus Indirect Overheads","Fixed Assets minus Depreciation"],"correct":1,"exp":"Working capital = current assets − current liabilities: the money available for day-to-day running.\n📍 Book M5 p.10"},{"q":"Why is the value of stock deducted from Current Assets when calculating the Acid Test (Quick Assets) Ratio?","options":["Stock is classified as a fixed asset","Stock is subject to Corporation Tax depreciation","Stock cannot be converted into cash immediately","Stock is owned by trade creditors"],"correct":2,"exp":"Stock takes time to turn into money, so the acid test removes it: (current assets − stock) ÷ current liabilities, ideally 1:1.\n📍 Book M5 p.10"},{"q":"A transport business sells its outstanding debtor sales invoices to a financial institution to release immediate working cash rather than waiting for customer credit terms. This is called:","options":["Invoice discounting equity","Debt factoring","Straight-line leasing","Debenture amortization"],"correct":1,"exp":"Debt factoring: selling unpaid invoices to a finance company, which advances the money in exchange for a fee.\n📍 Book M5 p.13"},{"q":"In transport commercial contracts, what is the meaning of the term 'Carriage Forward'?","options":["Transport costs are paid by the receiver","Transport costs are paid by the sender","Transport charges are waived by the NTA","Payment is due before goods leave the factory"],"correct":0,"exp":"'Carriage forward': the receiver (consignee) pays the carriage. 'Carriage paid': the sender (consignor) pays.\n📍 Book M6 p.2"},{"q":"What is the commercial purpose of issuing a Credit Note to a customer?","options":["To demand payment in advance before dispatch","To correct an undercharge on a previously issued invoice","To correct an overcharge on a previously issued invoice","To charge interest on overdue trade balances"],"correct":2,"exp":"Credit note: corrects an OVERcharge. A debit note corrects an undercharge, and a pro-forma invoice asks for payment in advance.\n📍 Book M6 p.3"},{"q":"A coach operator runs a small trial of a passenger satisfaction survey on a limited sample of 30 travellers to identify errors before launching a nationwide study. This is called a:","options":["Secondary research desk audit","Pilot study","Non-reactive review","Market segmentation exercise"],"correct":1,"exp":"Pilot study: testing the survey on a small group to correct mistakes before giving it to everyone.\n📍 Book M7 p.8"},{"q":"In organisational design, what is a primary operational disadvantage of a 'Flat Hierarchy'?","options":["Higher management costs","Large spans of control for managers and reduced promotion opportunities","Built-in resistance to change and long vertical reporting chains","Total inability to delegate work"],"correct":1,"exp":"Flat hierarchy: each manager supervises a lot of people and there are few promotions. High costs and resistance to change are problems of the tall hierarchy.\n📍 Book M8 p.2"},{"q":"Under operational management standards, what does the acronym 'SMART' stand for when preparing staff work plans?","options":["Standardized, Monitored, Audited, Recorded, Tested","Specific, Measurable, Achievable, Relevant, Timed","Systematic, Maintained, Approved, Regulated, Trained","Strategic, Managed, Authorized, Responsive, Tracked"],"correct":1,"exp":"SMART: Specific, Measurable, Achievable, Relevant, Timed. If an objective meets all five, whoever receives it knows exactly what is expected of them.\n📍 Book M8 p.4"},{"q":"What is the standard rate of Irish Corporation Tax applied to company trading profits?","options":["10%","12.5%","20%","25%"],"correct":1,"exp":"12.5% on trading profits. 25% is for non-trading income (rents, investments).\n📍 Book M9 p.1"},{"q":"Under Revenue rules, for what minimum period must business tax and VAT accounting records be retained?","options":["2 years","3 years","6 years","10 years"],"correct":2,"exp":"Tax and VAT records are kept for at least 6 years, including those of the self-employed.\n📍 Book M9 (records and VAT)"},{"q":"Which European country requires vehicles over 3,500 kg, including coaches, to be fitted with an electronic 'GO-Box' for motorway toll payments?","options":["Germany","France","Austria","Switzerland"],"correct":2,"exp":"The GO-Box is Austria's. Germany charges the LKW-Maut on lorries, Switzerland the LSVA and Norway uses AutoPASS.\n📍 Book M9 p.14"},{"q":"When entering Turkey with a commercial fleet vehicle, what is the fuel threshold in standard fuel tanks above which customs duty/tax is applied?","options":["Fuel in excess of 200 litres","Fuel in excess of 400 litres","Fuel in excess of 550 litres","All fuel is taxed regardless of volume"],"correct":2,"exp":"Turkey allows up to 550 litres in factory-fitted tanks in tax-free; anything above that is charged.\n📍 Book M9 p.18-19"},{"q":"Under EU Regulation 561/2006, after a driving period of 4½ hours, a driver must take an uninterrupted break of at least:","options":["30 minutes","45 minutes","60 minutes","15 minutes followed by 15 minutes"],"correct":1,"exp":"After 4 h 30 of driving: 45 consecutive minutes. It can also be split, but into 15 and then 30, never 15 + 15.\n📍 Book M11 p.2"},{"q":"Under Irish Domestic Regulations for passenger operations, what is the maximum permissible daily driving limit?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"Domestic rules: 10 hours of driving a day, a maximum of 5 h 30 continuous, a 16-hour working day and 10 hours of rest.\n📍 Book M11 p.11"},{"q":"Under EU Regulation 165/2014, what is the maximum interval for downloading data from a Digital Tachograph Vehicle Unit (VU)?","options":["At least every 14 days","At least every 28 days","At least every 56 days","At least every 90 days"],"correct":3,"exp":"The vehicle unit (VU), every 90 days at most. The driver card, every 28 days.\n📍 Book M12 p.5"},{"q":"How frequently must an analogue tachograph be fully recalibrated?","options":["Annually","Every 2 years","Every 5 years","Every 6 years"],"correct":3,"exp":"Analogue: inspection every 2 years and full recalibration every 6 (or when the seals are broken). The digital one is recalibrated every 2 years.\n📍 Book M12 p.11"},{"q":"Under Irish fleet maintenance guidelines, how long must defect reports and maintenance rectification records be retained by an operator?","options":["6 months","12 months","15 months","24 months"],"correct":2,"exp":"The module summary and test say 15 months, and that is the answer to give. Note: on p. 5 the book says 'at least 2 years' for the self-employed without a workshop.\n📍 Book M13 summary p.15 (and p.5)"},{"q":"If an operator contracts out vehicle safety inspections to an external garage, who carries statutory legal responsibility for vehicle roadworthiness and maintenance records?","options":["The external commercial garage foreman","The vehicle operator","The CVRT tester","The vehicle manufacturer"],"correct":1,"exp":"Even if maintenance is done by an external workshop (with a written contract), the operator is still responsible.\n📍 Book M13 p.7"},{"q":"Which of the following is classified as a Standing (Fixed) Cost in fleet management?","options":["Diesel fuel","Engine oil lubricants","Commercial fleet motor insurance","Replacement drive-axle tyres"],"correct":2,"exp":"Insurance is a fixed cost: it is paid even if the vehicle does not move. Fuel, lubricants and tyres are variable costs (per km).\n📍 Book M14 p.2"},{"q":"When calculating the straight-line depreciation of a new commercial vehicle, what must be deducted from the purchase price alongside the estimated residual value?","options":["The value of the original tyres","The first year's motor tax","Any driver training grants received","The expected fuel costs for the first year"],"correct":0,"exp":"Straight line = (price − tyres − residual value) ÷ years. The tyres are subtracted because they go in the variable costs.\n📍 Book M14 p.3"},{"q":"How is annual motor tax calculated for passenger buses and coaches in Ireland?","options":["Based on engine cubic capacity (cc)","Based on CO2 emissions ratings (g/km)","Based on the unladen weight of the vehicle","Based on the number of passenger seats"],"correct":3,"exp":"Buses pay according to seats (9 to 20, €133; 21 to 40, €175-202; 41 and over, €349-403). Unladen weight is for lorries. (The original question in the PDF was the lorry one; it has been changed to the bus one.)\n📍 Book M15 p.2-3"},{"q":"What on-board electronic network collects data from engine, braking and transmission control units to feed fleet telematics systems?","options":["The CAN-bus network","A GPS transponder","An RFID tag sensor","The tachograph VU"],"correct":0,"exp":"The CANbus is the internal network that connects the engine, brake and gearbox control units; that is where telematics gets its data.\n📍 Book M17 p.1"},{"q":"When must a newly registered commercial truck or passenger bus undergo its first CVRT roadworthiness test?","options":["At 6 months of age","When the vehicle is 1 year old","When the vehicle is 2 years old","At 4 years of age"],"correct":1,"exp":"First CVRT when the vehicle is 1 year old from registration, and then every 12 months.\n📍 Book M19 p.2 · M15 p.2"}]},"115":{"title":"Mock Exam 15 - Official CILT sample exam (Part 1)","questions":[{"q":"Which document is issued when a company is legally formed?","options":["Memorandum of Trading","Certificate of Incorporation","Company Licence","Share Certificate"],"correct":1,"exp":"When the CRO registers the company it issues the Certificate of Incorporation: from that date the company legally exists and has its registration number. The «Memorandum of Trading» and the «Company Licence» do not exist; the Share Certificate only proves who holds shares.\n📍 Book M2 p.8"},{"q":"Which business structure has separate legal identity from its owners?","options":["Sole Trader","Partnership","Franchise","Limited Company"],"correct":3,"exp":"A limited company is a legal person separate from its owners: it signs contracts, owes money and sues in its own name, and the members are liable only up to what they contributed. A sole trader and a partnership are not separate from their owners.\n📍 Book M2 p.5"},{"q":"Which of the following is a duty of a company director?","options":["Act in the best interests of the company","Ignore creditors","Increase share capital whenever required","Set tax rates"],"correct":0,"exp":"A director must act in good faith and in the interest of the company (and take the creditors into account, especially if there is a risk of insolvency). Increasing capital is decided by the members, and taxes are set by the State.\n📍 Book M2 p.11"},{"q":"Which organisation hears employment disputes in Ireland?","options":["RSA","Gardaí","WRC","Revenue"],"correct":2,"exp":"The Workplace Relations Commission (WRC) receives and decides employment complaints (dismissals, pay, hours...). Its decisions can be appealed to the Labour Court.\n📍 Book M3 p.1"},{"q":"Written particulars of employment should normally be provided:","options":["Within statutory time limits","After one year","Only if requested","Never"],"correct":0,"exp":"There are legal deadlines: 5 core terms within the first 5 days (Day 5 Statement) and the rest of the terms in writing within the first month. It does not depend on the worker asking for it.\n📍 Book M3 p.4"},{"q":"Which organisation enforces workplace health and safety legislation?","options":["Road Safety Authority","Health and Safety Authority","Department of Justice","EPA"],"correct":1,"exp":"The Health and Safety Authority (HSA) enforces the Safety, Health and Welfare at Work Act 2005: it inspects, issues improvement or prohibition notices and can take the employer to court. The RSA deals with road safety.\n📍 Book M4 p.11"},{"q":"What is the noise level above which hearing protection must be worn?","options":["90 dB(A)","100 dB(A)","80 dB(A)","85 dB(A)"],"correct":3,"exp":"85 dB(A) is the upper exposure action value: above it, hearing protection is compulsory and the area must be signposted. At 80 dB(A) (lower value) the employer only has to make it available.\n📍 Book M4 p.8"},{"q":"What is the first stage in a risk assessment?","options":["Notify the HSA","Inform a trade union","Identify the hazard","Appoint a safety representative"],"correct":2,"exp":"First step: identify the hazards. Then: decide who might be harmed, assess the risk and the measures, record it and review it. There is no need to notify the HSA or the trade union to do it.\n📍 Book M4 p.9"},{"q":"Working Capital equals:","options":["Debtors - Creditors","Fixed Assets - Current Liabilities","Sales - Costs","Current Assets - Current Liabilities"],"correct":3,"exp":"Working capital = current assets − current liabilities. It measures whether the company can pay its short-term debts. «Sales − Costs» is profit, not working capital.\n📍 Book M5 p.10"},{"q":"The Acid Test Ratio excludes:","options":["Stock","Debtors","Cash","Creditors"],"correct":0,"exp":"Acid test = (current assets − stock) ÷ current liabilities. Stock is removed because it may take time to turn into money.\n📍 Book M5 p.10"},{"q":"The primary aim of a commercial enterprise is:","options":["Social welfare","Employment growth","Profit","Market share"],"correct":2,"exp":"A commercial company exists above all to make money; that is why the book's definition of marketing ends in «profitably». Market share and employment are secondary objectives.\n📍 Book M7 p.1"},{"q":"A credit note is used when:","options":["Increasing an invoice","Reducing an invoice value","Paying wages","Paying VAT"],"correct":1,"exp":"A credit note confirms that the amount of an invoice is reduced, for example because of an overcharge. To increase an invoice, a debit note is used.\n📍 Book M6 p.3"},{"q":"Market segmentation involves:","options":["Dividing customers into groups","Reducing fleet size","Closing depots","Increasing prices"],"correct":0,"exp":"Segmenting means dividing the market into groups of customers with similar needs (for example, executives going to the airport, schools, tourists) to offer each one the right service.\n📍 Book M7 p.5"},{"q":"Public relations is primarily concerned with:","options":["Vehicle maintenance","Taxation","Drivers' hours","Public image"],"correct":3,"exp":"Public relations aims to present the company in the most favourable way to customers, the press and the public: its image.\n📍 Book M7 p.8"},{"q":"Which is a requirement for the grant of an Operator Licence?","options":["Union membership","Good repute","Driver CPC","ADR qualification"],"correct":1,"exp":"The 4 requirements for the operator licence: good repute, financial standing, professional competence (a transport manager with the manager's CPC) and a stable and effective establishment. The Driver CPC and ADR (dangerous goods) are something else.\n📍 Book M10 p.6"},{"q":"Financial standing is assessed when:","options":["Purchasing fuel","Applying for road tax","Applying for an operator licence","Applying for insurance"],"correct":2,"exp":"Financial standing is one of the 4 requirements for the operator licence: it is proved when applying (and when extending or renewing) with certified accounts or a Statement of Affairs.\n📍 Book M10 p.6"},{"q":"What must be done if fleet size is increased?","options":["Inform insurance only","Amend the transport licence","Notify Revenue","Notify customers"],"correct":1,"exp":"Each vehicle has to be on the operator licence: to have more, the licence must be amended (through the RTOL portal) and financial standing proved for the new total number of vehicles.\n📍 Book M10 p.8"},{"q":"EU drivers' hours rules apply principally to:","options":["Commercial road transport operations","All motorists","Motorcycles only","Agricultural tractors only"],"correct":0,"exp":"Regulation 561/2006 applies to professional road transport: buses and coaches with more than 9 seats (driver included) and lorries over 3.5 t, with some exemptions (for example, regular services up to 50 km).\n📍 Book M11 p.1"},{"q":"The normal daily driving limit is:","options":["7 hours","8 hours","11 hours","9 hours"],"correct":3,"exp":"Daily driving: 9 hours, which can be extended to 10 hours twice a week. 11 hours is the normal daily rest, not driving.\n📍 Book M11 p.2"},{"q":"Tachograph records must be retained:","options":["For one month","For one week","In accordance with legal requirements","Indefinitely"],"correct":2,"exp":"The operator must keep them for the time the law requires: at least 12 months, and 2 years if they are also used to monitor working time.\n📍 Book M12 p.10"},{"q":"A driver card is used with:","options":["Analogue tachographs","Odometers","Digital tachographs","GPS systems"],"correct":2,"exp":"The driver card goes into the digital (or smart) tachograph and stores the driver's activities. With the analogue one, paper charts are used.\n📍 Book M12 p.1"},{"q":"Downloading tachograph data assists:","options":["Fuel purchasing","Compliance monitoring","Tax returns","Recruitment"],"correct":1,"exp":"Downloading the cards (every 28 days) and the vehicle unit (every 90) is used to check that driving and rest hours are being complied with and to correct infringements.\n📍 Book M12 p.10"},{"q":"Planned preventive maintenance aims to:","options":["Maintain roadworthiness","Increase defects","Reduce driver numbers","Reduce taxation"],"correct":0,"exp":"Planned preventive maintenance aims to keep vehicles in a safe, roadworthy condition at all times, detecting defects before they cause a breakdown or an accident.\n📍 Book M13 p.2"},{"q":"Daily walk-around checks should be completed by:","options":["Traffic commissioner","Customer","Accountant","Driver"],"correct":3,"exp":"The daily walkround check is done by the driver before using the vehicle (and by each new driver who uses it that day), and they record the defects.\n📍 Book M13 p.2"},{"q":"Which of the following is a standing cost?","options":["Fuel","Vehicle depreciation","Tyres","AdBlue"],"correct":1,"exp":"Fixed (standing) costs: tax, insurance, driver's basic wage, depreciation and overheads; they are paid even if the vehicle does not move. Fuel, tyres and AdBlue are variable (running) costs, which depend on the km.\n📍 Book M14 p.2"},{"q":"Cost per kilometre is commonly used in:","options":["Licensing","Tax returns","Vehicle costing","Recruitment"],"correct":2,"exp":"Cost per kilometre is a «cost unit» in vehicle costing: it is used to compare vehicles and to quote for jobs.\n📍 Book M14 p.1"},{"q":"Vehicle tax classification is influenced by:","options":["Insurance company","Driver age","Fuel station used","Vehicle category"],"correct":3,"exp":"Motor tax depends on the type of vehicle: for buses and coaches, on the number of seats; for lorries, on the weight.\n📍 Book M15 p.2"},{"q":"Gross Vehicle Weight means:","options":["Total weight of vehicle, passengers and any load.","Empty vehicle weight","Axle weight only","Trailer weight only"],"correct":0,"exp":"Gross vehicle weight (GVW): the vehicle plus everything it carries (passengers, luggage, fuel, driver). The empty weight is the unladen weight.\n📍 Book M18 p.2"},{"q":"Axle limits are designed primarily to:","options":["Increase payloads","Reduce fuel costs","Protect roads","Simplify licensing"],"correct":2,"exp":"Axle limits exist mainly to protect roads and bridges from the wear and damage caused by weight concentrated on one axle.\n📍 Book M18 p.1"},{"q":"Overloading can result in:","options":["Higher speeds","Higher profits only","Reduced fuel usage","Prosecution"],"correct":3,"exp":"Driving above the authorised weights is an offence: fines, immobilisation of the vehicle and prosecution, as well as a risk to safety and to the licence.\n📍 Book M18 p.2"},{"q":"A passenger vehicle with 12 seat capacity requires:","options":["Category D1","Category C","Category BE","Category C1"],"correct":0,"exp":"D1: vehicles with more than 8 and up to 16 passenger seats (and a maximum length of 8 m). C and C1 are for lorries; BE is a car with a trailer.\n📍 Book M21 p.1"},{"q":"Medical standards are relevant to:","options":["Car purchasers","Vocational licence holders","Mechanics only","Shunters only"],"correct":1,"exp":"Professional drivers (C and D licences, group 2) have stricter medical requirements: a medical report (form D501/D4) when applying for the licence, and at each renewal from age 45; before that a signed declaration is enough.\n📍 Book M21 p.6"},{"q":"Speed limits for large passenger vehicles may differ from:","options":["VAT rates","Tax rules","Insurance terms","Passenger cars"],"correct":3,"exp":"Buses and coaches have their own limits, lower than cars: for example 100 km/h on the motorway (65 km/h if they carry standing passengers), compared with 120 km/h for cars.\n📍 Book M22 p.1"},{"q":"Prohibited parking restrictions are found within:","options":["Operator licensing","Traffic regulations","Marketing","Taxation"],"correct":1,"exp":"Parking prohibitions (clearways, bus lanes, pedestrian crossings, yellow lines...) are set out in the traffic regulations.\n📍 Book M22 p.3"},{"q":"A vehicle designed to carry 15 passengers is most likely:","options":["Motor Car","Large Bus","Minibus","Heavy Motor Car"],"correct":2,"exp":"A vehicle with more than 8 and up to 16 passenger seats is a minibus (driven with a D1 licence). A large bus has more than 16 seats.\n📍 Book M21 p.1"},{"q":"Which vehicle allows passenger movement between connected sections?","options":["Articulated Bus","Motor Car","Coach","Minibus"],"correct":0,"exp":"An articulated bus has two rigid sections joined by a bellows articulation, through which passengers can pass from one to the other (up to 18.75 m long).\n📍 Book M18 p.3"},{"q":"Operators must ensure:","options":["Waybills are unnecessary","Drivers choose their own route","Timetables are optional","Correct route and destination displays"],"correct":3,"exp":"On a regular service the bus must clearly display its route number and destination. The other three are false: waybills are needed, the driver follows the authorised route and the timetable is not optional.\n📍 No specific page: general obligation of regular service operators (M28)"},{"q":"Competition law seeks to:","options":["Increase taxes","Restrict operators","Promote fair competition","Reduce passenger numbers"],"correct":2,"exp":"Competition law (the Competition Act 2002 and Articles 101 and 102 TFEU, enforced by the CCPC) protects fair competition: it prohibits cartels and abuse of a dominant position.\n📍 Book M29 p.1"},{"q":"Headway is:","options":["Time between successive services","Distance between depots","Driver break duration","Route length"],"correct":0,"exp":"Headway is the interval of time between one bus and the next on the same route (for example, one every 15 minutes).\n📍 Book M30 p.2"},{"q":"A tapered fare structure means:","options":["All journeys cost the same","Longer journeys cost less per kilometre","Longer journeys cost more per kilometre","Distance has no effect on fare"],"correct":1,"exp":"Tapered fare: the further you go, the more you pay in total, but each kilometre is cheaper. When every journey costs the same, that is a flat fare.\n📍 Book M31 p.3"}]},"116":{"title":"Mock Exam 16","questions":[{"q":"An employee with 11 years' continuous service is being dismissed. What is the minimum notice the employer must give?","options":["4 weeks","6 weeks","8 weeks","2 weeks"],"correct":1,"exp":"10 to 15 years' service: 6 weeks. Table: less than 13 weeks, none; up to 2 years, 1; 2 to 5, 2; 5 to 10, 4; 10 to 15, 6; more than 15, 8 weeks.\n📍 Book M3 p.14"},{"q":"A driver has driven for 2 h 30, taken a 15-minute break, then driven another 2 hours. What break must he take now?","options":["15 minutes","30 minutes","45 minutes","No break yet"],"correct":1,"exp":"He has now driven 4 h 30 with a 15 min break: he must now stop for at least 30 min (15 + 30 = 45). The order is always 15 first and 30 afterwards.\n📍 Book M11 p.2"},{"q":"A vehicle costs €120,000, its tyres are worth €4,000 and its expected resale value after 5 years is €16,000. What is the annual straight-line depreciation?","options":["€20,000","€20,800","€23,200","€24,000"],"correct":0,"exp":"(120,000 − 4,000 − 16,000) ÷ 5 = 100,000 ÷ 5 = €20,000. The tyres are subtracted because they are a variable cost; the other results forget the tyres, the residual value or both.\n📍 Book M14 p.3"},{"q":"A company cannot pay its debts and its creditors decide to wind it up. What type of winding up is this?","options":["Members' voluntary","Creditors' voluntary","Compulsory","Examinership"],"correct":1,"exp":"If the company cannot pay and the creditors are in charge, it is a creditors' voluntary winding up. Members' voluntary is for a solvent company; compulsory is controlled by the courts.\n📍 Book M2 p.12"},{"q":"An operator is licensed for 4 vehicles and wants to add 2 more. How much additional financial standing must it show?","options":["€5,000","€10,000","€14,000","€18,000"],"correct":1,"exp":"Each additional vehicle requires €5,000: 2 × 5,000 = €10,000 more (the €9,000 for the first is already covered).\n📍 Book M10 p.8"},{"q":"Current assets are €90,000, of which stock is €30,000. Current liabilities are €60,000. What is the acid test ratio?","options":["0.5 : 1","1 : 1","1.5 : 1","2 : 1"],"correct":1,"exp":"Acid test = (current assets − stock) ÷ current liabilities = (90,000 − 30,000) ÷ 60,000 = 1 : 1, the ideal. The current ratio would be 1.5 : 1.\n📍 Book M5 p.10"},{"q":"A driver card was last downloaded 30 days ago. What is the position?","options":["Fine: the limit is 90 days","Late: the limit is 28 days","Fine: only the VU is downloaded","Late: the limit is 7 days"],"correct":1,"exp":"The driver card is downloaded at least every 28 days; the vehicle unit (VU), every 90.\n📍 Book M12 p.5"},{"q":"An employee earning €180 a day is off sick for 4 days with a medical certificate, after 2 years' service. How much Statutory Sick Pay is due?","options":["€440","€504","€550","€720"],"correct":0,"exp":"70% of 180 = €126, but the cap is €110 a day: 4 × 110 = €440.\n📍 Book M3 p.13-14"},{"q":"At what daily noise exposure must the employer make hearing protection available (lower action value)?","options":["75 dB(A)","80 dB(A)","85 dB(A)","87 dB(A)"],"correct":1,"exp":"At 80 dB(A) hearing protection must be made available with information and training; at 85 dB(A) wearing it is compulsory and the area must be signposted; 87 dB(A) is the maximum limit.\n📍 Book M4 p.8"},{"q":"By when must a company pay its corporation tax?","options":["Within 6 months after the year end","The 23rd of the 9th month after year end","By 31 October of the following year","Within 30 days after the year end"],"correct":1,"exp":"Corporation tax is paid at the latest on the 23rd day of the ninth month after the end of the accounting period. 31 October is the deadline for the self-employed (pay and file).\n📍 Book M9 p.1"},{"q":"A 13-year-old vehicle covers very few kilometres. How often must it have a safety inspection?","options":["Every 6 weeks at most","Every 10,000 km","Once a year, at the CVRT","Every 12 weeks at most"],"correct":0,"exp":"According to the RSA guide, inspections are based on time, not km: at 12 years or more, at most every 6 weeks.\n📍 Book M13 p.5"},{"q":"A driver aged 19 holds a full category D licence and the Driver CPC. Which bus work may he do?","options":["Any coach tour in Ireland","Only regular services up to 50 km","Only school runs in a minibus","None until he is 21"],"correct":1,"exp":"At 18, with a D licence and the full CPC, he can only drive regular services up to 50 km. At 21 with the CPC there is no distance limit.\n📍 Book M21 p.2"},{"q":"Offering a tailored service to one group of customers with similar needs, such as airport transfers for executives, is an example of:","options":["Market segmentation","Desk research","Public relations","Cross-subsidy"],"correct":0,"exp":"Segmenting means dividing the market into groups with similar needs and offering each one a tailored service.\n📍 Book M7 p.5"},{"q":"A transport company removes two levels of middle management. What is a likely disadvantage?","options":["Slower vertical communication","Higher management costs","Fewer promotion opportunities","More levels of command"],"correct":2,"exp":"A flatter structure improves communication and lowers costs, but there are fewer promotions and each manager supervises more people.\n📍 Book M8 p.2"},{"q":"An employee asks for a copy of all the personal data the company holds about him. Within what time must the company normally reply?","options":["7 days","14 days","1 month","3 months"],"correct":2,"exp":"It is a subject access request (GDPR): as a rule the reply is due within 1 month (30 days), free of charge.\n📍 Book M17 p.5"},{"q":"A city bus driver on a 20 km regular route starts work at 06:00. Under the domestic rules, what is the latest he can finish his working day (spreadover)?","options":["18:00","20:00","22:00","00:00"],"correct":2,"exp":"Regular services up to 50 km follow the domestic rules: the whole working day (spreadover) is 16 hours at most: 06:00 + 16 h = 22:00.\n📍 Book M11 p.10-11"},{"q":"A vehicle's annual fixed costs are €54,000. Using the book's working year, what is the fixed cost per day?","options":["€148","€208","€240","€270"],"correct":2,"exp":"The book uses 225 working days (5 days × 45 weeks): 54,000 ÷ 225 = €240 a day. Dividing by 365 (€148) is a typical mistake.\n📍 Book M14 p.12"},{"q":"When must a new heavy commercial vehicle take its first CVRT?","options":["1 year after first registration","2 years after first registration","4 years, like a private car","Before it is first registered"],"correct":0,"exp":"First CVRT when it is 1 year old from registration, and then every 12 months.\n📍 Book M19 p.2"},{"q":"A driver cannot produce his insurance certificate when a Garda asks for it. What happens?","options":["Produce it at a named station in 10 days","An on-the-spot fine and seizure","Show it at any station within 24 hours","Nothing, if the vehicle is taxed"],"correct":0,"exp":"He has 10 days to produce it in person at the Garda station named; the Garda can also check it on the IMID database.\n📍 Book M24 p.2"},{"q":"A dominant operator cuts its prices below cost, only on the route where a new rival has started, to push it out. This is:","options":["Normal and fair price competition","Predatory pricing (abuse of dominance)","A cross-subsidy that is allowed","A cartel agreement between rivals"],"correct":1,"exp":"Prices below cost intended to drive out the competitor: abuse of a dominant position (section 5 and Article 102). Having a dominant position is not illegal; abusing it is.\n📍 Book M29 p.4"},{"q":"A company with 120 employees plans 15 redundancies within 30 days. Is it a collective redundancy?","options":["No: the threshold is 30","Yes: the threshold is 10% (12)","No: the threshold is 20","Yes: any 5 redundancies count"],"correct":1,"exp":"With 100 to 299 employees the threshold is 10%: 12 people. 15 is more: a collective redundancy, with at least 30 days of consultation and notice to the Minister.\n📍 Book M3 p.13"},{"q":"On an analogue chart, the distance trace shows 8 complete 'V' shapes. How far did the vehicle travel?","options":["40 km","80 km","100 km","160 km"],"correct":1,"exp":"Each stroke is 5 km, so each complete 'V' is 10 km: 8 × 10 = 80 km.\n📍 Book M12 p.8"},{"q":"What can a court impose for serious vehicle roadworthiness offences?","options":["Up to €5,000 and/or 6 months' prison","A written warning, never a fine","A fine of up to €500, no prison","Up to 5 years in prison and a ban"],"correct":0,"exp":"Fines of up to €5,000, possible prison of up to 6 months, penalty points and a ban on using the vehicle.\n📍 Book M20 p.3"},{"q":"A bus route takes 40 minutes each way, with a 5-minute layover at each end. How many buses are needed for a 15-minute headway?","options":["5","6","7","8"],"correct":1,"exp":"(40 + 5) × 2 = 90 minutes per round trip ÷ a 15-minute headway = 6 buses.\n📍 Book M30 p.3"},{"q":"A supplier will only deliver once it has been paid. Which document does it send first?","options":["A pro-forma invoice","A credit note","A delivery note","A remittance advice"],"correct":0,"exp":"A pro-forma invoice is used when payment in advance is required.\n📍 Book M6 p.2"},{"q":"Two drivers share a vehicle (multi-manning). Within each period of 30 hours, how much daily rest must each of them take?","options":["At least 9 hours","At least 11 hours","At least 12 hours","At least 7 hours"],"correct":0,"exp":"With multi-manning, each driver rests at least 9 hours in each 30-hour period, with the vehicle stationary.\n📍 Book M11 p.3"},{"q":"A transport business that supplies services must register for VAT once its yearly turnover exceeds:","options":["€37,500","€42,500","€85,000","€100,000"],"correct":1,"exp":"Services: €42,500 a year; goods: €85,000. Below that you can register voluntarily.\n📍 Book M9 p.6"},{"q":"A company's transport manager is convicted of a serious offence. When must the operator tell the Department in writing?","options":["7 days after the conviction","3 months after the appeal period ends","12 months after the conviction","Only when the licence is renewed"],"correct":1,"exp":"In writing, within 3 months of the end of the appeal period (or of the appeal being decided or withdrawn). Failing to do so is an offence.\n📍 Book M10 p.8"},{"q":"Under a 'nil defect' reporting system, what does a driver who finds nothing wrong at the daily check do?","options":["Hands in the sheet marked 'NIL'","Says nothing and drives off","Phones the workshop manager","Waits for a mechanic to check"],"correct":0,"exp":"With the 'Nil' system, the driver hands in the sheet every day even when there are no defects; that way the operator can show the checks were done.\n📍 Book M13 p.3 and p.8"},{"q":"Which of these is NOT an accident that must be reported under section 106 of the Road Traffic Act 1961?","options":["Injuring a dog","Damaging a parked car","Injuring a cat","Damaging a roadside wall"],"correct":2,"exp":"The list of animals is horse, cattle, ass, mule, sheep, pig, goat and dog: a cat is not on it. Damaging a parked car or property beside the road does count.\n📍 Book M23 p.1"},{"q":"Which source of finance is NOT suitable for buying vehicles?","options":["Hire purchase","A long-term bank loan","A bank overdraft","Leasing"],"correct":2,"exp":"An overdraft is short-term finance for day-to-day needs; vehicles are bought with long-term loans, hire purchase, leasing or retained profits.\n📍 Book M5 p.3"},{"q":"Under a gross cost bus contract, who keeps the fare revenue?","options":["The bus operator","The contracting authority","The passengers' association","Both share it equally"],"correct":1,"exp":"Gross cost: the authority keeps the takings and pays the operator its cost. Net cost: the operator keeps the takings and asks for a subsidy.\n📍 Book M31 p.4"},{"q":"Which of these is NOT essential for a valid contract?","options":["Consideration","Offer and acceptance","A written document","Intention to create legal relations"],"correct":2,"exp":"A contract can be verbal: the essential elements are offer and acceptance, consideration, capacity, intention and legality.\n📍 Book M2 p.1"},{"q":"What is the motorway speed limit for a coach that carries no standing passengers?","options":["80 km/h","90 km/h","100 km/h","120 km/h"],"correct":2,"exp":"Coach without standing passengers: 100 km/h on motorways and dual carriageways and 80 on ordinary roads; with standing passengers, 65 on all roads.\n📍 Book M22 p.1"},{"q":"A mobile worker may work up to how many hours in a single week, provided the average stays at 48?","options":["48","56","60","72"],"correct":2,"exp":"An average of 48 hours a week (normally over 4 months), and never more than 60 in a single week.\n📍 Book M11 p.6"},{"q":"Which insurance covers the employer against claims from staff injured at work?","options":["Public liability","Employer's liability","Fidelity guarantee","Goods in transit"],"correct":1,"exp":"Employer's Liability: injuries to employees. Damage to third parties on the premises is Public Liability; employee dishonesty is fidelity guarantee.\n📍 Book M24 p.10-11"},{"q":"Total annual costs are €500,000 and the company wants a profit of €40,000. What mark-up on cost is needed?","options":["4%","8%","10%","12.5%"],"correct":1,"exp":"Mark-up = profit × 100 ÷ total costs = 40,000 × 100 ÷ 500,000 = 8%.\n📍 Book M14 p.10-11"},{"q":"A coach company is hired by a factory, under a contract, to carry its workers to and from work. What type of service is this?","options":["A regular service","A special regular service","An occasional service","Own-account transport"],"correct":1,"exp":"Special regular service: a specific category of passengers (workers, students) under a contract between the organiser and the carrier; a copy of the contract is carried on board.\n📍 Book M10 p.20"},{"q":"Since what date has the Euro 6 emissions standard been compulsory for new heavy vehicles?","options":["1 January 2009","1 January 2014","1 January 2018","1 January 2021"],"correct":1,"exp":"Euro 6 has been compulsory since 1 January 2014 (SCR and EGR technologies, particulate filters).\n📍 Book M25 p.7"},{"q":"A driver loses his driver card during a trip. Within how many days must he report it to the RSA?","options":["24 hours","7 days","15 days","28 days"],"correct":1,"exp":"He must tell the RSA within 7 days at most and, in the meantime, print out at the start and end of each working day; he can continue like that for up to 15 calendar days.\n📍 Book M12 p.3"}]},"117":{"title":"Mock Exam 17","questions":[{"q":"How much maternity leave is an employee entitled to, whatever her length of service?","options":["16 weeks, all of them paid","26 weeks + 16 optional unpaid","42 weeks, all of them paid","52 weeks, half of them paid"],"correct":1,"exp":"26 weeks of maternity leave plus 16 optional unpaid weeks, regardless of length of service. The State benefit requires PRSI contributions.\n📍 Book M3 p.8"},{"q":"A driver drove 52 hours last week. What is the most he may drive this week?","options":["34 hours","38 hours","48 hours","56 hours"],"correct":1,"exp":"A maximum of 90 h in two consecutive weeks: 90 − 52 = 38 h, even though the limit for a single week is 56.\n📍 Book M11 p.2-3"},{"q":"A vehicle costs €100,000, including tyres worth €4,000. Using 20% reducing balance, what is the depreciation in year 2?","options":["€15,360","€16,000","€19,200","€20,000"],"correct":0,"exp":"Base without tyres: 96,000. Year 1: 20% = 19,200 (76,800 left). Year 2: 20% of 76,800 = €15,360. The percentage is applied to what is left.\n📍 Book M14 p.4"},{"q":"An HSA inspector finds a risk of serious personal injury in a workshop. Which notice stops the activity?","options":["An Improvement Notice","A Prohibition Notice","An Improvement Plan","A Fixed Charge Notice"],"correct":1,"exp":"If there is a risk of serious injury, a Prohibition Notice: the activity stops until it is fixed. An Improvement Notice gives a deadline to correct something that does not comply.\n📍 Book M4 p.11"},{"q":"A company makes a trading profit of €80,000 and also earns €10,000 in rent. How much corporation tax is due?","options":["€11,250","€12,500","€22,500","€10,000"],"correct":1,"exp":"12.5% of 80,000 = €10,000 (trading) + 25% of 10,000 = €2,500 (non-trading income) = €12,500.\n📍 Book M9 p.1"},{"q":"An external transport manager already manages 3 companies with 40 vehicles in total. Can he take on a 4th company with 15 vehicles?","options":["Yes: up to 4 companies is allowed","No: the total would pass 50 vehicles","Yes, with verbal approval","No: the limit is 3 companies"],"correct":1,"exp":"Contracted transport manager: a maximum of 4 companies and 50 vehicles in total. 40 + 15 = 55 is over the limit.\n📍 Book M10 p.10"},{"q":"In what time does a digital tachograph record activities?","options":["Local time","UTC","Irish summer time","The driver's home time"],"correct":1,"exp":"The tachograph always records in UTC (Greenwich time); in summer Ireland is one hour ahead.\n📍 Book M12 p.5"},{"q":"An employee with 7 complete years' service earns €700 a week. What is the statutory redundancy payment?","options":["€9,000","€10,500","€8,400","€14,700"],"correct":0,"exp":"Weeks = (2 × 7) + 1 = 15. Pay is capped at €600: 15 × 600 = €9,000. (10,500 forgets the cap.)\n📍 Book M3 p.13"},{"q":"How long must maintenance and inspection records be kept?","options":["6 months","12 months","15 months","6 years"],"correct":2,"exp":"Maintenance records (inspections, defects and repairs) are kept for 15 months.\n📍 Book M13 p.5"},{"q":"The CIM defines marketing as the management process that identifies, anticipates and satisfies customer requirements…","options":["cheaply","profitably","efficiently","immediately"],"correct":1,"exp":"The Chartered Institute of Marketing's definition ends in 'profitably': a commercial company exists above all to make money.\n📍 Book M7 p.1"},{"q":"Which licence code means the holder may not drive a minibus for hire or reward?","options":["78","101","105","111"],"correct":1,"exp":"Code 101: not for hire or reward. 78: automatic only; 105: no more than 5.5 m; 111: maximum 16 seats.\n📍 Book M21 p.3"},{"q":"In SMART objectives, what does the 'T' stand for?","options":["Tested","Timed","Targeted","Tracked"],"correct":1,"exp":"SMART: Specific, Measurable, Achievable, Relevant (or Realistic) and Timed, i.e. with a deadline.\n📍 Book M8 p.4"},{"q":"Current assets are €150,000 and current liabilities €95,000. What is the working capital?","options":["€55,000","€95,000","€150,000","€245,000"],"correct":0,"exp":"Working capital = current assets − current liabilities = 150,000 − 95,000 = €55,000.\n📍 Book M5 p.10"},{"q":"A driver splits his regular daily rest. Which split is allowed?","options":["3 hours, then 9 hours","2 hours, then 9 hours","6 hours, then 5 hours","9 hours, then 3 hours"],"correct":0,"exp":"Split daily rest: first at least 3 hours and then at least 9, 12 h in total. The other way round is not valid.\n📍 Book M11 p.2-3"},{"q":"What does a Green Card prove?","options":["The driver's CPC qualification","The vehicle's insurance abroad","Payment of the motor tax","A clean driving record abroad"],"correct":1,"exp":"The Green Card is international proof of the vehicle's insurance.\n📍 Book M24"},{"q":"A depot needs 30 bus duties a day, 6 days a week, and each driver works 5 days. How many drivers are needed before holiday cover?","options":["30","36","42","45"],"correct":1,"exp":"Duties in the week = 30 × 6 = 180 ÷ 5 days = 36 drivers, plus holiday cover.\n📍 Book M30 p.8"},{"q":"What is the minimum issued share capital of a public limited company (PLC)?","options":["€1","€10,000","€25,000","€100,000"],"correct":2,"exp":"A PLC needs nominal and issued share capital of at least €25,000; a private limited company (Ltd) has no minimum.\n📍 Book M2 p.6"},{"q":"Within how long must a driver return used analogue charts to the employer?","options":["7 days","28 days","42 days","90 days"],"correct":2,"exp":"Used charts are returned to the company within 42 days, and kept for 12 months (2 years if used for working time).\n📍 Book M12 p.10"},{"q":"Diesel costs €1.44 a litre (excluding VAT) and the vehicle does 3.6 km per litre. What is the fuel cost per km?","options":["€0.25","€0.40","€0.52","€5.18"],"correct":1,"exp":"Fuel per km = price per litre ÷ km per litre = 1.44 ÷ 3.6 = €0.40. Multiplying (5.18) is the typical mistake.\n📍 Book M14 p.8"},{"q":"What does 'plating' a vehicle certify?","options":["Its maximum permitted weights","Its motor tax class","The driver's licence category","The tachograph calibration"],"correct":0,"exp":"Plating certifies the maximum weights (GVW, GTW and per axle). Exceeding them is an offence.\n📍 Book M19 p.1"},{"q":"On ferry crossings of more than 20 miles from an EU port, what must the coach operator give the shipping line?","options":["A passenger list (name, sex, age)","The coach's CRW certificate","The driver's tachograph card","The Community Licence copy"],"correct":0,"exp":"SOLAS Convention / Directive 98/41: surname, first name, sex, age and special needs of each passenger, on crossings of more than 20 miles.\n📍 Book M26 p.5-7"},{"q":"Two competing operators agree by phone that both will submit high bids for a public tender so that one of them wins. This is:","options":["Legal if nothing is written","Bid-rigging, a cartel offence","Fair cooperation","Interworking"],"correct":1,"exp":"It is bid-rigging, a cartel prohibited by section 4 of the Competition Act, even if the agreement is verbal.\n📍 Book M29"},{"q":"Under general working time law, after how long must an employee get a 15-minute break?","options":["3 hours","4 h 30","6 hours","8 hours"],"correct":1,"exp":"General law: 15 minutes after 4 h 30 of work and 30 minutes after 6 hours.\n📍 Book M3 p.18"},{"q":"Who may stop a moving vehicle on the road for a roadside check?","options":["Only the Garda","RSA inspectors alone","Any local council officer","The CCPC"],"correct":0,"exp":"Only the Garda can stop a moving vehicle; then the Garda and RSA inspectors check it.\n📍 Book M20 p.5"},{"q":"Under Regulation 1370/2007, a public bus contract may be awarded directly (de minimis) when its average annual value is below:","options":["€500,000","€1 million","€2 million","€5 million"],"correct":1,"exp":"De minimis: an average of less than €1 million a year or less than 300,000 km a year (for SMEs with 23 vehicles or fewer, €2 million or 600,000 km).\n📍 Book M31"},{"q":"What is the vehicle's internal network that links the engine, brake and gearbox control units called?","options":["The CANbus","The DSRC link","The GNSS signal","The EDI system"],"correct":0,"exp":"The CANbus connects the engine, brake and gearbox control units; that is where telematics gets its data.\n📍 Book M17 p.1"},{"q":"Which of these does NOT need a passenger operator licence?","options":["A hotel carrying its guests for free","A firm selling coach excursions","A firm hiring out coaches with drivers","A company running a paid shuttle"],"correct":0,"exp":"If no charge is made for carrying the passengers, no operator licence is needed; the book gives exactly the example of a hotel with free transport.\n📍 Book M10 p.4"},{"q":"Goods are sent 'carriage forward'. Who pays the carriage?","options":["The sender","The receiver","The carrier","The insurer"],"correct":1,"exp":"'Carriage forward': the receiver (consignee) pays the carriage. 'Carriage paid': the sender (consignor) pays.\n📍 Book M6 p.2"},{"q":"Under the 12-day rule for international coach tours, a single driver who drives between 22:00 and 06:00 must:","options":["Take a break every 3 hours","Take no breaks at all","Stop driving at midnight","Drive only on motorways"],"correct":0,"exp":"Under the 12-day rule, at night you need multi-manning or, with a single driver, a break every 3 hours instead of every 4 h 30.\n📍 Book M11 p.4"},{"q":"Which of these is a duty of EMPLOYEES under the Safety, Health and Welfare at Work Act 2005?","options":["Report hazards and defects","Write the safety statement","Pay for their protective equipment","Carry out the risk assessment"],"correct":0,"exp":"Employees must take care of their own safety and that of others, use protective equipment, not work under the influence of alcohol or drugs, report hazards and defects and attend training. The safety statement and the risk assessment are the employer's job.\n📍 Book M4"},{"q":"What does a double continuous yellow line along the kerb mean?","options":["No parking at any time","No parking during the hours shown","Loading only","Parking for taxis only"],"correct":0,"exp":"Double continuous line: no parking 24 hours a day. Single line: no parking during the hours shown on the sign.\n📍 Book M22 p.3"},{"q":"A coach hire costs €1,800 and the organiser expects to sell 45 tickets on a 53-seat coach. What should each ticket cost to cover the hire?","options":["€34","€40","€45","€50"],"correct":1,"exp":"Price per passenger = total price ÷ tickets expected to be sold = 1,800 ÷ 45 = €40. Dividing by the 53 seats only works if the coach is full.\n📍 Book M14 p.15"},{"q":"Net profit before tax is €45,000 and capital employed is €300,000. What is the return on capital employed (ROCE)?","options":["6.7%","12.5%","15%","20%"],"correct":2,"exp":"ROCE = net profit before tax × 100 ÷ capital employed = 45,000 × 100 ÷ 300,000 = 15%.\n📍 Book M5 p.10"},{"q":"From what age must a professional driver renewing a C or D licence provide a medical report?","options":["40","45","55","65"],"correct":1,"exp":"From age 45 a self-declaration is not enough: a medical check with form D4 is needed; from 65, renewal is every year.\n📍 Book M21 p.6"},{"q":"A coach trip lasts two days and includes a hotel night, sold at one inclusive price. Under package travel law it is:","options":["A package","An excursion","A regular service","A day trip"],"correct":0,"exp":"It is a 'package' if at least 2 elements are combined (transport, accommodation or another significant tourist service) at an inclusive price, for more than 24 h or including a night.\n📍 Book M30 p.10"},{"q":"A driver using analogue charts changes vehicle during the day. What must he do?","options":["Note its registration, time and km on the chart","Nothing: just start a fresh chart for it","Note only the new vehicle's registration","Note the new vehicle's fuel and oil level"],"correct":0,"exp":"The details of the second vehicle (registration, time of the change and odometer reading) are written on the chart already in use.\n📍 Book M12"},{"q":"By what date must a self-employed operator file and pay income tax each year (pay and file)?","options":["31 March","30 June","31 October","31 December"],"correct":2,"exp":"The self-employed file their return and pay every year by 31 October (pay and file), with Class S PRSI.\n📍 Book M9"},{"q":"Who should carry out vehicle safety inspections?","options":["Technically competent staff","Any driver on the fleet","The transport manager only","An RSA inspector only"],"correct":0,"exp":"They are carried out by technically competent staff, in-house or from a contracted workshop; they should not be asked to repair while inspecting.\n📍 Book M13 p.5"},{"q":"Why are there passport checks on journeys between Ireland and France?","options":["Ireland is not in Schengen","France is not in the EU","Because of Brexit only","Because of the Green Card"],"correct":0,"exp":"Ireland is not in Schengen (because of the Common Travel Area with the UK): there are passport checks when leaving and returning.\n📍 Book M32 p.4"},{"q":"How long do the other countries have to give their views on an application for an international regular coach service?","options":["1 month","2 months","4 months","6 months"],"correct":1,"exp":"The countries consulted have 2 months to give their views; the authority decides within 4 months and, if it cannot, the European Commission decides within 6.\n📍 Book M10 p.19"}]},"02":{"title":"Topic 2 - Business and Company Law","questions":[{"q":"In contract law the term 'consideration' means:","options":["Each party must behave fairly to the other","The parties must take legal advice before entering into the contract","A 14-day period following the signing of a contract","A right or benefit accruing to each party from the contract"],"correct":3,"exp":"'Consideration' is one of the 4 essential elements of a valid contract (offer, acceptance, consideration and intention to create legal relations). It means each party must give or receive something of value in return for what the other party promises."},{"q":"Which of the following statements relating to a public limited company are correct? 1. Minimum of two directors. 2. Not necessary to appoint a company secretary. 3. All PLCs must have accounts externally audited. 4. Nominal share capital not less than €25,000. 5. Cannot begin business until a Trading Certificate is issued.","options":["2 and 3 only","1 and 4 only","1, 3 and 5 only","2, 3 and 4 only"],"correct":2,"exp":"A PLC needs at least 2 directors, must have its accounts externally audited, and cannot trade until the CRO issues its Trading Certificate. Statement 2 is false (it does need a Company Secretary)."},{"q":"Which of the following items of information must a limited company display on all its business letters?","options":["Registered office address","Authorised share capital","Company Secretary's name","Managing director's name"],"correct":0,"exp":"The law requires the legal name, registration number and registered office address to appear on all business stationery."},{"q":"Which items must be submitted to the Companies Registration Office when forming a limited company? 1. Statement of compliance 2. Statement of capital 3. Name of accountants 4. Memorandum of association 5. Articles of association 6. Corporation Tax registration.","options":["1, 2, 4 and 5 only","2, 3 and 5 only","1, 4 and 6 only","3, 4, 5 and 6 only"],"correct":0,"exp":"What is filed: the statement of compliance, the initial capital, the Memorandum and the Articles. The accountants' names and the Corporation Tax registration are not part of incorporation."},{"q":"When satisfied that the requirements of the Companies Act 2014 have been met, the Companies Registration Office will issue a new company with:","options":["A memorandum of association","A certificate of incorporation","A prospectus","The articles of association"],"correct":1,"exp":"The Certificate of Incorporation confirms that the company legally exists: it is its 'birth certificate'."},{"q":"Which statements concerning private limited companies are correct? 1. Trading name ends with PLC. 2. Must be at least one director. 3. May invite public to buy shares. 4. May invite public to invest in debentures. 5. Trading name ends with Limited.","options":["2 and 4","2 and 5","1 and 3","1, 3 and 4"],"correct":1,"exp":"A private Ltd needs only 1 director and its name ends in 'Limited'. It cannot offer shares or debentures to the public."},{"q":"In the event of a members voluntary winding up of a limited company, the directors must file with the Companies Registration Office a declaration of:","options":["Total debt","Bankruptcy","Solvency","Insolvency"],"correct":2,"exp":"It is a VOLUNTARY liquidation because the company can pay its debts: the directors sign a Declaration of Solvency."},{"q":"An operator advertises a vehicle at €8500 ono. Offers are received between €8000 and €8800. Legally, the operator:","options":["Must accept first offer of €8500","Can accept or reject any offer","Must accept first over €8500","Must accept highest offer"],"correct":1,"exp":"An advertisement is an 'invitation to treat', not a binding offer: the seller is free to accept or reject any offer."},{"q":"For a valid contract to exist, which of the following factors must be present?","options":["Verbal offer and written acceptance","Written offer and written acceptance","Written offer, acceptance, consideration","Offer, acceptance and consideration"],"correct":3,"exp":"The 3 essential elements are offer, acceptance and consideration. The contract does not have to be in writing."},{"q":"Under the Companies Act 2014, a private limited company:","options":["Cannot offer shares or debentures to the public","May offer shares but not debentures to the public","May offer debentures but not shares to the public","May offer both shares and debentures to the public"],"correct":0,"exp":"A private Ltd is prohibited from offering either shares or debentures to the public for money."},{"q":"A partnership which is created to give members the benefit of limited liability must have:","options":["One general and one limited partner","One general partner only","One limited partner only","Two general and two limited partners"],"correct":0,"exp":"A limited partnership needs at least one general partner (manages the business and is liable with personal assets) and one limited partner (only invests)."},{"q":"The most common remedy for a breach of contract is:","options":["Damages","An injunction","Imprisonment","A fine"],"correct":0,"exp":"The usual civil remedy for breach of contract is 'damages' (financial compensation)."},{"q":"When creating a limited company a statement confirming that shareholders have limited liability can be found in the company's:","options":["Certificate of Incorporation","Memorandum of Association","Statement of Capital","Articles of Association"],"correct":3,"exp":"The Articles of Association state that the members' liability is limited to what they invested."},{"q":"A company's articles of association must contain details of which of the following? 1. Authorised share capital 2. Rules governing appointment of directors 3. Company registration number 4. Rights of shareholders at general meetings 5. Names of founding members.","options":["1 only","2 and 3","2 and 4 only","1, 3 and 5"],"correct":2,"exp":"The Articles set out how directors are appointed and the members' voting rights at meetings."},{"q":"Which position is required by a public limited company but is optional for a private limited company?","options":["Chief Executive Officer","Company Secretary","Company Director","Chairman of the board"],"correct":1,"exp":"A PLC always needs a Company Secretary; in a small Ltd the rules can be more flexible."},{"q":"For how many years does the Companies Act require a limited company to maintain copies of their accounting records?","options":["3 years","5 years","6 years","10 years"],"correct":2,"exp":"The Companies Act 2014 requires accounting records to be kept for 6 years."},{"q":"If directors deliberately set out to defraud creditors, they could face terms of imprisonment of up to 10 years. This criminal offence is known as:","options":["Insider trading","Reckless trading","Fraudulent trading","Breach of contract"],"correct":2,"exp":"'Fraudulent trading' means running the business with the deliberate intention of defrauding creditors."},{"q":"When distributing money raised by the disposal of assets during a liquidation, which of the following has the highest priority for payment?","options":["Unsecured debts","Liquidator's fees and expenses","Preferential debts (wages)","Fixed-Charge (secured) creditors"],"correct":3,"exp":"Order of priority: 1st secured (fixed-charge) creditors, 2nd liquidator's costs, 3rd preferential debts (wages), 4th floating charge, 5th unsecured creditors."},{"q":"What is the main difference in the internal structure between a Sole Trader and a Limited Company?","options":["Sole traders must file accounts with the CRO","Sole traders have unlimited liability for business debts","Sole traders pay Corporation Tax","Sole traders must have a Memorandum of Association"],"correct":1,"exp":"A sole trader is liable for debts with all personal assets (unlimited liability); in a Ltd the members only risk what they invested."},{"q":"At what point does a contract acceptance sent by post become legally complete?","options":["When the letter is received by the offeror","When the letter is read","On posting the letter","24 hours after posting"],"correct":2,"exp":"The 'postal rule': the contract is formed when the letter is posted, not when it is received."},{"q":"Which group of people do not have full contractual capacity under Irish law?","options":["People under 18","Company directors","Shareholders","Sole traders"],"correct":0,"exp":"People under 18 do not have full contractual capacity: their contracts are generally voidable."},{"q":"What is the key rule regarding dividend payments for ordinary and preference shares?","options":["Preference shareholders are paid before ordinary ones","Ordinary and preference shareholders are paid equally","Ordinary shareholders are paid before preference ones","Preference shareholders never receive a dividend"],"correct":0,"exp":"Preference shares are paid first; ordinary shareholders are only paid if there is profit left afterwards."},{"q":"A Designated Activity Company (DAC) must:","options":["Trade only within its designated activities","Have at least 149 members","Have a name ending in PLC","Offer its shares to the general public"],"correct":0,"exp":"A DAC keeps a limited objects clause, unlike an ordinary Ltd (which has unlimited capacity)."},{"q":"When an external auditor examines a company's accounts, who is their primary duty towards?","options":["The directors","The company secretary","The Companies Registration Office","The shareholders"],"correct":3,"exp":"The auditor's main duty is to the shareholders, to protect them against possible irregularities by the directors."},{"q":"What is the fundamental difference between a debenture holder and a shareholder?","options":["Debenture holders get interest and have no vote","Debenture holders own the company and vote","Shareholders get fixed interest, not dividends","Debenture holders get dividends and a vote"],"correct":0,"exp":"A debenture holder is a creditor (has lent money to the company), receives fixed interest and has no vote."},{"q":"If a shareholder cannot attend a general meeting, how can they legally pass their voting rights to someone else?","options":["By calling the company secretary","By appointing a proxy","By selling their shares","By emailing the director"],"correct":1,"exp":"They can appoint a 'proxy' (representative) by a formal form to vote on their behalf."},{"q":"Which type of company is legally obliged to hold an Annual General Meeting (AGM) each year?","options":["A public limited company","A private limited company","A partnership","A sole trader"],"correct":0,"exp":"PLCs must hold an AGM every year; many small Ltds can be exempt if all members agree."},{"q":"At what stage is an offer no longer possible to withdraw?","options":["After 24 hours","After the offeree has accepted it","Once it is written down","Before the offeree reads it"],"correct":1,"exp":"An offer can be freely withdrawn before acceptance; once accepted, a binding contract exists."}]},"03":{"title":"Topic 3 - Industrial Relations","questions":[{"q":"The WRC has the power to hear cases connected with which of the following workplace issues? 1. Employees' rights to time off work to carry out trade union duties 2. Alleged discrimination on the basis of sexual orientation 3. PAYE contributions 4. Failure to report an accident to the HSA 5. Equal pay complaints","options":["1 and 4 only","2 and 3 only","1, 2 and 5 only","3, 4 and 5 only"],"correct":2,"exp":"The WRC deals with trade union leave, discrimination and equal pay; not PAYE or unreported accidents (those are for Revenue and the HSA)."},{"q":"Under the general Working Time Regulations as they apply to non-driving employees of a transport company, which of the following statements are correct? 1. Employees are entitled to a minimum period of 13 hours uninterrupted rest each day 2. The working week should not exceed an average of 48 hours over the agreed reference period 3. All employees, irrespective of occupation, are entitled to free eyesight checks 4. Employees may not work for more than 6 continuous hours before a break is taken 5. A weekly rest of not less than 45 consecutive hours must be taken","options":["1 and 3 only","2 and 4 only","2, 4 and 5 only","1, 3 and 5 only"],"correct":1,"exp":"An average maximum of 48 hours a week and a break after 6 hours in a row. The general daily rest is 11 hours (not 13), and free eye tests apply only to screen work."},{"q":"Jack Smith is 48 and has been employed by the Ace Transport Company for 7½ years. What is Jack's minimum period of notice from the company?","options":["4 weeks","7 weeks","7½ weeks","10 weeks"],"correct":0,"exp":"With 5 to 10 years of continuous service, the legal minimum notice is 4 weeks."},{"q":"Which of the following items must be included in the written statement of the terms of employment given to employees? 1. Job title 2. Starting date 3. Pension provisions 4. Place of work 5. Detailed job description","options":["1, 2, 3 and 4 only","3, 4 and 5 only","2, 3, 4 and 5 only","All items"],"correct":0,"exp":"Job title, start date, place of work and pension terms. A detailed job description is not required."},{"q":"Which of the following is legally entitled to picket at the premises of an employer other than their own?","options":["Any member of the main trade union representing workers at that place of work","A trade union member from a different works in the same town","A trade union official accompanying employees from that workplace","An official from ICTU"],"correct":2,"exp":"It is only lawful when done by a trade union official accompanying workers from the workplace concerned."},{"q":"An employee who is pregnant is:","options":["Entitled to reasonable time off with pay to receive ante-natal care once she has completed 2 years' service","Not entitled to any time off for ante-natal care","Entitled to reasonable time off without pay to receive ante-natal care, irrespective of length of service","Entitled to reasonable time off with pay to receive ante-natal care, irrespective of length of service"],"correct":3,"exp":"Entitled to PAID time off straight away, with no length of service required."},{"q":"A driver has been employed by the Ace Transport company for 15 years. Their contract of employment states that all periods of notice will be the minimum laid down by law. The driver wishes to leave to take up another job. How much notice must they give as a minimum?","options":["None","One week","Twelve weeks","Fifteen weeks"],"correct":1,"exp":"The minimum notice an EMPLOYEE must give when resigning is always 1 week, after the first 13 weeks, whatever the length of service."},{"q":"Jack Smith has worked for Bloggs Limited for ten years. Bloggs Limited is then bought by Lax Transport plc. With regard to the legal provisions concerning continuous employment, Jack's service will be calculated from when:","options":["Lax Transport took control of Bloggs Limited","Bloggs Limited was officially removed from the Register of Companies","Lax Transport issued him with a new contract of employment","He started work for Bloggs Limited"],"correct":3,"exp":"A transfer of undertaking does not reset length of service: it counts from when the employee originally started."},{"q":"Changes to an employee's terms and conditions of employment must be confirmed in writing by the employer no later than:","options":["By the date the changes take effect","1 month before the changes take effect","Within 3 months of the changes","Within 4 months of the changes"],"correct":0,"exp":"At the latest, on the day the change takes effect."},{"q":"Which of the following statements relating to Statutory Sick Pay in Ireland are correct? 1. Statutory sick pay is currently payable for a maximum of 5 days per calendar year. 2. An employee must have at least 13 weeks' continuous service with the employer to qualify. 3. Statutory sick pay is not payable for the first 3 working days of illness. 4. Statutory sick pay is payable at 70% of the employee's normal daily pay, subject to a daily maximum limit.","options":["2 and 4 only","1, 2 and 4 only","2, 3 and 4 only","1 and 3 only"],"correct":1,"exp":"SSP covers up to 5 days a year, requires 13 weeks of service and pays 70% with a daily cap. Statement 3 does not apply to SSP."},{"q":"A pregnant employee who has been employed by the same company for six months is entitled to: 1. Maternity benefit irrespective of the length of service 2. Take maternity leave for up to a maximum of 42 weeks 3. Share their maternity leave with their partner 4. Shared parental leave for up to a maximum of 26 weeks","options":["2 and 4 only","1 and 3 only","2, and 3 only","1, 3, 4 only"],"correct":2,"exp":"Up to 42 weeks of leave, and she can share part of it with her partner. Maternity Benefit does require PRSI contributions."},{"q":"When was the Workplace Relations Commission (WRC) established as an independent, statutory body?","options":["1st January 2002","1st October 2015","1st August 2019","1st January 2024"],"correct":1,"exp":"The WRC (Workplace Relations Commission) began operating on 1 October 2015, under the Workplace Relations Act 2015. It replaced several earlier bodies and now hears employment complaints at first instance."},{"q":"Which organisation serves as the primary forum for the adjudication of industrial disputes and appeals from WRC Adjudication Officer decisions?","options":["The Workplace Relations Commission","The Labour Court","The Employment Appeals Tribunal","The Supreme Court"],"correct":1,"exp":"The Labour Court is the court of appeal."},{"q":"Within how many days must an employer notify a new employee of their core terms of employment via the 'Day 5 Statement'?","options":["Within 5 days","Within 14 days","Within 1 month","Within 3 months"],"correct":0,"exp":"Since 2019, the employer must give 5 core terms in writing within the first 5 days: the names of the parties, the employer's address, the expected duration if temporary, pay, and normal hours. The remaining terms within one month."},{"q":"What is the statutory deadline for an employer to provide the full written statement of terms of employment to a new employee?","options":["Within 5 days","Within 14 days","Within 1 month","Within 6 months"],"correct":2,"exp":"The remaining terms within the first month."},{"q":"What information must every itemized statement of wages (payslip) explicitly show alongside deductions?","options":["The gross wages payable to the employee","The employer's net profit margin for the year","The employee's home address and tax band","The company's annual turnover and profit"],"correct":0,"exp":"The payslip must show gross pay and every deduction (tax, PRSI and so on), so the employee can check what is deducted and why."},{"q":"Under Irish employment legislation, how many weeks of standard statutory maternity leave are qualifying employees entitled to?","options":["16 weeks","24 weeks","26 weeks","42 weeks"],"correct":2,"exp":"26 weeks basic (the total with additional leave reaches 42)."},{"q":"Are employees entitled to paid time off for ante-natal care medical appointments regardless of their length of service?","options":["Yes, regardless of length of service","No, 12 months' service is needed first","Only if the Minister approves in writing","No, ante-natal care is always unpaid"],"correct":0,"exp":"This right applies straight away, with no length of service required."},{"q":"How many weeks of statutory Parent's Leave are available to each relevant parent within the first two years of a child's life (or adoption placement)?","options":["2 weeks","5 weeks","9 weeks","26 weeks"],"correct":2,"exp":"Parent's Leave: 9 weeks for each parent, to be used in the child's first 2 years (or after adoption). Do not confuse with Parental Leave: 26 weeks unpaid until the child is 12."},{"q":"What is the minimum continuous service requirement for an employee to be eligible to apply for unpaid Carer's Leave?","options":["6 months","12 months","2 years","5 years"],"correct":1,"exp":"To take Carer's Leave (unpaid leave to care for someone who needs full-time care) you need 12 months' continuous service with the employer."},{"q":"How many days of paid domestic violence leave is an employee legally entitled to take in any 12-month period?","options":["1 day","3 days","5 days","10 days"],"correct":2,"exp":"Domestic violence leave: 5 paid days in any 12-month period, with no length of service required. Introduced in 2023."},{"q":"What is the minimum continuous service required for an employee to qualify for statutory redundancy payments upon dismissal due to redundancy?","options":["6 months","1 year","2 years","5 years"],"correct":2,"exp":"To receive statutory redundancy pay you need at least 2 years (104 weeks) of continuous service. Formula: (2 weeks × full years + 1 week) × weekly pay, capped at €600 a week."},{"q":"For how many days per calendar year is Statutory Sick Pay (SSP) established under current Irish regulations (following the 2025 pause)?","options":["3 days","5 days","7 days","10 days"],"correct":1,"exp":"Statutory Sick Pay: 5 days a year paid by the employer. It was due to rise to 7 in 2025, but this was postponed, so it is still 5."},{"q":"What percentage of normal daily earnings is paid under Statutory Sick Pay (SSP), subject to a daily cap?","options":["50%","60%","70%","100%"],"correct":2,"exp":"SSP: the employer pays 70% of normal daily pay, up to a maximum of €110 a day. To remember it: 5 days, 70%, €110."},{"q":"What is the maximum daily monetary cap applicable to Statutory Sick Pay (SSP) payments?","options":["€50 per day","€80 per day","€110 per day","€150 per day"],"correct":2,"exp":"SSP: capped at €110 a day (70% of normal pay, never more than €110). To remember it: 5 days, 70%, €110."},{"q":"What is the statutory minimum notice period required for an employee who has continuous service between 2 years and 5 years?","options":["1 week","2 weeks","4 weeks","6 weeks"],"correct":1,"exp":"Employer's minimum notice by length of service: under 13 weeks, none; 13 weeks to 2 years, 1 week; 2 to 5 years, 2 weeks; 5 to 10, 4; 10 to 15, 6; over 15 years, 8 weeks.\n📍 Book M3 p.14"},{"q":"How much notice must an employee give to their employer if they choose to resign after completing at least one month of service (unless a contract states longer)?","options":["24 hours","3 days","1 week","2 weeks"],"correct":2,"exp":"An employee who leaves only has to give 1 week's notice (legal minimum), unless the contract asks for more. The employer's notice, on the other hand, grows with length of service (from 1 to 8 weeks)."},{"q":"At what employment size threshold must companies include a statement regarding employee involvement in their annual report?","options":["More than 50 employees","More than 100 employees","More than 250 employees","More than 500 employees"],"correct":2,"exp":"Companies with more than 250 employees must explain in their annual report how they inform and involve their workers (employee involvement)."},{"q":"What is the National Minimum Wage hourly rate for experienced adult workers aged 20 and over (as of 1 January 2026)?","options":["€12.74","€13.50","€14.15","€15.00"],"correct":2,"exp":"National minimum wage from 1 January 2026: €14.15 an hour for adult workers aged 20 or over. Workers under 20 are paid a percentage of that rate."},{"q":"How many specific grounds of discrimination are prohibited under Ireland's Employment Equality Acts 1998-2015?","options":["5 grounds","7 grounds","9 grounds","12 grounds"],"correct":2,"exp":"9 grounds: gender, civil status, family status, sexual orientation, religion, age, disability, race and membership of the Traveller community."},{"q":"What age bracket defines the eligibility criteria for automatic enrolment into the 'My Future Fund' state retirement savings system introduced in January 2026?","options":["Aged 18 to 65","Aged 21 to 65","Aged 23 to 60","Aged 25 to 66"],"correct":2,"exp":"The automatic pension scheme 'My Future Fund' (January 2026) covers workers aged 23 to 60 who earn more than €20,000 a year and are not already in a workplace pension scheme."},{"q":"What is the minimum annual earnings threshold required for an employee to be automatically enrolled in the new auto-enrolment pension system?","options":["€10,000 per year","€15,000 per year","€20,000 per year","€30,000 per year"],"correct":2,"exp":"Workers are enrolled automatically in the pension scheme when they earn more than €20,000 a year (and are aged 23 to 60)."},{"q":"Under the auto-enrolment structure, for every €3 contributed by the employee, how much does the employer contribute?","options":["€1","€2","€3","€7"],"correct":2,"exp":"Auto-enrolment: for every €3 from the worker, the employer adds €3 and the State adds €1. At the start it is 1.5% of salary from the worker and another 1.5% from the employer."},{"q":"What is the maximum number of working hours allowed in an average working week under working time regulations, calculated over a reference period?","options":["40 hours","48 hours","50 hours","60 hours"],"correct":1,"exp":"A maximum of 48 hours a week on AVERAGE, calculated over a reference period (normally 4 months). Some weeks can be longer as long as the average does not exceed 48."},{"q":"What mandatory rest break must be provided to a worker scheduled for a shift lasting 6 hours or more?","options":["15 minutes","20 minutes","30 minutes","60 minutes"],"correct":2,"exp":"General law: a 15-minute break after 4 hours 30 of work, and 30 minutes after 6 hours (which can include the first). Drivers under Regulation 561/2006 also have their own break rules."},{"q":"How many consecutive hours of daily rest is each worker entitled to within every 24-hour period?","options":["8 consecutive hours","11 consecutive hours","12 consecutive hours","24 consecutive hours"],"correct":1,"exp":"Daily rest: 11 consecutive hours in every 24-hour period. There is also a weekly rest of 24 consecutive hours."},{"q":"How many statutory public holidays are employees in Ireland generally entitled to receive?","options":["7 public holidays","9 public holidays","10 public holidays","12 public holidays"],"correct":2,"exp":"Ireland has 10 public holidays a year (the February one, St Brigid's Day, was added in 2023)."},{"q":"What foundational law, supported by WRC codes of practice, establishes the framework for workplace disciplinary and grievance procedures?","options":["The Industrial Relations Act 1990","The Workplace Relations Act 2015","The Unfair Dismissals Act 1977","The Payment of Wages Act 1991"],"correct":0,"exp":"The Industrial Relations Act 1990 is the basis for disciplinary and grievance procedures. The WRC publishes codes of practice that develop it."},{"q":"Who is an employee legally entitled to be accompanied by during a formal internal disciplinary meeting?","options":["A colleague or trade union official","Only a practising barrister or solicitor","A local Garda inspector of their choice","An Adjudication Officer from the WRC"],"correct":0,"exp":"A work colleague or a trade union representative."},{"q":"What is the general continuous service requirement for an employee to bring an ordinary claim of unfair dismissal to the WRC?","options":["1 month","6 months","1 year","2 years"],"correct":2,"exp":"To claim unfair dismissal you normally need 1 year of continuous service. There are exceptions with no service requirement, such as dismissal for joining a trade union or for pregnancy."},{"q":"What term describes a form of dismissal where the employer's conduct forces the employee to resign?","options":["Summary dismissal","Constructive dismissal","Wrongful redundancy","Industrial lockout"],"correct":1,"exp":"Constructive dismissal: the employee resigns because the employer's conduct leaves no other option (for example, cutting pay without agreement). The law treats it as a dismissal."},{"q":"Within how many days must an employer provide a written statement of reasons for dismissal after receiving a valid request from a qualifying employee?","options":["7 days","14 days","21 days","30 days"],"correct":1,"exp":"If the dismissed employee asks, the employer must give the reasons for the dismissal in writing within 14 days."},{"q":"Which of the following is recognized as one of the five fair statutory reasons for dismissing an employee?","options":["Joining an independent trade union","Capability or qualifications of the employee","Taking maternity leave","Asserting statutory employment rights"],"correct":1,"exp":"Fair grounds for dismissal: the employee's capability, competence or qualifications; conduct; redundancy; a legal prohibition (for example, losing the driving licence); or some other substantial reason."},{"q":"Dismissal of an employee on what grounds is automatically deemed 'unfair' by the WRC, regardless of length of service?","options":["Incompetence after training","Redundancy through a fair selection process","Trade union membership and activities","Retirement at age 65 with objective justification"],"correct":2,"exp":"Dismissing someone for joining a trade union or for trade union activity is automatically unfair, whatever their length of service. The same applies to dismissal for pregnancy."},{"q":"What is the standard statutory time limit within which a complaint of unfair dismissal must be received by the WRC from the date of dismissal?","options":["3 months","6 months","12 months","2 years"],"correct":1,"exp":"An unfair dismissal complaint must reach the WRC within 6 months of the dismissal. This can be extended to 12 months if there is reasonable cause."},{"q":"Under what circumstances can the normal 6-month time limit for submitting a WRC complaint be extended up to 12 months?","options":["If reasonable cause prevented earlier referral","If the employer agrees to it in writing","Automatically for all trade union members","If the claim is worth more than €10,000"],"correct":0,"exp":"If there was a reasonable cause for not claiming in time."},{"q":"What is the maximum financial compensation an Adjudication Officer can award in an unfair dismissal case where the employee incurred financial loss?","options":["26 weeks' remuneration","52 weeks' remuneration","104 weeks' remuneration","Unlimited financial damages"],"correct":2,"exp":"Where there was financial loss, compensation can reach 104 weeks' pay (2 years). Where there was no loss, the maximum is 4 weeks."},{"q":"What is the maximum compensation limit if an unfairly dismissed employee incurred *no* financial loss?","options":["1 week's remuneration","4 weeks' remuneration","10 weeks' remuneration","No compensation can be awarded"],"correct":1,"exp":"With no financial loss, the maximum is 4 weeks' pay. With financial loss, up to 104 weeks."},{"q":"What is the minimum threshold of proposed redundancies over a 30-day period that triggers collective redundancy rules in an establishment of 50 to 99 employees?","options":["3 or more redundancies","5 or more redundancies","10 or more redundancies","30 or more redundancies"],"correct":2,"exp":"Collective redundancy within 30 days: workplace of 21 to 49 employees, 5 or more redundancies; 50 to 99, 10 or more; 100 to 299, 10%; 300 or more, 30 or more."},{"q":"For how many minimum days must an employer engage in an information and consultation process with employee representatives during collective redundancies?","options":["14 days","21 days","30 days","60 days"],"correct":2,"exp":"In a collective redundancy, the employer must inform and consult the employees' representatives at least 30 days before the first dismissal."},{"q":"To which government minister must an employer formally notify proposed collective redundancies?","options":["Enterprise, Tourism and Employment","Transport, Tourism and Sport","Social Protection and Employment","Finance and Public Expenditure"],"correct":0,"exp":"Collective redundancies must be notified in writing to the Minister for Enterprise, Tourism and Employment at least 30 days before the first dismissal."},{"q":"What protection does a temporary replacement worker have if hired to cover an employee on maternity leave?","options":["Fair dismissal only if told in writing at the start","Permanent status automatically after six months","Cannot be dismissed in any circumstances at all","Full redundancy rights from the very first day"],"correct":0,"exp":"They can only be dismissed if they were told in writing at the start that the job was temporary."},{"q":"What legal status does industrial action have if it is lawfully organized by a trade union following a proper ballot?","options":["It is classed as a 'wildcat strike' and unprotected","It is regarded as 'protected' under the Unfair Dismissals Acts","It is automatically prohibited by the WRC","It converts employee contracts into fixed-term agreements"],"correct":1,"exp":"It is 'protected' action: strikers cannot be dismissed for taking part."},{"q":"Who pays the State Maternity Benefit during the 26 weeks of statutory maternity leave (assuming PRSI conditions are met)?","options":["The employer directly via payroll","The Department of Social Protection","The Workplace Relations Commission","The Labour Court"],"correct":1,"exp":"During the 26 weeks of maternity leave the employer does not have to pay. Maternity Benefit is paid by the Department of Social Protection if the mother has the required PRSI contributions."},{"q":"What is the legal definition of 'night work' under Irish working time regulations?","options":["Work done between 8:00 PM and 4:00 AM","Work done between midnight and 7:00 AM","Any shift exceeding 10 hours in length","Work performed on weekends and public holidays"],"correct":1,"exp":"Under general law, 'night work' is work between midnight and 07:00. Under the working time rules for drivers, night time for passenger transport is 01:00 to 05:00."},{"q":"What key requirement governs employment agencies regarding charging job-seekers fees?","options":["They cannot charge job-seekers any fee","They may charge a €50 registration fee","They may deduct 5% of the first month's pay","They may charge fees for executive jobs only"],"correct":0,"exp":"They cannot charge the candidate for finding them a job."},{"q":"Which category of workers is explicitly excluded from coverage under the National Minimum Wage legislation?","options":["Close relatives of a sole trader employer","Part-time and temporary retail assistants","Foreign nationals on work permits","Seasonal agricultural workers"],"correct":0,"exp":"Close relatives, where the employer is self-employed."},{"q":"What principle does the Protection of Employees (Temporary Agency Work) Act 2012 guarantee for temporary agency workers compared to direct hires?","options":["Equal treatment on pay, working time and rest","A guaranteed permanent contract after 3 months","Exemption from tax on all agency earnings","Priority over internal candidates for promotion"],"correct":0,"exp":"Equal treatment in pay, working hours and breaks."},{"q":"What is the maximum duration generally permitted for successive fixed-term contracts before objective justification is required to prevent abuse?","options":["1 year","2 years","4 years","5 years"],"correct":2,"exp":"After 4 years of successive fixed-term contracts, the worker is entitled to a contract of indefinite duration, unless there is an objective justification."},{"q":"Under the Work Life Balance and Miscellaneous Provisions Act 2023, what must an employee complete before an approved flexible or remote working arrangement can actually start?","options":["6 months' continuous employment","At least 1 year of service","A WRC-approved training course","A formal interview with the directors"],"correct":0,"exp":"To request flexible or remote working you must have worked 6 months in a row for that employer before the new arrangement starts."},{"q":"What is the role of WRC Adjudication Officers when handling complaints referred to them?","options":["Hold a hearing and issue a written decision","Act as private mediators to agree a deal","Prosecute employers in the District Court","Inspect safety equipment on site"],"correct":0,"exp":"They hold a hearing and issue a written decision or recommendation."}]},"04":{"title":"Topic 4 - Health and Safety","questions":[{"q":"When was the current general framework of health and safety legislation in Ireland introduced via the Safety, Health and Welfare at Work Act?","options":["1996","2005","2014","2020"],"correct":1,"exp":"The current framework law dates from 2005 (it replaced the 1989 Act)."},{"q":"How many General Principles of Prevention form the central thrust of the Safety, Health and Welfare at Work Act 2005?","options":["5","7","9","12"],"correct":2,"exp":"There are 9 principles (avoid risks, assess the risks that cannot be avoided, combat them at source, and so on)."},{"q":"According to the general principles of prevention, what type of protective measures should be given priority over individual measures?","options":["Cost-effective measures","Temporary administrative measures","Collective protective measures","Emergency backup measures"],"correct":2,"exp":"The hierarchy of prevention puts COLLECTIVE measures before individual ones (such as PPE)."},{"q":"What key qualifying phrase recurs throughout the 2005 Act regarding an employer's duty to ensure health and safety?","options":["So far as is reasonably practicable","As cheaply and quickly as possible","Without any exception or delay at all","Subject to approval by the trade union"],"correct":0,"exp":"The employer must act 'so far as is reasonably practicable', not in an absolute and unlimited way."},{"q":"What is the maximum number of employees an enterprise may have for the employer to use a Code of Practice as an alternative to a written safety statement?","options":["1","3","5","10"],"correct":1,"exp":"Businesses with up to 3 employees can use a simplified code of practice instead of a full safety statement."},{"q":"Which of the following is a statutory right of a safety representative under the 2005 Act?","options":["Accompany an HSA inspector on an inspection","Change company work schedules alone","Impose fines on non-compliant colleagues","Hire and fire internal safety staff"],"correct":0,"exp":"They can accompany the HSA inspector during an inspection."},{"q":"If a Health and Safety Inspector serves an Improvement Plan on an employer, what is the maximum time allowed for the employer to respond with remedial measures?","options":["14 days","One month","Three months","Six months"],"correct":1,"exp":"The maximum time to respond to an Improvement Plan is 1 month."},{"q":"What is the legal distinction regarding an employer's duty of care under Irish health and safety law?","options":["Protect employees and others affected by the work","Protect full-time permanent staff only","Protect employees but not visiting contractors","Protect public roads outside the depot only"],"correct":0,"exp":"The duty of care extends to anyone affected by the company's activity, not only its staff."},{"q":"Which state body is explicitly responsible for the enforcement of workplace health and safety legislation in Ireland?","options":["Road Safety Authority (RSA)","Health and Safety Authority (HSA)","Workplace Relations Commission (WRC)","Environmental Protection Agency (EPA)"],"correct":1,"exp":"The HSA is the State body that enforces workplace safety law."},{"q":"Within how many days must a non-fatal accident at work be reported if it disables the worker?","options":["1 day","3 days","10 days","30 days"],"correct":2,"exp":"A non-fatal accident that incapacitates the worker must be reported within 10 days."},{"q":"To which entities must a fatal workplace accident be reported immediately?","options":["The Revenue Commissioners and local council","The Gardaí and the Health and Safety Authority","The Department of Transport only","The Coroners Court and trade union representatives"],"correct":1,"exp":"A fatal accident is reported immediately to the Gardaí and the HSA."},{"q":"What is the minimum period of work incapacity required for a non-fatal workplace accident to become officially reportable?","options":["More than 1 consecutive day excluding the day of the accident","More than 3 consecutive days excluding the day of the accident","Exactly 5 consecutive days including the day of the accident","More than 7 consecutive days"],"correct":1,"exp":"It must incapacitate the worker for more than 3 consecutive days (not counting the day of the accident) to be reportable."},{"q":"What is the maximum fine a court can impose on an employer for serious health and safety breaches prosecuted on indictment?","options":["€100,000","€1 million","€3 million","€5 million"],"correct":2,"exp":"The legal maximum fine for serious offences prosecuted on indictment is €3 million."},{"q":"At what continuous noise exposure action value must an employer provide personal hearing protectors and ensure they are worn?","options":["80 dB(A)","85 dB(A)","90 dB(A)","100 dB(A)"],"correct":1,"exp":"From 85 dB(A) the employer must provide hearing protection and make sure it is used."},{"q":"How frequently must vehicle tail lifts or lifting equipment used to lift personnel undergo a thorough statutory examination?","options":["Every 3 months","Every 6 months","Annually","Every 2 years"],"correct":1,"exp":"When used to lift PEOPLE, the required inspection is every 6 months."},{"q":"How frequently must standard lifting equipment (like standard forklifts not carrying personnel) undergo a thorough examination and report?","options":["Every 3 months","Every 6 months","Annually","Every 3 years"],"correct":2,"exp":"Standard lifting equipment for loads (no people) is inspected every year."},{"q":"According to standard manual handling guidance tables for women, what is the maximum recommended weight limit at knuckle height close to the body?","options":["7 kg","10 kg","16 kg","25 kg"],"correct":2,"exp":"Recommended limit at knuckle height, close to the body, for women: 16 kg."},{"q":"According to standard manual handling guidance tables for men, what is the maximum recommended weight limit at knuckle height close to the body?","options":["15 kg","20 kg","25 kg","30 kg"],"correct":2,"exp":"Manual handling tables: at knuckle height and close to the body, 25 kg for men and 16 kg for women. If the load is further from the body or higher, the limit goes down."},{"q":"What is the first foundational step when carrying out any structured risk assessment?","options":["Record the findings in writing","Identify potential hazards","Appoint an external auditor","Notify the HSA inspectors"],"correct":1,"exp":"First the hazards are identified; only then is the risk assessed and documented."},{"q":"What is the legal definition of a 'hazard' in health and safety terminology?","options":["Anything with the potential to cause harm","The probability that an accident will occur","The financial cost of a workplace injury","An unexpected delay in a delivery schedule"],"correct":0,"exp":"'Hazard' = anything that can cause harm."},{"q":"What does 'risk' mean in the context of workplace safety assessments?","options":["The chance that someone will be harmed","The weight of materials being handled","The insurance premium the company pays","The penalty issued by the District Court"],"correct":0,"exp":"'Risk' = the likelihood that the harm will actually happen."},{"q":"What enforcement notice can an HSA Inspector issue to demand the immediate cessation of a work activity involving risk of serious personal injury?","options":["Improvement Plan","Improvement Notice","Prohibition Notice","Advisory Warning Notice"],"correct":2,"exp":"A Prohibition Notice is used for serious and imminent risk; an Improvement Notice gives a minimum of 14 days."},{"q":"What is the minimum ambient air temperature required by workplace regulations for sedentary office work environments?","options":["15.0 °C","17.5 °C","20.0 °C","21.5 °C"],"correct":1,"exp":"Minimum temperature for sedentary office work: 17.5°C."},{"q":"Where do Personal Protective Equipment (PPE) requirements rank in terms of hazard control methods?","options":["The last line of defence","The first and preferred control","An optional recommendation","A substitute for a safety statement"],"correct":0,"exp":"PPE is always the last resort, never the first, in the hierarchy of risk control."},{"q":"Which of the following regulatory areas specifically governs screen equipment in office administration, while excluding vehicle cab screens?","options":["Chemical Agents Regulations","Display Screen Equipment Regulations","Pressure Systems Regulations","Explosive Atmospheres Regulations"],"correct":1,"exp":"The Display Screen Equipment Regulations cover office screens, not vehicle cab displays."},{"q":"Who carries primary responsibility for preparing and revising the company's safety statement?","options":["The Safety Representative","The Employer","The HSA Inspector","External trade union officials"],"correct":1,"exp":"The employer is responsible for writing and reviewing the safety statement."},{"q":"How frequently must an employer review and bring the safety statement to the attention of employees?","options":["At least weekly","Every six months","At least annually, or when amended","Only after a fatal accident occurs"],"correct":2,"exp":"It must be reviewed at least once a year, or whenever it changes."},{"q":"What are the legal responsibilities of employees under the Safety, Health and Welfare at Work Act 2005?","options":["Employees have no legal duties; safety is exclusively management's role","Take reasonable care for their own safety and cooperate with the employer","Fund all necessary PPE and medical checkups out of pocket","Conduct independent HSA prosecutions in the District Court"],"correct":1,"exp":"Employees must take reasonable care of their own safety and cooperate with the employer."},{"q":"What type of creditor or notice is issued when an inspector requires an employer to remedy a legislative contravention within a specified period (not less than 14 days)?","options":["Improvement Notice","Prohibition Notice","Statutory Liquidation Demand","Summary Indictment Warrant"],"correct":0,"exp":"An Improvement Notice gives a minimum of 14 days to correct the breach."},{"q":"Under the General Application Regulations, what specific document must employers maintain and consult regarding workplace chemical hazards?","options":["Safety Data Sheets from suppliers","Commercial invoices and packing lists","Annual corporation tax returns","Tachograph calibration certificates"],"correct":0,"exp":"The supplier's Safety Data Sheets (SDS) must be kept and consulted."},{"q":"Which hazard is recognised as a major risk factor in bus and coach depots and yards?","options":["Moving vehicles and pedestrians mixing","Changes in atmospheric pressure","Maritime navigation hazards","Airport runway clearances"],"correct":0,"exp":"Interaction between heavy vehicles and pedestrians is a major risk in yards and loading depots."},{"q":"What control measure is strongly recommended in transport depots to minimize vehicle-pedestrian conflicts?","options":["Allowing unrestricted random foot traffic across parking bays","Implementing designated walkways and one-way traffic management systems","Removing all exterior yard lighting to save electricity","Banning high-visibility vests entirely"],"correct":1,"exp":"Marked pedestrian walkways and one-way traffic are recommended."},{"q":"What is the primary objective of establishing a Safety Committee within a larger enterprise?","options":["Study accident data and develop safe systems","Negotiate executive salaries and bonuses","Agree contract prices with the clients","Take over the legal powers of the HSA"],"correct":0,"exp":"The safety committee reviews audits, studies accidents and develops safe systems of work."},{"q":"Are occupational illnesses, mental health impairments, or diseases reportable under standard workplace accident reporting rules?","options":["No, they are not reportable under those rules","Yes, they must be reported within 24 hours","Yes, but only if they last over 30 days","Only if a doctor certifies them as serious"],"correct":0,"exp":"Occupational diseases are not reportable under the standard accident criteria."},{"q":"What specialized medical check must an employer make available to workers exposed to noise levels exceeding upper exposure action values?","options":["A hearing check by a registered doctor","An eye examination by an optician","A lung function test by a nurse","A spinal check by a physiotherapist"],"correct":0,"exp":"Hearing checks under the responsibility of a registered medical practitioner."},{"q":"Which of the following is considered a primary duty of an employer regarding workplace welfare facilities?","options":["Washing facilities, toilets and changing rooms","Luxury company cars for every member of staff","Private gym memberships outside work hours","Free catered gourmet lunches every day"],"correct":0,"exp":"The employer must provide suitable toilets, showers and changing rooms."},{"q":"When must an employer review an existing risk assessment?","options":["Regularly, and after any serious accident or change","Only once every ten years","Never, once the safety statement is printed","Only when the shareholders ask in writing"],"correct":0,"exp":"It must be reviewed continuously, especially after a serious accident or an operational change."},{"q":"What are the requirements for emergency exits in workplaces under safety regulations?","options":["They must be securely locked from the outside to prevent theft","They must be kept unblocked, unlocked, and open outwards","They must be camouflaged for security purposes","They only need to be accessible during daytime shifts"],"correct":1,"exp":"Emergency exits must be kept clear, not locked, and must open outwards."},{"q":"Under the Safety, Health and Welfare at Work Act, what right does a safety representative have following an accident or dangerous occurrence?","options":["Inspect the scene without disturbing evidence","Start a criminal prosecution of the employer","Seize the company's bank accounts","Suspend the company director immediately"],"correct":0,"exp":"They can inspect the scene straight away, without disturbing evidence, before the inspector arrives."},{"q":"What must an employer do if a chemical hazard in the workplace cannot be entirely eliminated?","options":["Prevent exposure, or reduce and control it","Ignore it unless the workers complain","Raise the temperature to evaporate it","Rely on verbal warnings to the staff"],"correct":0,"exp":"They must prevent exposure where possible, or reduce and control it adequately."},{"q":"What is the legal status of summary safety offences prosecuted by the HSA in the District Court?","options":["Less serious offences carrying fines","They carry automatic life sentences","Only the European Court can start them","They bypass judicial review entirely"],"correct":0,"exp":"They are minor offences, dealt with by fines or summary penalties."},{"q":"Who is legally authorized to initiate a prosecution on indictment for major health and safety offences in Ireland?","options":["The Director of Public Prosecutions","Any employee on their own initiative","The local authority's town clerk","The company's insurance broker"],"correct":0,"exp":"The DPP (Director of Public Prosecutions), or someone on their behalf, brings a prosecution on indictment."},{"q":"What is a key requirement for employers regarding the communication of the safety statement to workers?","options":["In a form and language staff can understand","Written in Latin and kept in a safe","Shown only to staff who are retiring","Kept confidential from the employees"],"correct":0,"exp":"It must be communicated in a form, manner and language that can reasonably be understood."},{"q":"What training and time-off rights must an employer grant to a designated safety representative?","options":["Reasonable paid time off for training and duties","No time off; training on unpaid weekends","Permanent release from all normal duties","Unpaid leave, if the company can afford it"],"correct":0,"exp":"Reasonable paid time off to train and to carry out their duties."},{"q":"Which of the following is an example of technical control for airborne noise reduction?","options":["Shields, enclosures and sound-absorbent covers","Higher engine speed limits on all vehicles","Removing insulation from the building","Cutting rest breaks to shorten exposure"],"correct":0,"exp":"Screens, enclosures and sound-absorbing linings."},{"q":"What duty does an employer have regarding persons outside their direct employment (such as visitors or contractors)?","options":["Make sure they are not exposed to risks","None; visitors enter at their own risk","Employ them on permanent contracts","Give them shares in the company"],"correct":0,"exp":"It must be operated so that other people are not exposed to risks."},{"q":"What must an employer provide free of charge to employees when workplace risks cannot be otherwise eliminated?","options":["Personal protective equipment","Personal commercial vehicles","Housing near the depot","Private health insurance"],"correct":0,"exp":"PPE and its maintenance must be provided free of charge."},{"q":"What is a primary legal power of an HSA Inspector upon entering a workplace premises?","options":["Order areas left undisturbed and question people","Seize personal property unrelated to work","Run the company's payroll accounts","Change the directors' voting rights"],"correct":0,"exp":"They can order that an area is left undisturbed, remove items and interview people."},{"q":"Why must risk assessments always be formally recorded and documented?","options":["To show a diligent approach and meet the law","To create paperwork with no real purpose","To meet Revenue's tax deduction quotas","To publish trade secrets for competitors"],"correct":0,"exp":"To meet legal requirements and show due diligence in managing risks."}]},"05":{"title":"Topic 5 - Financial Management","questions":[{"q":"What is the primary motive for commercial business enterprises?","options":["To employ drivers","To make profits","To collect VAT","To issue debentures"],"correct":1,"exp":"The main motive of a commercial business is to make a profit: without profit it cannot reinvest, pay its owners or keep going."},{"q":"How is capital defined in financial management?","options":["Money invested to enable the business to run","Total annual turnover of the business","Net profit after corporation tax","Market value of the company vehicles"],"correct":0,"exp":"Money invested to make the business run."},{"q":"Which of the following are classified as fixed assets?","options":["Buildings, plant and company vehicles","Fuel stocks and spare parts in the stores","Cash in the bank and money owed by debtors","Bank overdrafts and trade creditors"],"correct":0,"exp":"Fixed assets: what the business keeps and uses for years, such as buildings, machinery and vehicles. Fuel, spare parts, cash and debtors are current assets."},{"q":"What distinguishes current assets from fixed assets?","options":["Current assets are used in day-to-day trading and fluctuate","Current assets are always financed by share capital","Fixed assets are never depreciated","Fixed assets include trade debtors and bank deposits"],"correct":0,"exp":"Current assets change every day with normal trading (cash, debtors, stock). Fixed assets stay in the business for years (vehicles, buildings)."},{"q":"How are long-term liabilities defined?","options":["Debts due after the end of the financial year","Supplier debts due within 30 days","Provisions for quarterly VAT payments","Drivers' wages unpaid at the week's end"],"correct":0,"exp":"They continue beyond the end of the financial year, e.g. a bank mortgage."},{"q":"What is the definition of debtors in business accounts?","options":["People or businesses who owe money to the company","Suppliers who have delivered goods on credit","Shareholders who have unpaid share capital","Financial institutions holding bank loans"],"correct":0,"exp":"Debtors are customers who owe you money. Creditors are those you owe money to."},{"q":"What does a trading account calculate?","options":["Gross profit: turnover minus direct costs","Net profit after all overheads","Total capital employed in fixed assets","Cash flow movements for the month"],"correct":0,"exp":"The GROSS profit: turnover minus the direct cost of sales."},{"q":"Where is the gross profit transferred to calculate net profit?","options":["The balance sheet","The profit and loss account","The cash budget","The revenue reserve fund"],"correct":1,"exp":"Gross profit comes from the trading account and is carried to the profit and loss account. There the overheads are deducted to give the net profit."},{"q":"What is a balance sheet?","options":["Assets, liabilities and capital on a given date","Turnover over a 12-month period","A forecast of cash receipts and payments","A calculation of vehicle running costs"],"correct":0,"exp":"A snapshot of assets, liabilities and capital at a given moment."},{"q":"How is liquidity defined in financial management?","options":["How quickly current assets can pay debts","Market value of freehold property","Percentage return on capital employed","Ratio of share capital to long-term loans"],"correct":0,"exp":"Money in current assets, quickly available to pay debts."},{"q":"Which of the following is a major source of long-term funds?","options":["Bank overdraft","Trade creditors","Share capital","Unpaid taxation due"],"correct":2,"exp":"Long-term funds: share capital, long-term loans, debentures and retained profits. A bank overdraft is short-term finance."},{"q":"What is a debenture?","options":["A long-term loan at a fixed rate of interest","A short-term loan repayable in 30 days","An ordinary share with voting rights","A temporary bank overdraft facility"],"correct":0,"exp":"A long-term loan at a fixed rate of interest, normally secured on assets."},{"q":"What is a 'revenue reserve' in financial management?","options":["Profits kept and reinvested in the business","Money raised by issuing new shares","A government grant for green vehicles","A short-term cash deposit account"],"correct":0,"exp":"Accumulated profits reinvested in the business."},{"q":"Which of the following is considered a short-term source of funds?","options":["Debentures","Ordinary shares","Bank overdrafts","Freehold property mortgages"],"correct":2,"exp":"A bank overdraft is short-term finance: it is for day-to-day needs and the bank can call it in at any time."},{"q":"Do hire vehicles form part of the fixed assets of a transport business?","options":["Yes, all vehicles operated must be listed as fixed assets","No, hire vehicles do not form part of the fixed assets","Only if the hire period exceeds 5 years","Yes, if they are used for international transport"],"correct":1,"exp":"No, they are not part of the business's own fixed assets."},{"q":"Which of the following expenses is classified as a direct cost (cost of sales) in a transport trading account?","options":["Directors' remuneration","Office heating and lighting","Drivers' wages","Audit and accountancy fees"],"correct":2,"exp":"Direct cost (cost of sales): the cost linked to the service you sell, such as drivers' wages, fuel or tyres. Advertising or the office are indirect costs (overheads)."},{"q":"Which of the following is an example of an indirect cost (overhead) in a profit and loss account?","options":["Vehicle fuel and lubricants","Vehicle excise duty and operator licenses","Advertising and website costs","Vehicle maintenance and repairs"],"correct":2,"exp":"Overheads (indirect costs): those that do not depend on each journey, such as advertising, the website or office rent. They go in the profit and loss account."},{"q":"What is a primary limitation of trading and profit and loss accounts?","options":["The figures are historical and may come too late","They are confidential and never seen by banks","They include future cash flow forecasts","They do not record turnover accurately"],"correct":0,"exp":"The information is historical and can arrive late."},{"q":"Under the Companies Act 2014 in Ireland, what is the turnover threshold for a small company to qualify for audit exemption?","options":["Not exceeding €5 million","Not exceeding €10 million","Not exceeding €15 million","Not exceeding €20 million"],"correct":2,"exp":"Under the Companies Act 2014, a small company can be exempt from audit if it stays within certain limits. The turnover limit is €15 million."},{"q":"How is Working Capital calculated?","options":["Fixed Assets minus Current Liabilities","Current Assets less Current Liabilities","Total Assets plus Long-term Liabilities","Current Assets plus Stock"],"correct":1,"exp":"Working capital = current assets − current liabilities. It is the money available for day-to-day running."},{"q":"What is the formula for the Current Ratio (Working Capital Ratio)?","options":["Current Assets divided by Current Liabilities","Current Liabilities divided by Current Assets","Fixed Assets divided by Working Capital","Net Profit divided by Turnover"],"correct":0,"exp":"Current ratio = current assets ÷ current liabilities. The ideal is 2:1, that is, twice as much in current assets as in short-term debts."},{"q":"What is considered an ideal benchmark for a healthy Current Ratio?","options":["0.5:1","1:1","2:1","5:1"],"correct":2,"exp":"A current ratio of 2:1 is considered healthy: €2 of current assets for every €1 of short-term debt. The ideal acid test is 1:1."},{"q":"How is the Acid Test Ratio (Quick Assets Ratio) calculated?","options":["Current assets less stock, divided by current liabilities","Current assets divided by current liabilities","Fixed assets less stock, divided by current liabilities","Current assets plus stock, divided by current liabilities"],"correct":0,"exp":"(Current assets − stock) ÷ current liabilities."},{"q":"Why is stock subtracted from current assets when calculating the acid test ratio?","options":["Stock may take time to turn into cash","Stock is classed as a fixed asset","Stock has no real monetary value","Stock belongs to the trade creditors"],"correct":0,"exp":"Because stock can take time to turn into cash."},{"q":"How is Total Capital Employed calculated?","options":["Total assets less current liabilities","Fixed assets plus current assets","Share capital plus reserves only","Current assets less long-term liabilities"],"correct":0,"exp":"Total assets (fixed + current) − current liabilities."},{"q":"What does the Return on Capital Employed (ROCE) measure?","options":["Net profit before tax as a % of capital employed","Gross profit as a percentage of turnover","How fast debtors pay their invoices","Short-term loans as a ratio of overdrafts"],"correct":0,"exp":"Net profit before tax as a % of total capital employed."},{"q":"What is the definition of a budget in financial management?","options":["A financial plan to control spending ahead","A rough estimate of random cash income","A historical record of past losses","An audited balance sheet statement"],"correct":0,"exp":"A financial plan for the future, used to control spending."},{"q":"What is Cash Flow defined as?","options":["The movement of cash into and out of a business","The total annual turnover of invoiced sales","The net profit left after corporation tax","The build-up of trade creditors over a year"],"correct":0,"exp":"The actual movement of cash into and out of the business."},{"q":"What is Debt Factoring?","options":["Selling invoices to a factor for immediate cash","Securing long-term loans against property","A discount for customers who pay in 7 days","A tax rebate scheme for transport firms"],"correct":0,"exp":"Selling invoices to a factoring company for immediate cash and credit control."},{"q":"What is Cash Budgeting?","options":["Forecasting cash receipts and payments","Calculating annual vehicle depreciation","Auditing past profit and loss accounts","Working out corporation tax liability"],"correct":0,"exp":"Forecasting expected cash flows, showing the differences between receipts and payments."},{"q":"What is the primary objective of a stock control system?","options":["Stock available in time at acceptable cost","As much cash tied up in spare parts as possible","No need for vehicle maintenance records","Obsolete parts kept indefinitely"],"correct":0,"exp":"Having stock available at an acceptable time and cost."},{"q":"Who should agree minimum safety levels for stock holdings?","options":["The storekeeper","A senior manager","The external auditor","The junior mechanics"],"correct":1,"exp":"The minimum safety stock should be set by a senior manager, because it means money tied up in the stores and the risk of running out of parts."},{"q":"What is meant by 'lead time' in purchasing and stock control?","options":["Time between ordering parts and receiving them","The working life of a vehicle tyre","The credit period given by fuel suppliers","The time needed to train a new driver"],"correct":0,"exp":"Lead time = the time from ordering a part until it arrives. It tells you when to reorder before you run out of stock."},{"q":"How frequently should a physical stock count of parts and materials be made for effective control?","options":["At least once every year","At least four times a year","Only when an audit is requested by Revenue","Once every month"],"correct":1,"exp":"The book recommends counting stock physically at least 4 times a year and comparing the result with the records."},{"q":"What action should be taken with stock items that are in good condition but moving slowly or becoming obsolete?","options":["Turn them into cash quickly, even as scrap","Store them until market prices rise","Write them off as fixed assets","Add them to the share capital value"],"correct":0,"exp":"Turn them into cash as soon as possible (sell them, or sell them as scrap)."},{"q":"If a company's turnover is €550,000 this year compared to €500,000 last year, what is the percentage increase?","options":["5.0%","9.1%","10.0%","11.0%"],"correct":2,"exp":"% increase = (new − old) × 100 ÷ old = (550,000 − 500,000) × 100 ÷ 500,000 = 10%. Always divide by the old value."},{"q":"Which of the following items would appear as current liabilities on a balance sheet?","options":["Trade creditors, tax due and overdrafts","Freehold property and plant","Share capital and revenue reserves","Long-term bank loans and mortgages"],"correct":0,"exp":"Trade creditors, corporation tax due and the overdraft."},{"q":"Why is a bank overdraft classified as a current liability rather than a long-term liability?","options":["The bank can demand repayment at any time","Overdrafts never incur any interest charges","Overdrafts are only used to buy fixed assets","The amount owed never changes over time"],"correct":0,"exp":"The bank can demand repayment at any time."},{"q":"What does the term 'depreciation' represent in financial accounts?","options":["An unexpected cash injection from shareholders","A provision for the decline in value of an asset over time","The increase in market value of freehold property","The reduction in trade debtors"],"correct":1,"exp":"A provision for the loss in value of an asset over time."},{"q":"Which of the following groups uses trading and profit and loss accounts to judge the wisdom of making loans?","options":["Potential lenders","Drivers and mechanics","Competitors in the transport sector","Vehicle manufacturers"],"correct":0,"exp":"Potential lenders (such as banks) look at the accounts to see whether the business earns enough to repay the loan."},{"q":"What is the financial effect if increased costs for overheads (like rent and rates) are not passed on to customers?","options":["Gross profit will be reduced","Net profit will be reduced","Turnover will automatically increase","Working capital will become zero"],"correct":1,"exp":"Overheads (rent, rates) do not affect gross profit, only net profit. If they rise and are not passed on in the price, net profit falls."},{"q":"What is the definition of total liabilities of a company?","options":["Long-term liabilities less current assets","Long-term and current liabilities combined","Current liabilities less fixed assets","Total assets minus share capital"],"correct":1,"exp":"Long-term liabilities plus current liabilities combined."},{"q":"Who receives annual fixed interest payments from a limited company?","options":["Ordinary shareholders","Preference shareholders","Debenture holders","Trade creditors"],"correct":2,"exp":"Debenture holders lend money to the company and receive fixed interest every year, whether there are profits or not. Shareholders, on the other hand, receive variable dividends."},{"q":"What type of financial document is drawn up to plan intended income and expenditure for the next 12 months?","options":["Balance Sheet","Trading Account","Budget","Capital Account"],"correct":2,"exp":"The budget plans income and spending for the next 12 months. The balance sheet and the trading account, on the other hand, look backwards."},{"q":"When reconciling fuel stocks, what physical check should support the closing stock balance figure?","options":["A check of bank statements","A tank dip","An inspection of vehicle tachographs","A count of spare tyres"],"correct":1,"exp":"Fuel stocks are checked by measuring the tank with a dipstick ('tank dip') and comparing it with the records."},{"q":"What is positive cash flow defined as?","options":["Payments made by a business to its suppliers","Receipts coming into a business from its customers","Invoiced sales that have not yet been paid","Outstanding corporation tax provisions"],"correct":1,"exp":"Positive cash flow = money coming in, mainly payments from customers. Negative cash flow is money going out (payments)."},{"q":"What is the consequence if a company has high profitability on paper but poor cash flow control?","options":["It may be unable to pay its debts when due","It will qualify for government subsidies","Its fixed assets will rise in value","Its working capital ratio will exceed 3:1"],"correct":0,"exp":"It may not pay its debts on time, with the risk of legal action and liquidation."},{"q":"Under what heading on the balance sheet are share capital and revenue reserves displayed?","options":["Current Liabilities","Fixed Assets","\"Financed by\"","Long-term Liabilities"],"correct":2,"exp":"On the balance sheet, share capital and reserves appear under 'Financed by', that is, how the company's assets are financed."},{"q":"What is a key advantage of using a debt factoring service?","options":["Immediate cash and less credit control work","No more vehicle maintenance costs","A higher gross profit margin on contracts","Full exemption from corporation tax"],"correct":0,"exp":"Immediate cash, and it reduces the work of credit control."},{"q":"Why must transport managers monitor budget variances (differences between actual and budgeted figures)?","options":["To spot financial problems early and act","To let drivers work unlimited overtime","To calculate depreciation on furniture","To value the company's freehold property"],"correct":0,"exp":"To spot financial problems early and act in time."}]},"06":{"title":"Topic 6 - Commercial Conduct of the Business","questions":[{"q":"What is the correct chronological sequence of commercial documents in a transport transaction?","options":["Invoice, Order, Quotation, Estimate","Estimate, Quotation, Order, Invoice","Quotation, Estimate, Invoice, Order","Order, Estimate, Quotation, Invoice"],"correct":1,"exp":"First an estimate, then a formal quotation, the customer confirms with an order, and finally the invoice."},{"q":"Which document is typically used to provide a rough or approximate cost for a particular job, often given verbally?","options":["Quotation","Estimate","Pro-forma invoice","Statement of account"],"correct":1,"exp":"An 'estimate' is a guide and is not binding."},{"q":"What does a formal written quotation normally contain?","options":["Service specification, price and terms","Only the total price, without any terms","Bank overdraft details and tax numbers","A request for advance cash payment"],"correct":0,"exp":"It sets out exactly what is being offered and on what terms."},{"q":"When must the existence of exemption or liability limitation clauses be brought to a customer's attention?","options":["After the invoice is paid","Before the contract is formed","Within 14 days of delivery","Only if requested in writing"],"correct":1,"exp":"Before the contract is formed, otherwise they are not binding."},{"q":"When is a pro-forma invoice issued by a transport operator?","options":["To correct an overcharge on a completed job","When the operator wishes to be paid in advance for a job","At the end of the month as a statement of account","When goods are sent carriage forward"],"correct":1,"exp":"When the operator wants to be paid in advance."},{"q":"What does the term 'carriage paid' mean on a transport quotation?","options":["Transport costs are paid by the sender","Transport costs are paid by the receiver","Transport costs are waived by the operator","Payment must be made by bank draft"],"correct":0,"exp":"'Carriage paid' on a quotation: the carriage is paid by the sender (consignor). The opposite is 'carriage forward': paid by the receiver (consignee)."},{"q":"What does the term 'carriage forward' mean?","options":["Charges are paid by the receiver of the goods","Charges are paid in advance by the sender","Delivery is postponed to a later date","Invoicing takes place after 14 days"],"correct":0,"exp":"The carriage is paid by the receiver (consignee)."},{"q":"How is an 'order' defined in commercial transactions?","options":["A customer's request for a product or service","A rough estimate of the cost of a job","A document correcting an invoice error","A monthly summary of the customer's account"],"correct":0,"exp":"A customer's request to be supplied with a specific product or service."},{"q":"What is the tax point rule regarding VAT invoices?","options":["Invoice date, if issued within 14 days of supply","It is always the date on which the order is placed","It is always exactly 30 days after delivery","It is the date that any credit note is issued"],"correct":0,"exp":"If the invoice is issued within 14 days of supply, the invoice date counts as the tax point."},{"q":"Which of the following must be shown on invoices issued by a VAT-registered transport company?","options":["VAT number, VAT rate, VAT amount and tax point","Only the net total and customer's bank details","The driver's name and personal salary details","The company's latest profit and loss account"],"correct":0,"exp":"A VAT invoice must show the operator's VAT number, the VAT rate and amount, and the tax point (the date the tax becomes due)."},{"q":"What is the purpose of a credit note?","options":["To confirm an invoice amount has been reduced","To correct an undercharge on an invoice","To request payment in advance of the work","To arrange a bank overdraft facility"],"correct":0,"exp":"It confirms that an amount has been reduced because of an overcharge."},{"q":"What is a debit note used for?","options":["To correct an undercharge on an invoice","To give a cash discount for prompt payment","To withdraw money via direct debit","To close a bank account"],"correct":0,"exp":"Debit note: corrects an invoice that UNDERcharged (asks for more money). Credit note: corrects an OVERcharge (gives money back)."},{"q":"What information does a statement of account typically summarize?","options":["Opening balance, invoices, payments and closing balance","Vehicle maintenance schedules and fuel use","Corporation tax returns and shareholder dividends","Daily driver working hours and rest periods"],"correct":0,"exp":"Opening balance, payments received, the month's invoices and closing balance."},{"q":"What do the letters 'DR' mean on a statement of account?","options":["Debit: the customer owes money","Direct remittance from the bank","Deferred revenue for next year","Discount received from a supplier"],"correct":0,"exp":"On a statement of account, DR (debit) means the customer owes that money; CR (credit) means the balance is in the customer's favour."},{"q":"How can an operator encourage customers to pay their accounts more promptly?","options":["A small cash discount for prompt settlement","High interest rates charged on debit notes","Issuing pro-forma invoices to every customer","Refusing to issue statements of account"],"correct":0,"exp":"A small discount for paying straight away (cash discount) encourages the customer to pay earlier and improves your cash flow."},{"q":"Why is the use of cash for settling business invoices declining?","options":["Handling time, bank charges and laundering risk","Because counting cash is fast and efficient","Because banks pay high interest on cash","Because cash is illegal in commercial transport"],"correct":0,"exp":"Time spent counting and lodging, high charges and the risk of money laundering."},{"q":"Why are cheques declining rapidly as a payment method?","options":["Cards and credit transfers are quicker and cheaper","Cheques can no longer be cleared by banks","The government has banned cheques completely","Cheques now need a special licence to issue"],"correct":0,"exp":"Cheques are used less and less because cards and transfers are faster, cheaper and safer."},{"q":"When using debit or credit card electronic terminals, when is the business typically credited with the funds?","options":["Exactly 30 days later","The following day at the latest","After the annual audit","Instantly before authorisation"],"correct":1,"exp":"With a debit or credit card, the bank credits the money to the business by the next day at the latest."},{"q":"Which card payment method generally incurs higher commission charges for businesses?","options":["Debit cards","Credit cards","Chip and PIN cards","Store cards"],"correct":1,"exp":"Credit cards charge the business a higher fee than debit cards, because the bank is advancing the money to the customer."},{"q":"What system is used in Ireland for electronic credit transfers across the SEPA zone?","options":["SEPA Credit Transfer, using an IBAN","The National Clearing Cheque System","Merchant Bank Direct Wire transfers","The An Post Money Order Network"],"correct":0,"exp":"SEPA Credit Transfer: euro transfers within the SEPA zone using the IBAN, the international account number."},{"q":"What document is normally sent by a paying organisation to a supplier when paying by credit transfer to detail the invoices being paid?","options":["A debit note","A remittance advice","A bank draft application","A pro-forma invoice"],"correct":1,"exp":"A remittance advice goes with a transfer and states which invoices are being paid, so the supplier knows where to apply the money."},{"q":"What makes a bank draft a secure method of transferring money?","options":["It is prepaid and only the named payee can cash it","Anyone holding the paper slip can collect it","It is backed by merchant bank share capital","It never requires an application form"],"correct":0,"exp":"Paid for in advance; only the named payee can cash it."},{"q":"What are High Street banks also commonly called?","options":["Merchant banks or investment trusts","Clearing banks or joint stock banks","Central reserve banks","Factoring institutions"],"correct":1,"exp":"High Street commercial banks are also called clearing banks (because they clear cheques between themselves) or joint stock banks (because they are companies owned by shareholders)."},{"q":"What is the primary function of merchant banks?","options":["Share issues, takeovers and mergers","Daily cheque books for retail shops","Personal current accounts and overdrafts","Debit card terminals for small traders"],"correct":0,"exp":"Large financial operations: share issues, mergers and acquisitions."},{"q":"What is the main difference between current accounts and deposit accounts?","options":["Current: daily trading, no interest; deposit: earns interest","Current earns high interest; deposit charges flat fees","Deposit accounts give cheque books for suppliers","Current accounts are only offered by merchant banks"],"correct":0,"exp":"Current account = day-to-day use, with charges and no interest; deposit account = interest on surplus funds."},{"q":"What is a 'stale cheque'?","options":["A cheque over 6 months old that will not be paid","A cheque that has bounced for lack of funds","A cheque issued by a company that has closed","A cheque that has been written in pencil"],"correct":0,"exp":"A cheque more than 6 months old, which the bank will no longer pay."},{"q":"How does a standing order operate?","options":["Customer tells the bank to pay fixed sums on set dates","A third party takes varying amounts at will","The bank lends money when the balance runs low","Invoices are sold automatically to a factor"],"correct":0,"exp":"The customer orders fixed payments on fixed dates, and keeps control."},{"q":"Who initiates and controls a direct debit arrangement?","options":["The supplier, using a mandate from the customer","The bank customer alone, for each payment","The manager of the local bank branch","The Revenue Commissioners, by law"],"correct":0,"exp":"A third party with a mandate to collect payment directly."},{"q":"For what common purpose do transport operators frequently favor direct debits?","options":["Paying for bulk deliveries of fuel","Paying annual corporation tax","Paying weekly driver overtime","Issuing credit notes to debtors"],"correct":0,"exp":"Large fuel purchases, charged by the supplier before delivery."},{"q":"What is the fundamental difference between a standing order and a direct debit?","options":["Standing order: fixed sums; direct debit: varying sums","Standing orders are electronic; direct debits need cash","Direct debits can only be used by merchant banks","Standing orders can never be cancelled by the customer"],"correct":0,"exp":"Standing order = fixed amount, the customer is in control; direct debit = a third party collects variable amounts."},{"q":"How do High Street banks typically classify 'small' business loans?","options":["Loans up to €5,000","Loans up to €25,000","Loans up to €100,000","Loans up to €500,000"],"correct":1,"exp":"According to the book, banks consider a business loan of up to €25,000 to be 'small'."},{"q":"What is a key characteristic of a formal business loan once established?","options":["Fixed repayment amounts and dates","Repayment dates can be changed at any time","No interest is charged to transport operators","It turns into an overdraft automatically"],"correct":0,"exp":"Fixed repayments on fixed dates, with a penalty for early repayment."},{"q":"What is a bank overdraft primarily used for by a transport operator?","options":["Short-term, unexpected expenses","Buying freehold depot premises","Issuing long-term debentures","Financing multi-year fleet replacement"],"correct":0,"exp":"An overdraft is for unexpected and short-term costs. Vehicles are bought with a loan, leasing or hire purchase."},{"q":"What are the main disadvantages of using an overdraft for financing?","options":["High interest and fees; repayable on demand","It takes months longer to set up than a loan","It needs a merchant banking licence","Overdraft money cannot be used for wages"],"correct":0,"exp":"High interest and charges, and the bank can demand repayment at any time."},{"q":"What alternative funding methods have developed to bridge gaps left by restrictive bank lending?","options":["Venture capital and peer-to-peer lending","Government-mandated credit notes for SMEs","Compulsory pro-forma invoicing of customers","Freezing deposits held in high street banks"],"correct":0,"exp":"Venture capital and peer-to-peer lending platforms."},{"q":"If a company's customers take too long to pay their bills, what commercial measure can be used to encourage quicker payment?","options":["Offer a cash discount","Offer a trade discount","Issue a credit note","Issue a cash flow budget"],"correct":0,"exp":"Offering a discount for prompt payment speeds up payments. Another option is factoring: selling unpaid invoices to a finance company."},{"q":"What document should a transport company issue when it requires payment in advance for a job?","options":["An advice note","A statement of account","A delivery note","A pro-forma invoice"],"correct":3,"exp":"A pro-forma invoice is sent before the work to be paid in advance. It is not the final invoice."},{"q":"Under 'carriage paid', who pays the transport costs?","options":["The receiver of the goods (consignee)","The sender of the goods (consignor)","The High Street bank","The factoring organisation"],"correct":1,"exp":"'Carriage paid': the carriage is paid by the sender (consignor). With 'carriage forward' it is paid by the receiver (consignee)."},{"q":"Under 'carriage forward', who pays the transport charges?","options":["The receiver of the goods","The sender of the goods","The transport operator","The driver of the vehicle"],"correct":0,"exp":"'Carriage forward': the carriage is paid by the receiver (consignee). With 'carriage paid' it is paid by the sender."},{"q":"What is a debit note used to correct?","options":["An overcharge on an invoice","An undercharge on an invoice","A stale cheque","A direct debit mandate"],"correct":1,"exp":"Debit note = corrects an undercharge. Credit note = corrects an overcharge."},{"q":"What is a credit note used to confirm?","options":["An invoice amount has been reduced","A loan has been approved by a merchant bank","Goods were sent carriage forward","A standing order has been cancelled"],"correct":0,"exp":"That an amount has been reduced because of an overcharge."},{"q":"What is the correct chronological sequence for a credit-based transaction involving an invoice, quotation, order, and estimate?","options":["Invoice, quotation, order, estimate","Estimate, quotation, order, invoice","Quotation, order, invoice, estimate","Order, estimate, invoice, quotation"],"correct":1,"exp":"Logical order: estimate (approximate price) → quotation (formal price) → order (the customer places the order) → invoice (you get paid)."},{"q":"What document would you use to convey a formal price and conditions for a large, complex journey?","options":["An invoice","An order form","A consignment note","A quotation"],"correct":3,"exp":"A quotation gives a firm price with the terms of the work. An estimate is only approximate, and the invoice comes at the end."},{"q":"How can a company settle multiple invoices by paying funds directly into suppliers' bank accounts?","options":["Standing orders","Credit transfers","Direct debits","Letters of credit"],"correct":1,"exp":"With credit transfers, several invoices are paid at once, paying the money straight into each supplier's account."},{"q":"Which element is mandatory on a sales invoice from a VAT-registered transport company?","options":["The tax point date","The customer's home address","The driver's licence number","The bank overdraft limit"],"correct":0,"exp":"The tax point (the date VAT becomes due) is required on every VAT invoice. If the invoice is issued within 14 days of the service, the invoice date is the tax point."},{"q":"What does a closing statement balance indicated as €4,000 (DR) mean?","options":["The customer is owed €4,000 by the operator","The customer currently owes the operator €4,000","The bank account has a positive credit balance","All invoices have been settled in cash"],"correct":1,"exp":"A DR balance is a debit: the customer owes the operator €4,000. If it said CR, it would be in the customer's favour."},{"q":"Which term best describes an approximate costing of a job given to a potential customer?","options":["A quotation","An estimate","An invoice","A statement"],"correct":1,"exp":"Estimate = approximate price, often given verbally. A quotation is the formal, firm price."},{"q":"How is an 'order' accurately described?","options":["A customer's request to be supplied","A detailed costing from the operator","A notice of outstanding debts","A formal bank draft application"],"correct":0,"exp":"A communication from the customer asking to be supplied with certain goods or services."},{"q":"What is a bank draft considered to be in terms of security and reliability?","options":["As good as cash, payable only to the payee","Unreliable, and it can bounce like a cheque","The same as a high-interest commercial loan","Only valid between merchant banks"],"correct":0,"exp":"A bank draft is guaranteed by the bank itself: it is as good as cash and safer, because only the person named on it can cash it."},{"q":"What is the primary function of a remittance advice sent with a credit transfer?","options":["To show which invoices are being paid","To request a cash discount from the supplier","To set up a direct debit mandate","To apply for a small business loan"],"correct":0,"exp":"The remittance advice lists which invoices you are paying with that transfer."}]},"07":{"title":"Topic 7 - Marketing","questions":[{"q":"How is marketing officially defined in business management?","options":["Identifying and satisfying customer needs profitably","Raising prices as high as the market allows","Filing the company's tax returns with Revenue","Planning transport logistics and routing"],"correct":0,"exp":"The management process that identifies, anticipates and satisfies customer needs profitably."},{"q":"What does SWOT stand for in strategic business analysis?","options":["Sales, Workloads, Operations, Tariffs","Strengths, Weaknesses, Opportunities, Threats","Systems, Workers, Orders, Transport","Suppliers, Wealth, Organization, Taxes"],"correct":1,"exp":"Strengths, Weaknesses, Opportunities, Threats."},{"q":"What are the traditional '4 Ps' of the standard marketing mix?","options":["Profit, People, Process, Place","Product, Price, Place, Promotion","Planning, Production, Packaging, Publicity","Performance, Purchasing, Public relations, Pricing"],"correct":1,"exp":"The classic 4 Ps: Product, Price, Place, Promotion. For services, 3 more are added: People, Process and Physical evidence (the 7 Ps)."},{"q":"Which three extra elements are added to create the 'Extended Marketing Mix' (the 7 Ps) for service industries like road transport?","options":["Profit, Productivity, Position","People, Process, Physical evidence","Packaging, Public relations, Partners","Planning, Performance, Portfolios"],"correct":1,"exp":"People, Process, Physical evidence: because it is a service, not a physical product."},{"q":"What does the 'Process' element in the service marketing mix primarily focus on?","options":["Making the service easy for customers to use","The physical weight of the goods carried","The calculation of vehicle depreciation","How the vehicles themselves are manufactured"],"correct":0,"exp":"Being easy to deal with and having a simple path for the customer."},{"q":"What does 'Physical evidence' refer to when marketing a service like road transport?","options":["Visible items such as offices and logos","The weight limits of a bridge on the route","The delivery receipt signed by the consignee","The mechanical condition of the brake pads"],"correct":0,"exp":"Visible, tangible points of contact before buying."},{"q":"What are the sequential stages of the product life cycle?","options":["Development, Growth, Maturity, Saturation, Decline","Introduction, Expansion, Peak, Plateau, Decline","Design, Testing, Launch, Growth, Retirement","Launch, Growth, Profit, Saturation, Loss"],"correct":0,"exp":"Development, Growth, Maturity, Saturation, Decline."},{"q":"During which stage of the product life cycle are development costs high, little income generated, and no profits made?","options":["Growth","Development","Maturity","Saturation"],"correct":1,"exp":"Product life cycle: Development (high costs, no sales), Introduction, Growth, Maturity and Decline. In Development there is no income yet."},{"q":"What happens to sales and profitability during the 'Maturity' stage of a product life cycle?","options":["Sales growth slows and profits start to fall","Sales fall to zero almost immediately","Profits rise fast with no competition","Development costs are incurred for the first time"],"correct":0,"exp":"Sales grow more slowly and profit starts to fall."},{"q":"How is market segmentation defined?","options":["Splitting a market into groups with similar needs","Calculating the total national turnover of a firm","Merging rival transport firms into one group","Splitting company shares among shareholders"],"correct":0,"exp":"Dividing the potential market into sub-markets with similar needs."},{"q":"Which of the following is an example of market segmentation in the passenger transport industry?","options":["An executive airport coach for business travellers","A single fare and timetable for all passengers","Cutting all routes to one standard coach type","Filing the company's corporation tax return"],"correct":0,"exp":"Segmenting means dividing the market into groups with similar needs and offering each one a tailored service, such as an airport transfer for executives. The other options are administrative tasks."},{"q":"What is the primary purpose of conducting marketing research?","options":["To base decisions on facts, not guesswork","To reduce the company's tax bill to zero","To recruit qualified professional drivers","To agree terms with the trade unions"],"correct":0,"exp":"Basing decisions on facts, not assumptions."},{"q":"What is secondary data in marketing research?","options":["Information that already exists somewhere","Information from brand-new postal surveys","Confidential data held only by the Revenue","Unverified rumours heard about competitors"],"correct":0,"exp":"Information that already exists and only needs to be extracted."},{"q":"What are key internal sources of secondary marketing data?","options":["Sales records and sales staff reports","National census reports from the CSO","Studies published by universities","International trade directories"],"correct":0,"exp":"Sales records, trade reports, response to advertising."},{"q":"What is another common term for research using secondary data?","options":["Desk research","Field research","Primary interview analysis","Pilot testing"],"correct":0,"exp":"Research using secondary data (which already exists) is called desk research or a non-reactive survey: it is done from the desk, without asking anyone."},{"q":"When an organisation needs specific new data (e.g., customer reactions to a proposed service), what type of research does it conduct?","options":["Secondary research","Primary research","Historical desk research","Statutory financial auditing"],"correct":1,"exp":"Primary research: collecting new data (surveys, interviews) when the information does not exist yet, such as customers' reaction to a new service."},{"q":"What is a major disadvantage of using postal questionnaires for primary research?","options":["They are extremely expensive compared to personal interviews","Response rates are usually very low, which can introduce response bias","They can only be conducted via telephone","They require real-time GPS tracking"],"correct":1,"exp":"A very low response rate, which creates bias."},{"q":"Why is a 'pilot study' conducted prior to launching a full survey?","options":["To test the questions on a small sample first","To calculate the annual profit and loss account","To train drivers in vehicle maintenance","To register the company with the CRO"],"correct":0,"exp":"Testing the questions and format on a small sample."},{"q":"What is the fundamental role of Public Relations (PR) in business?","options":["Presenting the business favourably to the public","Selling coach hire contracts face to face","Managing tax payments and payroll deductions","Negotiating wage agreements with unions"],"correct":0,"exp":"Presenting the business in the most favourable way possible."},{"q":"What is a cost-effective way for a transport company to publicize a new contract or major vehicle order to trade magazines without paying for advertising?","options":["Sending a professional press release","Launching a national television campaign","Issuing credit notes to debtors","Distributing postal questionnaires"],"correct":0,"exp":"A press release to trade magazines is free publicity: the magazine publishes the story if it is of interest."},{"q":"Why is face-to-face selling primarily reserved for large contracts?","options":["It is costly, so only worth it for big deals","Travelling salesmen are required for shops by law","Selling by phone is prohibited by the WRC","Direct mail always has a 100% conversion rate"],"correct":0,"exp":"It is expensive, only worthwhile for high-value negotiations."},{"q":"What characterizes direct mail as a sales approach?","options":["Material sent to decision-makers; low response rate","High response rate; always read by senior staff","It replaces all digital marketing and websites","It is run only through phone call centres"],"correct":0,"exp":"Written material sent to specific decision-makers, with a low conversion rate."},{"q":"What does SEO stand for in the context of digital marketing for transport operators?","options":["Secure Earnings Operation","Search Engine Optimisation","Standard Economic Outlay","Social Employee Organisation"],"correct":1,"exp":"SEO = Search Engine Optimisation: improving the website so it ranks higher on Google without paying for ads."},{"q":"How can transport operators optimize their online presence for Artificial Intelligence (AI) agentic search?","options":["Structured data, accurate live data, natural language","Removing all text content from the website","Relying only on printed newspaper adverts","Avoiding mobile and voice search optimisation"],"correct":0,"exp":"Structured data (Schema.org), accurate information and natural language."},{"q":"What does a 'service blueprint' identify in modern service-sector marketing?","options":["Front-stage contact and back-stage processes","The architectural plans of a depot building","Vehicle route maps for international trips","How shareholder dividends are paid out"],"correct":0,"exp":"Interactions visible to the customer and internal support processes."},{"q":"What does 'Market share' measure?","options":["The % of the total market a business holds","The total seating capacity of the fleet","The % of share capital owned by directors","Fixed assets as a ratio of current liabilities"],"correct":0,"exp":"Market share = what percentage of the total market, national or regional, your company has."},{"q":"Why is national television advertising generally unsuitable for regional road transport companies?","options":["It is too expensive and poorly targeted on potential business decision-makers","Television broadcasting is illegal for transport operators in Ireland","Television ads cannot display vehicle license plates","It is classified as a non-reactive survey"],"correct":0,"exp":"It is expensive and poorly targeted at business decision-makers."},{"q":"How do trade fairs and exhibitions assist transport businesses?","options":["They give sales leads in specific market segments","They replace the need for an annual audit","They give exemptions from statutory sick pay","They act as debt factoring agencies"],"correct":0,"exp":"Trade fairs and exhibitions bring together potential customers from a specific segment: they are a good source of contacts."},{"q":"What is a key marketing consideration when managing public relations after an environmental incident involving a vehicle?","options":["Show empathy and stress the safety record","Deny that the company owns the vehicle","Raise prices at once to cover legal fees","Say nothing until the investigation is over"],"correct":0,"exp":"Communicating by stressing how exceptional the event was, the safety record, and empathy."},{"q":"What does General Transit Feed Specification (GTFS) data provide for public transport operators?","options":["Timetable and route data for journey-planning apps","Balance sheet audits for the Revenue Commissioners","Calibration records for driver tachographs","Direct debit mandates for fuel purchases"],"correct":0,"exp":"Accurate timetable/route data for third-party map apps."}]},"08":{"title":"Topic 8 - Organisation Charts, KPIs and Work Plans","questions":[{"q":"What type of organisational structure is exemplified by a Police Force, the Armed Forces, the NHS, and the Civil Service?","options":["A flat hierarchy","A matrix organization","A tall hierarchy","A project-based network"],"correct":2,"exp":"Tall hierarchy: many levels of management, like the police, the army or the civil service. A flat hierarchy has few levels."},{"q":"How many layers or levels are in a classic Police Force tall hierarchy model as presented in the text?","options":["5 layers","8 layers","11 layers","15 layers"],"correct":2,"exp":"The book's police example has 11 levels, from Commissioner to Constable: it is the typical model of a tall hierarchy."},{"q":"Who sits at the very top of the 11-layer Police Force hierarchy example?","options":["Chief Superintendent","Commissioner","Deputy Commissioner","Commander"],"correct":1,"exp":"In the police example, the Commissioner is at the top (level 1) and the Constable at the bottom (level 11)."},{"q":"What rank immediately follows the Commissioner in the Police Force hierarchy?","options":["Assistant Commissioner","Deputy Commissioner","Chief Superintendent","Commander"],"correct":1,"exp":"Order in the example: Commissioner (1) → Deputy Commissioner (2) → … → Constable (11)."},{"q":"What rank is at the bottom (level 11) of the Police Force hierarchy?","options":["Sergeant","Inspector","Constable","Chief Inspector"],"correct":2,"exp":"The lowest level (11) in the police example is the Constable; the highest, the Commissioner."},{"q":"Which of the following is considered an advantage of a tall hierarchy?","options":["Excellent vertical communication across all levels","Clear lines of responsibility and close supervision","Low employment costs","Rapid capacity to adapt to market changes"],"correct":1,"exp":"Clear lines of responsibility and close supervision."},{"q":"What is a notable disadvantage of a tall hierarchy?","options":["Poor communication up and down the levels","Wide spans of control for every supervisor","Poor communication between departments","A lack of opportunities for promotion"],"correct":0,"exp":"Poor vertical communication through the levels."},{"q":"Why do some organisations choose to eliminate layers of management to create a 'flat' hierarchy?","options":["Better communication, lower costs, faster response","To increase the number of supervisory levels","To stop managers delegating any authority","To lengthen the chain of command for security"],"correct":0,"exp":"Improving vertical communication, reducing costs and responding better to the customer."},{"q":"What is a primary disadvantage of a flat hierarchy?","options":["Excessive administrative employment costs","Each manager or supervisor handles a large span of control","Too many opportunities for vertical promotion causing confusion","Overly rigid resistance to structural alterations"],"correct":1,"exp":"Each manager has a very wide span of control."},{"q":"What does an organisation chart primarily illustrate?","options":["Roles, status and lines of reporting","Daily fuel use and vehicle mileage","The annual profit and loss figures","Customer satisfaction ratings by route"],"correct":0,"exp":"How staff are organised: role, status, reporting and communication."},{"q":"In a standard hierarchical transport organisation chart, where are management staff and operatives positioned?","options":["Operatives at the top, management at the bottom","Management at the top and operative levels at the bottom","Both are placed on equal horizontal coordinates","Management in the centre with operatives surrounding them in a matrix"],"correct":1,"exp":"In a hierarchical organisation chart, management is at the top and operational staff (drivers, mechanics) at the bottom, joined by the lines of command."},{"q":"How are support staff, such as a Clerical Assistant or Stores Person, typically depicted on a hierarchical organisation chart?","options":["As side branches off their department's manager","As senior directors on the vertical line","At the very top of the whole structure","Separate from every line of reporting"],"correct":0,"exp":"As horizontal branches connected to a specific department."},{"q":"When are matrix organisation structures most commonly utilized?","options":["For the life of a project, e.g. a new depot","For routine day-to-day administration","Only when the company is being wound up","To calculate statutory redundancy pay"],"correct":0,"exp":"The matrix structure is used during a project (a new depot, a new service): each person reports at the same time to their department head and to the project manager."},{"q":"What is a defining characteristic of a matrix structure for an individual worker?","options":["They have a line manager and a project manager","They report to no one and work on their own","They are employed only through an agency","They move to a different employer each week"],"correct":0,"exp":"They have two bosses: a line manager and a project manager."},{"q":"What is an acknowledged disadvantage of a matrix organisation structure?","options":["Line and project managers may clash over staff","There is no teamwork on projects at all","Staff cannot communicate across departments","It creates too many vertical layers of managers"],"correct":0,"exp":"Conflict of interest between the line manager and the project manager over resources."},{"q":"What does the acronym KPI stand for in business management?","options":["Key Personnel Insurance","Kilometres Per Investment","Key Performance Indicator","Known Procedural Incident"],"correct":2,"exp":"KPI = Key Performance Indicator: a key measure of performance, such as cost per km, punctuality or accidents."},{"q":"Why is a KPI on its own generally considered insufficient for an operator?","options":["It means little without targets and regular checks","KPIs are not permitted under Irish company law","KPIs only apply to very large fleets","KPIs change daily without any warning"],"correct":0,"exp":"It does not say much unless targets are set and actual performance is measured."},{"q":"In a transport logistics business, which operational factor typically represents the single largest cost?","options":["Office stationery","Uniform laundering","Fuel","Building insurance"],"correct":2,"exp":"According to the book, fuel is usually the biggest cost of a transport company; that is why consumption is monitored so closely."},{"q":"What technological advancements have enabled transport operators to closely monitor individual driver behaviour and fuel economy?","options":["Computerised fuel records and telematics","Manual paper logbooks filled in weekly","Direct debit mandates from the bank","Postal survey questionnaires to drivers"],"correct":0,"exp":"Computerised fuel records and on-board telematics."},{"q":"Which of the following is listed as a relevant KPI for a logistics operation?","options":["Number of registered shareholders","Weekly costs/profit per vehicle","Authorised share capital total","Number of trade union officials employed"],"correct":1,"exp":"A useful KPI is the weekly cost or profit per vehicle: it lets you compare vehicles and spot problems early."},{"q":"What does a vehicle 'downtime percentage' measure in fleet management KPIs?","options":["The percentage of time vehicles spend running empty","The percentage of time that vehicles are unfit for service","The time drivers spend resting on ferries","The speed limit on regional motorways"],"correct":1,"exp":"The % of time vehicles are not fit for service."},{"q":"What does the acronym SMART stand for in the context of setting work plans and targets?","options":["Systematic, Meaningful, Analytical, Reliable, Timely","Specific, Measurable, Achievable, Relevant, Timed","Structured, Managed, Accountable, Resourceful, Thorough","Standard, Monitored, Active, Realistic, Total"],"correct":1,"exp":"Specific, Measurable, Achievable, Relevant, Timed."},{"q":"What is 'benchmarking' used for by commercial managers?","options":["Comparing performance with similar competitors","Calculating vehicle gross weight limits","Testing the strength of depot shelving","Setting up direct debits with fuel suppliers"],"correct":0,"exp":"Comparing performance against similar competitors."},{"q":"What is a primary objective of designing structured work plans?","options":["Use staff time well with realistic targets","Remove all supervision layers at once","Replace the management accounts entirely","Increase the fleet's fuel consumption"],"correct":0,"exp":"Using staff time cost-effectively, with realistic targets."},{"q":"What saying is frequently cited regarding the necessity of measurement in effective management?","options":["\"Without profit there is no business.\"","\"Without measurement there can be no effective management.\"","\"Tall structures always outperform flat structures.\"","\"Matrix management eliminates all conflict.\""],"correct":1,"exp":"'Without measurement there can be no effective management'."},{"q":"How do 'tall' and 'flat' hierarchical structures differ in their physical representation or 'footprint'?","options":["Tall: narrow, many layers; flat: broad, few layers","Tall: broad, few layers; flat: narrow, many layers","Both have exactly the same pyramid shape","Flat structures are drawn as upside-down triangles"],"correct":0,"exp":"'Tall' = narrow base, many levels; 'flat' = wide base, few levels."},{"q":"What is an advantage commonly associated with a 'flat' hierarchy?","options":["More delegation and better communication","Close supervision of every task at many levels","Unlimited chances of promotion upwards","No span of control problems at all"],"correct":0,"exp":"Delegation is encouraged and vertical communication improves."},{"q":"Which of the following is listed as a disadvantage of a 'flat' hierarchy?","options":["Excessive administrative salary overheads","Motivation of the large group of staff at the bottom can be a problem","Inability to modify corporate structures when markets change","Complete absence of horizontal communication"],"correct":1,"exp":"Motivating the large group of staff at the base can be a problem."},{"q":"In a matrix organisation chart, how are normal lines of reporting versus project communications typically represented?","options":["Vertical: line reporting; horizontal: project team","Horizontal: line managers; vertical: project managers","Diagonal lines show every channel of communication","Circles replace all the straight lines"],"correct":0,"exp":"Vertical = normal reporting; horizontal = project communication."},{"q":"Why are transport organisations overwhelmingly structured hierarchically?","options":["Everyone knows who they report to and manage","The law requires eleven layers of management","To prevent the use of onboard telematics","To remove the need for financial accounts"],"correct":0,"exp":"So that all staff know their place, who to report to and who they are responsible for."},{"q":"If a coach company operates a fleet of 50 coaches, each covering 200,000 km per year (total 10 million km), what financial impact does a small percentage improvement in fuel economy have?","options":["Even 1% saves a large sum, about €48,000 a year","It makes no difference to operating costs","It doubles the vehicle downtime percentage","It increases the maintenance staff needed"],"correct":0,"exp":"A small % improvement can save significant amounts of fuel."},{"q":"Which department or role is typically shown at the top of a standard commercial transport organisation chart?","options":["General Manager or Managing Director","The lead fitter in the workshop","The traffic office supervisor","The stores person and clerk"],"correct":0,"exp":"At the top of the organisation chart is the General Manager or the Managing Director; below them, the head of each department."},{"q":"What does 'span of control' refer to in management structures?","options":["The geographic distance a truck travels per delivery route","How many people are answerable directly to each manager or supervisor","The duration of a project team's existence in a matrix structure","The total number of layers in a tall hierarchy"],"correct":1,"exp":"How many people report directly to each manager."},{"q":"Which of the following is an example of an external or comparative performance evaluation method mentioned in the text?","options":["Benchmarking","Matrix auditing","Pyramid flattening","Tall consolidation"],"correct":0,"exp":"Benchmarking: comparing your results with those of competitors doing similar work."},{"q":"What is a key feature of the 'Smart' criteria in work planning regarding time?","options":["Targets must be open-ended with no deadlines.","Targets must be Timed","Targets must take at least 5 years to complete.","Timelines should be ignored during project phases."],"correct":1,"exp":"SMART objectives: Specific, Measurable, Achievable, Realistic and Timed. 'Timed' means they have a deadline."},{"q":"What organisational problem can arise from having too many layers in a tall hierarchy?","options":["Spans of control become impossibly wide for single supervisors.","Built-in resistance to change and poor vertical communication","Complete elimination of administrative costs","Immediate reduction in staff numbers at the bottom"],"correct":1,"exp":"Built-in resistance to change and poor vertical communication."},{"q":"How do weekly, monthly, and annual reports assist operators using KPIs?","options":["To track progress and spot areas to improve","To replace the statutory annual audit","To adjust driver pay scales automatically","To turn tall structures into flat ones"],"correct":0,"exp":"They let you monitor progress and see which areas need more improvement."},{"q":"Which KPI metric evaluates safety performance in road transport?","options":["Accidents per driver per 100,000 km","Percentage of kilometres run empty","Average office stationery cost per month","Number of direct debit transactions processed"],"correct":0,"exp":"Safety KPI: accidents per driver per 100,000 km. It lets you compare drivers who cover different mileages."},{"q":"What is indicated when a transport company measures the percentage of total kilometres run whilst empty?","options":["Vehicle utilisation efficiency","Total corporation tax liability","Staff sickness rates","Workshop fitter productivity"],"correct":0,"exp":"The percentage of empty km (no passengers or load) measures how well the vehicle is used: the higher it is, the worse."},{"q":"Why are graphical representations or charts often utilized alongside KPI reports?","options":["They are legally mandated by the Workplace Relations Commission.","They are effective ways of showing performance progress over time","They eliminate the need for fuel telematics.","They replace financial management accounts entirely"],"correct":1,"exp":"They are an effective way of showing progress in performance."}]},"09":{"title":"Topic 9 - Business Taxation","questions":[{"q":"What is corporation tax in Ireland?","options":["Tax paid by limited companies on their profits","Tax paid by sole traders on their turnover","A property tax charged on commercial depots","A fixed monthly tax paid by partnerships"],"correct":0,"exp":"Tax paid by limited companies on their annual net profit."},{"q":"Which organisation controls the collection of corporation tax, PAYE, PRSI, and VAT in Ireland?","options":["The Companies Registration Office (CRO)","Revenue Irish Tax and Customs (Revenue)","The Workplace Relations Commission (WRC)","Transport Infrastructure Ireland (TII)"],"correct":1,"exp":"Revenue (Irish Tax and Customs) collects corporation tax, PAYE, PRSI and VAT."},{"q":"Under Section 288 of the Companies Act 2014, what is the maximum initial period that a company's first financial statements can cover?","options":["12 months","18 months","24 months","6 months"],"correct":1,"exp":"A company's first financial statements can cover a maximum of 18 months; after that, each accounting period lasts 12 months."},{"q":"What is the standard rate of Corporation Tax in Ireland for trading income?","options":["12.5%","15%","23%","25%"],"correct":0,"exp":"Corporation tax: 12.5% on profits from normal business activity (trading). Non-trading income pays 25%."},{"q":"What higher rate of Corporation Tax applies to non-trading income, such as rental and investment income?","options":["12.5%","15%","20%","25%"],"correct":3,"exp":"25% for income that does not come from trading (rents, investments); 12.5% for normal trading."},{"q":"Within what timeframe after the end of the company's financial year must Corporation Tax be paid?","options":["3 months","6 months","9 months","12 months"],"correct":2,"exp":"Corporation tax is paid within 9 months of the end of the accounting period (on the 23rd day of the ninth month)."},{"q":"What tax advantage can small and medium transport businesses use when purchasing new energy-efficient vehicles?","options":["A 50% standard depreciation write-off","An Accelerated Capital Allowance of 100%","A complete exemption from vehicle registration tax","A direct cash subsidy from the Department of Transport"],"correct":1,"exp":"Accelerated Capital Allowance: 100% of the price of an energy-efficient vehicle can be deducted in the first year, instead of spreading it over several years."},{"q":"Under 'Real Time Reporting' introduced in January 2019, when must employers report payroll tax deductions (PAYE and PRSI) to Revenue?","options":["On or before the date the pay is made","Quarterly, at the end of each tax period","Once a year, by 31 October each year","Within 14 days of the end of the month"],"correct":0,"exp":"Since 2019 (Real Time Reporting), the company reports the PAYE and PRSI of each payroll to Revenue on or before the day it pays it."},{"q":"What class of PRSI do self-employed individuals pay in Ireland?","options":["Class A","Class J","Class S","Class P"],"correct":2,"exp":"The self-employed pay Class S PRSI. Ordinary employees pay Class A."},{"q":"What is the tax year period for self-employed individuals in Ireland?","options":["1 January to 31 December","6 April to 5 April","1 July to 30 June","1 October to 30 September"],"correct":0,"exp":"For the self-employed, the tax year is the calendar year: 1 January to 31 December."},{"q":"What is the standard annual Pay and File deadline for self-employed individuals filing via Revenue Online Service (ROS)?","options":["30 September","31 October","Mid-November","31 December"],"correct":2,"exp":"Mid-November, for filing via ROS."},{"q":"How long are self-employed individuals and companies legally required to retain tax and accounting records?","options":["At least 3 years","At least 5 years","At least 6 years","At least 10 years"],"correct":2,"exp":"Tax and accounting records must be kept for at least 6 years."},{"q":"What is the primary risk of 'false self-employment' in the road transport sector?","options":["Back-dated PAYE and PRSI, interest and penalties","Loss of the annual vehicle registration tags","Being forced onto annual VAT accounting","Automatic suspension of the operator licence"],"correct":0,"exp":"Revenue can reclassify the workers as employees, with backdated liabilities."},{"q":"How does Revenue treat nightly subsistence expense payments made to coach drivers that comply with published Civil Service Rates?","options":["They are fully taxable as benefit in kind","They incur no tax liability","They must be reported under Class S PRSI","They are deductible only under flat-rate VAT rules"],"correct":1,"exp":"Overnight subsistence allowances paid at the official Civil Service rates are not taxed, because they are not considered salary."},{"q":"What is the standard rate of Value Added Tax (VAT) in Ireland?","options":["9%","13.5%","21%","23%"],"correct":3,"exp":"The standard VAT rate in Ireland is 23%. There are reduced rates (13.5% and 9%) and 0% for some goods."},{"q":"What is the VAT registration threshold for businesses supplying services only in Ireland (as of January 2025)?","options":["€20,000 per year","€37,500 per year","€42,500 per year","€85,000 per year"],"correct":2,"exp":"You must register for VAT if services exceed €42,500 a year (threshold since January 2025). For those selling goods, the threshold is €85,000."},{"q":"What is the VAT registration threshold for businesses supplying goods in Ireland?","options":["€42,500 per year","€65,000 per year","€75,000 per year","€85,000 per year"],"correct":3,"exp":"VAT registration threshold for those selling goods: €85,000 a year. For services it is €42,500."},{"q":"How is the net VAT payable to Revenue calculated under the standard VAT accounting system?","options":["Output VAT minus input VAT","Input VAT minus output VAT","Total turnover multiplied by the flat-rate percentage","Gross profit minus allowable business expenses"],"correct":0,"exp":"VAT payable = output VAT (what you charge on your sales) − input VAT (what you pay on your purchases). If the result is negative, Revenue refunds you."},{"q":"How are transport services directly connected with exports to non-EU countries (e.g., Ireland to Kazakhstan) treated for VAT purposes?","options":["Zero-rated, if documentary evidence is held","Charged at the standard rate of 23%","Exempt, with no input VAT recovery allowed","Subject to local EU import tariffs"],"correct":0,"exp":"Zero rate (0%), with the required documentation."},{"q":"How can an Irish VAT-registered transport operator recover foreign VAT incurred on fuel and tolls in other EU countries?","options":["Electronic claim through the ROS VAT refund portal","Deduct it from the Irish corporation tax return","Send paper receipts to the Department of Transport","Foreign VAT can never be reclaimed"],"correct":0,"exp":"VAT paid in other EU countries (fuel, tolls) is reclaimed with an electronic application through ROS, Revenue's online portal."},{"q":"What barrier-free electronic toll system operates on the M50 motorway around Dublin?","options":["GO-Maut","eFlow","AutoPASS","HGS"],"correct":1,"exp":"eFlow is the barrier-free toll on the M50: cameras read the number plate and you pay online, by phone or with a registered account."},{"q":"Which three EU Member States participate in the joint time-based road-charging system known as the Eurovignette?","options":["Luxembourg, Netherlands and Sweden","Austria, Belgium and Switzerland","Germany, Czechia and Slovakia","France, Spain and Portugal"],"correct":0,"exp":"Luxembourg, the Netherlands and Sweden (with transition timetables for the last two)."},{"q":"What electronic on-board unit is required for heavy vehicles exceeding 3.5 tonnes using Austria's distance-based toll system?","options":["Telepass","GO-Box","AutoPASS tag","HGS sticker"],"correct":1,"exp":"In Austria, vehicles over 3.5 t (also buses and coaches) pay a toll per kilometre with an on-board device called a GO-Box."},{"q":"What is the name of the kilometre-based electronic tolling system introduced in Belgium in 2016?","options":["Belgian Kilometre Charge, run by Viapass","LKW-Maut, collected by Toll Collect","LSVA, collected by the Swiss customs","Eurovignette, sold at border points"],"correct":0,"exp":"Belgian Kilometer Charge, administered by Viapass."},{"q":"What is the official acronym for Switzerland's nationwide distance- and performance-related heavy vehicle fee?","options":["HGS","LSVA","KmToll","OBU"],"correct":1,"exp":"LSVA is the Swiss heavy vehicle charge, calculated according to distance, weight and emissions."},{"q":"What is the maximum fuel allowance that foreign vehicles may bring into Turkey within standard manufacturer-fitted running tanks without incurring customs duties?","options":["200 litres","400 litres","550 litres","1,000 litres"],"correct":2,"exp":"Turkey lets the fuel carried in the vehicle's factory-fitted tanks in without customs duty, up to 550 litres."},{"q":"Under the cash (moneys received) basis of accounting for VAT in Ireland, when does output VAT become payable?","options":["When the customer actually pays","When the sales invoice is issued","At the end of the financial year","When the journey actually starts"],"correct":0,"exp":"When the customer's payment is actually received."},{"q":"What is a key drawback of the cash basis of accounting for VAT in the transport sector?","options":["Costs are paid at once, but VAT recovery is delayed","It bans the use of international fuel cards","It doubles the standard corporation tax rate","It is compulsory for all large transport groups"],"correct":0,"exp":"Large costs are paid immediately, delaying the recovery of input VAT."},{"q":"What scheme is designed to reduce VAT bookkeeping for small businesses by paying Revenue a fixed percentage of gross turnover instead of calculating individual input VAT?","options":["Annual Accounting Scheme","Flat-Rate VAT Scheme","Cash Basis Accounting","Reverse-Charge Mechanism"],"correct":1,"exp":"Flat-Rate VAT Scheme: a simplified system that uses a fixed percentage instead of calculating input VAT invoice by invoice."},{"q":"What is the penalty for failing to pay the M50 barrier-free toll on time?","options":["Immediate confiscation of the operating license","Penalty charges that escalate rapidly","A mandatory 3-month driving ban for the company director","Automatic conversion to a quarterly VAT audit"],"correct":1,"exp":"If the M50 toll is not paid on time, surcharges are added that rise quickly with each notice."},{"q":"What pricing element has been introduced across major European toll systems (such as Germany, Austria, and Switzerland) to increase costs for older diesel vehicles?","options":["Axle-spacing surcharges","CO2 emission class pricing","Weekend driving bans","Mandatory overnight parking fees"],"correct":1,"exp":"Germany, Austria and Switzerland charge more toll to more polluting vehicles: the price depends on the CO2 emissions class."},{"q":"What electronic toll system is utilized in Norway for commercial vehicles exceeding 3.5 tonnes?","options":["Telepass","AutoPASS","HGS","GO-Box"],"correct":1,"exp":"In Norway the electronic toll is called AutoPASS. Vehicles over 3.5 t, buses included, need its tag."},{"q":"What happens if a vehicle passes through Turkish toll points (HGS) without sufficient credit?","options":["A violation that must be paid within a grace period","The vehicle is impounded permanently at the roadside","The debt passes automatically to Irish Revenue","The driver's personal income tax goes up"],"correct":0,"exp":"A toll violation, to be settled within a grace period."},{"q":"What is the daily standard charge for the London Congestion Charge (rising to £18 from January 2026)?","options":["£10","£12.50","£15","£20"],"correct":2,"exp":"The central London congestion charge was £15 a day and rises to £18 from January 2026."},{"q":"What daily charge applies to vehicles not meeting minimum emission standards within London's Ultra Low Emission Zone (ULEZ)?","options":["£10","£12.50","£15","£25"],"correct":1,"exp":"London's Ultra Low Emission Zone (ULEZ) charges non-compliant light vehicles £12.50 a day. Non-compliant heavy vehicles pay considerably more."},{"q":"What is the primary purpose of preliminary tax payments for self-employed individuals in Ireland?","options":["To pay projected income tax for the current year in advance","To cover historical VAT liabilities from previous trading years","To fund local authority road maintenance directly","To secure Class A social insurance benefits"],"correct":0,"exp":"Paying in advance the estimated income tax for the current year."}]},"11b":{"title":"Topic 11 (extra) - Drivers' Hours & Tachographs","questions":[{"q":"Which EU Regulation governs driving times, breaks, and rest periods for professional drivers across Member States?","options":["Regulation (EC) No 1071/2009","Regulation (EC) No 561/2006","Regulation (EU) No 165/2014","Directive 2003/59/EC"],"correct":1,"exp":"Regulation 561/2006 sets driving times, breaks and rests. Regulation 165/2014 regulates the tachograph."},{"q":"Which EU Regulation governs the technical standards, installation, use, and testing of tachographs in road transport?","options":["Regulation (EC) No 561/2006","Regulation (EU) No 165/2014","Directive 2002/15/EC","Regulation (EC) No 1072/2009"],"correct":1,"exp":"Regulation 165/2014 regulates the tachograph: technical standards, installation, use and inspections."},{"q":"What is the standard maximum daily driving limit under EU Regulation 561/2006?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":1,"exp":"Daily driving: 9 hours, extendable to 10 twice a week."},{"q":"How many times in any single fixed week may the daily driving limit be extended to 10 hours?","options":["Once","Twice","Three times","Four times"],"correct":1,"exp":"You can drive 10 hours in a day a maximum of twice a week."},{"q":"What is the maximum permitted cumulative driving time in any single fixed week (00:00 Monday to 24:00 Sunday)?","options":["48 hours","56 hours","60 hours","90 hours"],"correct":1,"exp":"Maximum 56 hours of driving in a fixed week (from 00:00 on Monday to 24:00 on Sunday)."},{"q":"What is the maximum permitted cumulative driving time in any two consecutive fixed weeks?","options":["80 hours","90 hours","100 hours","112 hours"],"correct":1,"exp":"In two consecutive weeks you cannot exceed 90 hours of driving. If you do 56 one week, the next you can only do 34."},{"q":"After driving for 4.5 hours (4 hours and 30 minutes), a driver MUST take an uninterrupted break of at least:","options":["30 minutes","45 minutes","60 minutes","15 minutes"],"correct":1,"exp":"After 4 h 30 of driving, a break of at least 45 minutes (or split into 15 + 30)."},{"q":"If a driver splits their required 45-minute break into two periods, how MUST those periods be taken?","options":["First a 15-minute break, followed later by a 30-minute break","First a 30-minute break, followed later by a 15-minute break","Two equal breaks of 22.5 minutes each","Three 15-minute breaks"],"correct":0,"exp":"A split break must be at least 15 minutes first and then at least 30. The other way round (30 + 15) is not valid."},{"q":"What is the standard regular daily rest period required within every 24-hour period after the end of the previous rest?","options":["11 hours","9 hours","10 hours","12 hours"],"correct":0,"exp":"Normal daily rest: at least 11 consecutive hours in each 24-hour period."},{"q":"If a regular daily rest period is split into two separate parts, how must it be structured and what is the minimum total duration?","options":["First part at least 3 hours, second part at least 9 hours (total 12 hours)","First part at least 2 hours, second part at least 10 hours (total 12 hours)","Two equal parts of 5.5 hours (total 11 hours)","First part at least 4 hours, second part at least 8 hours (total 12 hours)"],"correct":0,"exp":"Split daily rest: first at least 3 hours and then at least 9 hours; 12 hours in total."},{"q":"To what minimum duration may a daily rest period be reduced ('reduced daily rest') without needing compensation?","options":["8 hours","9 hours","9.5 hours","10 hours"],"correct":1,"exp":"The daily rest can be reduced to 9 hours without having to compensate for it (a maximum of 3 times between two weekly rests)."},{"q":"How many times between any two weekly rest periods may a driver take a reduced daily rest period (less than 11 hours, but at least 9 hours)?","options":["Maximum 2 times","Maximum 3 times","Maximum 4 times","Unlimited if approved by the operator"],"correct":1,"exp":"Between two weekly rests, the daily rest can be reduced (to between 9 and 11 hours) a maximum of 3 times."},{"q":"Under multi-manning (double-manning) operations, within what period must each driver take a daily rest period of at least 9 hours?","options":["Within 24 hours","Within 27 hours","Within 30 hours","Within 36 hours"],"correct":2,"exp":"With two drivers, each one must have at least 9 hours of rest within each 30-hour period."},{"q":"What is the minimum duration of a regular weekly rest period?","options":["24 hours","36 hours","45 hours","60 hours"],"correct":2,"exp":"Normal weekly rest: 45 consecutive hours."},{"q":"To what minimum duration can a weekly rest period be reduced ('reduced weekly rest') in any two consecutive weeks?","options":["12 hours","18 hours","24 hours","36 hours"],"correct":2,"exp":"The weekly rest can be reduced to 24 hours. In any two consecutive weeks there must be at least one normal 45 h rest, and the reduction must be made up before the end of the third following week."},{"q":"In any two consecutive weeks, a driver must take at least:","options":["Two regular, or one regular and one reduced, rest","Two reduced weekly rests of 24 hours each","One 45-hour rest in every 14-day period","One 90-hour continuous rest every fortnight"],"correct":0,"exp":"Two regular (45+45) OR one regular + one reduced (45+24)."},{"q":"When must any reduction taken in a weekly rest period (below 45 hours down to 24 hours) be compensated?","options":["En bloc by the end of the third week following","En bloc by the end of the following week","Spread out evenly over the next six months","Never: passenger transport needs no compensation"],"correct":0,"exp":"En bloc before the 3rd following week, attached to another rest of ≥9h."},{"q":"What special concession applies to international coach drivers performing a single international passenger service (the '12-day rule')?","options":["Weekly rest may be put off for up to 12 days","Drivers may drive 15 hours a day without breaks","Daily rest may be reduced to only 6 hours","No tachograph is needed during the 12 days"],"correct":0,"exp":"Weekly rest postponed for up to 12 periods of 24h."},{"q":"Which condition MUST be met to utilise the international passenger 12-day rule concession?","options":["The service must last at least 24 consecutive hours in another EU/non-EU state and the driver took a regular 45h rest prior to the trip","After the trip, the driver must take two regular weekly rests (90h) or one regular + one reduced (69h) with full compensation","The vehicle must be fitted with a digital tachograph (and if driving between 22:00 and 06:00, multi-manned or driving limited to 3h before break)","All of the above"],"correct":3,"exp":"To use the 12-day rule all the conditions on the list must be met (international occasional service, at least 24 h in another country, digital tachograph…)."},{"q":"When a driver accompanies a vehicle carried by ferry or train, how may a regular daily rest period (11h) be interrupted?","options":["Twice at most, 1 hour in total, with a bunk","Up to 4 times, for a total of 2 hours","It can never be interrupted for any reason","Only when ordered by the ship's captain"],"correct":0,"exp":"A maximum of 2 times, not exceeding 1h, with access to a bunk."},{"q":"Under Irish domestic rules (Transport Act 1961/1968) for out-of-scope local passenger services, what is the maximum continuous driving limit before a break?","options":["4.5 hours","5.5 hours","6.0 hours","8.0 hours"],"correct":1,"exp":"Domestic passenger rules: a maximum of 5 h 30 of continuous driving before a 30-minute break."},{"q":"What is the maximum daily driving time under Irish Domestic Regulations for out-of-scope transport?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"Domestic rules: maximum 10 hours of driving a day."},{"q":"What is the maximum length of the working day (spreadover) permitted under Irish Domestic Regulations?","options":["12 hours","14 hours","16 hours","18 hours"],"correct":2,"exp":"Domestic rules: the whole working day (spreadover) cannot exceed 16 hours."},{"q":"Under Irish Domestic Regulations, what is the standard minimum daily rest period?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"Domestic rules: daily rest of 10 hours, reducible to 8 h 30 up to 3 times a week."},{"q":"To what duration may the domestic daily rest period (10 hours) be reduced up to 3 times per week under Domestic Regulations?","options":["7.5 hours","8 hours","8.5 hours","9 hours"],"correct":2,"exp":"Domestic rules: the 10 hours of daily rest can be reduced to 8 h 30 up to 3 times a week."},{"q":"What passenger service operations are legally EXEMPT from EU Regulation 561/2006 (and tachograph requirements)?","options":["Regular passenger services where the route length does NOT exceed 50 km","Vehicles with 9 to 16 passenger seats used exclusively for non-commercial carriage of passengers","Specialised breakdown vehicles operating within a 100 km radius of base","All of the above"],"correct":3,"exp":"All of those on the list are exempt; for example, regular services up to 50 km and non-commercial vehicles with 9 to 16 seats."},{"q":"When a driver performs mixed driving (part under EU rules and part under Irish domestic rules), how must time spent driving under domestic rules be recorded on the EU tachograph?","options":["As Rest / Break","As 'Other Work'","As Period of Availability (POA)","It must not be recorded at all"],"correct":1,"exp":"In mixed driving, time driven under domestic rules is recorded on the tachograph as 'Other Work'."},{"q":"Can time spent driving under Domestic rules be counted as a break or rest period under EU Regulation 561/2006?","options":["No, domestic driving counts as work","Yes, provided it is recorded in a logbook","Yes, if the speed was under 30 km/h","Only on Sundays and public holidays"],"correct":0,"exp":"No, it can never count as an EU break or rest."},{"q":"How long must an operator retain completed tachograph charts, digital driver card download files, and printouts?","options":["12 months; 2 years for working time rules","At least 6 months from the date of use","At least 3 years from the date of use","5 years, the same as the tax records"],"correct":0,"exp":"At least 12 months (2 years if they are for Working Time)."},{"q":"Within how many days must a driver return completed analogue tachograph record sheets to their employer?","options":["Within 7 days","Within 14 days","Within 28 days","Within 42 days"],"correct":3,"exp":"Used analogue charts are returned to the company within 42 days."},{"q":"How often MUST data from a driver's digital tachograph card be downloaded by the operator?","options":["At least every 14 days","At least every 28 days","At least every 56 days","At least every 90 days"],"correct":1,"exp":"The driver card is downloaded at least every 28 days."},{"q":"How often MUST data from the digital tachograph vehicle unit (VU) be downloaded by the operator?","options":["At least every 28 days","At least every 56 days","At least every 90 days","Annually"],"correct":2,"exp":"The vehicle unit (VU) is downloaded at least every 90 days."},{"q":"How many preceding calendar days of tachograph records must a driver carry and be able to produce for inspection at the roadside?","options":["Today plus the previous 28 days","Today plus the previous 7 days","Today plus the previous 14 days","Today plus the previous 56 days"],"correct":0,"exp":"The current day plus the previous 28 calendar days."},{"q":"What information must a driver enter manually on the centre field of an analogue tachograph chart at the BEGINNING of the day?","options":["Name, start place, date, registration, odometer","Employer's tax number and the depot address","Fuel tank level, tyre pressures and oil level","The driver's CPC card number and expiry"],"correct":0,"exp":"Name, place and date, registration number, and starting odometer reading."},{"q":"What information must a driver enter on the centre field of an analogue chart at the END of the working day?","options":["End place, end date and closing odometer","The total revenue collected from fares","The reason for any traffic jams met","The signature of the workshop manager"],"correct":0,"exp":"Place and date of finishing, and final odometer reading."},{"q":"Under EU Regulation 561/2006 (Article 12), what action must a driver take if an unexpected emergency prevents reaching a planned stopping place?","options":["Go only as far as a safe stop; note the reason","Abandon the vehicle immediately where it is","Drive up to 15 hours without recording it","Phone the Minister for a verbal exemption"],"correct":0,"exp":"Depart only as far as necessary and note the reason on arrival."},{"q":"What does EU Regulation 561/2006 prohibit regarding driver pay and bonus schemes?","options":["Pay or bonuses that risk safety or hours breaches","Paying overtime rates for weekend work","Paying fixed monthly salaries to drivers","Giving drivers free uniforms and safety boots"],"correct":0,"exp":"Bonuses that endanger road safety."},{"q":"Within how many days must an operator produce requested tachograph records when formally demanded by Gardaí or RSA examiners?","options":["Within 24 hours","Within 7 days","Within 10 days","Within 28 days"],"correct":2,"exp":"If the Garda or the RSA formally request them, the operator has 10 days to produce the records."},{"q":"What is the maximum statutory fine per offence for serious tachograph or drivers' hours record-keeping breaches in court?","options":["€5,000","€1,000","€2,500","€20,000"],"correct":0,"exp":"A maximum fine of €5,000 per offence. In cases of fraud there can be prison and loss of the operator licence."},{"q":"How often must a digital tachograph system undergo full recalibration and inspection at an approved workshop?","options":["Every 1 year","Every 2 years","Every 3 years","Every 6 years"],"correct":1,"exp":"The digital tachograph is inspected and recalibrated at an approved workshop every 2 years."}]},"11c":{"title":"Topic 11 (extra) - Working Time (WTD)","questions":[{"q":"Which EU Directive regulates working time specifically for mobile workers in road transport activities?","options":["Directive 2003/88/EC","Directive 2002/15/EC","Directive 2006/126/EC","Regulation (EC) No 561/2006"],"correct":1,"exp":"Directive 2002/15/EC regulates the working time of mobile workers in road transport."},{"q":"Statutory Instrument No. 36 of 2012 (European Communities Road Transport Working Time Regulations 2012) in Ireland applies to:","options":["Mobile workers and self-employed drivers","Full-time employed drivers only","Office administration staff only","Mechanics in static workshops only"],"correct":0,"exp":"Mobile workers and self-employed drivers in road transport."},{"q":"Under Directive 2002/15/EC, what is the maximum average weekly working time permitted over the standard reference period?","options":["40 hours per week","48 hours per week","56 hours per week","60 hours per week"],"correct":1,"exp":"A maximum average of 48 working hours a week over the reference period."},{"q":"What is the absolute maximum working time permitted in any single week under the Road Transport Working Time Directive?","options":["48 hours","56 hours","60 hours","72 hours"],"correct":2,"exp":"In a single week a maximum of 60 hours can be worked, as long as the average stays at 48."},{"q":"Under Directive 2002/15/EC, what is the standard length of the reference period used to calculate the 48-hour average weekly working time?","options":["4 months","4 weeks","12 weeks","12 months"],"correct":0,"exp":"The 48 h average is normally calculated over 4 months; with a collective agreement it can be extended to 6."},{"q":"What activities are officially defined as 'Working Time' for mobile workers under the directive?","options":["Driving time and loading / unloading passengers or freight","Vehicle cleaning, daily maintenance checks, and administrative work related to transport operations","Waiting times where the exact duration is NOT known in advance by the driver","All of the above"],"correct":3,"exp":"Everything on the list counts as working time: driving, helping passengers on and off or with luggage, cleaning, checking the vehicle, paperwork and waiting whose length is not known in advance."},{"q":"Which of the following time periods is EXCLUDED from the definition of Working Time (classified as Period of Availability - POA)?","options":["Waiting time whose length is known in advance","Time spent driving in heavy traffic","Time spent on morning walkaround checks","Time spent securing passenger wheelchairs"],"correct":0,"exp":"Waiting whose length the driver knows in advance is not working time: it is availability (POA)."},{"q":"When a mobile worker works between 6 hours and 9 hours in a single shift, what is the mandatory minimum total break duration required under WTD?","options":["15 minutes","30 minutes","45 minutes","60 minutes"],"correct":1,"exp":"If working between 6 and 9 hours, the minimum total break is 30 minutes."},{"q":"If total working time exceeds 9 hours in a single shift, what is the mandatory minimum total break duration required under WTD?","options":["30 minutes","45 minutes","60 minutes","90 minutes"],"correct":1,"exp":"If working more than 9 hours, the minimum total break is 45 minutes."},{"q":"How can WTD breaks (30 min or 45 min) be broken down into smaller periods during the shift?","options":["Into periods of at least 15 minutes each","Into 5-minute increments","Breaks cannot be broken down under any circumstances","Into one 10-minute and two 20-minute periods"],"correct":0,"exp":"The 30- or 45-minute breaks can be split into parts of at least 15 minutes."},{"q":"Under Directive 2002/15/EC, what is the definition of 'Night Time'?","options":["At least 4 hours between 00:00 and 07:00","At least 7 hours between 22:00 and 07:00","Any period between sunset and sunrise","The period from 20:00 to 06:00"],"correct":0,"exp":"At least 4h between midnight and 07:00 (in Ireland: 00:00-04:00)."},{"q":"If a mobile worker performs ANY work during the defined 'Night Time' period (00:00 to 04:00), what is the maximum permitted working time in that 24-hour period?","options":["10 hours","8 hours","12 hours","14 hours"],"correct":0,"exp":"If any work is done during night time, the working time in those 24 hours cannot exceed 10 hours (unless there is a collective agreement)."},{"q":"Under EU Working Time Regulations, how many weeks of paid annual leave are mobile workers entitled to per year?","options":["4 weeks","2 weeks","3 weeks","6 weeks"],"correct":0,"exp":"Mobile workers have 4 weeks of paid holidays a year (20 working days)."},{"q":"Are statutory breaks or rest periods allowed to be counted as part of a driver's 4-week paid annual leave entitlement?","options":["No, leave is separate and cannot be paid off","Yes, breaks count as part of annual leave","Only if agreed verbally with the manager","Only during the quieter winter months"],"correct":0,"exp":"Paid holidays are separate: they cannot be covered by breaks or rests, or exchanged for money except when the contract ends."},{"q":"How long must a transport employer retain records of mobile workers' working time (including tachograph downloads and working pattern logs)?","options":["2 years","6 months","1 year","5 years"],"correct":0,"exp":"Working time records are kept for at least 2 years."},{"q":"What is the legal obligation of an operator regarding mobile workers who work for MULTIPLE employers?","options":["Ask in writing for hours worked elsewhere","Employers must not know about other jobs","Second jobs are illegal in all cases","Only the main employer keeps any records"],"correct":0,"exp":"They must request in writing a statement of the time worked for other employers."},{"q":"Does time spent traveling to take charge of a vehicle located away from the base count as Working Time or Period of Availability?","options":["Working time, or POA on a train or ferry","It counts as daily rest, as no work is done","It is ignored for all working time purposes","It counts as part of the annual leave"],"correct":0,"exp":"It counts as Working Time or POA, depending on the case."},{"q":"What is a 'Self-employed driver' under Directive 2002/15/EC?","options":["Has own licence and earns directly from profits","Anyone who drives a taxi for a living","A driver supplied by an employment agency","A part-time driver who works at weekends"],"correct":0,"exp":"Transport as their main occupation, their own licence, freedom to organise their work and income linked to profit."},{"q":"Are self-employed drivers subject to the maximum average 48-hour working week and night work limits under Irish WTD law?","options":["Yes, they are fully covered by the Directive","No, self-employed drivers are fully exempt","Only if they operate international routes","Only if they drive coaches with over 50 seats"],"correct":0,"exp":"Yes, fully within the scope of the Directive."},{"q":"Which statutory authority in Ireland is responsible for enforcing Working Time Directive compliance for mobile workers in road transport?","options":["The WRC, together with the RSA","The National Transport Authority","The Revenue Commissioners","All of the above"],"correct":0,"exp":"In Ireland, compliance with drivers' working time is monitored by the WRC and the RSA."},{"q":"What happens if an employer fails to maintain accurate working time records for mobile workers for at least 2 years?","options":["An offence, with fines of up to €5,000","They only receive a verbal reminder","The company's tax rate rises by 5%","Drivers get 10 extra days of leave"],"correct":0,"exp":"An offence under S.I. 36/2012, with fines of up to €5,000."},{"q":"What mode must a digital tachograph be set to while a driver is performing manual loading, cleaning, or administrative work?","options":["Rest / Break (Bed symbol)","Other Work (Crossed hammers symbol)","Availability (Square symbol with diagonal line)","Driving (Steering wheel symbol)"],"correct":1,"exp":"Helping with luggage, cleaning or doing paperwork is 'Other Work' (crossed hammers)."},{"q":"When a driver is waiting at a terminal for a ferry departure and has been informed in advance that the delay will last 2 hours, how should this time be logged?","options":["Period of availability","Other work time","Driving time","Annual leave"],"correct":0,"exp":"If the driver knows in advance how long the wait will last (2 hours for the ferry), it is availability (POA, the box with a diagonal line)."},{"q":"Is a driver permitted to perform 'Other Work' for a non-transport employer (e.g., bartending or security) during their off-duty hours without informing their transport employer?","options":["No, all work counts and must be declared","Yes, private work is never monitored","Yes, provided the other job pays cash","Only if it is done on public holidays"],"correct":0,"exp":"It must be declared so that the 48h limit is respected."},{"q":"If a driver works 50 hours in Week 1, 55 hours in Week 2, 45 hours in Week 3, and 42 hours in Week 4, what is their average weekly working time over this 4-week period?","options":["45.0 hours","48.0 hours","49.0 hours","52.0 hours"],"correct":1,"exp":"Average = sum of hours ÷ weeks = (50 + 55 + 45 + 42) ÷ 4 = 192 ÷ 4 = 48 hours: exactly at the limit."},{"q":"What is the maximum permitted working time in a single week if a driver works 60 hours in Week 1?","options":["Legal, if the 4-month average stays at 48 or less","Illegal, as 48 hours is the weekly maximum","Allowed only for drivers on international trips","Needs written permission from the Gardaí"],"correct":0,"exp":"Legal if the average over the reference period does not exceed 48h/week."},{"q":"Under WTD rules, if a shift involves 5 hours of total working time, how much break time is legally required?","options":["0 minutes","15 minutes","30 minutes","45 minutes"],"correct":0,"exp":"With 5 hours of work there is no compulsory working-time break: the break is compulsory from 6 hours."},{"q":"Under WTD rules, if a shift involves 7 hours of total working time, what is the minimum break required?","options":["15 minutes","30 minutes","45 minutes","60 minutes"],"correct":1,"exp":"Between 6 and 9 hours of work: minimum break of 30 minutes. With 7 hours, 30 minutes."},{"q":"Under WTD rules, if a shift involves 9.5 hours of total working time, what is the minimum break required?","options":["30 minutes","45 minutes","60 minutes","90 minutes"],"correct":1,"exp":"More than 9 hours of work: minimum break of 45 minutes. With 9 h 30, 45 minutes."},{"q":"Does a 45-minute driving break taken under Regulation 561/2006 also satisfy the break requirements of the Working Time Directive?","options":["Yes, it satisfies both sets of rules","No, WTD breaks are separate and additional","Only if the break is taken in a hotel","Only if the WRC has approved it"],"correct":0,"exp":"Yes: a 45-minute break that complies with Regulation 561/2006 also satisfies the working-time break."},{"q":"Can a driver extend the 10-hour night work limit to 12 hours if a formal collective agreement or workforce agreement is in place?","options":["Yes, by collective or workforce agreement","No, night limits can never be extended","Yes, but only for drivers under 25","Only during a national emergency"],"correct":0,"exp":"Yes, by collective agreement, respecting health/safety."},{"q":"What is the reference period default framework in Ireland if no collective agreement specifies otherwise?","options":["4-month periods: Jan-Apr, May-Aug, Sep-Dec","Fixed 52-week periods from the start date","Each calendar week, Monday to Sunday","Two-year periods matching record keeping"],"correct":0,"exp":"4-month periods (Jan-Apr, May-Aug, Sep-Dec)."},{"q":"How does the Working Time Directive define 'mobile worker'?","options":["Travelling staff such as drivers and conductors","Office staff who use company mobile phones","Mechanics fixing vehicles in the depot","Security staff who patrol the depot at night"],"correct":0,"exp":"Travelling staff of a transport company."},{"q":"What record must an employer provide to a mobile worker upon request regarding their working time history?","options":["A copy of their working hours for 2 years","A copy of the company's tax returns","The Transport Manager's personal logbook","The repair bills for their vehicle"],"correct":0,"exp":"A written copy of their hours for the last 2 years."},{"q":"What is the primary purpose of the Road Transport Working Time Directive 2002/15/EC?","options":["Prevent fatigue and improve road safety","To increase revenue from speed limiters","To replace digital tachographs with paper","To abolish overtime pay for drivers"],"correct":0,"exp":"Preventing fatigue, protecting health/safety and improving road safety."},{"q":"In Case Study calculations, if a driver completes 4 hours of driving, 2 hours of loading ('Other Work'), and 1 hour of POA in a day, what is their total 'Working Time' for WTD purposes?","options":["6 hours","4 hours","7 hours","5 hours"],"correct":0,"exp":"Working time = driving + other work = 4 + 2 = 6 hours. Availability (POA) does not count as work."},{"q":"If a mobile worker works from 01:00 to 09:00 (including 01:00 to 04:00 night time), what is the maximum total working time allowed for that shift unless covered by a collective agreement?","options":["8 hours","10 hours","12 hours","15 hours"],"correct":1,"exp":"If the working day includes night time, the maximum working time in those 24 hours is 10 hours (unless there is a collective agreement)."},{"q":"Are agency drivers covered by the Road Transport Working Time Regulations?","options":["Yes, agency and hirer share the responsibility","No, agency drivers are exempt from the rules","Yes, but they can work unlimited hours","Only if they drive vehicles under 3.5 tonnes"],"correct":0,"exp":"Yes, the agency and the operator share responsibility."},{"q":"What symbol represents 'Period of Availability' (POA) on digital tachograph displays and printouts?","options":["A square box","A steering wheel","Crossed hammers","A bed or chair"],"correct":0,"exp":"Availability (POA): a box with a diagonal line. Driving: steering wheel; other work: hammers; rest: bed."},{"q":"What is the role of a Transport Manager regarding Working Time Directive compliance?","options":["Set up systems to record and audit working time","Pay drivers' fines out of personal funds","Make drivers work 70 hours every week","Ignore drivers' declarations of other jobs"],"correct":0,"exp":"Setting up systems to track and audit compliance with the WTD."}]},"11d":{"title":"Topic 11 (extra) - Rest Rules & Exemptions","questions":[{"q":"Under EU Regulation (EC) No 561/2006, what is the default legal classification for a passenger transport service operating on a route where the distance does NOT exceed 50 km?","options":["Exempt from EU hours and tachograph rules","Subject to full EU driving and break limits","Exempt from all speed limits on the route","Covered only by the international AETR rules"],"correct":0,"exp":"Exempt from EU rules, subject to domestic rules."},{"q":"Under Irish national law, what legislation governs passenger transport operations that fall OUT OF SCOPE of EU Regulation 561/2006 (e.g. regular services under 50 km)?","options":["The Irish domestic drivers' hours regulations","The Companies Act 2014 and its regulations","The Organisation of Working Time Act 1997","The Safety, Health and Welfare at Work Act 2005"],"correct":0,"exp":"Road Transport Act 1933 and the domestic rules."},{"q":"Under Irish domestic drivers' hours rules for out-of-scope bus operations, what is the maximum continuous driving limit before a mandatory break?","options":["4.5 hours","5.5 hours","6.0 hours","8.0 hours"],"correct":1,"exp":"Domestic passenger rules: a maximum of 5 h 30 of continuous driving before a break."},{"q":"What is the minimum break required after 5.5 hours of continuous driving under Irish domestic bus rules?","options":["15 minutes","30 minutes","45 minutes","60 minutes"],"correct":1,"exp":"Domestic rules: after 5 h 30 of driving, a break of at least 30 minutes."},{"q":"Under Irish domestic bus rules, what is the absolute maximum daily driving time permitted for a driver?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"Domestic rules: maximum 10 hours of driving a day."},{"q":"What is the maximum permitted daily spreadover (working day duration) under Irish domestic rules for out-of-scope passenger transport?","options":["12 hours","14 hours","16 hours","18 hours"],"correct":2,"exp":"Domestic rules: a whole working day (spreadover) of 16 hours at most."},{"q":"What is the standard minimum daily rest period required within a 24-hour period under Irish domestic bus rules?","options":["8 hours","9 hours","10 hours","11 hours"],"correct":2,"exp":"Domestic rules: daily rest of 10 hours in each 24-hour period."},{"q":"To what duration may the domestic daily rest period (10 hours) be reduced, and how many times per week?","options":["Reduced to 8.5 hours up to 3 times per week","Reduced to 8.0 hours twice per week","Reduced to 9.0 hours once per week","No reductions are permitted under domestic rules"],"correct":0,"exp":"Domestic rules: the 10-hour rest can be reduced to 8 h 30 up to 3 times a week."},{"q":"Is a driver who drives a bus for LESS than 4 hours on any day required to comply with domestic daily rest rules for that day?","options":["No, they are exempt from rest rules that day","Yes, rest rules apply whatever the driving time","Only if they drive double-deck buses that day","Only at weekends and on bank holidays"],"correct":0,"exp":"If they drive less than 4 hours that day, the driver does not have to comply with the domestic daily rest rules."},{"q":"What special exemption applies to regular passenger services where the route length does NOT exceed 50 km under EU Regulation 561/2006?","options":["No tachograph needed and EU limits do not apply","No need to hold a category D driving licence","No need to pay motor tax on the vehicles","No need to follow passenger fare tariffs"],"correct":0,"exp":"Exemption from the tachograph and EU limits (Article 3(a))."},{"q":"Which of the following passenger transport operations is ALSO exempt from EU Regulation 561/2006?","options":["Vehicles with a maximum seating capacity of 9 to 16 seats used exclusively for non-commercial carriage of passengers","Specialized breakdown vehicles operating within 100 km of base","Vehicles used by armed forces, civil defence, fire services, and emergency services","All of the above"],"correct":3,"exp":"All of those on the list are exempt from Regulation 561/2006."},{"q":"If a passenger transport operator uses a vehicle carrying 12 passengers for a non-commercial community trip, is a digital tachograph legally required?","options":["No, non-commercial use up to 16 seats is exempt","Yes, all vehicles with over 8 seats need one","Yes, whenever it is driven on motorways","Only if the driver is paid overtime for it"],"correct":0,"exp":"A vehicle with 9 to 16 seats used for non-commercial purposes is exempt from the EU rules: it does not need a tachograph."},{"q":"What is the legal requirement when a driver operates a mixed schedule (driving part of the day on an exempt 30 km route and part on a non-exempt 150 km tour)?","options":["Record the whole day; local driving as other work","Take the card out during the local route","The driver is exempt for the rest of the week","Log the local driving as a break or rest"],"correct":0,"exp":"The whole day on the tachograph, with the domestic route as 'Other Work'."},{"q":"Can time spent driving on an exempt local bus route (under 50 km) be counted as a Break or Daily Rest under EU rules?","options":["No, it counts as other work, not as rest","Yes, local driving is treated as rest","Yes, if the average speed is under 20 km/h","Only if the driver has a part-time contract"],"correct":0,"exp":"No, it is 'Other Work' and never counts as a break/rest."},{"q":"What is the '12-Day Rule' (Article 8(6a) of Regulation 561/2006) in international road passenger transport?","options":["Weekly rest postponed up to 12 days on one trip","Drivers may work 12 weeks without a holiday","Drivers must stay in a hotel every 12 days","International tours are limited to 12 passengers"],"correct":0,"exp":"Postponing the weekly rest for up to 12 periods of 24h."},{"q":"Which of the following conditions MUST be satisfied to legally use the International 12-Day Rule?","options":["The service must be a single international passenger service (crossing at least one border) lasting at least 24 consecutive hours","The driver took a regular weekly rest (at least 45 hours) immediately prior to the journey","Following the 12 days, the driver takes two regular weekly rest periods (45h + 45h) OR one regular and one reduced weekly rest (45h + 24h with full compensation)","All of the above"],"correct":3,"exp":"The 12-day rule only applies if ALL the conditions are met: international occasional service, 24 consecutive hours in another country, weekly rests before and after, etc."},{"q":"What additional safety/technical requirement applies under the 12-Day Rule if driving occurs between 22:00 and 06:00?","options":["Two drivers, or a break after 3 hours' driving","Night driving is forbidden during the trip","The speed limiter must be set to 80 km/h","Passengers must sign a night travel waiver"],"correct":0,"exp":"Multi-manning OR reducing continuous driving to 3h."},{"q":"Since 1st January 2014, what tachograph requirement must vehicles satisfy to utilize the 12-Day Rule?","options":["A digital or smart tachograph","An analogue tachograph only","No tachograph is needed","Hand-written logbooks only"],"correct":0,"exp":"Since 1 January 2014, to use the 12-day rule the vehicle must have a digital or smart tachograph."},{"q":"Can the 12-Day Rule concession be used on purely DOMESTIC Irish passenger tours (e.g., Dublin to Kerry tour)?","options":["No, only international trips qualify","Yes, all coach tours qualify for it","Yes, if the RSA approves it in advance","Only during summer bank holidays"],"correct":0,"exp":"No: the 12-day rule only applies to international occasional services, which cross at least one border. A Dublin–Kerry tour is national."},{"q":"What is the rules framework for driving hours when transporting passengers on international journeys between Ireland and non-EU AETR countries (e.g., Switzerland, UK, Turkey)?","options":["The AETR Agreement rules","Irish domestic drivers' hours rules","US federal highway rules","United Nations maritime law"],"correct":0,"exp":"With non-EU countries that signed the AETR (such as Switzerland, the United Kingdom or Turkey) the AETR agreement applies, which is almost the same as 561/2006."},{"q":"When a driver accompanies a coach carried on a ferry or train, how may a regular daily rest period (at least 11 hours) be interrupted?","options":["Twice at most, 1 hour in total, with a bunk","Up to 5 times, for 3 hours in total","Only if harbour staff unload the vehicle","Daily rest can never be taken on a ferry"],"correct":0,"exp":"On a ferry or train, the normal daily rest can be interrupted a maximum of 2 times, not exceeding 1 hour in total, and the driver must have a bunk or cabin."},{"q":"Does the ferry interruption concession apply to REDUCED daily rest periods (9 hours)?","options":["No, it applies to regular daily rest only","Yes, all daily rest periods qualify","Only if the crossing lasts over 12 hours","Only on domestic ferries within Ireland"],"correct":0,"exp":"The ferry exception only applies to the NORMAL daily rest (11 h), or to the normal weekly rest in certain cases; not to the reduced 9 h rest."},{"q":"Under EU Regulation 561/2006, what is the rule regarding taking REGULAR weekly rest (45 hours) inside the vehicle cab?","options":["Banned: it must be in suitable accommodation","Allowed if the cab has a comfortable bunk","Allowed only at motorway service areas","Compulsory for all international drivers"],"correct":0,"exp":"Prohibited; it must be taken in suitable accommodation."},{"q":"Can REDUCED weekly rest (24 hours to 44 hours) be taken in the vehicle cab?","options":["Yes, if stationary with a bed for each driver","No, it must also be taken in a hotel room","Only if the Gardaí authorise it in writing","Never, under any circumstances"],"correct":0,"exp":"The reduced weekly rest (24 to 44 h) can be taken in the vehicle if it is stationary and has a suitable bunk for each driver. The normal 45 h rest cannot."},{"q":"What is the penalty for an operator who forces drivers to take regular weekly rest periods (45 hours) inside the vehicle cab?","options":["Fines, prosecution and loss of the licence","Only a minor administrative warning","A written warning from the NTA","A fixed charge notice for the driver only"],"correct":0,"exp":"Heavy fines, prosecution and risk of licence suspension."},{"q":"What is the maximum continuous driving limit allowed under EU Regulation 561/2006 before a mandatory 45-minute break?","options":["4.5 hours","4 hours","5 hours","5.5 hours"],"correct":0,"exp":"A maximum of 4 h 30 of driving before a 45-minute break."},{"q":"If a driver takes a 15-minute break after 2 hours of driving, how long must the second break be to satisfy the split break requirement under EU rules?","options":["15 minutes","30 minutes","45 minutes","60 minutes"],"correct":1,"exp":"If the first break is 15 minutes, the second must be at least 30 (15 + 30 = 45)."},{"q":"Under EU rules, is it legal to take a 30-minute break first, followed by a 15-minute break later?","options":["No, it must be 15 minutes first, then 30","Yes, the order does not matter at all","Only when driving on international routes","Yes, but only for drivers of minibuses"],"correct":0,"exp":"No, the correct order is 15 min first, 30 min afterwards."},{"q":"What is the legal status of an emergency departure from driving hours rules under Article 12 of Regulation 561/2006?","options":["Drivers may exceed driving limits to enable the vehicle to reach a suitable stopping place to ensure safety of persons, vehicle, or load, provided road safety is not endangered","Drivers must indicate the reason manually on the tachograph chart/printout upon arrival at the stopping place","It cannot be used for known or predictable delays (such as scheduled traffic jams)","All of the above"],"correct":3,"exp":"Everything on the list: the limit can be exceeded only to reach a safe place, the reason must be noted on arrival, and it does not apply to delays that could have been foreseen."},{"q":"In Case Study calculations, an operator runs an urban bus service on a 25 km route. What hours regime applies to this service?","options":["Irish domestic rules","EU Regulation 561/2006","The AETR rules","No driving hours rules at all"],"correct":0,"exp":"A 25 km urban route: as it does not exceed 50 km, it is outside the EU rules and the Irish domestic rules apply."},{"q":"In Case Study calculations, a driver on a domestic 25 km bus route drives 5 hours continuously without a break. Is this legal under Irish domestic rules?","options":["Yes, up to 5.5 hours is allowed before a break","No, the limit is 4.5 hours under all laws","Yes, domestic rules allow unlimited driving","No, domestic rules need a break after 3 hours"],"correct":0,"exp":"Yes: the domestic rules allow up to 5 h 30 of continuous driving before a 30-minute break."},{"q":"If a driver on an exempt route works a 15-hour spreadover day with 9 hours driving under domestic rules, is this legal under Irish domestic regulations?","options":["Yes: spreadover up to 16 h, driving up to 10 h","No, the maximum spreadover is 12 hours","No, daily driving cannot exceed 8 hours","Only with written permission from the RSA"],"correct":0,"exp":"Yes, within the domestic limits (16h spreadover, 10h driving)."},{"q":"What record-keeping mechanism must be used by drivers operating domestic out-of-scope bus services if no tachograph is fitted?","options":["A logbook or duty roster with hours and rests","Verbal notes given to the dispatcher","Text messages sent from a mobile phone","None: domestic services need no records"],"correct":0,"exp":"Without a tachograph, the domestic record book or duty rosters are used, with the start and finish times, driving and rests."},{"q":"How long must an operator retain domestic driver logbooks and duty rosters for RSA inspection?","options":["12 months","6 months","3 years","5 years"],"correct":0,"exp":"Record books and rosters are kept for at least 12 months (2 years if they are also used for working time)."},{"q":"What is the definition of 'Multi-manning' (double-manning) under EU Regulation 561/2006?","options":["During each period of driving between two consecutive daily rest periods, or between a daily rest and a weekly rest, there are at least two drivers on board to drive","For the first hour of multi-manning, the presence of the second driver is optional, but compulsory for the remainder","Both A and B","Two drivers operating separate buses on the same route"],"correct":2,"exp":"A and B: at least 2 drivers, with the first hour optional for the second one."},{"q":"Under multi-manning, what daily rest requirement must each driver fulfill within a 30-hour period?","options":["A daily rest period of at least 9 hours","A daily rest period of at least 11 hours","A daily rest period of at least 12 hours","No daily rest is required while traveling as passenger"],"correct":0,"exp":"With two drivers, each one rests at least 9 hours in each 30-hour period."},{"q":"Is time spent by Driver B sitting in the passenger seat while Driver A drives under multi-manning counted as Rest or Break?","options":["Period of availability; 45 minutes may be a break","It is all counted as daily rest","It is counted as driving time for both","It is counted as other work, like loading"],"correct":0,"exp":"The time the second driver spends sitting while the other drives is availability (POA). It can count 45 minutes as a break if they do not assist the driver."},{"q":"What is the impact of failing to comply with rest rules and drivers' hours on the Transport Manager's status?","options":["Loss of good repute and disqualification as TM","A fine paid by the insurance company","The licence becomes a private licence","No personal impact on the manager at all"],"correct":0,"exp":"Loss of Good Repute, with disqualification."},{"q":"What is the legal requirement for driver rest compensation when a reduced weekly rest (e.g. 24 hours) is taken?","options":["21 hours en bloc by the end of the third week","It can be paid off as a cash bonus instead","It is waived for passenger operators","21 hours, to be taken within the next 48 hours"],"correct":0,"exp":"Compensation en bloc before the 3rd following week."},{"q":"What is the primary objective of enforcing strict driver rest rules, bus driver rules, and exemptions across Ireland and the EU?","options":["Keep drivers alert and prevent fatigue crashes","Maximise fare revenue for private companies","Eliminate the use of digital tachographs","Encourage single-driver long-distance trips"],"correct":0,"exp":"Driver alertness, preventing fatigue-related collisions and fair competition."}]},"12b":{"title":"Topic 12 (extra) - Tachograph Calibration & Operation","questions":[{"q":"Which EU Regulation sets the technical standards, installation, calibration, and operational rules for digital and smart tachographs?","options":["Regulation (EC) No 561/2006","Regulation (EU) No 165/2014","Directive 2003/59/EC","Regulation (EC) No 1071/2009"],"correct":1,"exp":"Regulation 165/2014 regulates tachographs (technical aspects, installation, calibration and use). Regulation 561/2006 regulates hours."},{"q":"How often MUST a commercial vehicle tachograph system undergo full recalibration and inspection at an approved workshop?","options":["Every 2 years","Every year","Every 3 years","Every 6 years"],"correct":0,"exp":"The tachograph is inspected and recalibrated at an approved workshop every 2 years."},{"q":"In addition to the bi-annual (2-year) recalibration, under what other circumstances MUST a tachograph be recalibrated immediately?","options":["If the vehicle registration number changes","If the effective circumference of the tyres (tyre size) changes or repairs affect the calibration parameters","If the vehicle's speed limiter or gearbox is repaired/replaced","All of the above"],"correct":3,"exp":"As well as every 2 years, it must be recalibrated straight away in all the cases on the list (for example, after the tachograph is repaired or after changing something that affects how it measures distance or speed)."},{"q":"What physical proof must be affixed to the vehicle near or on the tachograph following a successful calibration?","options":["A calibration plaque with w, l and workshop details","A green RSA sticker on the front bumper","A copy of the driver's CPC card in the cab","A copy of the motor tax disc on the dashboard"],"correct":0,"exp":"A calibration plaque/certificate with the coefficients and workshop details."},{"q":"Who is legally authorised to calibrate, seal, and issue calibration plaques for tachographs in Ireland?","options":["An RSA-approved tachograph workshop","Any licensed commercial bus driver","The Transport Manager, using an app","The local Garda station"],"correct":0,"exp":"Only a workshop or technician approved by the RSA can calibrate, seal and fit the calibration plaque."},{"q":"How long is an analogue tachograph chart designed to record data?","options":["12 hours","24 hours","48 hours","7 days"],"correct":1,"exp":"An analogue chart records 24 hours."},{"q":"What color is the trace made by the stylus on an analogue tachograph chart paper?","options":["Black or grey, on wax-coated paper","Blue ink from a felt-tip stylus","Red ink from a cartridge","Pencil lead on plain paper"],"correct":0,"exp":"A black/grey trace on pressure-sensitive waxed paper."},{"q":"On an analogue tachograph chart, what information MUST a driver write manually on the centre field BEFORE starting their duty?","options":["Name, start place, date, registration, odometer","The fuel price and the weather conditions","The employer's tax number and depot address","The number of passenger tickets to be sold"],"correct":0,"exp":"Name, place and date of starting, registration number and starting odometer reading."},{"q":"On an analogue tachograph chart, what information MUST a driver write manually on the centre field at the END of their duty?","options":["End place, end date and closing odometer","Total fare revenue collected that day","The weather forecast for the next day","The workshop technician's signature"],"correct":0,"exp":"Place and date of finishing, and final odometer reading."},{"q":"If a driver changes vehicles during a working day, how is this recorded on an analogue tachograph chart?","options":["Write the second vehicle's details on the back","A new chart must be used for each vehicle","Vehicle changes cannot be recorded by hand","The driver logs off until the next day"],"correct":0,"exp":"Write the details of the second vehicle on the back of the chart."},{"q":"What are the four operational mode symbols displayed on digital and analogue tachographs?","options":["Wheel, hammers, square and bed","Car, truck, bus and taxi","Speed, distance, time and fuel","Red, amber, green and blue"],"correct":0,"exp":"Steering wheel, crossed hammers, box/envelope and bed/chair."},{"q":"Which mode is automatically selected by a digital tachograph as soon as the vehicle begins moving?","options":["Other Work","Availability (POA)","Driving Mode","Rest / Break"],"correct":2,"exp":"As soon as the vehicle moves, the digital tachograph switches to driving mode by itself."},{"q":"When a vehicle comes to a complete standstill, what mode does a digital tachograph default to (unless changed manually by the driver)?","options":["Other work","Driving","Rest or break","Power off"],"correct":0,"exp":"Other Work (or Availability depending on the settings)."},{"q":"What are the four different types of Smart Tachograph / Digital Tachograph Cards used in the EU system?","options":["Driver Card, Workshop Card, Control Card, and Company Card","Fuel Card, Toll Card, Maintenance Card, and Driver Card","Bronze, Silver, Gold, and Platinum Cards","RSA Card, Garda Card, NTA Card, and Revenue Card"],"correct":0,"exp":"Driver, Workshop, Control and Company Card."},{"q":"What is the validity period of a Digital Tachograph Driver Card issued by the RSA in Ireland?","options":["1 year","2 years","5 years","10 years"],"correct":2,"exp":"The driver card is issued by the RSA and lasts 5 years."},{"q":"What is the validity period of a Tachograph Workshop Card?","options":["1 year","2 years","3 years","5 years"],"correct":0,"exp":"The workshop card lasts only 1 year, for security."},{"q":"How long is a Tachograph Company Card valid once issued to an operator?","options":["1 year","3 years","5 years","10 years"],"correct":2,"exp":"The company card lasts 5 years."},{"q":"What is the primary function of a Tachograph Company Card?","options":["Lock company data and allow downloads","Let drivers drive without a driver card","Pay motorway tolls automatically","Calibrate the vehicle's speed limiter"],"correct":0,"exp":"Locking/protecting data, authorising downloads from the VU."},{"q":"Under EU Regulation 165/2014, how often MUST an operator download data from a driver's digital tachograph card?","options":["At least every 7 days","At least every 14 days","At least every 28 days","At least every 90 days"],"correct":2,"exp":"The driver card is downloaded at least every 28 days."},{"q":"How often MUST an operator download data from the digital tachograph Vehicle Unit (VU)?","options":["At least every 28 days","At least every 56 days","At least every 90 days","Annually"],"correct":2,"exp":"The vehicle unit (VU) is downloaded at least every 90 days."},{"q":"What action must a driver take if their digital tachograph card is lost, stolen, or damaged while away from base?","options":["Print at start and end, sign, apply in 7 days","Stop driving and wait until the new card arrives","Keep driving without making any records at all","Borrow another driver's card until it arrives"],"correct":0,"exp":"Daily printouts with details and signature, and applying for a replacement within 7 days."},{"q":"Within how many days must a driver apply to the RSA for a replacement digital tachograph card if it is lost, stolen, or malfunctioning?","options":["Within 3 calendar days","Within 7 calendar days","Within 14 calendar days","Within 28 calendar days"],"correct":1,"exp":"If the card is lost, stolen or fails, the driver applies to the RSA for another one within 7 calendar days."},{"q":"What is the maximum period a driver is legally permitted to continue driving without a digital tachograph card (using manual daily printouts) while awaiting a replacement?","options":["15 calendar days","7 calendar days","30 calendar days","No time limit"],"correct":0,"exp":"15 calendar days (or longer if it is necessary to return to base)."},{"q":"What mandatory feature was introduced with Smart Tachographs Version 1 (GEN2 V1) enforced on new vehicles since August 2019?","options":["GNSS position recording and DSRC remote checks","Voice recording of driver conversations","Facial recognition cameras in the cab","Automatic speed reduction on sharp bends"],"correct":0,"exp":"GNSS position at the start/end of the day and every 3h, plus DSRC."},{"q":"Smart Tachographs Version 2 (GEN2 V2), mandatory on new registered vehicles since August 2023, includes which additional capability?","options":["Recording border crossings and loading places","Remote engine cut-off by the Gardaí on demand","Automatic head counts of passengers on board","Automatic tyre inflation when pressure drops"],"correct":0,"exp":"Automatic recording of border crossings and loading/unloading."},{"q":"What technology allows roadside enforcement officers (RSA/Gardaí) to read basic tachograph compliance data from a moving vehicle without stopping it?","options":["DSRC short-range wireless","Satellite radar imaging","Infrared thermal cameras","All of the above"],"correct":0,"exp":"DSRC: wireless technology that lets the Garda and the RSA read basic data from the smart tachograph without stopping the vehicle."},{"q":"Can a roadside officer issue a fine solely based on data transmitted via DSRC from a moving vehicle?","options":["No, it only selects vehicles to be stopped","Yes, DSRC issues fines automatically","DSRC is used only for toll payments","Yes, penalty points are added instantly"],"correct":0,"exp":"Only for screening vehicles; a physical inspection is required."},{"q":"If a driver forgets to insert their driver card into the tachograph at the start of a shift and drives for 2 hours, what is recorded on the Vehicle Unit (VU)?","options":["A 'driving without card' event in the VU","Nothing is recorded until a card goes in","The VU deletes that driving from memory","The engine locks after 15 minutes"],"correct":0,"exp":"A 'driving without an appropriate card' event."},{"q":"How must a driver record activities performed away from the vehicle (such as administrative work or training) before inserting their card into a digital tachograph?","options":["By performing a manual entry on the tachograph display upon card insertion","By writing a note on a piece of paper and leaving it in the glovebox","Manual entries are not permitted on digital tachographs","By calling the RSA call centre"],"correct":0,"exp":"Manual entry on the screen when the card is inserted."},{"q":"If a digital tachograph unit breaks down or malfunctions during a journey, within how many days must it be repaired by an approved workshop?","options":["Within 7 calendar days","Within 24 hours of the fault","Within 14 calendar days","At the next annual CVRT test"],"correct":0,"exp":"If the tachograph breaks down on the road, it must be repaired at an approved workshop within 7 calendar days. In the meantime, the driver records their activity by hand."},{"q":"While traveling with a broken tachograph unit during the 7-day grace period, how must the driver record their driving and rest activities?","options":["Manual entries on printouts or chart backs","No records are needed until it is fixed","Verbal notes to the transport manager","Times kept on a smartphone stopwatch"],"correct":0,"exp":"Temporary paper printouts with manual entries."},{"q":"How long must an operator retain all downloaded digital tachograph files, printouts, and analogue charts at their operating base?","options":["12 months","6 months","3 years","5 years"],"correct":0,"exp":"At least 12 months (2 years if they are for Working Time)."},{"q":"How many preceding days of tachograph records must a driver carry on board the vehicle and present to enforcement officers upon request?","options":["Current day plus preceding 7 days","Current day plus preceding 14 days","Current day plus preceding 28 calendar days","Current day plus preceding 56 calendar days"],"correct":2,"exp":"The current day plus the previous 28 calendar days."},{"q":"What is the legal outcome if an operator fails to lock-in their company card before placing a new digital tachograph vehicle into service?","options":["Company data is left unprotected","The unit cannot record driving time","The vehicle's motor tax becomes invalid","The driver card is destroyed"],"correct":0,"exp":"Unprotected data, risk of failing an audit."},{"q":"What is the requirement regarding spare printer paper rolls for digital tachographs?","options":["Drivers must always carry enough spare rolls","Spare rolls are optional for the driver","Rolls are only needed for workshop checks","Gardaí supply rolls free at roadside checks"],"correct":0,"exp":"The driver MUST always carry enough spare paper."},{"q":"Under EU Regulation 165/2014, what is the penalty for tampering with a tachograph (e.g. using magnets, cheat devices, or modified software)?","options":["Prosecution, fines, prison and loss of licence","Only a minor administrative warning letter","A one-day suspension of the driving licence","Having to re-take the driver CPC theory test"],"correct":0,"exp":"Criminal prosecution, fines of up to €5,000, possible prison."},{"q":"What information is stored on a digital tachograph Driver Card?","options":["Identity, vehicles used and activity records","The driver's bank account and salary details","Home addresses of the passengers carried","Fuel consumption figures for each vehicle"],"correct":0,"exp":"Identity, licence details, registration numbers driven, activity and events."},{"q":"Can a driver hold more than one valid digital tachograph Driver Card at any time?","options":["No, only one valid card is allowed","Yes, one card for each employer","Yes, one domestic and one international","Only if the Transport Manager approves"],"correct":0,"exp":"Each driver can only hold ONE valid card. Having several or using someone else's is a serious offence."},{"q":"What is the role of the Transport Manager regarding tachograph compliance?","options":["Download cards every 28 days, VUs every 90 days","Drive all vehicles personally to test them","Pay drivers' speeding fines personally","Change tachograph clocks for summer time"],"correct":0,"exp":"Downloading cards/VUs regularly, auditing and keeping archives."},{"q":"How often must the internal clock (UTC time) of a digital tachograph be verified against standard time?","options":["By GNSS on smart units, or at calibration","Manually by the driver every morning","Only every 5 years, at a workshop","Never: no clock checks are required"],"correct":0,"exp":"Via satellite on smart tachographs, or at the two-yearly recalibration."}]}};
